INSERT INTO public.items (id, type, character, slug, level, lesson_position, meaning_mnemonic, reading_mnemonic, svg_filename) VALUES
  ('00000000-0000-4000-8000-000000000001', 'radical', '一', 'ground', 1, 0, 'Radikal ini terdiri dari satu guratan horizontal. Berapakah pukulan horizontal tunggal terbesar? Itulah <radikal>landasan</radikal>. Lihatlah ke bawah, lihat ke arah radikal ini, sekarang lihatlah ke bawah lagi. Sama saja kan?', NULL, NULL),
  ('00000000-0000-4000-8000-000000000002', 'radical', 'ハ', 'fins', 1, 1, 'Bayangkan seekor ikan. Sekarang bayangkan ikannya sedikit lebih buruk, seperti gambar ikan anak-anak. Sekarang hapus tubuh ikannya dan... Anda akan mendapatkan dua <radikal>sirip</radikal>! Apakah Anda melihat kedua sirip ini? Ya, Anda melihatnya.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000003', 'radical', '丶', 'drop', 1, 2, 'Radikal kecil ini adalah <radikal>tetesan</radikal> air atau cairan lainnya. Perhatikan bagaimana itu hanya satu tetes? Terkadang radikal atau kanji memiliki lebih dari satu huruf, jadi penting bagi Anda untuk mengetahui cara membedakannya.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000004', 'radical', '七', 'seven', 1, 14, 'Seperti apa sikap radikal ini? Hmm, tidak banyak. Bagaimana jika Anda membalikkannya? Sekarang apakah terlihat seperti angka 7 dengan garis melewatinya? Cukup dekat untuk membantu Anda mengingat bahwa radikal ini adalah <radikal>tujuh</radikal>, bukan? Ingat saja, ketika Anda melihat radikal ini, balikkan dan lihat seperti apa angkanya. Jika Anda bisa melakukan itu, Anda bisa mengingat maknanya!', NULL, NULL),
  ('00000000-0000-4000-8000-000000000005', 'radical', '丿', 'slide', 1, 3, 'Tutup mata Anda dan bayangkan Anda menjadi anak-anak lagi. Sekarang buka dan... lihat! Itu adalah <radikal>slide</radikal>! Bayangkan Anda meluncur ke bawah slide ini berulang kali, bersenang-senang. Imajinasi + emosi menghasilkan hafalan yang baik!', NULL, NULL),
  ('00000000-0000-4000-8000-000000000006', 'radical', '亅', 'barb', 1, 4, 'Radikal ini berbentuk seperti duri. Seperti yang Anda lihat di kawat duri. Bayangkan salah satu benda ini menempel di lengan atau pakaian Anda. Pikirkan betapa sakitnya jika kait kecil di ujungnya menempel pada Anda. Katakan dengan lantang, "Oh sial, ada duri yang tertancap di tubuhku!"', NULL, NULL),
  ('00000000-0000-4000-8000-000000000007', 'radical', '二', 'two', 1, 5, 'Satu baris ditambah baris lainnya sama dengan <radikal>dua</radikal> baris. Radikal ini mewakili nomor dua. Cukup sederhana, bukan? Bisakah kamu menebak seperti apa ketiganya? Saya yakin Anda bisa...', NULL, NULL),
  ('00000000-0000-4000-8000-000000000008', 'radical', '亠', 'lid', 1, 6, 'Ini terlihat seperti sesuatu yang Anda taruh di ketel atau panci, bukan? Bahkan ada pegangan kecil untuk memastikan Anda tidak terbakar. Ini semacam <radikal>penutup</radikal>.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000009', 'radical', '人', 'person', 1, 8, 'Jika Anda menggambar <radical>orang</radical> hanya dengan guratan seperti yang Anda lihat di kanji, Anda akan membuat figur tongkat, mungkin seperti ini: <ja>大</ja>. Tapi ini hanyalah seseorang, bukan seseorang yang mengulurkan tangannya untuk menunjukkan betapa besarnya mereka. Jadi lengannya diturunkan, sehingga terlihat seperti batang tubuh dengan sepasang kaki. Mungkin mereka juga sedang berjalan, makanya kaki mereka direntangkan seperti itu. Anda dapat melihat orang itu sekarang, bukan?', NULL, NULL),
  ('00000000-0000-4000-8000-000000000010', 'radical', 'ト', 'toe', 1, 24, 'Bentuk radikal ini mirip dengan karakter katakana <ja>ト</ja> (to), yang bunyinya seperti kata <radical>toe</radical>. Jadi ketika Anda melihat <ja>ト</ja>, pikirkanlah.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000011', 'radical', '九', 'nine', 1, 20, 'Jika Anda melihat radikal ini dengan cara yang benar, Anda akan melihat bahwa ini terlihat seperti huruf "n" dan "i" ("i" berasal dari guratan kecil di sisi kanan). Huruf "n" dan "i" mulai dieja apa? Wah, kata <radikal>sembilan</radikal>.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000012', 'radical', '入', 'enter', 1, 9, 'Hati-Hati! Ini bukan orangnya radikal, tapi hal lain. Apa bedanya? Sisi kanan lebih panjang dari sisi kiri. Dan pada komputer, biasanya ada bagian tambahan yang menonjol di bagian atas. Ini terlihat seperti penutup yang membuka ke teepee. Dan apa yang Anda lakukan dengan pembukaan? Anda memasukkannya! Itu sebabnya radikal ini <radikal>masuk</radikal>.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000013', 'radical', '力', 'power', 1, 10, 'Bayangkan seorang pria melenturkan lengannya ke bawah untuk memamerkan lengannya yang dipompa steroid. Ini sangat besar. Ini penuh dengan <radikal>kekuatan</radikal>. RRRRWWWRRR!!', NULL, NULL),
  ('00000000-0000-4000-8000-000000000014', 'radical', '勹', 'prison', 1, 11, 'Ini tampak seperti semacam kandang - itulah mengapa ini disebut <radikal>penjara</radikal>. Ia membungkus dirinya sendiri di sekitar benda-benda dan menguncinya di sana. Penjara cukup menakutkan, bahkan sebelum Anda membayangkan penjara perlahan-lahan melayang turun dari langit untuk menjebak Anda.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000015', 'radical', '十', 'cross', 1, 15, 'Radikal ini tampak seperti <radikal>silang</radikal>. Maksudku, lihat saja. Dua batang saling bersilangan = sebuah salib!', NULL, NULL),
  ('00000000-0000-4000-8000-000000000016', 'radical', '口', 'mouth', 1, 12, 'Lubang persegi yang besar dan menganga melambangkan seseorang yang membuka <radikal>mulut</radikal> raksasanya untuk memberi tahu Anda sesuatu yang bodoh.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000017', 'radical', '土', 'dirt', 2, 0, 'Ada tanda salib yang tergambar di tanah, membuat <radikal>kotoran</radikal> ini. Anda dapat menggambar apa saja di tanah, kali ini kebetulan berupa salib. Bayangkan menggambar salib di tanah dengan jari Anda. Rasakan kotoran tersangkut di bawah kuku Anda dan jangan pernah lupa.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000018', 'radical', '大', 'big', 1, 7, 'Radikal ini tampak seperti figur tongkat—lebih khusus lagi, seorang pria yang sangat <radikal>besar</radikal> dengan tangan terentang bagus dan besar. Kalau melihat radikal ini, berpikirlah besar saja, karena orang ini BESAR banget!', NULL, NULL),
  ('00000000-0000-4000-8000-000000000019', 'radical', '女', 'woman', 1, 13, 'Radikal ini terlihat seperti orang lebar yang terdiri dari dua huruf X yang bertumpuk. Wanita umumnya memiliki dua kromosom XX, dan dulu mereka dipuji karena pinggul mereka yang lebar dan dapat melahirkan anak. Kita mungkin tidak lagi menganggap perempuan seperti itu lagi, tapi dulu ketika Jepang masih ada, hal ini membuat mereka berpikir tentang <radikal>perempuan</radikal>.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000020', 'radical', '山', 'mountain', 1, 16, 'Ini adalah <radikal>gunung</radikal>. Anda harus menambahkan garis-garis yang membentuk puncak gunung jika ingin lebih "seperti gunung". Juga sesuatu yang mungkin bisa membantu: terkadang gunung memiliki beberapa puncak kecil yang juga muncul di sisi puncak utama. Hubungkan titik-titiknya dan ciptakan gunung dalam pikiran Anda.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000021', 'radical', '川', 'river', 1, 17, 'Radikal ini sudah tampak seperti <radikal>sungai</radikal>. Lihat tepian sungai di samping dan aliran sungai di tengah? Bahkan ada sedikit belokan di sungai juga. Jadi ketika Anda melihat radikal ini, Anda harus berpikir "sungai".', NULL, NULL),
  ('00000000-0000-4000-8000-000000000022', 'radical', '日', 'sun', 1, 23, 'Karena tidak ada lingkaran dalam karakter Jepang, terkadang persegi panjang atau persegi harus digunakan. Dalam hal ini, persegi panjang besar ini adalah <radical>matahari</radikal>. Garis tengah yang melalui pusat secara horizontal adalah garis khatulistiwa. Atau mungkin itu awan yang bergerak melintasi matahari. Bayangkan saja, tapi jangan menatap matahari dan membuat mata Anda terbakar!', NULL, NULL),
  ('00000000-0000-4000-8000-000000000023', 'radical', '木', 'tree', 1, 18, 'Apakah Anda melihat <radical>pohon</radical> di sini? Ia memiliki cabang-cabang, dan dedaunannya turun secara diagonal, menyebar seperti pohon. Itu sebabnya radikal ini adalah sebuah pohon.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000024', 'radical', '刀', 'sword', 2, 1, 'Jika Anda melihat radikal ini, ia tampak seperti bagian bawah sebuah <radikal>pedang</radikal>—lebih khusus lagi gagangnya. Radikal ini juga sangat mirip dengan radikal kekuasaan (<ja>力</ja>), jadi jangan bingung. Tidak ada inti kecil di atas, karena 90% kekuatan berasal dari pedang untuk menebas musuh Anda (itulah sebabnya radikal pedang adalah 90% dari radikal kekuatan).', NULL, NULL),
  ('00000000-0000-4000-8000-000000000025', 'radical', '工', 'construction', 1, 19, 'Anda tahu balok baja besar yang digunakan untuk rangka bangunan besar? Ini seperti akhir dari salah satu dari itu, dan mempunyai bentuk yang sangat berbeda, sama seperti radikal ini. Balok-balok ini digunakan dalam konstruksi, itulah sebabnya kata radikal ini berarti <radikal>konstruksi</radikal>. Lucunya, Anda menggunakan balok-balok ini untuk menyusun bangunan seperti Anda akan menggunakan radikal ini untuk menyusun kanji!', NULL, NULL),
  ('00000000-0000-4000-8000-000000000026', 'radical', 'ナ', 'narwhal', 2, 2, 'Radikal ini terlihat seperti karakter katakana <ja>ナ</ja> (na), yang akan kita sebut sebagai singkatan dari <radical>narwhal</radical>. Ditambah lagi, jenis radikal ini terlihat seperti narwhal, bukan? Tubuh dan kepala di bawah, dan satu tanduk narwhal yang megah muncul di atas, melesat keluar dari air dan ke udara. Oh, dan jangan bingung membedakan radikal ini dengan harta karun. Garis samping untuk narwhal (<ja>ナ</ja>) berbentuk horizontal, garis samping untuk harta karun lebih mengarah ke bawah (<ja>メ</ja>), seperti tanda "X".', NULL, NULL),
  ('00000000-0000-4000-8000-000000000027', 'radical', '丁', 'street', 2, 3, 'Ada duri di bawah tanah, menahannya di tempatnya. Ini sebenarnya adalah <radical>jalan</radikal>. Semua jalan harus diamankan ke tanah dengan duri agar tidak tergelincir ke mana-mana. Jika Anda mencoba memperbaiki jalanan aspal yang kita miliki saat ini, Anda masih akan menemukan duri di bawah tanah untuk menahannya. Semakin banyak Anda tahu! ⭐', NULL, NULL),
  ('00000000-0000-4000-8000-000000000028', 'radical', '儿', 'legs', 2, 4, 'Radikal ini sudah tampak seperti sepasang <radikal>kaki</radikal>. Bahkan ada kaki di kaki ini (tidak seperti sirip radikal yang Anda pelajari sebelumnya). Begitulah cara Anda mengetahui bahwa ini adalah kaki dan bukan sirip (atau yang lainnya).', NULL, NULL),
  ('00000000-0000-4000-8000-000000000029', 'radical', '冂', 'head', 2, 5, 'Ini adalah jenis <radikal>kepala</radikal> yang mungkin digambar oleh seorang anak—dapatkah Anda membayangkannya dengan mata, hidung, mulut, dan telinga juga? Siapapun yang kepalanya ini, bentuknya persegi banget. Mungkin itu adalah kepala dari <a href="https://en.wikipedia.org/wiki/SpongeBob_SquarePants_(character)" target="_blank">karakter kartun spons yang terkenal</a>. Hmm.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000030', 'radical', '又', 'stool', 2, 6, 'Ini tampak seperti <radical>bangku</radikal> yang dapat dilipat, bukan?', NULL, NULL),
  ('00000000-0000-4000-8000-000000000031', 'radical', 'メ', 'treasure', 2, 7, 'Radikal ini adalah <radikal>harta</radikal> karena "X menandai titiknya", demikian kata mereka. Bukankah ini terlihat seperti tanda X pada peta harta karun bajak laut? Kamu ingin mencari harta karun itu sekarang, kan?!', NULL, NULL),
  ('00000000-0000-4000-8000-000000000032', 'radical', '千', 'thousand', 2, 8, 'Anda berada di sebuah ruangan, dikelilingi oleh perosotan. Turun dari perosotan berjatuhan salib demi salib demi salib. Mereka memantul dan memukul wajah Anda, lengan, di mana-mana... Dengan setiap umpan silang terdengar suara yang berteriak, "SATU! DUA! TIGA RATUS! LIMA RATUS!" dan sebagainya. Anda khawatir hal itu tidak akan pernah berakhir, karena Anda mulai tenggelam dalam salib. Kemudian suara itu meneriakkan SATU <radikal>RIBU</radikal> dan mereka berhenti. Tetap saja, kamu tidak bisa bergerak. Pikirkan tentang semua nomor yang dipanggil, dan teruslah bertanya-tanya apakah itu nomor terakhir. Rasakan kelegaan yang akan kamu rasakan jika berhenti di angka seribu, karena kamu tidak akan terkubur lagi. Seribu salib menutupi seluruh tubuhmu, menutupi kepalamu, tapi karena itu salib, kamu masih bisa bernapas.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000033', 'radical', '夕', 'evening', 2, 9, 'Apakah Anda melihat penjara dan drop radikal yang mengarang radikal ini? Penjara ini menahan jatuhnya karena ini <radikal>malam</radikal>. Udara malam bekerja lebih baik dalam menahan tetesan cairan seperti ini, itulah sebabnya semuanya tertutup embun di pagi hari.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000034', 'radical', '子', 'child', 2, 10, 'Radikal ini terdiri dari dua duri dan satu radikal dasar. Jika terdapat duri di tanah, siapa (terutama) yang ingin Anda hindari di area tersebut? Anda ingin <radikal>anak</radikal> Anda menghindarinya, karena anak-anak sangat ceroboh dan sering tidak memakai sepatu. Bayangkan betapa buruknya perasaan Anda jika Anda membiarkan seorang anak berjalan-jalan di atas duri-duri ini! Cukup buruk, menurutku.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000035', 'radical', '小', 'small', 2, 11, 'Anda memiliki sirip dan Anda memiliki duri. Ikan yang durinya bisa ditusukkan seluruhnya seperti ini harus benar-benar <radikal>kecil</radikal>, karena duri tersebut menembus seluruh tubuh ikan (yang dapat Anda bayangkan dengan mendasarkan tubuhnya pada ukuran sirip dibandingkan dengan duri yang sudah kecil.)', NULL, NULL),
  ('00000000-0000-4000-8000-000000000036', 'radical', '弓', 'bow', 2, 12, 'Radikal ini terlihat seperti <radikal>busur</radikal> komposit mewah yang digunakan orang untuk menembak sasaran dan jelas bukan hewan hidup normal. Lihat bagaimana bagian tengahnya ditarik ke belakang? Bayangkan memegang busur ini dan menembakkannya ke sasaran berbentuk monster kepiting aligator raksasa.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000037', 'radical', '尸', 'flag', 2, 13, 'Lihat <radical>bendera</radikal> di radikal ini? Ada sebuah tiang dengan bendera di ujungnya, tertiup angin. Pada dasarnya, radikal ini terlihat seperti sebuah bendera.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000038', 'radical', '彡', 'hair', 2, 14, 'Tiga helai rambut yang mengalir ke samping ini adalah tiga helai rambut. Cukup mudah untuk dilihat dan diingat, bukan?', NULL, NULL),
  ('00000000-0000-4000-8000-000000000039', 'radical', '五', 'five', 2, 15, 'Jika Anda menggunakan imajinasi Anda, radikal ini sebenarnya terlihat seperti angka "5". Anda harus menghapus garis vertikal di kiri bawah, tetapi setelah Anda melakukannya, Anda memiliki cara mudah untuk mengingat bahwa radikal ini berarti <radikal>lima</radikal>.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000040', 'radical', '天', 'heaven', 2, 16, 'Ada dua orang radikal dan satu orang radikal. Tingkat pertama kehidupan seseorang adalah di bumi. Tingkat kedua (tingkat ini, itulah sebabnya ada dua radikal di sini) ada di surga. Jadi ketika Anda melihat seseorang di level 2, Anda tahu dia ada di <radical>surga</radical>.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000041', 'radical', '手', 'hand', 2, 17, 'Yang ini agak sulit untuk dibayangkan, tapi aku percaya padamu. Duri di tengah adalah pergelangan tangan/lengan. Lalu, ada empat jari biasa yang keluar dan satu ibu jari besar (slide radikal di atas). Jadi Anda memiliki empat jari, satu ibu jari, dan satu pergelangan tangan. Inilah yang membuat <radikal>tangan</radikal> Anda tampak gila.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000042', 'radical', '文', 'writing', 2, 18, 'Bentuknya seperti bangku dengan penutup, namun sebenarnya ini adalah meja <radikal>tulis</radikal>. Apakah kamu melihatnya? Ini tempat yang bagus dan tenang untuk menulis. Anda bahkan dapat melihat pena mencuat di tengah. Tidakkah Anda ingin menulis di sini?', NULL, NULL),
  ('00000000-0000-4000-8000-000000000043', 'radical', '月', 'moon', 2, 19, '<radikal>bulan</radikal> sebenarnya terbuat dari matahari, namun memiliki kaki-kaki kecil yang condong ke kiri. Mengapa? Karena bulan selalu menjauhi matahari secepat mungkin. Ia tidak ingin terbakar, jadi ia harus berlari agar tetap berada di depan!', NULL, NULL),
  ('00000000-0000-4000-8000-000000000044', 'radical', '止', 'stop', 2, 20, 'Ada jari kaki raksasa dan tongkat di tanah di depan Anda. Anda mengendarai mobil Anda ke arah mereka, tetapi Anda tidak melihatnya sampai lampu Anda menyinari mereka. Hal-hal ini menyebabkan Anda melakukan apa? Kemungkinan besar <radical>menghentikan</radical> mobil Anda segera.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000045', 'radical', '水', 'water', 2, 21, 'Ada tetesan cairan yang keluar dari kedua sisi duri ini. Bisa dibayangkan durinya ditancapkan ke tanah lalu dicabut. Saat itu terjadi, <radical>air</radical> keluar dari kedua sisi! Itu sebabnya radikal ini adalah air.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000046', 'radical', '火', 'fire', 2, 22, 'Lihat orang radikal di sini? Ada sesuatu yang keluar darinya... benda apa itu—YA TUHAN ITU <radikal>API</radikal>!!! Tolong tolong! Padamkan apinya!', NULL, NULL),
  ('00000000-0000-4000-8000-000000000047', 'radical', '犬', 'dog', 2, 23, 'Ingat orang besar yang membantu Anda mengingat orang radikal besar? Sekarang lelaki besar itu mempunyai sesuatu di bahunya... apa itu? Anda melihat dan melihat bahwa dia memiliki seekor <radical>anjing</radical> di atas sana, bertengger seolah-olah itu adalah burung beo atau kucing atau semacamnya. Anjing tidak seharusnya berada di pundak orang seperti itu, tapi untuk dia? Itu berhasil!', NULL, NULL),
  ('00000000-0000-4000-8000-000000000048', 'radical', '王', 'king', 2, 24, 'Radikal ini bukanlah sesuatu yang bisa dimiliki oleh siapa pun. Hanya seorang <radikal>raja</radikal> yang dapat memakai mahkota ini di kepalanya. Radikal ini adalah tanda raja. Bayangkan raja favorit Anda memakai ini di kepala mereka. Bentuknya cukup khas—saya rasa Anda bisa melakukannya.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000049', 'radical', '中', 'middle', 2, 25, 'Ada sebatang tongkat menembus <radikal>tengah</radikal> mulut seseorang! Bayangkan mulut itu menjadi milik Anda. Ukur penempatan tongkat. Sejajar sempurna, tepat di tengah. Itu luar biasa, meski sejujurnya, Anda mungkin menghadapi masalah yang lebih besar daripada mengukur lokasi tongkat ini di mulut Anda.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000050', 'radical', '本', 'book', 2, 26, 'Ada potongan tepat di pangkal pohon ini. Mengapa seseorang menebang pohon? Untuk membuat <radikal>buku</radikal> darinya! Bayangkan hidup di masa lalu ketika Anda harus menebang pohon sendiri untuk menulis atau membaca buku.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000051', 'radical', '田', 'rice-paddy', 2, 27, 'Sawah terdiri dari ladang-ladang dengan saluran irigasi di antara keduanya. Lihat empat sawah dengan air mengalir di antara dan di sekitarnya? Itu sebabnya radikal ini adalah <radical>padi</radikal>.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000052', 'radical', '白', 'white', 2, 28, 'Tambahkan setetes matahari pada sesuatu dan itu akan mengubahnya menjadi <radikal>putih</radikal>. Matahari sangat terik, bahkan setetes pun bisa membakar apa pun yang putih. Menurut Anda mengapa banyak pantai berwarna putih? Bahkan tetes tabir surya yang Anda gunakan untuk menghentikan sinar matahari pun berwarna putih. Jadi ketika Anda memikirkan tetesan matahari, pikirkanlah putih.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000053', 'radical', '目', 'eye', 2, 29, 'Lihat iris di tengah bola mata? Ingatlah bahwa tidak ada benda bulat dalam kanji, jadi benda persegilah yang menggantikannya. Hal ini membuat <radical>mata</radikal> persegi ini cukup realistis. Anda hanya perlu sedikit menyipitkan mata dengan mata asli Anda.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000054', 'radical', '石', 'stone', 2, 30, 'Ada daun yang tumbuh dari benda persegi (biasanya berupa mulut, tapi kali ini tidak). Daunnya tumbuh dari <radikal>batu</radikal>. Maksudku, tentu saja, karena daun tidak tumbuh dari mulut. Saya harap. Bayangkan sebuah batu di tengah alam dengan daun yang tumbuh di atasnya atau tepat di belakangnya dan Anda tidak akan pernah melupakan hal radikal ini!', NULL, NULL),
  ('00000000-0000-4000-8000-000000000055', 'radical', '立', 'stand', 2, 31, 'Dua batang kayu menopang tutupnya. Dengan melakukan hal ini, mereka membuat <radikal>berdiri</radikal>.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000056', 'radical', 'L', 'lion', 6, 0, 'Radikal berbentuk L ini adalah radikal <radikal>singa</radikal>, karena "L berarti Singa". Ini juga terlihat seperti mulut singa yang terbuka sangat-sangat lebar. Bayangkan seekor singa membuka mulutnya untuk menguap. Sepertinya ini radikal!', NULL, NULL),
  ('00000000-0000-4000-8000-000000000057', 'radical', '匕', 'spoon', 3, 0, 'Radikal ini tampak seperti <radical>sendok</radikal>! Nah, sendok yang banyak dibengkokkan oleh orang yang sedang marah atau paranormal. Ambil sendok dan coba tekuk menjadi bentuk ini. Kemudian peganglah agar Anda tidak pernah lupa bahwa ini adalah sendok radikal!', NULL, NULL),
  ('00000000-0000-4000-8000-000000000058', 'radical', 'ラ', 'ra-58', 3, 0, 'Radikal ini terlihat seperti karakter katakana "ra" (ラ). Bunyi "ra" juga terdengar seperti Dewa Mesir yang terkenal "Ra", jadi kita dapat mengatakan bahwa kata radikal ini melambangkan Dewa Ra di Mesir.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000059', 'radical', '久', 'raptor-cage-59', 3, 0, 'Ini bukan kandang biasa. Ini adalah selungkup dengan penguatan tambahan (lihat itu mencuat di kanan bawah selungkup radikal?). Mengapa selungkup ini diperkuat? Karena itu kandang raptor. Aku bertanya-tanya berapa lama mereka bisa menahan raptor... Itu tidak berjalan dengan baik di Jurassic Park...', NULL, NULL),
  ('00000000-0000-4000-8000-000000000060', 'radical', '夂', 'winter', 3, 1, 'Radikal ini terlihat seperti radikal malam tetapi memiliki pukulan yang ekstra panjang. Hal ini karena malam hari merupakan waktu yang panjang di <radical>musim dingin</radical>. Hari mulai gelap.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000061', 'radical', '干', 'dry', 3, 2, 'Anda memiliki dua tongkat. Dua apa? Ya, Anda tidak bisa membedakannya karena terlalu <radikal>kering</radikal>. Seseorang menaruh dua benda pada tongkat ini hingga kering, tapi sepertinya mereka sudah terlalu lama membiarkannya. Apakah itu daging? Ikan? Mentimun? Anda tidak tahu, tapi itu dua hal yang sangat kering, itu sudah pasti.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000062', 'radical', '广', 'canopy', 3, 3, 'Ini adalah <radical>kanopi</radikal>. Lihat kainnya menjuntai ke bawah dan ujung kecil di tengahnya menahannya? Anda bisa duduk di bawah sini dan menikmati hari musim panas yang cerah tanpa terkena sinar matahari!', NULL, NULL),
  ('00000000-0000-4000-8000-000000000063', 'radical', '扌', 'fingers', 3, 4, 'Ini tampak seperti tangan (<ja>手</ja>) yang radikal, namun lebih kecil. Itu karena itu hanya <radical>jari</radical>. Anda tidak selalu memiliki ruang untuk seluruh tangan untuk menulis kanji, tetapi selalu ada ruang untuk beberapa jari.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000064', 'radical', '元', 'origin', 3, 5, 'Anda memiliki dua kaki yang membentuk radikal ini. Di antara dua kaki adalah tempat asalmu, tidak peduli bagaimana kamu melihatnya. Kedua kaki ini adalah <radikal>asal</radikal> Anda.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000065', 'radical', '心', 'heart', 3, 6, 'Perhatikan baik-baik yang ini. Bentuknya seperti <radikal>hati</radikal> (namun, bukan hati pada Hari Valentine pada umumnya). Pikirkan hati yang nyata. Pada dasarnya, terdapat benjolan (jantung) di tengahnya, dan tiga garis yang membentuk arteri yang masuk dan keluar dari jantung untuk membuat Anda tetap hidup. Radikal ini sering muncul, jadi tidak akan terlalu sulit untuk mempelajarinya seiring berjalannya waktu. Ingat, benjolan (jantung) ditambah pembuluh darah sama dengan jantung… seperti, jantung asli, bukan palsu, cantik.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000066', 'radical', '方', 'direction', 3, 7, 'Radikal ini terlihat seperti pria yang lari ke kanan. Dia sedang menuju ke <radikal>arah</radikal> yang sangat berbeda. Ke arah mana lagi?', NULL, NULL),
  ('00000000-0000-4000-8000-000000000067', 'radical', '毛', 'fur', 3, 8, 'Apakah Anda ingat radikal rambut? Begitulah, hanya saja sekarang rambutnya menempel di ekor. Namun, hewan biasanya tidak memiliki rambut. Sebaliknya, mereka mempunyai bulu.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000068', 'radical', '父', 'father', 3, 9, 'Terdapat sirip yang menutupi harta penyusun radikal ini. Anda menarik siripnya dan mulai menggali di mana letak X (karena "X" menandai di mana harta karun itu berada, bukan?). Saat Anda menggali, alih-alih menemukan harta karun, Anda malah menemukan <radikal>ayah</radikal> Anda. Kejutan dalam imajinasi Anda akan membantu Anda mengingat makna radikal ini!', NULL, NULL),
  ('00000000-0000-4000-8000-000000000069', 'radical', '古', 'old', 3, 10, 'Mulutmu berbentuk salib—mulut itu cukup religius. Siapa yang paling banyak berbicara tentang agama? <radikal>Tua</radikal> kebanyakan. Juga, pikirkan tentang ajaran agama itu sendiri - juga cukup tua, berdasarkan usia. Tidak peduli bagaimana Anda melihatnya, segala sesuatu tentang radikal ini sudah “kuno”.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000070', 'radical', '母', 'drawer-70', 3, 0, 'Lihat <radical>laci</radical>? Ada dua rak di dalamnya dengan pegangan nubbin kecil di masing-masing rak agar Anda dapat menariknya keluar. Bayangkan menggunakan laci ini - bentuknya sangat aneh.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000071', 'radical', '用', 'task', 3, 11, 'Ini terlihat seperti kalender dengan ruang untuk Anda tuliskan dalam <radical>tugas</radikal> Anda untuk hari itu. Lihat bagian kosong itu? Pastikan Anda menuliskan tugas harian Anda, agar tidak lupa melakukan sesuatu yang penting!', NULL, NULL),
  ('00000000-0000-4000-8000-000000000072', 'radical', '矢', 'arrow', 3, 12, 'Anda memiliki senjata yang sangat besar. Mengapa? Karena hanya senjata besar yang mampu menembakkan <radikal>panah</radikal>! Pelurunya cukup kecil, jadi senjata yang menembakkannya bisa berukuran berapa pun. Namun Anda membutuhkan senjata yang besar jika Anda ingin memasukkan anak panah ke dalamnya dan kemudian menembakkannya ke musuh Anda.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000073', 'radical', '戸', 'door', 3, 13, 'Kemana biasanya sebuah bendera dibawa? Itu melewati sebuah pintu. Saya tahu radikal 一 biasanya berarti tanah, tetapi dalam kasus ini kita akan mengatakan benderanya ada di ambang pintu (di mana 一 adalah bagian atas pintu).', NULL, NULL),
  ('00000000-0000-4000-8000-000000000074', 'radical', '寸', 'measurement', 4, 0, 'Pernahkah Anda menggunakan salah satu kompas matematika itu? Ini terlihat seperti salah satunya karena ini adalah radikal <radikal>pengukuran</radikal>. Kompas digunakan untuk mengukur sesuatu, seperti ini.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000075', 'radical', 'ｲ', 'leader', 4, 1, 'Kata radikal ini secara teknis berarti orang (seperti <ja>人</ja>), namun kita akan mengubah maknanya sedikit. Ini seperti orang radikal, tapi lebih tinggi dan lebih kurus, berdiri di atas prajurit infanteri lainnya. Itu sebabnya dia adalah <radikal>pemimpin</radikal>, bukan orang tua biasa.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000076', 'radical', '冖', 'forehead', 4, 2, 'Tentu saja, <radikal>dahi</radikal> ini agak persegi, tapi itu karena itu adalah dahi Monster Frankenstein. Juga, apakah Anda memperhatikan bahwa ini hanyalah bagian atas kepala (<ja>冂</ja>) yang radikal? Ini hanya bagian dahi saja!', NULL, NULL),
  ('00000000-0000-4000-8000-000000000077', 'radical', '也', 'alligator', 4, 3, 'Lihat mulut dan gigi <radical>buaya</radical> ini yang menghadap ke kanan? Anda tidak ingin tangan Anda tersangkut di sana, itu sudah pasti.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000078', 'radical', '宀', 'roof', 4, 4, 'Ini adalah <radikal>atap</radikal>. Anda tahu itu atap dan bukan dahi karena ada cerobong kecil yang mencuat dari atasnya. Dan dahi pastinya tidak mempunyai cerobong asap.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000079', 'radical', '弋', 'ceremony', 4, 5, 'Radikal ini terlihat seperti orang dengan gaun panjang atau kereta api yang berjalan di belakangnya. Itu karena calon pengantin akan menghadiri <radikal>upacara</radikal> pernikahan mereka! Biasanya Anda harus mengenakan gaun panjang atau jubah jika berada di sebuah upacara. Jadi ketika Anda melihat hal radikal ini, pikirkan semua upacara berbeda yang mungkin harus Anda hadiri dalam hidup Anda dan apa yang perlu Anda kenakan.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000080', 'radical', 'ネ', 'spirit', 4, 6, 'Ini terlihat seperti karakter katakana untuk ne. Bukan untuk ahli nujum! Itu menjadikannya <radikal>roh</radikal>, yang dibangkitkan dari kubur. OooooOOooooOoo!', NULL, NULL),
  ('00000000-0000-4000-8000-000000000081', 'radical', '支', 'branch', 4, 7, 'Ada salib yang tumbuh dari bangku ini. Itu bercabang, jika Anda mau. Pohon tempat bangku ini dibuat hidup kembali dalam bentuk dahan.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000082', 'radical', '气', 'energy', 4, 8, 'Radikal ini bentuknya seperti bendungan. Lihat tembok dan air mendorong dari atas? Jika radikal ini adalah sebuah bendungan, maka ia harus menciptakan banyak <radikal>energi</radikal> juga!', NULL, NULL),
  ('00000000-0000-4000-8000-000000000083', 'radical', '世', 'world', 4, 9, 'Tidak ada lingkaran dalam kanji, ingat? Jadi bayangkan sudut-sudut ini benar-benar berbentuk lingkaran. Lingkaran kecil dalam lingkaran besar, dengan garis melewatinya. Ya, itulah <radikal>dunia</radikal>. Dunia terlihat seperti ini, dengan benua di dunia dan sebuah garis adalah garis khatulistiwa. Bisakah kamu melihatnya?', NULL, NULL),
  ('00000000-0000-4000-8000-000000000084', 'radical', '皿', 'plate', 4, 10, 'Ini adalah beberapa piring yang dikeringkan di rak. Mereka ditumpuk dalam satu baris. Bayangkan mengulurkan tangan dan mengambil salah satu piring itu untuk Anda sendiri.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000085', 'radical', '竹', 'bamboo', 4, 11, 'Lihat seberapa tinggi batangnya dengan tanaman kecil yang lebat di bagian atasnya? Ini terlihat seperti <radical>bambu</radical>, jika Anda menggunakan imajinasi Anda.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000086', 'radical', '糸', 'thread', 4, 12, 'Ada sesuatu yang kecil di beberapa kotoran. Anda mencondongkan tubuh ke dalam, menariknya keluar dengan hati-hati, dan menyadari bahwa itu adalah <radikal>utas</radikal>. Mengapa ada benang di kotoran kecil ini? Karena itu kotoran kucing. Dan kucing suka memakan benang saat Anda tidak melihat. Dan benang benang, tali hoodie, dan ekor tikus. Tapi kotoran ini hanya ada benang di dalamnya.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000087', 'radical', '幺', 'poop', 3, 14, 'Ada sesuatu yang menonjol dari diri Anda saat Anda sendirian. Itu <radikal>kotoran</radikal>! Anda tidak bisa buang air besar begitu saja di depan umum, itu ilegal dan menjijikkan di zaman sekarang ini. Jadi jika lain kali sesuatu mulai keluar dari diri Anda saat Anda sedang sendirian, pikirkan, "Ah ya, itu kotoran."', NULL, NULL),
  ('00000000-0000-4000-8000-000000000088', 'radical', '耳', 'ear', 4, 13, 'Radikal ini sedikit lebih rumit daripada mata, meski serupa. Faktanya, jika Anda menjadi buta, <radical>telinga</radical> Anda menjadi salah satu indra penglihatan Anda yang baru, itulah sebabnya mengapa ini seperti mata lain yang agak dimodifikasi. Anda bahkan akan melihat garis-garis kecil menonjol dari mata. Itu karena telinga lebih menonjol dibandingkan mata (<ja>目</ja>), itulah sebabnya radikal ini disebut radikal telinga.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000089', 'radical', '虫', 'insect', 4, 14, 'Ada sesuatu yang pribadi di mulutmu. Anda merahasiakannya karena Anda tidak ingin orang lain menghakimi Anda. Mengapa? Karena itu adalah <radikal>serangga</radikal>. Anda suka makan serangga, tetapi masyarakat sepertinya menganggapnya salah. Jangan khawatir, teman. Suatu hari nanti seluruh dunia akan menerima makan serangga seperti Anda.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000090', 'radical', '艹', 'flowers', 4, 15, 'Lihat hal-hal kecil yang mencuat dari tanah? Hal-hal kecil itu adalah <radikal>bunga</radikal> yang cantik. Anda tahu itu bunga dan bukan, katakanlah, rumput, karena letaknya di luar. Anda akan mempelajari rumput nanti, dan jaraknya akan lebih sedikit, tetapi agak mirip dengan ini, jadi ingatlah itu!', NULL, NULL),
  ('00000000-0000-4000-8000-000000000091', 'radical', '見', 'see', 4, 16, 'Ada bola mata di atas beberapa kaki. Ketika mata Anda tertuju pada suatu tempat (dalam hal ini pada kaki), mata Anda <radikal>melihat</radikal> hal-hal tersebut. Itu sebabnya cara radikal ini lihat.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000092', 'radical', '赤', 'red', 4, 17, 'Ada beberapa kaki dan sirip di bawah tanah. Bayangkan diri Anda melihat semua anggota tubuh yang terputus ini... ada darah di mana-mana. Tidak peduli seberapa dalam Anda menggali, semuanya berwarna <radikal>merah</radikal>.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000093', 'radical', '車', 'car', 4, 18, 'Bukankah ini terlihat seperti tampilan bingkai <radical>mobil</radical> dari atas ke bawah? Ada batang-batang yang menjadi alas mobil dan benda-benda yang menggerakkan roda. Itu sebabnya radikal ini adalah radikal mobil.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000094', 'radical', '貝', 'shellfish', 4, 19, 'Ada mata raksasa di atas beberapa sirip. Bayangkan mata raksasa ini berada di atas kerang atau remis. Ia mempunyai sirip-sirip kecil, yang berfungsi sebagai tempat berjalannya, menghindari setiap upaya Anda untuk menangkapnya. Itu sebabnya ini disebut radikal <radikal>kerang</radikal>.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000095', 'radical', '足', 'foot', 4, 20, 'Apakah Anda melihat pria itu melakukan tendangan naga terbang ke kanan? Dengan apa dia mencapai target? Jelas sekali itu adalah <radical>kaki</radical> miliknya.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000096', 'radical', '不', 'not', 4, 21, 'Jika Anda melihat radikal ini dalam sebuah kanji, Anda pasti ingin memikirkan kebalikan dari radikal apa pun yang ada. Kelihatannya sangat mirip "di bawah", tapi coba tebak? Ini <radikal>bukan</radikal> yang di bawah radikal. Hanya saja tidak.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000097', 'radical', '士', 'samurai', 4, 22, 'Radikal <radikal>samurai</radikal> sangat mirip dengan radikal tanah. Perbedaannya terletak pada garis horizontal atas. Bagi samurai, atasannya lebih panjang karena dia memegang pedang. Kotoran tidak dapat menampung apa pun karena lengannya terlalu pendek. Jadi ketika Anda melihat hal radikal ini, pikirkan: lengan panjang sama dengan pedang panjang. Itu seorang samurai!', NULL, NULL),
  ('00000000-0000-4000-8000-000000000098', 'radical', '米', 'rice', 4, 23, 'Jangan bingung dengan sawah (<ja>田</ja>). Ini hanyalah <radikal>beras</radikal> mentah, seperti biji-bijian yang tumbuh dari tanah ketika beras masih mentah dan segar. Jika nasi sudah sangat matang, bagian atas batangnya akan terlihat seperti ini. Lihat daunnya yang panjang dengan sedikit jumbai nasi di atasnya? Itu sebabnya radikal ini disebut "beras".', NULL, NULL),
  ('00000000-0000-4000-8000-000000000099', 'radical', '彳', 'loiter', 4, 24, 'Pemimpin (<ja>ｲ</ja>) yang radikal memiliki sesuatu yang ekstra di atas dirinya, menahannya, menahannya. Itu menyebabkan dia menunggu... itu menyebabkan dia <radikal>berkeliaran</radikal>.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000100', 'radical', '巴', 'bed', 4, 25, 'Anda harus menyelesaikan garis di sisi kanan dalam pikiran Anda, tetapi lihat tempat tidur persegi panjang dan bantal? Ini benar-benar sebuah tempat tidur. Garis yang hilang itu adalah tempat Anda menarik kembali seprai ketika Anda bangun pagi ini.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000101', 'radical', '兀', 'pi', 4, 26, 'Tentu saja, ini tampak seperti sesuatu yang bagus di versi 3.14, sesuatu yang seharusnya dipelajari oleh semua orang. Itu simbol matematika yang ada hubungannya dengan lingkaran... pi!', NULL, NULL),
  ('00000000-0000-4000-8000-000000000102', 'radical', '巾', 'towel', 3, 15, 'Ada sesuatu yang menutupi tongkat itu. Itu adalah <radikal>handuk!</radikal>! Bayangkan mengambil handuk basah dan menggantungnya di pagar atau tongkat agar tidak pengap dan kotor. Ini akan terlihat seperti ini.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000103', 'radical', '氵', 'tsunami', 5, 0, 'Kamu pernah melihat satu tetes (<ja>丶</ja>), tapi apa yang terjadi jika kamu melipatgandakannya dan mendapat tiga tetes, yang merupakan jumlah maksimum tetes yang bisa kamu dapatkan? Anda akan mengalami <radikal>tsunami</radikal> yang menghancurkan, karena terlalu banyak air dan tidak ada tempat untuk mengalirkannya. Anggap saja ini sebagai banyak air. Ketika Anda memiliki banyak air, Anda mengalami tsunami.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000104', 'radical', '耂', 'coffin', 5, 1, 'Lihat slidenya masuk ke tanah? Di situlah mereka membuang tubuhmu saat kamu mati. Ini sebenarnya adalah <radical>peti mati</radikal>!', NULL, NULL),
  ('00000000-0000-4000-8000-000000000105', 'radical', 'ヨ', 'wolverine', 5, 2, 'Anda tahu <radical>Wolverine</radical> dari X-Men? Dia memiliki tiga cakar yang keluar dari tangannya kapan pun dia perlu bertarung, sama sekali tidak berbeda dengan radikal yang Anda lihat di sini.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000106', 'radical', '廾', 'twenty', 5, 3, 'Anda memiliki 十 plus 十... apa yang Anda dapatkan jika Anda menambahkan kedua kanji ini bersama-sama? Anda mendapat dua puluh.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000107', 'radical', '毋', 'window', 5, 4, 'Lihat salib dalam bentuk persegi semu? Itu adalah bingkai <radical>jendela</radical> besar yang dapat Anda lihat ke luar. Bentuknya tidak sempurna seperti sawah, lebih artistik. Itu sebabnya ini adalah jendela dan <ja>田</ja> bukan.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000108', 'radical', '肉', 'meat', 5, 5, 'Di dalam kepala Anda, Anda hanya bisa memikirkan orang, orang, dan lebih banyak orang. Ini buruk, karena sebenarnya yang kamu inginkan hanyalah <radikal>daging</radikal> mereka, karena kamu adalah sejenis kanibal yang sakit... dasar monster. Ketika Anda memikirkan "orang" di kepala Anda, Anda sebenarnya hanya memikirkan tentang lebih banyak daging yang bisa Anda makan.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000109', 'radical', '自', 'self', 5, 6, 'Flek/tetesan kecil di matamu itulah yang membuatmu unik. Itulah yang menjadikan Anda <radikal>diri</radikal> Anda. Itu kamu, kamu tahu?', NULL, NULL),
  ('00000000-0000-4000-8000-000000000110', 'radical', '色', 'color', 5, 7, 'Tempat tidur yang Anda dapatkan di penjara adalah satu-satunya dengan <radikal>warna</radikal> yang akan Anda lihat saat berada di sana. Bayangkan sebuah sel yang gelap dan lembap. Mungkin toilet juga. Sekarang bayangkan tempat tidur yang cerah dan berwarna-warni menempel di dinding. Inilah satu-satunya kebahagiaan yang Anda miliki.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000111', 'radical', '行', 'go', 5, 8, 'Anda memiliki kata radikal untuk loiter, two, dan barb. Seseorang yang menggunakan dua duri pada Anda saat Anda berkeliaran benar-benar ingin Anda PERGI!! Ayo, berhenti berkeliaran di luar toko serba adaku, ya, anak-anak!', NULL, NULL),
  ('00000000-0000-4000-8000-000000000112', 'radical', '西', 'west', 5, 9, 'Anda memiliki pi yang keluar dari mulut. "3.14," katanya. Kita harus membawa rahasia lingkaran itu, menjauh dari sini. Kita harus pergi ke tempat ajaib di mana tak seorang pun akan menganiaya kita karena matematika kita... tempat di <radikal>Barat</radikal>!', NULL, NULL),
  ('00000000-0000-4000-8000-000000000113', 'radical', '可', 'lip-ring', 5, 10, 'Ada sesuatu yang ketagihan masuk ke dalam mulut. Namun, bukannya pengait, ini adalah <radical>cincin bibir</radical>. Mereka biasa menggunakan kail dan paku ikan di masa lalu. (Senang kita tidak hidup di masa itu lagi!)', NULL, NULL),
  ('00000000-0000-4000-8000-000000000114', 'radical', '⻌', 'scooter', 5, 11, 'Radikal ini adalah <radikal>skuter</radikal>. Lihat stang dan lampu kecilnya? Dan ada platform di bagian bawah tempat Anda dapat berdiri atau duduk (jika itu salah satu platform bermotor yang bagus).', NULL, NULL),
  ('00000000-0000-4000-8000-000000000115', 'radical', '斤', 'axe', 5, 12, 'Saya tahu, ini kapak yang tampak aneh. Tapi coba pikirkan seperti ini: huruf "T" ada di tebing. Apa itu "T"? Tentu saja harus Pak T yang super hebat. Bayangkan Tuan T yang memegang kapak yang menakutkan, berlari mengejar Anda sambil berteriak, "Kasihan sekali orang bodoh itu!" sambil mencoba menebasmu. Itu menghasilkan <radical>kapak</radikal> yang cukup menakutkan.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000116', 'radical', '厂', 'cliff', 4, 27, 'Lihat tebingnya? Itu menghadap ke arah barat. Laut apa yang ada di sebelah baratmu? Ke sanalah arah hadap tebing ini.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000117', 'radical', '言', 'say', 5, 13, 'Ada banyak gelombang suara yang keluar dari mulut. Gelombang tersebut mewakili hal-hal yang Anda <radikal>ucapkan</radikal>.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000118', 'radical', '金', 'gold', 5, 14, 'Ada dua set paku di bawah topi itu. Ini sebenarnya sebuah jebakan, untuk mencegah siapa pun masuk dan mencuri <radikal>emas</radikal> Anda. Kenapa lagi kamu membuat jebakan? Semua orang suka melindungi emas mereka.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000119', 'radical', '雨', 'rain', 5, 15, 'Handuknya basah oleh tetesan cairan. Itu karena sedang <radikal>hujan</radikal>. Bawalah handuk dan pakaian lain ke dalam sebelum basah kuyup karena hujan ini!', NULL, NULL),
  ('00000000-0000-4000-8000-000000000120', 'radical', '青', 'blue', 5, 16, 'Anda memiliki kehidupan di atas bulan (abaikan bahwa kehidupan tidak memiliki slide kecil di sisi kiri). Seperti apa kehidupan di bulan? Pertama-tama, mereka tidak memiliki udara, jadi mereka mungkin terlihat sangat <radikal>biru</radikal> karena sesak napas. Saat Anda bertemu mereka, ternyata Anda benar. Mereka adalah peradaban orang-orang biru. Bayangkan mereka semua tinggal di sana, berwarna biru dan Smurfy.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000121', 'radical', '冋', 'mustache', 5, 17, 'Lihat <radikal>kumis</radikal> di sekitar mulut? Saya berharap saya bisa menumbuhkan kumis manis seperti ini.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000122', 'radical', '乍', 'key', 5, 18, 'Ini adalah <radical>kunci</radikal> yang bentuknya sangat aneh, namun tetap saja ini adalah kunci.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000123', 'radical', '冫', 'ice', 5, 19, 'Ingat kata radikal untuk setetes (cairan)? Ini adalah dua tetes, bukan satu. Saat Anda melihat dua tetes, Anda harus berpikir, "tahap air selanjutnya". Apa tahap selanjutnya? Wah, itu <radikal>es</radikal>.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000124', 'radical', '走', 'run', 5, 20, 'Lihat orang yang <radikal>berlari</radikal>ning? Namun, jangan bingung membedakannya dengan kaki (<ja>足</ja>). Kepalanya hanya terbentur karena orang ini larinya kencang sekali.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000125', 'radical', '里', 'village', 5, 21, 'Ini adalah sawah dengan tanah di sekitarnya. Ini adalah tempat yang tepat untuk mendirikan <radical>desa</radical>. Anda memiliki tempat untuk bertani dan tanah untuk ditinggali. Apa lagi yang Anda perlukan?', NULL, NULL),
  ('00000000-0000-4000-8000-000000000126', 'radical', '牛', 'cow', 2, 32, 'Ada salib dan pistol, dengan pistol menembus salib. Anda menggunakan salib untuk menstabilkan senjata Anda, karena Anda harus menembak <radikal>sapi</radikal> untuk makan malam. Anda membawa salib Anda karena Anda perlu memberkati sapi itu setelah Anda membunuhnya (dan itu juga merupakan tempat yang baik untuk senjata Anda). Sapi yang malang.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000127', 'radical', '凵', 'box', 6, 0, '<radikal>kotak</radikal> ini terbuka. Mungkin ada banyak hal di dalamnya, tetapi untuk saat ini yang perlu Anda ketahui hanyalah arti dari kata radikal ini, yaitu kotak.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000128', 'radical', '刂', 'knife', 6, 0, 'Ini adalah <radikal>pisau</radikal>. Lihat bagaimana ia memiliki dua sisi yang tajam? Dan ada pegangan kecil di bagian bawah untuk... yah pegangannya. Hati-hati jangan sampai melukai diri sendiri!', NULL, NULL),
  ('00000000-0000-4000-8000-000000000129', 'radical', '斗', 'ladle', 6, 0, 'Ada <radical>sendok</radikal> yang menyendok dua tetes cairan. Lihat bagian gagang dan sendok sendoknya? Bayangkan menyendok air ke dalam mulut Anda. MM.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000130', 'radical', 'ホ', 'angel', 6, 0, 'Pertama, ada tanda silang di tengah, yang otomatis menjadikan ini radikal berbasis agama. Salib itu adalah kerangka tubuh seseorang dan yang keluar darinya adalah sayap. Ini adalah <radikal>malaikat</radikal>.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000131', 'radical', '灬', 'boil', 6, 0, 'Radikal ini terlihat seperti api dari kompor atau uap yang keluar dari panci berisi air. Itu karena ini adalah bisul radikal. Anda perlu merebus banyak air di atas api. Radikal ini terlihat seperti semua bagian itu sekaligus!', NULL, NULL),
  ('00000000-0000-4000-8000-000000000132', 'radical', '歹', 'yakuza', 6, 0, 'Kelompok radikal malam ada di bawah tanah. Siapa yang melakukan hal-hal di bawah tanah pada malam hari? <radikal>Yakuza</radikal>. Bayangkan anggota Yakuza menyelinap di kereta bawah tanah, atau di selokan. Mereka pasti sedang merencanakan sesuatu yang tidak baik di bawah sana.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000133', 'radical', '向', 'cyclops-133', 6, 0, 'Ada kepala dengan sedikit rambut di atasnya. Ada juga satu mata besar di tengahnya. Hanya satu makhluk yang memiliki kepala seperti ini, dan makhluk itu adalah cyclop.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000134', 'radical', '未', 'jet', 6, 0, 'Ini seperti salah satu <radical>jet</radical> yang mempunyai sayap hidung kecil juga. Bayangkan Anda sedang melihat jet dari atas ke bawah, seperti inilah tampilannya. Itu juga mengapa ini disebut jet radikal.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000135', 'radical', '禾', 'grain', 6, 0, 'Ini adalah pohon dengan slide yang memotong bagian atasnya. Dengan apa Anda memotong bagian atas pohon dan tanaman? <radikal>biji-bijian</radikal>. Bayangkan mengambil sabit dan mengiris butiran beras atau gandum. Tanaman yang Anda tinggalkan akan terlihat radikal seperti ini. Itu tandanya kamu mendapat semacam butiran darinya.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000136', 'radical', '羊', 'sheep', 6, 0, 'Ini adalah <radical>domba</radical> dan Anda melihatnya dari atas. Lihat kedua telinga dan tubuh domba menghadap ke belakang (dengan seluruh bulunya menyembul ke samping) dan kemudian ekor kecil mencuat ke belakang. Domba yang lucu!', NULL, NULL),
  ('00000000-0000-4000-8000-000000000137', 'radical', '血', 'blood', 6, 0, 'Ada setitik kecil sesuatu di piringmu (皿). "Apa itu?" kamu bertanya. Oh tidak... bintik itu DARAH!!! Saya harap itu darah mimisan yang Anda alami secara tiba-tiba dan bukan darah orang lain. (Pelayan Anda mungkin akan dipecat, btw.) Setidaknya trombosit Anda akan segera menghentikan pendarahan. Haha, mengerti? PLATE-ayo? Lelucon darah Jepang.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000138', 'radical', '長', 'long', 6, 0, 'Anda memiliki radikal kunci yang dimodifikasi di atas radikal tendangan. Anda menendang kunci sejauh yang Anda bisa, lalu mengukur jaraknya. Berapa <radikal>lama</radikal> perjalanannya? Berapa lama waktu yang Anda perlukan untuk menemukannya? Berapa lama Anda akan mendapat masalah karena menendang kunci ke dalam hutan?', NULL, NULL),
  ('00000000-0000-4000-8000-000000000139', 'radical', '食', 'eat', 6, 0, 'Anda memakai topi dan pergi keluar untuk menendang sesuatu yang berwarna putih. Itu angsa putih besar dan kamu membunuhnya dengan tendanganmu. Itu karena Anda akan memasak dan <radikal>memakannya</radikal> itu. enak!', NULL, NULL),
  ('00000000-0000-4000-8000-000000000140', 'radical', 'ム', 'private', 2, 33, 'Ini adalah segitiga kecil yang hampir tertutup seluruhnya. Saat Anda ingin sendirian, Anda bersembunyi di tempat di mana Anda bisa berada dalam <radical>pribadi</radikal>. Itu sebabnya ini disebut radikal swasta. Anda menutup diri dari dunia luar, hanya dengan sedikit lubang intip.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000141', 'radical', 'マ', 'mama', 6, 0, 'Radikal ini sama seperti karakter katakana "ma" (<ja>マ</ja>). Jadi mari kita buat semuanya tetap sederhana dan jadikan <radikal>mama</radikal> yang radikal.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000142', 'radical', '欠', 'lack', 6, 0, 'Ada seseorang di penjara. Mengapa orang ini dipenjara? Karena mereka <radikal>kekurangan</radikal> hal-hal yang dibutuhkan manusia untuk berada di dekat manusia lain. Jika Anda kekurangan sesuatu (kebaikan, pengendalian diri, dll.), Anda mungkin melakukan sesuatu yang membuat orang lain memenjarakan Anda. Berusahalah untuk memperbaiki kekuranganmu agar hal ini tidak menimpamu.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000143', 'radical', '占', 'fortune', 6, 0, 'Seseorang memiliki jari kaki di mulutnya. Mereka adalah peramal yang meramal <radikal>keberuntungan</radikal> Anda. Tapi agar dia bisa melakukannya, dia harus mengambil salah satu jari kakimu dan mencicipinya. Ini lebih baik menjadi keberuntungan bagi Anda untuk membiarkan seseorang memasukkan kaki Anda ke dalam mulutnya.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000144', 'radical', '犭', 'animal', 6, 0, 'Ini terlihat seperti ekor dengan beberapa helai rambut yang terlepas darinya. Namun jangan bingung dengan jari, karena bentuknya melengkung, dan benda yang menonjol lebih tidak menentu, seperti rambut atau bulu. Itu sebabnya radikal ini adalah radikal hewan.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000145', 'radical', '卩', 'stamp', 7, 0, 'Radikal ini bentuknya agak mirip huruf P ya? Itu adalah huruf P yang dicetak pada sesuatu... tunggu, itu tidak dicetak, itu adalah <radikal>stempel</radikal> yang ditempelkan pada kertas. Peter Parker suka menggunakan prangko daripada pulpen.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000146', 'radical', '夫', 'husband', 7, 1, 'Kaum radikal yang mendasar dan besar membentuk radikal ini. Ada pria besar di tanah... siapa pria besar itu? Yang memalukan, itu suamimu. Rasakan rasa malu karena dia terjatuh ke tanah. Naik apa? Siapa? Bagaimana? (Tidak masalah.)', NULL, NULL),
  ('00000000-0000-4000-8000-000000000147', 'radical', '氏', 'clan', 7, 2, 'Ini terlihat seperti tamagotchi kecil atau (jika Anda bukan anak tahun 90an) bebek. Apa kesamaan yang dimiliki kedua makhluk ini? Mereka memiliki pengikut <radikal>klan</radikal> yang sangat gila. Dan orang-orang yang menikmatinya (permainan kecil-kecilan atau menonton bebek berkuak) membentuk klan yang berkumpul dan berbagi pengalaman. Anda termasuk dalam klan mana?', NULL, NULL),
  ('00000000-0000-4000-8000-000000000149', 'radical', '舟', 'boat', 7, 3, 'Ini terlihat seperti perahu yang datang ke arah Anda di dalam air. Lihat layar yang mengepul dan pantulan air? Seperti itulah penampakan perahu.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000150', 'radical', '魚', 'fish', 7, 4, 'Di penjara di sawah mereka sedang merebus sesuatu. Menurutmu apa itu? <radikal>Ikan</radikal>! Apa yang lebih baik dengan nasi? Apa yang mudah ditemukan sehingga menjadikannya makanan penjara yang murah? Ikan, tentu saja!', NULL, NULL),
  ('00000000-0000-4000-8000-000000000151', 'radical', '鳥', 'bird', 7, 5, 'Lihat sayap keren di bawah? Lihat kepala dengan bulu rapi keluar dari atasnya? Ini adalah <radikal>burung</radikal>. Tweet tweet!', NULL, NULL),
  ('00000000-0000-4000-8000-000000000152', 'radical', '黄', 'yellow', 7, 6, 'Bunga yang tumbuh dari tanah sawah setelah Anda mengubur siripnya di sana akan tumbuh berwarna kuning. Mengapa? Karena kuning adalah warna jiwa ikan, maka menanam bunga di atas siripnya akan mengubahnya menjadi kuning yang bagus dan cantik.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000153', 'radical', '黒', 'black', 7, 7, 'Jika Anda merebus sebuah desa, semuanya akan menjadi <radikal>hitam</radikal>. Sebagian besar karena Anda adalah seorang pembunuh gila, namun terlebih lagi karena ketika Anda merebus sebuah desa, seluruh jalan akan meleleh dan melapisi segala sesuatunya dengan tar hitam. Bayangkan! Sepertinya Pompeii. (Oof, terlalu cepat?)', NULL, NULL),
  ('00000000-0000-4000-8000-000000000154', 'radical', '主', 'master', 4, 28, 'Raja ini mempunyai setetes air yang mengambang di atas kepalanya. Itu karena dia bukan hanya seorang raja, dia adalah <radikal>penguasa</radikal> air. Ahli elemen. Penguasa Segala Sesuatu!', NULL, NULL),
  ('00000000-0000-4000-8000-000000000155', 'radical', '会', 'meet', 5, 22, 'Di bawah topi ada dua orang yang <radikal>bertemu</radikal> secara pribadi. Lihatlah mereka meringkuk di sana. Mereka pasti punya alasan ingin bertemu di tempat privat seperti itu, tapi itu bukan hak Anda untuk menilai. Mungkin lain kali Anda harus bertemu dengan seseorang, Anda juga akan bersembunyi di bawah topi bersama mereka.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000156', 'radical', '首', 'neck', 6, 0, 'Ada beberapa tanduk di tanah yang Anda inginkan untuk diri Anda sendiri. Anda mengambilnya dan menempelkannya ke <radical>leher</radical> Anda. Bayangkan tanduk ini mencuat di leher Anda. Tidak ada yang bisa menggorok leher Anda sekarang karena leher Anda terlindungi.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000157', 'radical', 'ユ', 'hook', 8, 0, 'Ada garis datar di tempat tangan terpotong. Di dalamnya ada kail seperti yang dimiliki bajak laut. Yarrrr.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000158', 'radical', '巳', 'snake', 8, 1, 'Ada dua cara untuk mengingat yang satu ini. Pertama, Anda dapat melihat ini dan melihat bahwa itu adalah ular yang melingkar. Atau kalau mau, bisa dibayangkan sebagai kepala ular dengan wajah menghadap ke kanan (lihat mulutnya yang terbuka?). Kami mungkin menggunakan keduanya saat mempelajari kanji, namun untuk saat ini Anda dapat memilih salah satu yang paling sesuai dengan gaya hafalan Anda. Pastikan Anda menjadi ular ketika Anda melihat radikal ini.
INSERT INTO public.items (id, type, character, slug, level, lesson_position, meaning_mnemonic, reading_mnemonic, svg_filename) VALUES
  ('00000000-0000-4000-8000-000000000233', 'radical', '豕', 'pig', 7, 14, 'Anda sudah mengetahui adanya unsur radikal dalam hal ini, itu seharusnya menjadi petunjuk. Hewan apa itu? Letaknya di dalam tanah, tertutup lumpur. Juga, ada jari-jari kakinya yang tergeletak di sana-sini, karena hewan ini akan memakan apa saja (cara yang baik untuk menyingkirkan mayat... kudengar). Lalu hewan apa yang berlumuran lumpur dan memakan jari kaki karena mau memakan apa saja? Itu adalah <radikal>babi</radikal>!', NULL, NULL),
  ('00000000-0000-4000-8000-000000000238', 'radical', '今', 'now', 3, 17, 'Ini adalah topi di atas katakana untuk "ra". Bayangkan Ra, dewa Mesir. Kapan Ra memakai topi? Sekarang juga <radikal>sekarang</radikal>! Selalu begitu sekarang, karena dia tidak pernah melepasnya. Tidak juga, lihatlah, itu benar.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000240', 'radical', '隹', 'turkey', 10, 11, 'Ini tampak seperti puncak dari burung yang radikal, tetapi tidak sepenuhnya. Ini semacam atasan radikal yang tampak bodoh. Burung apa yang bodoh, begitu bodohnya sehingga ia memandang ke langit untuk menenggelamkan dirinya dengan mulut terbuka? <radikal>kalkun</radikal>.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000267', 'radical', '市', 'city', 6, 0, 'Anda sudah mempelajari kanji <ja>市</ja>, yang artinya kota. Kami juga memperlakukannya sebagai radikal, karena ini muncul di banyak kanji lainnya. Jika digunakan sebagai kata radikal, tetap berarti <radikal>kota</radikal>.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000275', 'radical', '失', 'fault', 10, 12, 'Radikal ini sama dengan kanji. Itu berarti kesalahan.
INSERT INTO public.items (id, type, character, slug, level, lesson_position, meaning_mnemonic, reading_mnemonic, svg_filename) VALUES
  ('00000000-0000-4000-8000-000000000631', 'kanji', '知', '知', 6, 0, 'Tepat sebelum mengatakan sesuatu yang penting, Anda mengarahkan <radical>panah</radical> ke <radical>mulut</radical> yang menutup bibir Anda, sehingga Anda tidak dapat berbicara. Seseorang tidak ingin Anda membagikan apa yang <kanji>ketahui</kanji> Anda kepada orang lain.', 'Untuk mengingat bacaan <ja>ち</ja> kita menggunakan kata "keju".
INSERT INTO public.items (id, type, character, slug, level, lesson_position, meaning_mnemonic, reading_mnemonic, svg_filename) VALUES
  ('00000000-0000-4000-8000-000000002510', 'vocabulary', '一千', '一千', 2, 75, 'If you have one thousand, you have one thousand.', 'This is a jukugo word, which usually means on''yomi readings from the kanji. If you know the readings of your kanji you''ll know how to read this as well. The only thing that''s a bit weird is the reading of the 一. The ち turns into a small っ, making the reading for this word いっせん.', NULL),
  ('00000000-0000-4000-8000-000000002511', 'vocabulary', '夕べ', '夕べ', 2, 76, 'Kosa kata ini memiliki sedikit tambahan yang aneh (<ja>べ</ja>). Anda bisa mengabaikannya, itu tidak berarti apa pun secara khusus. Arti kosakata ini dan kanji asalnya sama: <vocabulary>malam</vocabulary>', 'Ketika hiragana dilampirkan pada sebuah kanji, Anda biasanya dapat berasumsi bahwa kanji tersebut akan dibaca menggunakan pembacaan kun''yomi, dan itulah yang terjadi dengan kata ini juga. Dengan mempelajari kanji kata ini, Anda juga mempelajari cara membaca kata tersebut.', NULL),
  ('00000000-0000-4000-8000-000000002512', 'vocabulary', '女の子', '女の子', 2, 78, 'Karena kata ini terdiri dari kanji dengan hiragana di tengahnya, Anda dapat menebaknya seperti menggabungkan dua kata terpisah yang telah Anda pelajari menjadi satu kata. Hiragana ini adalah <ja>の</ja>, sebuah partikel yang membuat sesuatu menjadi posesif. Dalam hal ini, <ja>子</ja> adalah dari <ja>女</ja>. Pada dasarnya hal ini mengisyaratkan bahwa perempuan tersebut adalah seorang anak-anak alias <vocabulary>girl</vocabulary>.', 'Karena ada hiragana di sini, bisa dipastikan kanji ini akan menggunakan pembacaan kun''yomi. Anda sudah mengetahui bacaan kun''yomi untuk <vocabulary>女</vocabulary>. Satu-satunya hal yang harus saya pastikan Anda mengetahuinya adalah <ja>子</ja>. Saat kamu perlu mengingat bacaan kun''yomi dari <ja>子</ja>, bayangkan saja kamu berkelahi dengan seorang anak kecil (tampaknya kamu brengsek!). Ketika Anda memukul wajahnya, dia terbang ke lantai, dan wasit berteriak "<reading>KO</reading>!" karena kamu baru saja menjatuhkan anak malang itu.', NULL),
  ('00000000-0000-4000-8000-000000002513', 'vocabulary', '子', '子', 2, 77, 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Karena kata ini terdiri dari satu kanji, maka menggunakan bacaan kun''yomi. Saat mempelajari kanji, Anda tidak mempelajari bacaan tersebut, jadi inilah mnemonik untuk membantu Anda dengan kata ini:
INSERT INTO public.items (id, type, character, slug, level, lesson_position, meaning_mnemonic, reading_mnemonic, svg_filename) VALUES
  ('00000000-0000-4000-8000-000000002714', 'vocabulary', '主に', '主に', 4, 137, '<ja>主</ja> berarti <kanji>main</kanji> sehingga ketika Anda menambahkan <ja>に</ja> itu menjadi kata keterangan <vocabulary>mainly</vocabulary>.', 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: 
INSERT INTO public.items (id, type, character, slug, level, lesson_position, meaning_mnemonic, reading_mnemonic, svg_filename) VALUES
  ('00000000-0000-4000-8000-000000002917', 'vocabulary', '海', '海', 9, 0, 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Karena kata ini terdiri dari satu kanji, maka sebaiknya menggunakan bacaan kun''yomi. Saat mempelajari kanji, Anda tidak mempelajari bacaan tersebut, jadi inilah mnemonik untuk membantu Anda dengan kata ini: 
INSERT INTO public.items (id, type, character, slug, level, lesson_position, meaning_mnemonic, reading_mnemonic, svg_filename) VALUES
  ('00000000-0000-4000-8000-000000003121', 'vocabulary', '魚屋', '魚屋', 9, 95, '<kanji>ikan</kanji> <kanji>toko</kanji> adalah <vocabulary>toko ikan</vocabulary>, tempat Anda membeli ikan. Khususnya di Jepang, sangat penting.', 'Pembacaan kun''yomi digunakan untuk <ja>魚</ja> (jadi <ja>さかな</ja>) dan pembacaan kun''yomi digunakan untuk <ja>屋</ja> (<ja>や</ja>). Anda harus menggunakan bacaan <ja>魚</ja> dari kosakata beberapa level yang lalu untuk mengingat bacaan yang satu ini.', NULL),
  ('00000000-0000-4000-8000-000000003122', 'vocabulary', '名古屋', '名古屋', 9, 96, 'Tempat yang <kanji>terkenal</kanji> dengan <kanji>tua</kanji> <kanji>atap</kanji>. Saya tidak tahu kenapa, tapi ini adalah kota <vocabulary>Nagoya</vocabulary>. Gabungkan saja kedua hal tersebut dan Anda akan sulit untuk melupakannya (selama Anda pernah mendengar tentang Nagoya sebelumnya - jika belum, bacalah tentangnya!).', 'Ini adalah kata jukugo, yang biasanya berarti pembacaan on''yomi dari kanji (kecuali <ja>名</ja> dan <ja>屋</ja>, yang merupakan kun''yomi di sini). Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya. Untuk <ja>な</ja> coba pikirkan <ja>名前</ja> (<ja>なまえ</ja>) yang menggunakan bacaan <ja>な</ja>. "Nama" (<ja>名前</ja>) kota ini adalah apa? Itu <read>Na</reading>goya. Hati-hati jika rendaku juga berubah <ja>こ</ja> menjadi <ja>ご</ja>.', NULL),
  ('00000000-0000-4000-8000-000000003123', 'vocabulary', '今度', '今度', 9, 97, 'Dalam <kanji>sekarang</kanji> <kanji>kejadian</kanji> Anda akan mempelajari kanji Anda, bukan? Kata ini berarti <vocabulary>kali ini</vocabulary>. Meskipun "kali ini", namun ada perasaan <vocabulary>next time</vocabulary>. Ini seperti mengatakan "oke, kali ini kita akan mendapatkannya" dimana "kali ini" sebenarnya berarti "lain kali", membuatnya sedikit berbeda dari <ja>今回</ja>.', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000003124', 'vocabulary', '丁度', '丁度', 9, 98, 'Oke, kita akan sedikit curang untuk mengingat arti kata ini. Katakanlah Anda mengukur suhu jalanan. Tepatnya seratus derajat. Memang itulah kenyataannya. Hanya 100 derajat, tidak lebih atau kurang satu derajat. Anda menaruh telur Anda di jalan dan melihatnya memasak.', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000003125', 'vocabulary', '毎度', '毎度', 9, 99, 'Ketika sesuatu terjadi <kanji>setiap</kanji> <kanji>kejadian</kanji> dan <kanji>setiap</kanji> <kanji>derajat</kanji>, itu adalah sesuatu yang <vocabulary>sering</vocabulary>. Itu terjadi <vocabulary>setiap kali</vocabulary>.', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000003126', 'vocabulary', '角度', '角度', 9, 100, 'Derajat sudut menunjukkan berapa sudutnya. 90 derajat? 160 derajat? Semuanya masih bersudut saat Anda melakukannya.', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000003127', 'vocabulary', '〜度', '〜度', 9, 101, 'Kanji <kanji>derajat</kanji> dapat berarti derajat dalam hal sudut dan derajat dalam hal suhu. Kata ini adalah cara Anda membicarakan hal-hal ini. Cukup lampirkan ke sebuah angka dan Anda akan mendapatkan sendiri jumlah <vocabulary>derajat</vocabulary> sesuatu itu. Setelah angka 1, 2 dan 3 (dan dalam beberapa situasi lainnya) ini juga bisa berarti <vocabulary>kali</vocabulary>.', 'Bacaannya sama dengan bacaan kanji yang Anda pelajari. Saat menulis jawaban untuk bacaan ini, hilangkan <ja>〜</ja> karena ini hanya untuk memberi tahu Anda bahwa ada kata lain yang harus didahulukan.', NULL),
  ('00000000-0000-4000-8000-000000003130', 'vocabulary', '持つ', '持つ', 9, 102, 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi <ja>う</ja>, Anda tahu bahwa kata tersebut adalah kata kerja.
INSERT INTO public.items (id, type, character, slug, level, lesson_position, meaning_mnemonic, reading_mnemonic, svg_filename) VALUES
  ('00000000-0000-4000-8000-000000003501', 'vocabulary', '名', '名', 4, 163, 'Kosakata ini sama dengan arti ''nama'' dalam kanji. Jika Anda bisa mengingatnya, Anda tidak akan kesulitan mengingat kata ini juga.', 'Karena kata ini terdiri dari satu kanji, kemungkinan besar menggunakan bacaan kun''yomi. Anda tidak mempelajari bacaan ini, jadi inilah mnemonik untuk membantu Anda mengingat: Coba pikirkan bagian pertama dari kata bahasa Inggris <vocabulary>name</vocabulary>. Apa itu? Itu <reading>na</reading> (<ja>な</ja>), seperti kata ini!', NULL),
  ('00000000-0000-4000-8000-000000003506', 'vocabulary', '出会う', '出会う', 10, 152, 'Anda <kanji>keluar</kanji> rumah Anda dan <kanji>bertemu</kanji> seseorang. Anda tidak bermaksud untuk bertemu mereka, tetapi hal itu tetap terjadi. Itu sebabnya kata ini berarti <vocabulary>bertemu secara kebetulan</vocabulary>.', 'Pembacaannya adalah kata <ja>出る</ja> dan kata <ja>会う</ja>, yang keduanya mudah-mudahan sudah Anda lihat. Bagian <ja>出</ja> mungkin membingungkan, tetapi Anda biasanya dapat berasumsi bahwa jika salah satu bagian dari kata tersebut adalah kun''yomi / bacaan vocab, bagian lainnya juga demikian, itulah sebabnya <ja>出</ja> menggunakan bacaan vocab.
INSERT INTO public.items (id, type, character, slug, level, lesson_position, meaning_mnemonic, reading_mnemonic, svg_filename) VALUES
  ('00000000-0000-4000-8000-000000008801', 'vocabulary', '以後', '以後', 7, 158, '<kanji>Dari</kanji> <kanji>sesudah</kanji>, berarti <vocabulary>setelah ini</vocabulary> atau <vocabulary>mulai sekarang</vocabulary>.', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000008802', 'vocabulary', '使用', '使用', 9, 176, 'Sesuatu yang Anda <kanji>gunakan</kanji> yang memiliki <kanji>penggunaan</kanji> memiliki... ya, <vocabulary>use</vocabulary>. Anda bahkan dapat menggunakannya untuk <vocabulary>aplikasi</vocabulary> praktis.', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000008803', 'vocabulary', '番号札', '番号札', 10, 180, 'Anda tahu 番号 berarti "angka" jadi tambahkan tag padanya dan Anda akan mendapatkan tag bernomor.', 'This is a jukugo word (番号) with a single-word kanji added. That means you have two on''yomi readings from the jukugo word and the kun''yomi reading from the single kanji (ふだ). Put them all together and you have the reading of this kanji!', NULL),
  ('00000000-0000-4000-8000-000000008814', 'vocabulary', '投手', '投手', 8, 179, 'Orang yang melempar dengan tangannya adalah pelempar dalam permainan bisbol. Permainan lain tidak melibatkan melempar dengan tangan, melainkan menendang dengan kaki. Jadi, ketika Anda membayangkan sebuah lemparan tangan, bayangkanlah pelempar favorit Anda!', 'This is a jukugo word that uses the on''yomi readings of the kanji. You haven''t learned this reading for 手 yet, so here''s a mnemonic to help you:
