INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES
  ('00000000-0000-4000-8000-000000002467', '一ど、あいましょう。', 'Let’s meet up once.'),
  ('00000000-0000-4000-8000-000000002467', '一いはアメリカ人でした。', 'First place was an American.'),
  ('00000000-0000-4000-8000-000000002467', 'ぼくはせかいで一ばんよわい。', 'I’m the weakest (person) in the world.'),
  ('00000000-0000-4000-8000-000000002468', 'こたえを一つえらびます。', 'Choose one answer.'),
  ('00000000-0000-4000-8000-000000002468', 'お一人さま一つかぎりです。', 'It''s limited to one per customer.'),
  ('00000000-0000-4000-8000-000000002468', 'きのう、一つめこぞうにあった。', 'I met a one-eyed goblin yesterday.'),
  ('00000000-0000-4000-8000-000000002469', 'あしたのあさ、七じにえきであいませんか。', 'Why don’t we meet at the station at seven tomorrow morning?'),
  ('00000000-0000-4000-8000-000000002469', 'みかんが七こあります。', 'There are seven mandarin oranges.'),
  ('00000000-0000-4000-8000-000000002469', '七にんのこびととともだちになりたい。', 'I want to be friends with the seven dwarves.'),
  ('00000000-0000-4000-8000-000000002470', 'はこのなかにりんごが七つあります。', 'There are seven apples in a box.'),
  ('00000000-0000-4000-8000-000000002470', '二人でメロンを七つたべました。', 'Just the two of us ate seven melons.'),
  ('00000000-0000-4000-8000-000000002470', '七つかぞえると、わたしは女になる。', 'After I count to seven, I will be a woman.'),
  ('00000000-0000-4000-8000-000000002471', 'まいにち九じかんぐらいべんきょうします。', 'I study for about nine hours every day.'),
  ('00000000-0000-4000-8000-000000002471', '九ページをひらいてください。', 'Please open to page 9.'),
  ('00000000-0000-4000-8000-000000002471', '九羽の九官鳥をかっていました。', 'I used to have nine mynah birds.'),
  ('00000000-0000-4000-8000-000000002472', 'きょうのテストには、じしょをつかうもんだいが九つあります。', 'There are nine questions that require a dictionary on today’s test.'),
  ('00000000-0000-4000-8000-000000002472', 'ねこには九つのいのちがあるってほんとう？', 'Is it true that a cat has nine lives?'),
  ('00000000-0000-4000-8000-000000002472', 'ドーナツを九つつくった。', 'I made nine donuts.'),
  ('00000000-0000-4000-8000-000000002473', '二十一ページの二ばんはクラスでします。', 'We will work on question two on page twenty-one in class.'),
  ('00000000-0000-4000-8000-000000002473', 'わたしのこどもは二さいです。', 'My child is 2 years old.'),
  ('00000000-0000-4000-8000-000000002473', 'わたしのおじは、ねこを二ひきかっています。', 'My uncle has two cats.'),
  ('00000000-0000-4000-8000-000000002474', '二つのかいわです。', 'It’s two dialogues.'),
  ('00000000-0000-4000-8000-000000002474', 'このカゴにリンゴを二つ入れてください。', 'Please put two apples in this basket.'),
  ('00000000-0000-4000-8000-000000002474', 'かれの二つめのあくぎょうは、かえるのあんさつだった。', 'His second evil deed was the frog’s assassination.'),
  ('00000000-0000-4000-8000-000000002475', 'やじるしの人はなんといいますか。', 'What will the person the arrow is pointing at say?'),
  ('00000000-0000-4000-8000-000000002475', 'あの人は何人ですか？', 'What is that person''s nationality?'),
  ('00000000-0000-4000-8000-000000002475', '人びとは、かれをばかな人だという。', 'People say he''s a stupid person.'),
  ('00000000-0000-4000-8000-000000002476', 'DVDを、あねと二人でみています。', 'I am watching a DVD with my older sister.'),
  ('00000000-0000-4000-8000-000000002476', 'あの二人はいつも二人でくみたがる。', 'Those two want to be a couple all the time.'),
  ('00000000-0000-4000-8000-000000002476', 'かのじょは二人ごろしでたいほされた。', 'She was arrested for double murder.'),
  ('00000000-0000-4000-8000-000000002477', '一人でカラオケにいきました。', 'I went to karaoke alone.'),
  ('00000000-0000-4000-8000-000000002477', '一人はアメリカ人です。', 'One of them is American.'),
  ('00000000-0000-4000-8000-000000002477', 'むすめは、きょうはじめて一人でおつかいにいきました。', 'My daughter did the errands by herself for the first time today.'),
  ('00000000-0000-4000-8000-000000002478', 'おれはアメリカ人か？', 'Am I American?'),
  ('00000000-0000-4000-8000-000000002478', 'アメリカ人が二人います。', 'There are two American people.'),
  ('00000000-0000-4000-8000-000000002478', 'アメリカ人の女とともだちになった。', 'I made friends with an American girl.'),
  ('00000000-0000-4000-8000-000000002479', 'フランス人のゆうじんができました。', 'I made a French friend.'),
  ('00000000-0000-4000-8000-000000002479', '二人はアメリカ人で、あとの三人はフランス人です。', 'Two of them are American and the other three are French.'),
  ('00000000-0000-4000-8000-000000002479', 'とてもセクシーなフランス人シェフにあった。', 'I met a very sexy French chef.'),
  ('00000000-0000-4000-8000-000000002480', 'プールに入るまえに、じゅんびうんどうをしてください。', 'Please stretch before getting in the pool.'),
  ('00000000-0000-4000-8000-000000002480', 'ちゃんと入り口から入ってください。', 'Please enter from the entrance.'),
  ('00000000-0000-4000-8000-000000002480', 'へやに入って、いっしょにまゆげをかこうよ！', 'Let’s go in the room and draw our eyebrows on!'),
  ('00000000-0000-4000-8000-000000002481', 'しかくになにを入れますか。', 'What will you put in the square?'),
  ('00000000-0000-4000-8000-000000002481', 'ここにおりがみを十二まい入れてください。', 'Please insert twelve pieces of origami paper here.'),
  ('00000000-0000-4000-8000-000000002481', 'わたしはハンバーガーをひつぎに入れた。', 'I put a hamburger into the coffin.'),
  ('00000000-0000-4000-8000-000000002482', 'がくせいは、きょううちで、八ページをべんきょうします。', 'Students will study page eight at home today.'),
  ('00000000-0000-4000-8000-000000002482', 'あめを八こカバンに入れました。', 'I put eight candies in my purse.'),
  ('00000000-0000-4000-8000-000000002482', '八じ？ほんとうに、八じ？', 'Eight o’clock? Are you sure it’s eight o’clock?'),
  ('00000000-0000-4000-8000-000000002483', 'ふくろには、じゃがいもが八つ入っています。', 'There are eight potatoes in a bag.'),
  ('00000000-0000-4000-8000-000000002483', '八つしかありませんよ。', 'There are only eight of them.'),
  ('00000000-0000-4000-8000-000000002483', '八つのかおと六つのうでがあるもの、なーんだ。', 'What has eight faces and six arms?'),
  ('00000000-0000-4000-8000-000000002484', 'おなかがすいて、力がでない。', 'I’m hungry and losing strength.'),
  ('00000000-0000-4000-8000-000000002484', 'あのアメリカ人の女にはふじ山をうごかす力がある。', 'That American woman has the power to move Mt. Fuji.'),
  ('00000000-0000-4000-8000-000000002484', 'おかあさんは、のこりのかぞくがたばになってもかなわない力をもっている。', 'My mom is more powerful than the rest of my family put together.'),
  ('00000000-0000-4000-8000-000000002485', 'わたしは、ツバメを十わかっています。', 'I have ten swallows.'),
  ('00000000-0000-4000-8000-000000002485', '十までかぞえることができますよ。', 'I can count up to ten!'),
  ('00000000-0000-4000-8000-000000002485', '十ねんかん十にんのじゅうにんとくらした。', 'For ten years I lived with ten other people.'),
  ('00000000-0000-4000-8000-000000002486', 'このもんだいようしは、ぜんぶで三ページあります。', 'There are three pages of these questions total.'),
  ('00000000-0000-4000-8000-000000002486', 'わたしは三十二さいです。', 'I’m 32 years old.'),
  ('00000000-0000-4000-8000-000000002486', '三かいまわってワンとほえろ。', 'Turn around three times and bark!'),
  ('00000000-0000-4000-8000-000000002487', '三つのせんたくしがおんせいできこえます。', 'You will hear three choices.'),
  ('00000000-0000-4000-8000-000000002487', 'ここにボールを三つ入れてください。', 'Please put three balls in here.'),
  ('00000000-0000-4000-8000-000000002487', '三つもかにかまれた。', 'I got three mosquito bites.'),
  ('00000000-0000-4000-8000-000000002488', 'わたしには、きょうだいが三人います。', 'I have three siblings.'),
  ('00000000-0000-4000-8000-000000002488', 'その川には二、三人しかいませんでした。', 'There were only two or three people in the river.'),
  ('00000000-0000-4000-8000-000000002488', '三人のうちで、だれがいちばんタイプ？', 'Out of those three people, which one is your type?'),
  ('00000000-0000-4000-8000-000000002489', '上のひょうをみてください。', 'Please look at the chart above.'),
  ('00000000-0000-4000-8000-000000002489', 'このフロアの三かい上にトーフグのオフィスがあります。', 'The Tofugu office is three floors up.'),
  ('00000000-0000-4000-8000-000000002489', 'くつ下のかたほうは、かいだんの上にあったわよ。', 'One of your socks was at the top of the stairs.'),
  ('00000000-0000-4000-8000-000000002490', 'このはこをれいぞうこの上に上げてください。', 'Please put this box on top of the refrigerator for me.'),
  ('00000000-0000-4000-8000-000000002490', '三センチ上げてください。', 'Please lift it three centimeters.'),
  ('00000000-0000-4000-8000-000000002490', 'りょうてを上に上げて、大きくおならをした。', 'I raised my hands and let out a huge fart.'),
  ('00000000-0000-4000-8000-000000002491', 'どんどんねつが上がっています。', 'My fever is rising steadily.'),
  ('00000000-0000-4000-8000-000000002491', '三かいまでエレベーターで上がりましょう。', 'Let''s go up to the 3rd floor using the elevator.'),
  ('00000000-0000-4000-8000-000000002491', 'けむりが上がってる。', 'Smoke is rising. '),
  ('00000000-0000-4000-8000-000000002492', 'わたしがやねに上りましょう。', 'I can go up to the roof.'),
  ('00000000-0000-4000-8000-000000002492', '十かいまでかいだんを上った。', 'I climbed up stairs to the 10th floor.'),
  ('00000000-0000-4000-8000-000000002492', 'サケが川を上っているのをみた。', 'I saw a salmon swimming upstream.'),
  ('00000000-0000-4000-8000-000000002493', 'つくえの下にはなにがありますか。 ', 'What’s under the desk?'),
  ('00000000-0000-4000-8000-000000002493', '下に下りてきてください。', 'Please come down.'),
  ('00000000-0000-4000-8000-000000002493', 'ぼくはトーフグオフィスの下のかいにすんでいる。', 'I live on the floor below the Tofugu office.'),
  ('00000000-0000-4000-8000-000000002494', 'せかいじゅうのかぶかが下がった。', 'Stock prices all over the world fell.'),
  ('00000000-0000-4000-8000-000000002494', 'ねつが三十七どに下がりました。', 'My temperature dropped to 37℃.'),
  ('00000000-0000-4000-8000-000000002494', 'ズボンが下がるようにベルトをゆるめなさい。', 'Unfasten your belt so that your pants will hang down.'),
  ('00000000-0000-4000-8000-000000002495', 'けつあつを下げるほうほうをおしえてください。', 'Please tell me how to lower my blood pressure.'),
  ('00000000-0000-4000-8000-000000002495', 'あのみせは、入り口にふうりんを一つ下げています。', 'That shop has one wind chime hanging in its entrance.'),
  ('00000000-0000-4000-8000-000000002495', 'きおんを下げるために、あまごいダンスをおどってみた。', 'I tried performing a rain dance to lower the temperature.'),
  ('00000000-0000-4000-8000-000000002496', 'それを下さい。', 'Please give me that one.'),
  ('00000000-0000-4000-8000-000000002496', 'りんごを二こ下さい。', 'Please give me two apples.'),
  ('00000000-0000-4000-8000-000000002496', 'ぼくに百万円を下さい。', 'Please give me a million yen.'),
  ('00000000-0000-4000-8000-000000002497', '口にソースがついていますよ。', 'There is some sauce on your mouth.'),
  ('00000000-0000-4000-8000-000000002497', 'これを口に入れてください。', 'Please put this in your mouth.'),
  ('00000000-0000-4000-8000-000000002497', 'きのうから口がとじられない。', 'I haven’t been able to close my mouth since yesterday.'),
  ('00000000-0000-4000-8000-000000002498', '入り口のところでまっています。', 'I will wait for you at the entrance.'),
  ('00000000-0000-4000-8000-000000002498', '入り口が三つあります。', 'There are three entrances.'),
  ('00000000-0000-4000-8000-000000002498', '入り口にジョニーデップがいるよ。', 'Johnny Depp is at the entrance.'),
  ('00000000-0000-4000-8000-000000002499', 'このぼうしは大きすぎます。', 'This hat is too big.'),
  ('00000000-0000-4000-8000-000000002499', 'その大きいももを二つください。', 'Can I get those two big peaches?'),
  ('00000000-0000-4000-8000-000000002499', 'わたしのあかちゃんは、こうしとおなじくらい大きい。', 'My baby is about as big as a calf.'),
  ('00000000-0000-4000-8000-000000002500', 'このテーブルの大きさは、よこ100センチ、たて120センチです。', 'The size of this table is 100cm in width and 120cm in length.'),
  ('00000000-0000-4000-8000-000000002500', 'テレビの大きさは三十二インチです。', 'The size of the TV is 32 inches.'),
  ('00000000-0000-4000-8000-000000002500', 'ロナルド・マクドナルドはいつも大きさのちがうくつをはいていた。', 'Ronald McDonald always wore different-sized shoes.'),
  ('00000000-0000-4000-8000-000000002501', 'それは大したことはない。', 'It’s not a big deal.'),
  ('00000000-0000-4000-8000-000000002501', 'まったく大した女だよ。', 'She is such a great woman.'),
  ('00000000-0000-4000-8000-000000002501', 'マクドナルドのしゃちょうになれれば大したものだ。', 'Being the president of McDonald’s would be a big deal.'),
  ('00000000-0000-4000-8000-000000002502', 'これは、大人のりょうきんです。', 'This is the adult price.'),
  ('00000000-0000-4000-8000-000000002502', '大人は三人だけです。', 'There are only three adults.'),
  ('00000000-0000-4000-8000-000000002502', '大人たちはいざかやにいった。', 'The adults went to an izakaya.'),
  ('00000000-0000-4000-8000-000000002503', 'あの女はだれ？', 'Who is that woman?'),
  ('00000000-0000-4000-8000-000000002503', 'わたしは女です。', 'I''m a woman.'),
  ('00000000-0000-4000-8000-000000002503', 'おれはこどもをせわする女がほしい。', 'I want a woman who will help look after my children.'),
  ('00000000-0000-4000-8000-000000002504', 'ともだちといっしょに、山にのぼります。', 'I''ll climb a mountain with my friends.'),
  ('00000000-0000-4000-8000-000000002504', 'これはせかい一大きい人工の山なんですよ。', 'This is the world''s biggest man-made mountain.'),
  ('00000000-0000-4000-8000-000000002504', 'あさ八じに、はだかではげ山にしゅうごうしましょう。', 'At 8 am, let’s meet naked on Bald Mountain.'),
  ('00000000-0000-4000-8000-000000002505', 'ふじ山に、ごぜん十一じごろまでにつきたいです。', 'I want to arrive at Mt. Fuji by around 11 a.m.'),
  ('00000000-0000-4000-8000-000000002505', 'ふじ山にはいつも大人のフランス人が三人とちいさいアメリカ人が二人とカナダ人が一人います。', 'There are always three adult French people, two small Americans, and one Canadian on Mt. Fuji.'),
  ('00000000-0000-4000-8000-000000002505', 'ふじ山はしろいとりのふんでおおわれていた。', 'Mt. Fuji was covered in white bird poop.'),
  ('00000000-0000-4000-8000-000000002506', 'この川には、さかながたくさんおよいでいます。', 'There are a lot of fish swimming in this river.'),
  ('00000000-0000-4000-8000-000000002506', 'にほんいちながい川は、しなの川です。', 'Japan''s longest river is Shinano River.
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES
  ('00000000-0000-4000-8000-000000002534', 'わたしは円い月がこわい。', 'I’m afraid of the full moon.'),
  ('00000000-0000-4000-8000-000000002535', 'ポチは天のほしになりました。', 'Pochi became a star in heaven.'),
  ('00000000-0000-4000-8000-000000002535', 'わたしがコウイチから四千えんをぬすんだことを、天のかみさまはしっかりとみていました。', 'God in Heaven definitely saw me steal Koichi''s 4000 yen.'),
  ('00000000-0000-4000-8000-000000002535', 'じゃんけんにかって、わたしは天にものぼるきもちだった。', 'I won the rock-paper-scissors competition and I felt like I was in heaven.'),
  ('00000000-0000-4000-8000-000000002536', 'かれはしょうぎの天才です。', 'Dia seorang shogi yang jenius.'),
  ('00000000-0000-4000-8000-000000002536', 'あのフランス人の女は天才だ。', 'Wanita Perancis itu jenius.'),
  ('00000000-0000-4000-8000-000000002536', 'そのゴリラは、まぎれもなく天才だ。', 'Gorila itu benar-benar jenius.'),
  ('00000000-0000-4000-8000-000000002537', '手がカサカサになってしまいました。', 'My hands got really dry.'),
  ('00000000-0000-4000-8000-000000002537', '手をつないでもいい？', 'Can I hold your hand?'),
  ('00000000-0000-4000-8000-000000002537', 'パパの手はモジャモジャだ。', 'Dad''s arms are all shaggy.'),
  ('00000000-0000-4000-8000-000000002538', 'ギターはまだ下手ですが、まいばんれんしゅうしています。', 'I’m still bad at the guitar, but I practice every night.'),
  ('00000000-0000-4000-8000-000000002538', 'アメリカ人のまねが下手な人は、フランス人のまねが上手です。', 'The person, who is not good at imitating Americans, is good at imitating French people.'),
  ('00000000-0000-4000-8000-000000002538', 'わたしははをみがくのが下手です。', 'I’m bad at brushing my teeth.'),
  ('00000000-0000-4000-8000-000000002539', 'さとうさんは、うたを上手にうたいます。', 'Satou is good at singing.'),
  ('00000000-0000-4000-8000-000000002539', 'オリーブオイルのつかいかたが上手な王子をしっていますか。', 'Do you know any princes who are good at using olive oil?'),
  ('00000000-0000-4000-8000-000000002539', 'わたしはへんがおをつくるのが上手です。', 'I’m good at making funny faces.'),
  ('00000000-0000-4000-8000-000000002540', 'はやく文をよんでください。', 'Please read the sentence faster.'),
  ('00000000-0000-4000-8000-000000002540', 'おどろいたことに、そのアメリカ人の文はイギリス人のわたしの文よりえいごが上手にかけていました。', 'To my surprise, that American''s English writing was written better than mine, and I''m British.'),
  ('00000000-0000-4000-8000-000000002540', 'かなしい文をよむと、いつもなみだが二ふん二十びょうだけとまらない。', 'Whenever I read a sad story I can’t stop crying for exactly two minutes and twenty seconds.'),
  ('00000000-0000-4000-8000-000000002541', 'そろそろ日がのぼるじかんだ。', 'It is time for the sun to rise.'),
  ('00000000-0000-4000-8000-000000002541', 'きょうは、トーフグがけっこんするたいせつな日です。', 'Today is the important day that Tofugu is getting married.'),
  ('00000000-0000-4000-8000-000000002541', '日がおちると、すぐにあたりはまっくらになって、わたしは本をよむことができなくなってしまった。', 'Shortly after sunset, it became so dark that I couldn’t read my book anymore.'),
  ('00000000-0000-4000-8000-000000002542', 'こんやは月がきれいですね。', 'The moon is beautiful tonight.'),
  ('00000000-0000-4000-8000-000000002542', 'わたしもその月に日本にきたんです。', 'I also came to Japan that month.'),
  ('00000000-0000-4000-8000-000000002542', 'ピンクの月が出たら、出ぱつのあいずだ。', 'If the pink moon comes out, that’s our signal to leave.'),
  ('00000000-0000-4000-8000-000000002543', 'さらいねんの十月で、六十さいになります。', 'Two years from now I will turn sixty in October.'),
  ('00000000-0000-4000-8000-000000002543', '十月にはだんだんすずしくなってくるでしょう。', 'It should gradually be getting cooler in October.'),
  ('00000000-0000-4000-8000-000000002543', 'かれがおかしいのは、十月なのにすいえいにさそったわたしのせきにんだ。', 'It’s my fault that he’s acting strange; I asked him to go swimming even though it is October.'),
  ('00000000-0000-4000-8000-000000002544', 'わたしは一月にかんじを千こおぼえました。', 'I learned one thousand kanji in January.'),
  ('00000000-0000-4000-8000-000000002544', '一月うまれのアメリカ人と六月うまれのイタリア人では、どちらのほうがおおいとおもいますか。', 'Which do you think there are more of: Americans who were born in January or Italians who were born in June?'),
  ('00000000-0000-4000-8000-000000002544', '一月にたべるアイスクリームもわるくない。', 'It’s not bad to eat ice cream in January.'),
  ('00000000-0000-4000-8000-000000002545', '二月三日にけっこんしました。', 'I got married on February third.'),
  ('00000000-0000-4000-8000-000000002545', '二月は、日本いきのチケットがとてもやすいです。', 'In February, air tickets to Japan are very cheap.'),
  ('00000000-0000-4000-8000-000000002545', 'きょねんの二月に、わたしたちのふりんははじまったの。', 'Our affair began in February of last year.'),
  ('00000000-0000-4000-8000-000000002546', 'いえのにわには、さくらの木があります。', 'There is a cherry tree in my garden.'),
  ('00000000-0000-4000-8000-000000002546', 'ともだちのアメリカ人のうちは、木とほねでできています。', 'My American friend''s house is made of wood and bones.'),
  ('00000000-0000-4000-8000-000000002546', 'あのりんごの木からおちたのは、はじめてじゃない。', 'It wasn’t my first time falling from the apple tree.'),
  ('00000000-0000-4000-8000-000000002547', '水かおちゃをもらえますか。', 'Can I have some water or tea?'),
  ('00000000-0000-4000-8000-000000002547', 'ふじ山にのぼるときは、水をわすれないようにしましょう。', 'Don''t forget to bring water when you climb Mt. Fuji.'),
  ('00000000-0000-4000-8000-000000002547', 'コップ一ぱいの水とあいをください。', 'Give me a cup of water and some love, please.'),
  ('00000000-0000-4000-8000-000000002548', 'はやく火をけしてください。', 'Please put the fire out soon.'),
  ('00000000-0000-4000-8000-000000002548', '石をつかって火をおこしたことはありますか？', 'Have you ever started a fire with stones?'),
  ('00000000-0000-4000-8000-000000002548', '火は、かれのかみのけをぜんぶやいてしまった。', 'The fire burned off all of his hair.'),
  ('00000000-0000-4000-8000-000000002549', '火山のふんかもありました。', 'There was a volcanic eruption too.'),
  ('00000000-0000-4000-8000-000000002549', 'ふじ山は火山です。いまから四十二じかんごにふんかします。', 'Mt. Fuji is a volcano. It will erupt in 42 hours.'),
  ('00000000-0000-4000-8000-000000002549', 'きっと火山にちがいない。', 'I’m sure that’s a volcano.'),
  ('00000000-0000-4000-8000-000000002550', '犬とねこがいます。', 'There is a dog and a cat.'),
  ('00000000-0000-4000-8000-000000002550', 'その王は犬を六ぴきかっています。', 'That king has six dogs.'),
  ('00000000-0000-4000-8000-000000002550', 'わたしの犬は、白さいがすきだ。', 'My dog likes Chinese cabbage.'),
  ('00000000-0000-4000-8000-000000002551', 'けさ、子犬がうまれました。', 'The puppies were born this morning.'),
  ('00000000-0000-4000-8000-000000002551', 'その子犬は王子にもらった九つの玉をくびから下げて入り口に立っていた。', 'The puppy that was standing at the entrance was given the nine balls around its neck by the prince.'),
  ('00000000-0000-4000-8000-000000002551', '子犬ごっこをしましょうよ。', 'Let’s pretend we’re puppies!'),
  ('00000000-0000-4000-8000-000000002552', 'このくにの王はわたしだ。', 'Saya adalah raja negara ini.'),
  ('00000000-0000-4000-8000-000000002552', '王の刀をみせてください。', 'Tolong tunjukkan padaku pedang Raja.'),
  ('00000000-0000-4000-8000-000000002552', '王さまでもカレーをたべるのだ。', 'Bahkan raja pun makan kari.'),
  ('00000000-0000-4000-8000-000000002553', '王子は、じょうばをはじめました。', 'Pangeran mulai menunggang kuda.'),
  ('00000000-0000-4000-8000-000000002553', 'あの王子の左手は大きい。', 'Tangan kiri Pangeran besar.'),
  ('00000000-0000-4000-8000-000000002553', '王子がかえるにキスをすると、そのかえるは王子をたべてしまった。', 'Setelah sang pangeran mencium sang katak, sang katak pun memakan sang pangeran.'),
  ('00000000-0000-4000-8000-000000002554', 'それは、女王のいすです。', 'Itu adalah kursi ratu.'),
  ('00000000-0000-4000-8000-000000002554', '女王は目が大きくてかわいい王女のことが大きらいです。', 'Ratu membenci sang putri karena dia lucu dan bermata besar.'),
  ('00000000-0000-4000-8000-000000002554', 'エリザベス女王と文つうをはじめた。', 'Saya mulai bertukar surat dengan Ratu Elizabeth.'),
  ('00000000-0000-4000-8000-000000002555', '王子は、王女のうつくしさにうっとりしました。', 'Sang pangeran terpesona melihat kecantikan sang putri.'),
  ('00000000-0000-4000-8000-000000002555', '王は王女に木のつくえをかってあげました。', 'Raja membelikan meja kayu untuk sang putri.'),
  ('00000000-0000-4000-8000-000000002555', '王女さまはよろこびをバクてんでひょうげんしているようです。', 'Sang putri mengungkapkan kegembiraannya dengan melakukan jungkir balik ke belakang.'),
  ('00000000-0000-4000-8000-000000002556', 'つくえの上に、じしょを出してください。', 'Please put the dictionary out on the desk.'),
  ('00000000-0000-4000-8000-000000002556', 'そのアメリカ人は、あしから二ひきのガラガラヘビにかまれたどくをぜんぶ出した。', 'That American removed all the venom he got from two rattle snakes out of his leg.'),
  ('00000000-0000-4000-8000-000000002556', 'どろぼうはぬすんだものをすべて出してくばった。', 'The thief handed out all the goods he stole.'),
  ('00000000-0000-4000-8000-000000002557', 'あちらの出口から出てください。', 'Please leave using that exit.'),
  ('00000000-0000-4000-8000-000000002557', 'くしゃみが出そうで出ない。', 'It looks like you have to sneeze, but can''t.'),
  ('00000000-0000-4000-8000-000000002557', 'わたしは、パチンコやからいそいで出た。', 'I made a hasty exit from that pachinko parlor.'),
  ('00000000-0000-4000-8000-000000002558', 'そこは出口ではありません。', 'That is not an exit.'),
  ('00000000-0000-4000-8000-000000002558', 'ふじ山にはひみつの入り口と出口があるらしいですよ。', 'I heard that Mt. Fuji has a secret entrance and exit.'),
  ('00000000-0000-4000-8000-000000002558', 'このきゅうじょうの出口はあちらです。', 'This baseball stadium’s exit is over there.'),
  ('00000000-0000-4000-8000-000000002559', '右のしゃしんは、とうきょうでとったしゃしんです。', 'The photo on the right was taken in Tokyo.'),
  ('00000000-0000-4000-8000-000000002559', '右には王の好きなメイドが五十人、ひだりには王子のすうはいする天才かがくしゃが一人いる。', 'On the right are fifty of the king''s favorite maids and on the left is a genius scientist who worships the prince.'),
  ('00000000-0000-4000-8000-000000002559', 'うまが右にまがったとき、ロバは右をチラリとみた。', 'When the horse turned to the right, the donkey glanced right as well.'),
  ('00000000-0000-4000-8000-000000002560', '山下さんは、右手にくろいかさをもっています。', 'Ms. Yamashita has a black umbrella in her right hand.'),
  ('00000000-0000-4000-8000-000000002560', '小さい女の子が、右手にビー玉をにぎりしめて立っていた。', 'There was a little girl holding a marble in her right hand.'),
  ('00000000-0000-4000-8000-000000002560', 'あ、赤ちゃんの右手のひじにホクロがある！', 'Oh, the baby has a mole on the elbow of his right arm.'),
  ('00000000-0000-4000-8000-000000002560', '右手の山はふじ山です。', 'The mountain on the right-hand side is Mt. Fuji.'),
  ('00000000-0000-4000-8000-000000002561', 'もんだい四は、えなどがありません。', 'There are no pictures for question four.'),
  ('00000000-0000-4000-8000-000000002561', '王のへやには大きい、白い一千万円玉が四こもある。', 'There are four big, white, 10 million yen balls in the king''s room.'),
  ('00000000-0000-4000-8000-000000002561', 'おやしらずを四ほんともばっしした。', 'I had all four of my wisdom teeth pulled out.'),
  ('00000000-0000-4000-8000-000000002562', 'たんじょうびは、四月九日です。', 'My birthday is April ninth.'),
  ('00000000-0000-4000-8000-000000002562', '四月はさくらがさくので、王子は日本にいきたがっています。', 'Since cherry blossoms are in bloom in April, the prince wants to go to Japan.'),
  ('00000000-0000-4000-8000-000000002562', '四月にりょうしんがりこんしたストレスで、おれのガールフレンドにはすこしひげがはえた。', 'My girlfriend suffered from so much stress after her parents divorced in April that she started to grow a little bit of a mustache.'),
  ('00000000-0000-4000-8000-000000002563', 'らい月の四日に、わたしといっしょにやきゅうをみにいきませんか？', 'Why don’t you come watch baseball with me on the fourth of next month?'),
  ('00000000-0000-4000-8000-000000002563', '七月四日はアメリカのどくりつきねん日です。', 'July 4th is Independence Day in America.'),
  ('00000000-0000-4000-8000-000000002563', 'あのくまに出あって四日ご、ぼくのせなかにかびがはえた。', 'Four days after I met that bear, my back started growing mold.'),
  ('00000000-0000-4000-8000-000000002564', 'このはこには、みかんが四つあります。', 'There are four oranges in this box.'),
  ('00000000-0000-4000-8000-000000002564', '小さい玉ねぎを四つ下さい。', 'Please give me four small onions.'),
  ('00000000-0000-4000-8000-000000002564', '今朝、クロワッサンを四つか五つ食べました。', 'This morning, I ate four or five croissants.'),
  ('00000000-0000-4000-8000-000000002565', 'フォロワーが四千人になりました。', 'I hit four thousand followers.'),
  ('00000000-0000-4000-8000-000000002565', 'これは、ちゅうごく四千ねんのれきしがつくり上げた、せかいに一つしかないとうふです。', 'This is the only tofu in the world created by China with great 4000 years of history.'),
  ('00000000-0000-4000-8000-000000002565', '四千ぼんのでんちゅうをいっせいにたおせるくらい、きみのことをあいしているよ。', 'I love you so much that I could knock down four thousand telephone poles at once.'),
  ('00000000-0000-4000-8000-000000002566', 'Tシャツを四十まいもっています。', 'I have forty T-shirts.'),
  ('00000000-0000-4000-8000-000000002566', 'あの天才アメリカ人は四十才です。', 'That genius American is 40 years old.'),
  ('00000000-0000-4000-8000-000000002566', '四十だいにもなると、ぜんしんがかゆい。', 'Since reaching my forties, my entire body has been itchy.'),
  ('00000000-0000-4000-8000-000000002567', 'わたしは、左ききです。', 'I’m left-handed.'),
  ('00000000-0000-4000-8000-000000002567', '左の山のなまえはなんですか？', 'What''s the name of the mountain on the left?'),
  ('00000000-0000-4000-8000-000000002567', 'あのむすめが左みみのピアスをあけたときのことがわすれられない。', 'I will never forget the time that girl got her left ear pierced.'),
  ('00000000-0000-4000-8000-000000002568', 'あねの左手には、ほくろがある。', 'My older sister has a mole on her left hand.'),
  ('00000000-0000-4000-8000-000000002568', '左手を上げてください。', 'Please raise your left hand.'),
  ('00000000-0000-4000-8000-000000002568', '左手のひじをハチにさされた。', 'I was stung by a bee on the elbow of my left arm.'),
  ('00000000-0000-4000-8000-000000002568', '左手にみえるのが、スカイツリーです。', 'What you can see on your left-hand side is the Sky Tree.'),
  ('00000000-0000-4000-8000-000000002569', 'この本はどこでかいましたか。', 'Where did you buy this book?'),
  ('00000000-0000-4000-8000-000000002569', 'コウイチがあやしいフランス人からかった本のカバーは本がわのカバーでした。', 'The book cover that Koichi bought from a spooky French person was covered with genuine leather.'),
  ('00000000-0000-4000-8000-000000002569', 'ここで本をよみたければ、きんをわたしてもらおう。', 'If you want to read a book here, you have to give me some gold.'),
  ('00000000-0000-4000-8000-000000002570', '日本のカレーはおいしいです。', 'Japanese curry is delicious.'),
  ('00000000-0000-4000-8000-000000002570', '十月から、日本にすみます。', 'I''m gonna live in Japan starting in October.'),
  ('00000000-0000-4000-8000-000000002570', '日本のかたちをしたケーキをやいた。', 'I baked a cake shaped like Japan.'),
  ('00000000-0000-4000-8000-000000002571', 'かれは、じぶんがいつも正しいとおもっている。', 'He always thinks he’s right.'),
  ('00000000-0000-4000-8000-000000002571', '王女はいつも正しくて、王子はいつもまちがっている。', 'The princess is always correct and the prince is always wrong.'),
  ('00000000-0000-4000-8000-000000002571', 'ぼくのこころのとびらをあけるには、正しいかぎがひつようだよ、ベイビー。', 'If you want to open the door to my heart, you need the right key, baby.'),
  ('00000000-0000-4000-8000-000000002572', 'しせいを正しなさい。', 'Correct your posture.'),
  ('00000000-0000-4000-8000-000000002572', '王子はまちがいを正されてプライドがきずついた。', 'The prince''s mistake was corrected and his pride was wounded.'),
  ('00000000-0000-4000-8000-000000002572', 'あやまりを正すことができれば、ごほうびをあげるわ。', 'If you can correct my mistakes, I’ll give you a reward.'),
  ('00000000-0000-4000-8000-000000002573', 'うんどうかいで玉入れをしました。', 'Saya bermain lempar bola pada hari olahraga.'),
  ('00000000-0000-4000-8000-000000002573', 'ここに、白の玉が九つあります。', 'Ada sembilan bola putih di sini.'),
  ('00000000-0000-4000-8000-000000002573', 'けいとの玉のようなどうぶつをみかけませんでしたか？', 'Pernahkah Anda melihat binatang yang bentuknya seperti bola wol?'),
  ('00000000-0000-4000-8000-000000002574', 'ビー玉をつかってゲームをしましょう。', 'Ayo mainkan permainan yang menggunakan kelereng.'),
  ('00000000-0000-4000-8000-000000002574', 'アメリカではまいとし一月にビー玉をつかったゲームが上手なフランス人がつどうコンテストがあります。', 'Di Amerika, setiap bulan Januari diadakan kontes yang mempertemukan orang-orang Perancis yang pandai kelereng.'),
  ('00000000-0000-4000-8000-000000002574', 'かれは、けっこんのあかしに一つぶのビー玉をくれた。', 'Dia memberiku satu kelereng sebagai bukti pernikahan kami.'),
  ('00000000-0000-4000-8000-000000002575', '玉ねぎをきっていたら、なみだが出てきた。', 'Saat saya memotong bawang, saya menangis.'),
  ('00000000-0000-4000-8000-000000002575', 'この玉ねぎを立たせることができたあなたは天才です。', 'Pasti kamu jenius kalau bisa membuat bawang ini berdiri sendiri.'),
  ('00000000-0000-4000-8000-000000002575', 'きみは玉ねぎをいくつわきにはさめるかい？', 'Berapa banyak bawang yang bisa Anda pegang di bawah ketiak?'),
  ('00000000-0000-4000-8000-000000002576', '日よう日、ヤンさんの子どもが生まれました。', 'On Sunday, Yang’s child was born.'),
  ('00000000-0000-4000-8000-000000002576', 'マイケルせん手の、力づよいフルスイングから生まれるホームランのかずかずをごらんください。', 'Please watch these home runs produced by the strong swings of a pro player named Michael.'),
  ('00000000-0000-4000-8000-000000002576', '生まれたばかりの子どもに、さけをのませるな。', 'Do not make a newborn baby drink alcohol.'),
  ('00000000-0000-4000-8000-000000002577', 'かれのはつげんは、ぎもんを生んだ。', 'His remark produced problems.'),
  ('00000000-0000-4000-8000-000000002577', 'ごかいを生むようなとうこうはしないでください。', 'Please do not post things that could give rise to misunderstandings.'),
  ('00000000-0000-4000-8000-000000002577', 'おっとの子ではなかったが、生むしかなかった。', 'Even though it wasn’t my husband’s, I had no choice but to give birth to the baby.'),
  ('00000000-0000-4000-8000-000000002578', 'しつれんで生きる気力をうしなった。', 'I lost the will to live from heartbreak.'),
  ('00000000-0000-4000-8000-000000002578', '今、かれが生きているのかすら分かりません。', 'I don''t even know if he''s alive now.'),
  ('00000000-0000-4000-8000-000000002578', 'わたしの大好きなアニメキャラが、今生きるかしぬかのせとぎわにいる。', 'My favorite anime character is currently in a critical moment between life and death.'),
  ('00000000-0000-4000-8000-000000002579', '生のやさいはにが手です。', 'I don''t like raw veggies.'),
  ('00000000-0000-4000-8000-000000002579', '生ビール一ちょう、下さーい。', 'Give me a draft beer!'),
  ('00000000-0000-4000-8000-000000002579', 'ビートルズは生でみれたらいいな〜。', 'If only I could have seen the Beatles live!'),
  ('00000000-0000-4000-8000-000000002580', 'あしたはかぞくみんなで田をたがやします。', 'Tomorrow we’re tilling the rice field with the whole family.'),
  ('00000000-0000-4000-8000-000000002580', 'そのフランス人は四十ユーロで田を一つかいました。', 'That French person purchased a rice field for 40 euros.'),
  ('00000000-0000-4000-8000-000000002580', 'わたしのファーストキスは、田んぼのかかしにうばわれた。', 'My first kiss was stolen by a scarecrow in a rice paddy.'),
  ('00000000-0000-4000-8000-000000002581', 'テーブルに、白のおさらをならべてください。', 'Can you put the white dishes on the table?'),
  ('00000000-0000-4000-8000-000000002581', '七つの石のうち、三つは白でした。', 'Three out of seven stones were white.'),
  ('00000000-0000-4000-8000-000000002581', 'そのおとこは、ゆきのように白いので、白ゆきおとことなづけられた。', 'The man was as white as snow, so he was named "Snow White."'),
  ('00000000-0000-4000-8000-000000002582', '白人だんせいとけっこんしました。', 'I married a white man.'),
  ('00000000-0000-4000-8000-000000002582', 'わたしはケニア出しんのこく人ですが、アメリカの白人かぞくにそだてられました。', 'I am black and from Kenya, but I was raised by a white family in America.'),
  ('00000000-0000-4000-8000-000000002582', 'おおくの白人たちは、日本のなつが大のにが手だ。', 'Many caucasians hate summer in Japan.'),
  ('00000000-0000-4000-8000-000000002583', 'はなこさんの目はいいですか？ ', 'Does Hanako have good eyes?'),
  ('00000000-0000-4000-8000-000000002583', 'アメリカには目が三つある人々がすんでいる山があって、そこではまいとし二月八日におまつりがある。', 'In America, there is a mountain where people with three eyes live and they hold a festival on February 8th every year.'),
  ('00000000-0000-4000-8000-000000002583', 'うつくしいあおい目のおとこが大すき！', 'I love men with beautiful blue eyes!'),
  ('00000000-0000-4000-8000-000000002584', 'このじゃがいもを、ゆきだるまの目玉にします。', 'Saya akan menggunakan kentang ini untuk bola mata manusia salju.'),
  ('00000000-0000-4000-8000-000000002584', '王女は目玉をコレクションするしゅみがあります。', 'Hobi sang putri adalah mengoleksi bola mata.'),
  ('00000000-0000-4000-8000-000000002584', 'ようかいの目玉のようなぶどうだとおもう。', 'Menurutku buah anggur ini terlihat seperti bola mata monster.'),
  ('00000000-0000-4000-8000-000000002585', '人にむかって石をなげるんじゃない。', 'Anda tidak boleh melempari orang dengan batu.'),
  ('00000000-0000-4000-8000-000000002585', '石が一つくつに入った。', 'Sebuah batu masuk ke dalam sepatuku.'),
  ('00000000-0000-4000-8000-000000002585', '石と石がぶつかるおとにいらいらする。', 'Suara batu bertabrakan membuatku kesal.'),
  ('00000000-0000-4000-8000-000000002586', 'あそこに立っているのは、ぼくのあにです。', 'That person standing over there is my brother.'),
  ('00000000-0000-4000-8000-000000002586', 'その石の上に立ってください。', 'Please stand on the stone.'),
  ('00000000-0000-4000-8000-000000002586', 'あそこに立っているのが、あなたのみらいの子どもです。', 'The person standing over there is your future child.'),
  ('00000000-0000-4000-8000-000000002587', 'ロウソクは、なん本立てますか？ ', 'How many candles will you put out?'),
  ('00000000-0000-4000-8000-000000002587', 'このしゃしん立てを立てるためのスタンドをさがしています。', 'I’m looking for an easel to stand this photo frame up on.'),
  ('00000000-0000-4000-8000-000000002587', 'ぼくのつくえにえんぴつを立ててくれませんか？', 'Could you please stand some pencils up on my desk?'),
  ('00000000-0000-4000-8000-000000002588', 'わたしのぜんざいさんは一万円です。', 'Ten thousand yen is all I have.'),
  ('00000000-0000-4000-8000-000000002588', '一万RTいったら、こく白します。', 'If this gets ten thousand retweets, I''ll confess my love.'),
  ('00000000-0000-4000-8000-000000002588', 'ちくしょう！にせの一万円さつをつかまされた。', 'Crap! I was cheated into accepting a fake 10,000 yen bill.'),
  ('00000000-0000-4000-8000-000000002589', 'このぶどうは二万円もしました。', 'These grapes were 20,000 yen!'),
  ('00000000-0000-4000-8000-000000002589', '二万フォロワーおめでとうございます。', 'Congratulations on twenty thousand followers!'),
  ('00000000-0000-4000-8000-000000002589', '二万ドルかけるよ。', 'I will bet twenty thousand dollars.'),
  ('00000000-0000-4000-8000-000000002590', 'パチンコで十万円かちました。', 'I won one hundred thousand yen at pachinko.'),
  ('00000000-0000-4000-8000-000000002590', 'このアイフォンは、十万六千九ひゃく円でした。', 'This iPhone cost me 106,900 yen.'),
  ('00000000-0000-4000-8000-000000002590', 'ウォッカをのむと、すう十万でん子ボルトものエネルギーがみなぎってくる。', 'Whenever I drink vodka, I get pumped full of hundreds of thousands of electron volts.'),
  ('00000000-0000-4000-8000-000000002593', '今、しんぶんをよんでいます。', 'I’m reading the newspaper right now.'),
  ('00000000-0000-4000-8000-000000002593', 'おれは今までなにをしていたんだ。', 'What was I doing until now?'),
  ('00000000-0000-4000-8000-000000002593', '今から、ヘルメットにおはようといいます。', 'Now I’m going to say good morning to my helmet.'),
  ('00000000-0000-4000-8000-000000002594', '今日のしゅくだいは、二十一ページの二ばんです。', 'Today’s homework is question two on page twenty-one.'),
  ('00000000-0000-4000-8000-000000002594', '今日はいつもよりうり上げが少ない。', 'Today''s sales are less than usual.'),
  ('00000000-0000-4000-8000-000000002594', 'あら、今日が私のたん生日だったんですか？', 'Oh, was today my birthday?'),
  ('00000000-0000-4000-8000-000000002595', '今月は大切なテストがあります。', 'There''s an important test this month.'),
  ('00000000-0000-4000-8000-000000002595', '今月の十日までにやってください。', 'Please do this by the tenth of this month.'),
  ('00000000-0000-4000-8000-000000002595', '今月は、シアトル市にいます。', 'I''ll be in Seattle this month.'),
  ('00000000-0000-4000-8000-000000002596', 'きのう、元つまにあってきました。', 'Yesterday, I ran into my ex-wife.'),
  ('00000000-0000-4000-8000-000000002596', '元のきじはけされてしまいました。', 'The original article was deleted.'),
  ('00000000-0000-4000-8000-000000002596', '元は月の出しんなんです。', 'I’m originally from the moon.'),
  ('00000000-0000-4000-8000-000000002597', 'この本を半分までよみました。', 'I’ve read halfway through this book.'),
  ('00000000-0000-4000-8000-000000002597', 'このクラスのがくせいの半分は女子です。', 'Half of this class''s students are girls.'),
  ('00000000-0000-4000-8000-000000002597', 'ざっくり日本人の半分ぐらいは、にんじゃです。', 'Roughly half of all Japanese people are ninjas.'),
  ('00000000-0000-4000-8000-000000002598', 'おいしいかどうか分かりません。', 'I don’t know if this tastes good.'),
  ('00000000-0000-4000-8000-000000002598', '分かるような、分からないような。', 'I kind of got it, but I am not sure if I understood all of it.'),
  ('00000000-0000-4000-8000-000000002598', '日本ごは分かりますか？', 'Do you understand Japanese?'),
  ('00000000-0000-4000-8000-000000002599', 'このにくまんを二人で分けましょう。', 'Let’s split this meat bun between two people.'),
  ('00000000-0000-4000-8000-000000002599', '生しを分けるけつだんになった。', 'It was a decision that spelt the difference between life and death.'),
  ('00000000-0000-4000-8000-000000002599', 'ピザを半分に分けるなら、大きい方を下さい。', 'If you split the pizza, could you give me the bigger half?'),
  ('00000000-0000-4000-8000-000000002600', 'その玉ねぎは女王の分だ。', 'That onion is the queen''s portion. '),
  ('00000000-0000-4000-8000-000000002600', 'このウィスキーのアルコール分は四十パーセントです。', 'The alcohol content of this whisky is forty percent.'),
  ('00000000-0000-4000-8000-000000002600', 'この市はシアトル市の3分の1の大きさです。', 'This city is one-third the size of Seattle.'),
  ('00000000-0000-4000-8000-000000002601', 'テープが切れてしまいました。', 'The tape was cut.'),
  ('00000000-0000-4000-8000-000000002601', 'でんわが切れるおとをきくとさみしくなる。', 'I feel lonely when I hear the sound of the phone being cut off.'),
  ('00000000-0000-4000-8000-000000002601', '糸が切れてしまいました。', 'The thread snapped.'),
  ('00000000-0000-4000-8000-000000002602', 'これは、メアリーが大切にしている人ぎょうです。', 'This is the doll that Mary treats with a great deal of care.'),
  ('00000000-0000-4000-8000-000000002602', 'そばにいてくれる友人やこい人、かぞくを大切にした方がいいですよ。', 'You should cherish your friends, partner, and family who stand by you.')
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES
  ('00000000-0000-4000-8000-000000002602', '大切なしょるいときくと、いつも中みをみたくなる。', 'Whenever I hear that a document is very important, I always want to look at what’s inside.'),
  ('00000000-0000-4000-8000-000000002603', 'つぎに、かみをハサミで切ります。', 'Next, you will cut the paper with your scissors.'),
  ('00000000-0000-4000-8000-000000002603', 'いとを切るはさみをさがしています。', 'I''m looking for scissors that cut thread.'),
  ('00000000-0000-4000-8000-000000002603', 'うっかりかみのけをみじかく切りすぎちゃったけど、そのあといぜんよりもよくナンパされるようになった。', 'Even though I accidentally cut my hair shorter than I intended, more people have been flirting with me since.'),
  ('00000000-0000-4000-8000-000000002604', '友人のけっこんしきで、とうきょうにいっていました。', 'I went to Tokyo for my friend’s wedding.'),
  ('00000000-0000-4000-8000-000000002604', 'さらい月、アメリカ人の友人が日本にあそびにきてくれます。', 'An American friend will come to Japan to visit me the month after next.'),
  ('00000000-0000-4000-8000-000000002604', 'あにの友人に、こく白された。', 'My brother’s friend told me he has feelings for me.'),
  ('00000000-0000-4000-8000-000000002605', '山田さんのまゆげはとても太いです。', 'Alis Yamada sangat tebal.'),
  ('00000000-0000-4000-8000-000000002605', 'このおみせのめんはおもったより太かったです。', 'Mie di toko ini lebih kental dari yang saya kira.'),
  ('00000000-0000-4000-8000-000000002605', 'おれの母ちゃんは、ちょう太いんだぜ。', 'Ibuku sangat gemuk.'),
  ('00000000-0000-4000-8000-000000002606', 'さいきん、たべすぎで少し太りました。', 'Akhir-akhir ini aku menjadi sedikit gemuk karena makan berlebihan.'),
  ('00000000-0000-4000-8000-000000002606', 'たべても太らない人がうらやましい。', 'Aku iri pada orang yang tidak gemuk meski makannya banyak.'),
  ('00000000-0000-4000-8000-000000002606', '太れば太るほど、わたしはおなかがすく。', 'Semakin gemuk saya, semakin saya lapar.'),
  ('00000000-0000-4000-8000-000000002607', 'ぎゅうにゅうは、少ししかありません。', 'There is only little milk.'),
  ('00000000-0000-4000-8000-000000002607', '少ししかのこってないよ。', 'There are only a few left.'),
  ('00000000-0000-4000-8000-000000002607', 'かれのプロポーズは少しあいまいだった。', 'His proposal was a little vague.'),
  ('00000000-0000-4000-8000-000000002608', 'ひゃくさいまで生きる人は少ない。', 'There are few people who live to be 100 years old.'),
  ('00000000-0000-4000-8000-000000002608', 'りょうりのレパートリーが少ないんです。', 'I don''t know how to cook many things.'),
  ('00000000-0000-4000-8000-000000002608', 'びようしさんから、かみのけが少ないとよくいわれます。', 'I’m often told by hairdressers that I don’t have much hair.'),
  ('00000000-0000-4000-8000-000000002609', '十引く四は六です。', 'Sepuluh dikurangi empat sama dengan enam.'),
  ('00000000-0000-4000-8000-000000002609', 'どうせ、女のきを引くためにいってるだけでしょう。', 'Dia mungkin mengatakan hal itu hanya untuk menarik perhatian para gadis.'),
  ('00000000-0000-4000-8000-000000002609', '引きがねを引いて、フライパンをうった。', 'Saya menarik pelatuknya dan menembak penggorengan.'),
  ('00000000-0000-4000-8000-000000002610', 'せつなさで、心がしめつけられた。', 'My heart constricted with longing.'),
  ('00000000-0000-4000-8000-000000002610', 'おもわず心の中でさけんでしまった。', 'I couldn''t help shouting in my mind.'),
  ('00000000-0000-4000-8000-000000002610', 'もしアンパンマンがれいこくな心をもっていたらどうしよう。', 'I wouldn’t know what to do if Anpanman had a cruel heart.'),
  ('00000000-0000-4000-8000-000000002611', '戸口に手ぶくろがおちていました。', 'Sebuah sarung tangan dijatuhkan di ambang pintu.'),
  ('00000000-0000-4000-8000-000000002611', 'たまたま、戸口でぬすみぎきしてしまったんです。', 'Saya mengupingnya di ambang pintu secara tidak sengaja.'),
  ('00000000-0000-4000-8000-000000002611', '戸口に三枚のトーストがあった。', 'Ada tiga potong roti panggang di ambang pintu saya.'),
  ('00000000-0000-4000-8000-000000002612', 'どちらの方がすきですか。', 'Which one do you prefer?'),
  ('00000000-0000-4000-8000-000000002612', 'あちらの方に行ってください 。', 'Please go that direction.'),
  ('00000000-0000-4000-8000-000000002612', 'かの女のわらい方がきらいだ。', 'I don’t like the way she laughs.'),
  ('00000000-0000-4000-8000-000000002613', 'あかしんごうで、くるまは止まりました。', 'The car stopped at the red signal.'),
  ('00000000-0000-4000-8000-000000002613', '心ぞうが止まるかとおもった。', 'I was so surprised I thought my heart leapt into my mouth.'),
  ('00000000-0000-4000-8000-000000002613', 'こおりの上で、止まることができなかった。', 'I couldn’t stop on the ice.'),
  ('00000000-0000-4000-8000-000000002614', 'おんがくを止めてください。', 'Stop the music please.'),
  ('00000000-0000-4000-8000-000000002614', '三びょうかんいきを止めてください。', 'Please hold your breath for 3 seconds.'),
  ('00000000-0000-4000-8000-000000002614', 'かれがはしりさるのを止めるひつようがある。', 'We need to stop him from running away.'),
  ('00000000-0000-4000-8000-000000002615', 'やきゅうのしあいは、あめで中止になりました。', 'The baseball game was called off due to rain.'),
  ('00000000-0000-4000-8000-000000002615', 'ざんねんですが、このきかくはいったん中止することになりました。', 'Sorry, but it was decided that this project will be canceled for now.'),
  ('00000000-0000-4000-8000-000000002615', 'たのしみにしていた生ほうそうが中止になった。', 'The live show I had been looking forward to was canceled.'),
  ('00000000-0000-4000-8000-000000002616', 'あしの毛がボーボーです。', 'Bulu kakiku lebat.'),
  ('00000000-0000-4000-8000-000000002616', 'うちの犬の毛はよくぬける。', 'Bulu anjing kami banyak rontok.'),
  ('00000000-0000-4000-8000-000000002616', '今一ばん大切なのはあたまの毛だ。', 'Saat ini hal terpenting bagi saya adalah rambut di kepala saya.'),
  ('00000000-0000-4000-8000-000000002617', '父がいるから、さびしくありません。', 'I’m not lonely because my father is here.'),
  ('00000000-0000-4000-8000-000000002617', 'わたしの父は、ドイツ人です。', 'My father is German.'),
  ('00000000-0000-4000-8000-000000002617', '父はうしのちちをしぼるのがうまい。', 'My father is very good at milking cows.'),
  ('00000000-0000-4000-8000-000000002618', 'お父さんはまい日リンゴをたべます。', 'My father eats an apple every day.'),
  ('00000000-0000-4000-8000-000000002618', 'お父さんにだって分からないことはある。', 'Even your father has something he doesn''t understand. '),
  ('00000000-0000-4000-8000-000000002618', 'お父さんのねこはかわいい。', 'My dad’s cat is adorable.'),
  ('00000000-0000-4000-8000-000000002619', 'きょうこさんは牛をかっているらしい。', 'Apparently Kyoko is raising a cow.'),
  ('00000000-0000-4000-8000-000000002619', 'デイブは、牛ですよ。', 'Dave is a cow.'),
  ('00000000-0000-4000-8000-000000002619', 'かの女は、牛がらのドレスをきて、牛どんやに行ってきました。', 'She came to a gyudon restaurant in a cow-spot patterned dress.'),
  ('00000000-0000-4000-8000-000000002620', '山下さんはわたしの兄ににていますね。', 'You look like my older brother, Mr. Yamashita.'),
  ('00000000-0000-4000-8000-000000002620', '一ヶ月まえに兄がくろラブをつれていえにかえってきました。', 'A month ago, my older brother came home with a black labrador.'),
  ('00000000-0000-4000-8000-000000002620', '兄は、とうふにコーヒーをかけてたべるのがすきだ。', 'My older brother likes eating tofu covered in coffee.'),
  ('00000000-0000-4000-8000-000000002621', 'どれがたかしのお兄さんですか。', 'Which one is Takashi’s older brother?'),
  ('00000000-0000-4000-8000-000000002621', '今日のたっきゅうびんのお兄さんのかおがタイプすぎた。', 'The delivery guy today had exactly the type of face I go for.'),
  ('00000000-0000-4000-8000-000000002621', 'お兄さんのはなげがきになってしかたがない。', 'I can’t help thinking about my older brother’s nose hair.'),
  ('00000000-0000-4000-8000-000000002622', 'ことしの冬は、ゆきがたくさんふりました。', 'It snowed a lot this winter.'),
  ('00000000-0000-4000-8000-000000002622', 'きょねんの冬にかいたえです。', 'It''s an illustration I drew last winter.'),
  ('00000000-0000-4000-8000-000000002622', '冬をなめるといたい目にあうぞ！', 'Don’t make light of winter or you’re sure to have a painful experience.'),
  ('00000000-0000-4000-8000-000000002623', 'えきの北には、びょういんがあります。', 'There is a hospital on the north side of the station.'),
  ('00000000-0000-4000-8000-000000002623', '北ちょうせんが又ミサイルをはっしゃした。', 'North Korea launched a missile again.'),
  ('00000000-0000-4000-8000-000000002623', '北アメリカのゆうれいはとてもこわい。', 'The ghosts in North America are so scary.'),
  ('00000000-0000-4000-8000-000000002624', 'わたしはこのえいがを三かい半みました。', 'I’ve watched this movie three and a half times.'),
  ('00000000-0000-4000-8000-000000002624', 'JLPTまであと一ヵ月半しかありません。', 'There is only a month and a half left until the JLPT.'),
  ('00000000-0000-4000-8000-000000002624', 'かの女は半じゅくたまごのようにかわいいね。', 'She is as cute as a half-cooked egg.'),
  ('00000000-0000-4000-8000-000000002625', 'そのふくは古いので、もういりません。', 'Those clothes are old, so I don’t need them anymore.'),
  ('00000000-0000-4000-8000-000000002625', '古いものにしがみついていては、あたらしいものをうけとることができません。', 'If you hold onto old stuff, you can''t get anything new.'),
  ('00000000-0000-4000-8000-000000002625', 'ガレージで、古いパンツをみつけた。', 'I found an old pair of underwear in our garage.'),
  ('00000000-0000-4000-8000-000000002626', '中古ですが、ベンツをかいました。', 'It’s used, but I bought a Benz.'),
  ('00000000-0000-4000-8000-000000002626', 'このあたりは、中古ショップがじゅうじつしています。', 'There are a lot of secondhand stores in this area. '),
  ('00000000-0000-4000-8000-000000002626', '中古のかぐのような人とはけっこんしたくない。', 'I don’t want to get married to someone who is like a piece of used furniture.'),
  ('00000000-0000-4000-8000-000000002627', 'このテレビは、一台四万九千円です。', 'These televisions are forty-nine thousand yen each.'),
  ('00000000-0000-4000-8000-000000002627', '今はパソコン一台でかせぐじだいですからね。', 'We''re living in an era where you can make a living with a single computer.'),
  ('00000000-0000-4000-8000-000000002627', 'タクシーを一台よんでください。', 'Could you call me a taxi?'),
  ('00000000-0000-4000-8000-000000002628', 'どうしてけいたいを二台もっているんですか。', 'Why do you have two cell phones?'),
  ('00000000-0000-4000-8000-000000002628', 'コウイチの母のいえには、ピアノが二台ある。', 'There are two pianos at Koichi''s mom''s house.'),
  ('00000000-0000-4000-8000-000000002628', 'うちのトイレにはテレビが二台しかない。', 'There are only two televisions in our bathroom.'),
  ('00000000-0000-4000-8000-000000002629', 'たいじゅうけいを五台かいました。', 'I bought five scales.'),
  ('00000000-0000-4000-8000-000000002629', 'あのいえのまえに、パトカーが五台もとまっている。', 'There are five police cars parked in front of that house.'),
  ('00000000-0000-4000-8000-000000002629', '五台のバンがげきとつしてめりこんだ。', 'The five vans smashed into each other.'),
  ('00000000-0000-4000-8000-000000002630', 'パソコンを十台ちゅう文しました。', 'We ordered ten computers.'),
  ('00000000-0000-4000-8000-000000002630', 'ぼうはんカメラを十台せっちしました。', 'We installed ten surveillance cameras.'),
  ('00000000-0000-4000-8000-000000002630', 'たんじょう日にはでんたくが十台ほしい。', 'I want ten calculators for my birthday.'),
  ('00000000-0000-4000-8000-000000002631', '外でまちましょう。', 'Let’s wait outside.'),
  ('00000000-0000-4000-8000-000000002631', 'ねこたちは、まどの外にいるとりをジーッとみています。', 'The cats are staring at the bird outside of the window.'),
  ('00000000-0000-4000-8000-000000002631', '今日は一日中外であくびをしていた。', 'I kept yawning outside all day today.'),
  ('00000000-0000-4000-8000-000000002632', '田中さんのむすめさんは外人さんとけっこんしたんだよ。', 'Tanaka’s daughter got married to a foreigner.'),
  ('00000000-0000-4000-8000-000000002632', 'でんしゃでよっぱらった外人にからまれた。', 'A drunk foreigner tried to pick a fight with me on the train.'),
  ('00000000-0000-4000-8000-000000002632', '日本人と外人のあしのながさはかなりちがう。', 'Leg length is quite different between Japanese people and foreigners.'),
  ('00000000-0000-4000-8000-000000002633', 'かれはまち外れの小さないえにすんでいます。', 'He lives in a small house in the outskirts of town.'),
  ('00000000-0000-4000-8000-000000002633', '王女は、きせつ外れのドレスをきていた。', 'The princess was wearing a dress that doesn''t suit the season.'),
  ('00000000-0000-4000-8000-000000002633', '「あたりが出ると、もう一本」とかかれたアイスをかったが、ぜんぶ外れだった。', 'I bought some ice cream that had, "If you hit, you get another" written on them, but they were all misses.'),
  ('00000000-0000-4000-8000-000000002634', 'あみ戸が外れてしまいました。', 'The sliding door came off.'),
  ('00000000-0000-4000-8000-000000002634', 'けがをして、スタメンから外れることになっちゃったんだ。', 'I got injured, so I''m going to be taken off the starting players.'),
  ('00000000-0000-4000-8000-000000002634', 'プラグが外れたので、Mr.ロボットはありがとうといえなくなった。', 'Since the plug was disconnected, Mr. Robot was no longer able to say, "thank you," anymore.'),
  ('00000000-0000-4000-8000-000000002635', '大阪市で生まれました。', 'Saya lahir di Kota Osaka.'),
  ('00000000-0000-4000-8000-000000002635', '市のあたらしいマスコットキャラクターがけっていしました。', 'Maskot baru kota telah diputuskan.'),
  ('00000000-0000-4000-8000-000000002635', 'きょうとの市バスの中で、はいてしまった。', 'Saya muntah di bus kota Kyoto.'),
  ('00000000-0000-4000-8000-000000002636', 'そぼは市立びょういんに入いんしています。', 'Nenek saya dirawat di rumah sakit di rumah sakit kota.'),
  ('00000000-0000-4000-8000-000000002636', '市立としょかんまでのみちをおしえてください。', 'Tolong beritahu saya arah ke perpustakaan kota.'),
  ('00000000-0000-4000-8000-000000002636', '大さか市立大がくのまえでさか立ちをした。', 'Saya berdiri tegak di depan Universitas Kota Osaka.'),
  ('00000000-0000-4000-8000-000000002637', '今はシアトル市にすんでいます。', 'Saya tinggal di Seattle sekarang.'),
  ('00000000-0000-4000-8000-000000002637', 'わたしのお母さんは、シアトル市でそだちました。', 'Ibu saya dibesarkan di Seattle.'),
  ('00000000-0000-4000-8000-000000002637', 'あなたのへんがおしゃしんを、シアトル市におくります。', 'Aku akan mengirimkan foto lucumu itu ke Seattle.'),
  ('00000000-0000-4000-8000-000000002638', '友だちのへやは、広くてきれいです。', 'My friend’s room is spacious and clean.'),
  ('00000000-0000-4000-8000-000000002638', 'あのフランス人はおでこが広い。', 'That French person has a wide forehead.'),
  ('00000000-0000-4000-8000-000000002638', 'すげー広いな！', 'Wow, this place is huge!'),
  ('00000000-0000-4000-8000-000000002639', '母はタクシーにのりました。', 'My mother got in a taxi.'),
  ('00000000-0000-4000-8000-000000002639', 'いもうとは、どんどん母ににてきました。', 'My younger sister is getting to look like our mother more and more.'),
  ('00000000-0000-4000-8000-000000002639', '母はとうふとふぐがすきだ。', 'My mother likes tofu and fugu.'),
  ('00000000-0000-4000-8000-000000002640', 'お母さんはどこ？', 'Where’s mom?'),
  ('00000000-0000-4000-8000-000000002640', 'ひこうき代なら、お母さんが出してあげるよ。', 'I''m your mother, so I can pay for your flight for you.'),
  ('00000000-0000-4000-8000-000000002640', 'お母さんのはなげはながい。', 'My mom’s nose hair is long.'),
  ('00000000-0000-4000-8000-000000002641', 'トーフグににたなまえを用いるものがいます。', 'There is a person who uses a name similar to Tofugu.'),
  ('00000000-0000-4000-8000-000000002641', '北ちょうせんは、かくへいきをおどしに用いる。', 'North Korea uses nuclear weapons to threaten others.'),
  ('00000000-0000-4000-8000-000000002641', 'えをかくために用いるふでで、かの女をくすぐった。', 'I tickled her with a brush used for painting.'),
  ('00000000-0000-4000-8000-000000002642', '今、公用でパリにきています。', 'I’m coming to Paris now on official business.'),
  ('00000000-0000-4000-8000-000000002642', 'これは公用のアカウントです。', 'This is an official account.'),
  ('00000000-0000-4000-8000-000000002642', 'おれたちがぬすむのは公用のかねだ。', 'We’re gonna steal government money.'),
  ('00000000-0000-4000-8000-000000002643', '矢はなん本のこっていますか？', 'Berapa banyak anak panah yang tersisa?'),
  ('00000000-0000-4000-8000-000000002643', 'こいのキューピッドが矢をはなとうとしているよ。', 'Cupid hendak menembakkan panah.'),
  ('00000000-0000-4000-8000-000000002643', 'ほくべい土人の矢じりがとんできた。', 'Mata panah penduduk asli Amerika terbang ke arah saya.'),
  ('00000000-0000-4000-8000-000000002644', 'かとうさんのつぎの休みはいつですか？', 'When is Kato’s next day off?'),
  ('00000000-0000-4000-8000-000000002644', 'ひる休みにカフェでかき氷をたべました。', 'During lunch break, I ate shaved ice at a cafe.'),
  ('00000000-0000-4000-8000-000000002644', '明日は休みなので、一日中一人でマリオカートをする予定です。', 'Tomorrow is my day off, so I’m planning to play Mario Kart by myself for the entire day.'),
  ('00000000-0000-4000-8000-000000002645', 'わたしはいえで休んでいます。', 'I’m resting at home.'),
  ('00000000-0000-4000-8000-000000002645', 'やるときにきちんとやることをやって、休むときはしっかり休んだ方がいいよ。', 'You should rest up well when you can, and then work hard when you have to.'),
  ('00000000-0000-4000-8000-000000002645', '一日で休むことができるのは、トイレに座っている時だけだ。', 'The only time that I rest each day is when I’m sitting on the toilet.'),
  ('00000000-0000-4000-8000-000000002646', 'わたしの大すきなバンドが、かつどうを休止しました。', 'My absolute favorite band is on hiatus.'),
  ('00000000-0000-4000-8000-000000002646', 'パソコンのスリープと休止じょうたいのちがいをおしえてください。', 'Could you tell me the difference between sleep mode and hibernation mode on the computer, please?'),
  ('00000000-0000-4000-8000-000000002646', 'しごとのと中で、小まめに小休止をとってエクササイズをするようにしています。', 'I''m trying to take little breaks and exercise frequently during work.'),
  ('00000000-0000-4000-8000-000000002647', '休日は、えいがを見ることがおおいです。', 'I watched a bunch of movies over the holiday.'),
  ('00000000-0000-4000-8000-000000002647', 'たのしい休日をすごしてくださいね。', 'Have a nice holiday!'),
  ('00000000-0000-4000-8000-000000002647', '休日をツリーハウスで過ごした。', 'I spent the holiday in my tree house.'),
  ('00000000-0000-4000-8000-000000002648', '先ず、下ごしらえをします。', 'First, we do the prep work.'),
  ('00000000-0000-4000-8000-000000002648', '先ず、その五十ねんかけてあつめた切手コレクションからだんしゃりしましょう。', 'Why don''t you declutter the stamp collection you''ve been working on for fifty years first?'),
  ('00000000-0000-4000-8000-000000002648', '先ずは、チキンの羽をむしりとって、それぞれの羽に名前をつけます。', 'First you need to pluck the chicken and then name each of the feathers.'),
  ('00000000-0000-4000-8000-000000002649', 'ペンの先がつぶれた。', 'The tip of the pen got crushed.'),
  ('00000000-0000-4000-8000-000000002649', 'お先にどうぞ。', 'Please go first.'),
  ('00000000-0000-4000-8000-000000002649', 'この先にレストランがある。', 'There''s a restaurant just ahead of us.'),
  ('00000000-0000-4000-8000-000000002649', '先のことはだれにも分かりません。', 'Nobody knows what the future holds.'),
  ('00000000-0000-4000-8000-000000002650', '先々月、キューバにりょこうにいきました。', 'I took a trip to Cuba the month before last.'),
  ('00000000-0000-4000-8000-000000002650', '先々月、シアトル市で大あめがふったせいで、市のめいぶつの玉ねぎばたけがぜんめつしてしまった。', 'Two months ago, due to the heavy rain in the city of Seattle, the city''s famous onion field was entirely destroyed.'),
  ('00000000-0000-4000-8000-000000002650', 'お母さんが先々月の携帯電話代を払ってくれた。', 'My mom paid my cellphone bill the month before last.'),
  ('00000000-0000-4000-8000-000000002651', '先月、田中さんにあいました。', 'I met Tanaka last month.'),
  ('00000000-0000-4000-8000-000000002651', '先月、市立びょういんであなたのお兄さんを見ましたよ。', 'I saw your older brother in the municipal hospital last month.'),
  ('00000000-0000-4000-8000-000000002651', '彼らは先月コスプレパーティーをしました。', 'They had a cosplay party last month.'),
  ('00000000-0000-4000-8000-000000002652', '先日はどうもありがとうございました。', 'Thank you so much for the other day.'),
  ('00000000-0000-4000-8000-000000002652', '先日いった北かいどうのおまつりは二十日かんもつづくものらしい。', 'I heard that the festival I went to the other day in Hokkaido is held for twenty days.'),
  ('00000000-0000-4000-8000-000000002652', '彼女は先日からずっと病気で寝ていると嘘をついた。', 'She was lying about being sick in bed for a few days.'),
  ('00000000-0000-4000-8000-000000002653', '先生がアンナさんに手がみをかきました。', 'The teacher wrote a letter to Anna.'),
  ('00000000-0000-4000-8000-000000002653', 'ダリン先生のつぎの休みはいつですか？', 'When is Dr. Darin''s next day off?'),
  ('00000000-0000-4000-8000-000000002653', '先生と生徒の恋愛についてどう思いますか？', 'What do you think of love between a student and a teacher?'),
  ('00000000-0000-4000-8000-000000002655', 'かれは、けんどうの名人です。', 'He is a kendo master.'),
  ('00000000-0000-4000-8000-000000002655', 'かの女は、このくにに四人しかいないはいくの名人の一人です。', 'She is one of the four haiku masters in this country.'),
  ('00000000-0000-4000-8000-000000002655', '彼はチェスの名人であるだけでなく、トランプの名人でもある。', 'Not only is he an expert at chess, he’s also a master at cards.'),
  ('00000000-0000-4000-8000-000000002656', 'さくらさんの名字は何といいますか。', 'What is Sakura’s last name?'),
  ('00000000-0000-4000-8000-000000002656', 'コウイチの名字をおしえてくれたら、お礼にてつ人二十八号のフィギュアをあげるよ。', 'If you tell me Koichi''s surname, I will give you a figure of Tetsujin 28 in return.'),
  ('00000000-0000-4000-8000-000000002656', '私の名字はあなたには絶対教えません。', 'I will never tell you my family name.'),
  ('00000000-0000-4000-8000-000000002657', 'もっとていねいに字をかいてください。', 'Please write the character more carefully.'),
  ('00000000-0000-4000-8000-000000002657', '八の字まゆ毛の男せいとけっこんしました。', 'I married a man whose eyebrows are shaped like the character for eight.'),
  ('00000000-0000-4000-8000-000000002657', 'この字は何という意味ですか？', 'What does this character mean?'),
  ('00000000-0000-4000-8000-000000002658', 'この字は太字にしてください。', 'Tolong buat karakter ini berani.'),
  ('00000000-0000-4000-8000-000000002658', 'マンションのエレベーターにのったら、でんこうけいじばんに赤い太字で「じしんです今すぐ外に出てください｣とかひょうじが出てきて、マジびびったよ。', 'Saat aku menaiki lift di apartemenku, muncul pesan tebal berwarna merah yang berbunyi "Gempa bumi! Keluar dari lift ini sekarang juga," di papan buletin listrik sehingga aku menjadi sangat takut.'),
  ('00000000-0000-4000-8000-000000002658', '太字にすることで、その言葉を強調しましょう。', 'Mari kita cetak tebal untuk menambah penekanan.'),
  ('00000000-0000-4000-8000-000000002659', '文字はきいろにしてください。', 'Make this letter yellow, please.'),
  ('00000000-0000-4000-8000-000000002659', 'マイケルは八じかんかけてコウイチにしょうけい文字で手がみをしたためた。', 'Michael took eight hours to write a letter to Koichi in hieroglyphics.'),
  ('00000000-0000-4000-8000-000000002659', 'あなたからのメール、文字化けしちゃったみたいなんだけど、何て書いてたの？', 'It looks like that email from you contained corrupted characters, what did you write?'),
  ('00000000-0000-4000-8000-000000002660', '女の子は、おこって口を一文字にむすびました。', 'The girl got angry and her mouth pursed into a straight line.'),
  ('00000000-0000-4000-8000-000000002660', 'ペーパータオルでさかなの水気をふきとったら、かわに一文字の切り目を入れてください。', 'After wiping moisture off the fish with paper towels, score the skin straight across.'),
  ('00000000-0000-4000-8000-000000002660', '白鳥たちは、うちの風呂場からその湖へ、真一文字になって飛んでいった。', 'The swans flew in a straight line from our bathtub to the lake.'),
  ('00000000-0000-4000-8000-000000002661', 'さいしょの字は、大文字でかいてください。', 'Please capitalize the first letter.'),
  ('00000000-0000-4000-8000-000000002661', 'タイトルを大文字でかき直してください。', 'Please rewrite the title in uppercase letters.'),
  ('00000000-0000-4000-8000-000000002661', '何故だかわからないけど、小文字より大文字の方が好きです。', 'For some reason I like uppercase more than lowercase.'),
  ('00000000-0000-4000-8000-000000002662', '２０１１年に、日本にいきました。', 'I went to Japan in 2011.'),
  ('00000000-0000-4000-8000-000000002662', '主人は、２０１１年から火せいではたらいています。', 'My husband has been working on Mars since 2011.'),
  ('00000000-0000-4000-8000-000000002662', '父は、２０１１年にようやくドラッグの使用を認めました。', 'My father finally admitted to drug use in 2011.'),
  ('00000000-0000-4000-8000-000000002663', '年内には、かんせいするはずです。', 'Ini harus selesai dalam tahun ini.'),
  ('00000000-0000-4000-8000-000000002663', '年内にフォロワー10万人目ざします。', 'Saya menargetkan mencapai 100.000 pengikut pada akhir tahun ini.'),
  ('00000000-0000-4000-8000-000000002663', 'この暗殺は、年内に遂行されなくてはならない。', 'Pembunuhan harus dilakukan sebelum tahun ini berakhir.'),
  ('00000000-0000-4000-8000-000000002664', 'この町のそらは、年中どんよりしています。', 'The sky in this town is overcast all year.'),
  ('00000000-0000-4000-8000-000000002664', 'トーフグのしゃいんは、二十四じかん年中むきゅうではたらいている。', 'Tofugu employees work twenty four seven, year round.'),
  ('00000000-0000-4000-8000-000000002664', 'この国では一年中雨が降るんだが、妻もまた年中その文句を言うんだ。', 'It rains year round in this country and my wife complains about it year round as well.'),
  ('00000000-0000-4000-8000-000000002665', '川下さんは、小学一年生のおとうとがいます。', 'Kawashita has a brother who is a first year student in elementary school.'),
  ('00000000-0000-4000-8000-000000002665', 'ことしの四月、わたしは中学一年生になり、わたしのいもうとは小学一年生、兄はこうこう一年生、母と父は大学一年生になります。', 'This April, I’m starting the first year of middle school, my little sister is starting the first year of elementary school, my older brother is starting the first year of high school, and my mother and father are starting the first year of university.'),
  ('00000000-0000-4000-8000-000000002665', 'まだ小学一年生が学ぶ漢字ですら知りません。', 'I haven’t even learned the kanji that first grade elementary school students know yet.'),
  ('00000000-0000-4000-8000-000000002666', '少年は、やきゅうが大すきでした。', 'The boy loved baseball.'),
  ('00000000-0000-4000-8000-000000002666', 'けいさつかんは、一ぱんてきに、少年はんざいのかがいしゃを、けいさつの少年かにれんこうします。', 'Police officers generally bring young offenders in to the police department''s juvenile division.'),
  ('00000000-0000-4000-8000-000000002666', '私は腕白な少年ではなく、気が弱くて無口な少年でした。', 'I wasn''t a naughty boy, but a dimwitted and hesitant one.'),
  ('00000000-0000-4000-8000-000000002667', '去年の四月に日本にきました。', 'I came to Japan in April of last year.'),
  ('00000000-0000-4000-8000-000000002667', '去年、はじめて夏コミにさんせんしました。', 'Last year, I participated in the Summer Comiket for the first time.'),
  ('00000000-0000-4000-8000-000000002667', '彼はハンバーガーを毎日食べるので、去年よりも太ってしまった。', 'He is fatter than he was last year because he eats hamburgers every day.'),
  ('00000000-0000-4000-8000-000000002668', 'よていより、十五分早くつきました。', 'We arrived 15 minutes earlier than scheduled.'),
  ('00000000-0000-4000-8000-000000002668', 'かの女にこく白するのはまだ早いとおもうんだ。', 'I think it''s too early to ask her out.'),
  ('00000000-0000-4000-8000-000000002668', '豆腐屋さんの朝はいつも早い。', 'A tofu maker always wakes up early in the morning.'),
  ('00000000-0000-4000-8000-000000002669', '早々におへんじいただきありがとうございます。', 'Thank you for your prompt reply.'),
  ('00000000-0000-4000-8000-000000002669', '年まつだからか、人々が早々とすぎさっていく。', 'I wonder if this is because it''s the end of year, but people are passing by quickly.'),
  ('00000000-0000-4000-8000-000000002669', '新年早々、借金を催促されるなんてひどすぎる。', 'It’s too cruel to demand money right after the start of the new year.')
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES
  ('00000000-0000-4000-8000-000000002670', 'かのじょはとつぜん、気をうしなった。', 'She suddenly lost consciousness.'),
  ('00000000-0000-4000-8000-000000002670', '気をつけてかえってきてね。', 'Please come back safe.'),
  ('00000000-0000-4000-8000-000000002670', 'おまえ、気は確かか？', 'Are you out of your mind?'),
  ('00000000-0000-4000-8000-000000002671', 'このぼうし、とっても気に入りました。', 'I’m very happy with this hat.'),
  ('00000000-0000-4000-8000-000000002671', '玉ねぎ王子に気に入ってもらうために、アメリカ中の玉ねぎをかいしめて玉ねぎごてんをたてました。', 'In order to please Prince Onion, I bought all the onions in America and built an onion palace.'),
  ('00000000-0000-4000-8000-000000002671', '君の新しい子犬が気に入ってもらえるといいんだけど。', 'I hope you’re happy with your new puppy.'),
  ('00000000-0000-4000-8000-000000002672', 'にがいくすりを一気にのみほしました。', 'I drank the bitter medicine down in one gulp.'),
  ('00000000-0000-4000-8000-000000002672', '元気そうな父のかおを見たら、一気に気がぬけました。', 'It was such a relief to see my father, who looked well.'),
  ('00000000-0000-4000-8000-000000002672', '僕のひいお婆さんは、ぎょう子を二百こ一気にたべた。', 'My great-grandma ate two hundred gyoza in one sitting.'),
  ('00000000-0000-4000-8000-000000002673', '今日はあさから気分がいいです。', 'I’ve been feeling great since this morning.'),
  ('00000000-0000-4000-8000-000000002673', 'なんとなくピクニックに出かけたい気分です。', 'I feel like going on a picnic now.'),
  ('00000000-0000-4000-8000-000000002673', '君が僕と結婚してくれたら、残りの人生ずっといい気分ですごせると思うよ。', 'If you marry me, I think I’ll be in a good mood for the rest of my life.'),
  ('00000000-0000-4000-8000-000000002674', 'このビールはとても人気があります。', 'This beer is very popular.'),
  ('00000000-0000-4000-8000-000000002674', 'あのどう人しの人気のひみつをさぐっている。', 'I am probing into why that doujinshi is so popular.'),
  ('00000000-0000-4000-8000-000000002674', '「私がこの辺りで一番人気の高いベリー採集者であります。」と熊が言った。', '"I am the most popular berry collector around here," said the bear.'),
  ('00000000-0000-4000-8000-000000002675', 'お父さんは、元気ですか。', 'How is your father?'),
  ('00000000-0000-4000-8000-000000002675', 'かなちゃんは、元気いっぱいですね。', 'Kana is full of energy.'),
  ('00000000-0000-4000-8000-000000002675', '彼は元気そうに見えたが、実はひどい下りだったらしい。', 'He seemed fine but apparently he had a bad diarrhea.'),
  ('00000000-0000-4000-8000-000000002676', '今日は天気がわるいです。', 'The weather is bad today.'),
  ('00000000-0000-4000-8000-000000002676', '天気よほうをかくにんしましょう。', 'Let''s check the weather forecast.'),
  ('00000000-0000-4000-8000-000000002676', '天気と気候の違いは何ですか？', 'What’s the difference between weather and climate?'),
  ('00000000-0000-4000-8000-000000002677', 'いつになったら、本気を出すんですか。', 'How soon before you make a serious effort?'),
  ('00000000-0000-4000-8000-000000002677', 'ついにコウイチが本気を出してきた。', 'Koichi is finally getting serious.'),
  ('00000000-0000-4000-8000-000000002677', '私があの男の頭の毛をむしったなんて、本気で思ってないよね？少しは私を信用してよ。', 'You didn’t seriously think I pulled that guy’s hair out, did you? Give me some credit.'),
  ('00000000-0000-4000-8000-000000002678', 'よく平気でいられますね。', 'Kenapa kamu selalu begitu tenang?'),
  ('00000000-0000-4000-8000-000000002678', '王女はペットの子犬をなくしても平気な人です。', 'Sang putri adalah tipe orang yang tidak akan marah meskipun dia kehilangan anak anjing peliharaannya.'),
  ('00000000-0000-4000-8000-000000002678', '夫が会社を首になったが、意外と平気だ。', 'Suamiku dipecat, tapi ternyata aku tetap tenang.'),
  ('00000000-0000-4000-8000-000000002679', 'かれは、とても一本気なせいかくです。', 'He has a really single-minded personality.'),
  ('00000000-0000-4000-8000-000000002679', 'モテないだん子には、じゅんじょうで一本気なおとこがおおい気がする。', 'I feel that many men who are not popular among girls are naive and single-minded.'),
  ('00000000-0000-4000-8000-000000002679', '俺の親友は、とても一本気な男で、90歳になった今でも初恋の女を思い続けている。', 'My best friend has a one-track mind; he’s 90 years old and still has feelings for his first love.'),
  ('00000000-0000-4000-8000-000000002680', 'このCDは、百万まいうれたそうです。', 'I heard that this CD sold a million copies.'),
  ('00000000-0000-4000-8000-000000002680', 'WaniKaniで百万ドルもうけたので、きんでできたトーフグのおきものをつくるつもりです。', 'We are planning to make a Tofugu ornament made of gold with the million dollars we profited from WaniKani.'),
  ('00000000-0000-4000-8000-000000002680', 'AKB48の裁判を見に、百万人の人々が法廷に出席した。', 'A million people attended the AKB48 court case.'),
  ('00000000-0000-4000-8000-000000002681', 'このしりょうを四百枚コピーしてください。', 'Please make four hundred copies of this document.'),
  ('00000000-0000-4000-8000-000000002681', 'アメリカのシアトル市で、一やにして四百人がしっそうするというじけんがあった。', 'There was an incident where 400 people went missing overnight in the city of Seattle in the US.'),
  ('00000000-0000-4000-8000-000000002681', 'いったいどうして四百ドルも一本の爪楊枝を買うのに使ったんだい？', 'How did you spend four hundred dollars on a toothpick?'),
  ('00000000-0000-4000-8000-000000002682', '三月まつまでに、かん字を五百こおぼえてください。', 'Please memorize five hundred kanji by the end of March.'),
  ('00000000-0000-4000-8000-000000002682', '日本には五百円玉というものがあります。', 'Japan has 500-yen coins.'),
  ('00000000-0000-4000-8000-000000002682', '「どうやって五百頭もの馬を車に乗せるっていうの？」と女が聞いた。「そうだよね。代わりにバンを持ってきた方が良かったかな。」と男は答えた。', '"How are we going to get five hundred horses into one car?" asked the woman. "You’re right! Do you think I should have brought the van instead?" the man replied.'),
  ('00000000-0000-4000-8000-000000002683', 'オーブンを、二百どによねつしてください。', 'Please preheat the oven to two hundred degrees.'),
  ('00000000-0000-4000-8000-000000002683', 'フェイスブックで二百もいいねをもらいました。', 'I got two hundred likes on Facebook.'),
  ('00000000-0000-4000-8000-000000002683', '僕は、レジの人に二百ドルをあげて、これで制汗剤を買うように言いました。', 'I gave the cashier two hundred dollars and told her to buy some deodorant.'),
  ('00000000-0000-4000-8000-000000002684', '竹の子をゆでているところです。', 'Saya sedang merebus rebung.'),
  ('00000000-0000-4000-8000-000000002684', 'ふじ山の入り口から北の方にのぼっていくと、と中に竹の子が山のようにとれるところがあります。', 'Jika Anda pergi ke utara dari pintu masuk Gunung Fuji, ada tempat di mana Anda bisa menggali banyak rebung di sepanjang jalan.'),
  ('00000000-0000-4000-8000-000000002684', '「あ、お兄さん。わかりました。わかりました。竹の子、好きなだけ持って行ってください。」とパンダが言った。', 'Ambil semua rebung yang kamu mau,” kata panda.'),
  ('00000000-0000-4000-8000-000000002685', 'このおはしは竹でできています。', 'Sumpit ini terbuat dari bambu.'),
  ('00000000-0000-4000-8000-000000002685', '竹は、一メートルぐらいのたかさまで切ってしまうと、ねまでかれてしまいます。', 'Jika bambu ditebang setinggi sekitar satu meter, bambu tersebut akan mati bahkan akarnya pun layu.'),
  ('00000000-0000-4000-8000-000000002685', '竹細工が本当に好きなんだ！うちのテレビも俺が竹から作ったんだよ。まあ、動かないけどね。でも、見た目がいいんだよ。', 'Saya suka bekerja dengan bambu! Saya membuat televisi saya dari bambu. Itu tidak berhasil, tapi kelihatannya bagus.'),
  ('00000000-0000-4000-8000-000000002686', '糸は、ここにまいてください。', 'Tolong gulung benangnya di sini.'),
  ('00000000-0000-4000-8000-000000002686', 'うんめいの赤い糸をしんじますか？', 'Apakah Anda percaya pada benang merah takdir?'),
  ('00000000-0000-4000-8000-000000002686', '私は足の傷口を縫うのに針と糸を使った。', 'Saya menggunakan jarum dan benang untuk menjahit luka di kaki saya.'),
  ('00000000-0000-4000-8000-000000002687', 'このねこの耳はちゃいろです。', 'Telinga kucing ini berwarna coklat.'),
  ('00000000-0000-4000-8000-000000002687', 'パンの耳はわたしの大こうぶつです。', 'Saya suka kerak roti.'),
  ('00000000-0000-4000-8000-000000002687', 'わたしは、左耳をミミと名付けた。右耳はよく聞こえないので、ママと名付けた。', 'Aku menamai telinga kiriku Mimi. Telinga kananku tidak bisa mendengar dengan baik, jadi aku beri nama Mama.'),
  ('00000000-0000-4000-8000-000000002688', 'かれは、わたしにこっそり耳打ちしました。', 'Dia diam-diam berbisik di telingaku.'),
  ('00000000-0000-4000-8000-000000002688', 'ミーティングのときに、コウイチがニッカになにか耳打ちしてるのをみてしまった。', 'Saya kebetulan menyaksikan Koichi membisikkan sesuatu di telinga Nikka selama pertemuan.'),
  ('00000000-0000-4000-8000-000000002688', '私が彼に、何かセクシーな言葉を耳打ちしてというと、彼は「テープやCDは好きかい？」と囁いてくれた。', 'Saya menyuruhnya untuk membisikkan sesuatu yang seksi di telinga saya dan dia berkata, "Apakah kamu suka kaset dan CD?"'),
  ('00000000-0000-4000-8000-000000002689', '虫はにが手です。', 'Saya tidak suka serangga.'),
  ('00000000-0000-4000-8000-000000002689', 'あの虫、口から白い糸をはいているよ！', 'Serangga itu mengeluarkan benang putih dari mulutnya.'),
  ('00000000-0000-4000-8000-000000002689', 'ううん。その虫は噛まないよ。でも、もし君がそれでもそいつを殺すって言うなら、僕が君のことを噛むよ。', 'Tidak, serangga itu tidak menggigit. Namun, aku akan menggigitmu jika kamu masih membunuhnya.'),
  ('00000000-0000-4000-8000-000000002690', 'ちかくに村があります。', 'Ada sebuah desa di dekatnya.'),
  ('00000000-0000-4000-8000-000000002690', 'あなたのお母さんはこの村で生まれたのよ。', 'Ibumu lahir di desa ini.'),
  ('00000000-0000-4000-8000-000000002690', 'ええ、私はあなたの村で一度本当に馬糞を踏んでしまったんです。', 'Ya, saya pasti pernah menginjak kotoran kuda di desa Anda.'),
  ('00000000-0000-4000-8000-000000002691', '村人は、年よりばかりです。', 'Penduduk desa semuanya adalah orang tua.'),
  ('00000000-0000-4000-8000-000000002691', 'なんかファンタジーゲームの村人っぽいセリフだよね。', 'Kalimat itu seperti sesuatu yang diucapkan penduduk desa di game fantasi, bukan?'),
  ('00000000-0000-4000-8000-000000002691', '悲観主義者は「もうコップ半分しかない」と言うが、その村人は「おかわり！」と言って私を驚かせた。', 'Orang yang pesimis berkata, “gelasnya setengah kosong,” tapi penduduk desa mengejutkan saya dengan berteriak “Isi ulang!”'),
  ('00000000-0000-4000-8000-000000002692', 'あの男はだれですか。', 'Who is that man?'),
  ('00000000-0000-4000-8000-000000002692', '今日は男友だちとパチンコを打ちにいくよていです。', 'I plan to go play pachinko with my guy friends today.'),
  ('00000000-0000-4000-8000-000000002692', '知らない男と花火大会で意気投合した。', 'I developed quite a rapport with a man I didn''t know at a fireworks show.'),
  ('00000000-0000-4000-8000-000000002693', 'この町には、コンビニがおおいです。', 'There are a lot of convenience stores in this town.'),
  ('00000000-0000-4000-8000-000000002693', 'よる、一人でこの町をあるくのはきけんだ。', 'It''s dangerous to walk alone in this town at night.'),
  ('00000000-0000-4000-8000-000000002693', '私の町は、最高のエアギターを作ることで有名です。', 'My town is famous for making the best invisible guitars.'),
  ('00000000-0000-4000-8000-000000002694', 'ヒマワリは、とてもきれいな花です。', 'The sunflower is a very beautiful flower.'),
  ('00000000-0000-4000-8000-000000002694', 'この花の花ことばは、はな毛ボーボーです。', 'In the language of flowers, this one means bushy nose hair.'),
  ('00000000-0000-4000-8000-000000002694', '何か花を使った料理が知りたいんだけど。花のスープとかって聞いたことある？', 'I want to learn how to cook with flowers. Have you ever heard of flower soup?'),
  ('00000000-0000-4000-8000-000000002695', '花火が上がるのはきんよう日だけです。', 'The fireworks are only going off on Friday.'),
  ('00000000-0000-4000-8000-000000002695', '昨日、かぞくで花火大かいに出かけました。', 'I went to see a fireworks display with my family yesterday.'),
  ('00000000-0000-4000-8000-000000002695', '花火ってめっちゃいい匂いだよね？', 'Fireworks have a great smell, don’t they?'),
  ('00000000-0000-4000-8000-000000002696', 'ことしは花見にいかなかった。', 'I didn’t go sakura viewing this year.'),
  ('00000000-0000-4000-8000-000000002696', '北りくち方の花見の名しょをごしょうかいします。', 'I''m gonna introduce you to the best cherry blossom viewing spots in Hokuriku region.'),
  ('00000000-0000-4000-8000-000000002696', '死ぬ前にもう一度花見をしながら宴会がしたいなあ。', 'Before I die, I want to have a drinking party under the cherry blossoms one more time.'),
  ('00000000-0000-4000-8000-000000002697', 'このもんだいでは、えを見ながらしつもんをきいてください。', 'In this problem, please listen to the questions while looking at the pictures. '),
  ('00000000-0000-4000-8000-000000002697', 'その女がのっていた車のうんてん手は、よく見るとわたしの主人でした。', 'When I looked closer, the driver of the car the woman was in was my husband.'),
  ('00000000-0000-4000-8000-000000002697', 'ちょっと僕の手を見て、それが縮んでいるかどうか教えてくれませんか？', 'Can you please look at my hand and tell me if it is shrinking?'),
  ('00000000-0000-4000-8000-000000002698', 'ここから火山が見える。', 'The volcano is visible from here.'),
  ('00000000-0000-4000-8000-000000002698', 'あそこの赤いはたが見えますか。', 'Can you see the red flag over there?'),
  ('00000000-0000-4000-8000-000000002698', '自分が人からどう見えるのかがすごく気になる。', 'I''m really curious about how I seem to others.'),
  ('00000000-0000-4000-8000-000000002699', 'みせの人は、なんのえを女の人に見せましたか？', 'What picture did the shop worker show the woman?'),
  ('00000000-0000-4000-8000-000000002699', '今年のなつは、すはだをチラリと見せるトップスが人気のようです。', 'It seems tops that show a bit of skin are popular this summer.'),
  ('00000000-0000-4000-8000-000000002699', 'もし俺がこのポーカーゲームでかったら、お前らに俺のリザードンのカードを見せてやるよ。', 'If I win this poker game, I’ll show you guys my Charizard card.'),
  ('00000000-0000-4000-8000-000000002700', '本ものかにせものか見分けられない。', 'I can’t tell whether it’s real or fake.'),
  ('00000000-0000-4000-8000-000000002700', 'こい人がサイコパスかどうか見分ける方ほうはありますか？', 'Is there a way to find out if my significant other is a psychopath?'),
  ('00000000-0000-4000-8000-000000002700', '首輪をつけておくべきだったよね。だって、どっちの犬がどっちの犬か見分けるのが難しくなっちゃったよ。', 'We should have put collars on our dogs, because now it''s difficult to tell which one is mine and which one is yours.'),
  ('00000000-0000-4000-8000-000000002701', 'このひょうの見方が分かりません。', 'I don''t know how to look at this chart.'),
  ('00000000-0000-4000-8000-000000002701', 'いろんな見方やとらえ方があります。', 'There are various ways of seeing and understanding.'),
  ('00000000-0000-4000-8000-000000002701', '別の見方をすれば、トーフグは河豚味の豆腐だと考えることもできる。', 'If you look at it from a different point of view, we could consider Tofugu to be tofu that''s fugu flavor.'),
  ('00000000-0000-4000-8000-000000002702', '月見のおだん子をつくっています。', 'I’m making rice dumplings for moon viewing.'),
  ('00000000-0000-4000-8000-000000002702', '今日のよる、友人たちと、お月見をするよていです。', 'I am planning to have a moon viewing party with my friends tonight.'),
  ('00000000-0000-4000-8000-000000002702', 'そ父は、月見の日に餅でのどを詰まらせて死にました。', 'My grandpa passed away from choking on a mochi cake on a moon viewing day.'),
  ('00000000-0000-4000-8000-000000002703', 'かえりに、貝をかってきましょうか。', 'Haruskah saya membeli kerang dalam perjalanan pulang?'),
  ('00000000-0000-4000-8000-000000002703', '貝るいやこうかくるいをたべると、からだがかゆくなります。', 'Badan saya gatal kalau makan kerang.'),
  ('00000000-0000-4000-8000-000000002703', '私は、牡蠣の貝殻の中に置かれていることに気付かずに、婚約指輪を飲み込んでしまった。', 'Saya menelan cincin pertunangan saya karena saya tidak memperhatikan dia memasukkannya ke dalam cangkang tiram.'),
  ('00000000-0000-4000-8000-000000002704', 'その赤のくつをとってください。', 'Please take the red shoes.'),
  ('00000000-0000-4000-8000-000000002704', 'つぎは、まえがみのいろを赤にしようとおもっています。', 'I’m thinking of dyeing my bangs red next time. '),
  ('00000000-0000-4000-8000-000000002704', 'オーランド・ブルームという名前を聞くだけで、今でも頬が赤くなる。', 'My cheeks still go red when I hear the name Orlando Bloom.'),
  ('00000000-0000-4000-8000-000000002705', 'ぶじに、女の赤ちゃんがうまれました。', 'The baby girl was born without complications.'),
  ('00000000-0000-4000-8000-000000002705', 'このかわいい女の子の赤ちゃんの名まえはエマちゃんです。', 'This cute baby girl''s name is Emma.'),
  ('00000000-0000-4000-8000-000000002705', 'あなたの赤ちゃんの頃の写真が見てみたいわ。', 'I want to see a picture of you from when you were a baby.'),
  ('00000000-0000-4000-8000-000000002706', 'これだけで、足りるのかな。', 'I wonder if this much will be enough.'),
  ('00000000-0000-4000-8000-000000002706', 'モナコの王女はせけんしらずなので、車をかうのに十万円もあれば足りるとおもっている。', 'Because the princess in Monaco is ignorant to most things, she thinks that 100,000 yen is enough to buy a car.'),
  ('00000000-0000-4000-8000-000000002706', '今夜、ワインコルクで何か工作をするのに足りるだけのワインを飲むことを誓います。', 'I vow to drink enough wine to make something crafty with the corks tonight.'),
  ('00000000-0000-4000-8000-000000002707', '足にタトゥーがある。', 'I have a tattoo on my leg.'),
  ('00000000-0000-4000-8000-000000002707', 'わたしは子どものとき、手のことを足、足のことを手だとおもっていました。', 'When I was a kid, I thought hands were feet and feet were hands.'),
  ('00000000-0000-4000-8000-000000002707', 'もし私が足を切り落としても、すぐにまた生えてくるんだよね？', 'If I cut off my foot it will grow back soon, right?'),
  ('00000000-0000-4000-8000-000000002708', 'おつりが不足しています。', 'I don’t have enough change.'),
  ('00000000-0000-4000-8000-000000002708', 'しきん不足で中央せいふのきかくしたプロジェクトが中止になった。', 'Due to the lack of funds, the project that the central government planned was suspended.'),
  ('00000000-0000-4000-8000-000000002708', '経験が不足しているうえにいつも寝不足なので、あなたは首です。', 'You are fired because you lack experience and are always sleep deprived.'),
  ('00000000-0000-4000-8000-000000002709', '日よう日に、車でうみにいきました。', 'I went to the ocean in my car on Sunday.'),
  ('00000000-0000-4000-8000-000000002709', 'だれか車出してくれないかな？', 'I wonder if somebody could give us a ride.'),
  ('00000000-0000-4000-8000-000000002709', '私の車は、フロリダまでもたないだろう。', 'My car wouldn’t be able to make it all the way to Florida.'),
  ('00000000-0000-4000-8000-000000002710', 'ちょっと車内でまっていてください。', 'Harap tunggu di mobil sebentar.'),
  ('00000000-0000-4000-8000-000000002710', 'シアトル市のバスの車内にスタバのコップをもったきょどうふしんな外人がいたとおもったら、ただのドバイのイケメン王子さまだった。', 'Ada seorang pria berpenampilan gelisah dengan cangkir Starbucks di dalam bus di Seattle, tapi sebenarnya dia adalah seorang pangeran tampan dari Dubai.'),
  ('00000000-0000-4000-8000-000000002710', '誰かが車内にベーコンをいくつか忘れていったようだ。', 'Sepertinya ada yang meninggalkan daging asap di dalam mobil.'),
  ('00000000-0000-4000-8000-000000002711', 'このアプリは、まだ世に出ていません。', 'This app still isn’t world famous.'),
  ('00000000-0000-4000-8000-000000002711', 'まったく世も末だね。', 'The world really is coming to an end.'),
  ('00000000-0000-4000-8000-000000002711', '暗殺者は別にして、スズメ蜂ほど怖いものはこの世の中にない。', 'Other than assassins, nothing in this world is scarier than wasps.'),
  ('00000000-0000-4000-8000-000000002712', 'かれは、日けいアメリカ人二世の一人です。', 'He’s one of the second generation Japanese-Americans.'),
  ('00000000-0000-4000-8000-000000002712', 'せいこうしている二世タレントは少ない。', 'Not many children of celebrities can be celebrities too.'),
  ('00000000-0000-4000-8000-000000002712', '私は、父が日系イギリス人二世だということを知らなかった。', 'I didn’t know that my father is second generation Japanese-British.'),
  ('00000000-0000-4000-8000-000000002713', 'このスクールには三世の子がたくさんいます。', 'There are many third-generation children in this school.'),
  ('00000000-0000-4000-8000-000000002713', '三世のほとんどはシアトル市生まれです。', 'Most third-generation people were born in Seattle.'),
  ('00000000-0000-4000-8000-000000002713', 'これは、三世のアイデンティティーについての本です。', 'This book is about the identity of the third generation.'),
  ('00000000-0000-4000-8000-000000002714', '主に日本ごをべんきょうしています。', 'I’m mainly studying Japanese.'),
  ('00000000-0000-4000-8000-000000002714', 'ポートランドでは、赤い車と白い車が主にうれています。', 'Primarily red and white cars are sold in Portland.'),
  ('00000000-0000-4000-8000-000000002714', '彼は研究者で、主にバナナに興味があります。', 'He is a researcher who is mainly interested in bananas.'),
  ('00000000-0000-4000-8000-000000002715', 'きのう、ご主人とどこかへいきましたか？', 'Did you and your husband go somewhere yesterday?'),
  ('00000000-0000-4000-8000-000000002715', 'ご主人さま、それは少しかいすぎではないでしょうか。', 'I''m afraid you bought too many of them, master.'),
  ('00000000-0000-4000-8000-000000002715', '私の主人は何の信念も無い政治家なんです。', 'My husband is a politician who doesn’t have any conviction.'),
  ('00000000-0000-4000-8000-000000002716', 'おじぎの仕方をおしえてください。', 'Please teach me how to bow.'),
  ('00000000-0000-4000-8000-000000002716', 'フランス人の友人にフランスしきのあいさつの仕方をおしえてもらいました。', 'My French friend taught me how to greet people in the French way.'),
  ('00000000-0000-4000-8000-000000002716', '「運転の仕方」という本は今年のベストセラーとなった。', '"How to Drive" became a best-selling book this year.'),
  ('00000000-0000-4000-8000-000000002717', 'かれがおこるのは、仕方がないよ。', 'If he’s angry, it can’t be helped.'),
  ('00000000-0000-4000-8000-000000002717', '泣いてばかりいても仕方がないよ。', 'There''s no use in just crying.'),
  ('00000000-0000-4000-8000-000000002717', 'お前は本当に仕方がないやつだ！', 'You’re really hopeless!'),
  ('00000000-0000-4000-8000-000000002718', '他にしつもんはありませんか。', 'Ada pertanyaan lain?'),
  ('00000000-0000-4000-8000-000000002718', 'クラスの他のがく生はぜんぜん大したことのないように見えた。', 'Sepertinya siswa lain di kelas itu tidak hebat.'),
  ('00000000-0000-4000-8000-000000002718', 'この卵をあいつの家に投げるのは、他の日にしようぜ。', 'Mari kita lempar telur-telur ini ke rumahnya suatu hari nanti.'),
  ('00000000-0000-4000-8000-000000002719', '他人のかねにたよるな。', 'Jangan mengandalkan uang orang lain.'),
  ('00000000-0000-4000-8000-000000002719', '他人のあなたには分からないでしょうが、この玉ねぎはわたしのいのちのおん人なんです！', 'Karena kamu adalah orang lain selain diriku, kamu mungkin tidak mengerti, tapi bawang ini adalah penyelamat hidupku.'),
  ('00000000-0000-4000-8000-000000002719', '他人とは思えないほど親切にしてくれたんだけど、単に自分の叔母さんと私を間違えていただけみたい。', 'Dia lebih baik hati padaku daripada yang bisa kuharapkan dari orang asing, tapi itu hanya karena dia mengira aku adalah bibinya.'),
  ('00000000-0000-4000-8000-000000002720', 'もしよければ、代わりましょうか。', 'If you don’t mind, can I take your place?'),
  ('00000000-0000-4000-8000-000000002720', '王子は、けん玉に代わるあたらしいあそびを見つけた。', 'The prince found a new way to amuse himself, replacing kendama.'),
  ('00000000-0000-4000-8000-000000002720', '私はスティーブ・ジョブズに代わる天才を探しています。', 'I am looking for another genius to replace Steve Jobs.'),
  ('00000000-0000-4000-8000-000000002721', 'かれは、一代でここまでかいしゃを大きくした。', 'He made the company this much larger in just one generation.'),
  ('00000000-0000-4000-8000-000000002721', 'コウイチは一世一代の大しょうぶに打って出た。', 'Koichi went to take a once-in-a-lifetime gamble.'),
  ('00000000-0000-4000-8000-000000002721', '彼は一代で巨額の財産を作ったが、彼の息子がさらにそれを二倍にした。', 'He amassed an enormous fortune over the course of his lifetime and his son doubled it.'),
  ('00000000-0000-4000-8000-000000002722', 'サワークリームをヨーグルトで代用しました。', 'I substituted sour cream with yogurt.'),
  ('00000000-0000-4000-8000-000000002722', 'きもののこしひもは、ストッキングでも代用かのうです。', 'You can use stockings as a substitute for the cord you wear under your kimono.'),
  ('00000000-0000-4000-8000-000000002722', '糊がないので飯粒で代用した。', 'We didn’t have glue so we substituted grains of boiled rice for it.'),
  ('00000000-0000-4000-8000-000000002723', 'となりのページに、この字を写してください。', 'Please copy the characters onto the next page of your workbooks.'),
  ('00000000-0000-4000-8000-000000002723', 'ビエトの写す写しんの大ファンです。', 'I''m a big fan of the photos Viet takes.'),
  ('00000000-0000-4000-8000-000000002723', 'お経を書き写すには、千円支払う必要があります。', 'You must pay 1,000 yen in order to transcribe a sutra by hand.'),
  ('00000000-0000-4000-8000-000000002724', 'あなたのお兄さんは、このしゃしんに写っていますか。', 'Is your brother in these pictures?'),
  ('00000000-0000-4000-8000-000000002724', '今年とった五百まいの写しんの内、なんと百三まいの写しんに去年しんだ父のすがたが写っていた。', 'Among the 500 pictures I took this year, 103 of them had my father who had died last year in them.'),
  ('00000000-0000-4000-8000-000000002724', 'この写真に写っている男の人は、私のファーストキスです。', 'The guy in this picture was my first kiss.'),
  ('00000000-0000-4000-8000-000000002725', 'なん号車にのるよていですか。', 'Gerbong kereta mana yang akan Anda naiki?'),
  ('00000000-0000-4000-8000-000000002725', '天才かがくしゃと天才こうがくしゃの手によって、われわれのみらいを百パーセントよそうてきちゅうできるうらないロボットだい一号がかんせいしました。', 'Robot peramal pertama dengan akurasi 100% dibuat oleh seorang ilmuwan jenius dan insinyur jenius.'),
  ('00000000-0000-4000-8000-000000002725', '日本では新聞の号外は大抵無料で配られます。', 'Di Jepang, kami biasanya membagikan terbitan tambahan surat kabar secara gratis.'),
  ('00000000-0000-4000-8000-000000002726', '中央に立っているのが、田中さんのおねえさんです。', 'Itu adalah kakak perempuan Tanaka yang berdiri di tengah.'),
  ('00000000-0000-4000-8000-000000002726', '大さかえきの、中央かいさつ口でまっています。', 'Saya menunggu Anda di gerbang tiket pusat stasiun Osaka.'),
  ('00000000-0000-4000-8000-000000002726', '私の頭の中央部分には小さな凹みがある。', 'Ada sedikit penyok di bagian tengah kepalaku.'),
  ('00000000-0000-4000-8000-000000002727', 'パソコンを、どこか平らなところにおいてください。', 'Tolong letakkan PC Anda di tempat yang datar.'),
  ('00000000-0000-4000-8000-000000002727', 'その女の子は赤のビー玉を八つ平らなところにおいた。', 'Gadis itu meletakkan delapan kelereng merah pada suatu tempat datar.'),
  ('00000000-0000-4000-8000-000000002727', '平らで細長いパスタの名前覚えてない？', 'Ingatkah Anda dengan nama pasta yang tipis, panjang dan pipih?'),
  ('00000000-0000-4000-8000-000000002728', '平日は仕ごとをしています。', 'Saya ada pekerjaan di hari kerja.'),
  ('00000000-0000-4000-8000-000000002728', 'ざんねんだけど、平日だからたぶんいけないなぁ。', 'Sayangnya, saya mungkin tidak bisa pergi karena ini pada hari kerja.'),
  ('00000000-0000-4000-8000-000000002728', '私は料理人で、平日は仕事で忙しいので、家庭ではふだん料理をしません。', 'Saya seorang koki tetapi karena saya sibuk bekerja di hari kerja, saya biasanya tidak memasak di rumah.'),
  ('00000000-0000-4000-8000-000000002729', 'カブレラがホームランを打ちました。', 'Cabrera melakukan home run.'),
  ('00000000-0000-4000-8000-000000002729', 'ぼくの先生は、キーボードを打つのが世かいで一ばんはやい。', 'Guru saya adalah pengetik keyboard tercepat di dunia.'),
  ('00000000-0000-4000-8000-000000002729', 'ママは狂って、人参で僕のおしりを何度もひどく打った。', 'Ibuku menjadi gila dan memukul pantatku dengan wortel.'),
  ('00000000-0000-4000-8000-000000002730', 'ボールは、一打でグリーンにのりました。', 'Bola mendarat di lapangan dalam satu pukulan.'),
  ('00000000-0000-4000-8000-000000002730', 'テニスでは、さいしょの一打を「サービス」とよびます。', 'Dalam tenis, pukulan untuk memulai suatu poin disebut "servis".'),
  ('00000000-0000-4000-8000-000000002730', '一打逆転の大チャンスだ。', 'Hanya satu pukulan saja akan menguntungkan kita.'),
  ('00000000-0000-4000-8000-000000002731', '氷をつくっておいてください。', 'Tolong buatkan esnya.'),
  ('00000000-0000-4000-8000-000000002731', 'タピオカミルクティーを氷ぬきでちゅう文した。', 'Saya memesan bubble tea tanpa es.'),
  ('00000000-0000-4000-8000-000000002731', '「どうしてあの女は俺のグラスに氷を入れるのを忘れたんだ？」「彼女は今日自動車にひかれたんです。きっと飲み物を作っている時にまだふらふらしていたんだと思います。」', '"Kenapa wanita itu lupa menaruh es di gelasku?" "Dia ditabrak mobil tadi hari. Dia pasti masih sedikit pusing saat membuatkan minumanmu."'),
  ('00000000-0000-4000-8000-000000002732', 'かき氷は、あついなつによくたべられます。', 'Saya banyak makan es serut di musim panas.'),
  ('00000000-0000-4000-8000-000000002732', 'この赤いシロップがかかったかき氷はトマトあじです。', 'Es serut dengan sirup merah ini rasa tomat.'),
  ('00000000-0000-4000-8000-000000002732', '世界で一番いい気分になる時は、嫌いなやつに冷たいかき氷をぶちまけてやった時だよ。', 'Perasaan terbaik di dunia adalah ketika kamu melemparkan es serut super dingin dengan sirup pada seseorang yang kamu benci.'),
  ('00000000-0000-4000-8000-000000002733', 'トーフグのコウイチと申します。', 'Saya Koichi dari Tofugu.'),
  ('00000000-0000-4000-8000-000000002733', 'トーフグが日本のわかものにモノ申す！', 'Tofugu memberikan nasihat jujur ​​kepada generasi muda Jepang!'),
  ('00000000-0000-4000-8000-000000002733', '申すまでもなく、私の上司は性転換手術をなされました。今の彼女は大変嬉しいそうだ。', 'Tentu saja bos saya menjalani operasi penegasan gender. Sekarang dia sangat bahagia.'),
  ('00000000-0000-4000-8000-000000002734', '申し申し、花子ちゃん？', 'Halo? Hanako?'),
  ('00000000-0000-4000-8000-000000002734', 'あの、申し申し？きいていますか？？？', 'Hei, halo? Apakah kamu mendengarkan???'),
  ('00000000-0000-4000-8000-000000002734', '「申し申し。鈴木と申しますが、佐藤さんはいらっしゃいますか？」', '"Halo? Ini Suzuki yang menelepon. Bisakah saya berbicara dengan Tuan Satou?"'),
  ('00000000-0000-4000-8000-000000002735', 'にわに、みかんの皮がおちていました。', 'Ada kulit jeruk tergeletak di taman.'),
  ('00000000-0000-4000-8000-000000002735', 'らく天で、天ねんの牛の皮でできた小さいラグをかった。', 'Saya membeli permadani kecil dari kulit sapi alami di Rakuten.'),
  ('00000000-0000-4000-8000-000000002735', '俺のジャケットは、100%竜の皮でできているんだ。', 'Jaket saya terbuat dari 100% kulit naga.'),
  ('00000000-0000-4000-8000-000000002736', 'お皿をあらってから、ベッドにいきました。', 'Aku mencuci piring lalu pergi tidur.'),
  ('00000000-0000-4000-8000-000000002736', 'あとは、この竹の子を皿にもりつければかんせいです。\(*皿* ) ', 'Susun rebung ini di atas piring dan selesai! \(*皿* )')
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES
  ('00000000-0000-4000-8000-000000002736', 'うちのいいお皿を射撃の標的に使うのはやめてくれ！', 'Berhenti menggunakan piring bagus kami untuk latihan sasaran!'),
  ('00000000-0000-4000-8000-000000002737', '小皿をテーブルにならべてください。', 'Silakan letakkan piring-piring kecil di atas meja.'),
  ('00000000-0000-4000-8000-000000002737', 'かくじ、小皿にとり分けてたべましょう。', 'Mengapa kita tidak menyajikan makanan di piring kecil saja dan makan sesuai keinginan kita sendiri?'),
  ('00000000-0000-4000-8000-000000002737', 'このどでかいステーキを、その小皿に載せるのは無理だ。', 'Mustahil untuk menaruh steak sebesar ini di piring kecil itu.'),
  ('00000000-0000-4000-8000-000000002738', 'あなたにお礼をいいたかったんです。', 'Saya ingin mengucapkan terima kasih.'),
  ('00000000-0000-4000-8000-000000002738', 'お礼にビールをもらいました。', 'Saya mendapat bir sebagai ucapan terima kasih.'),
  ('00000000-0000-4000-8000-000000002738', 'この町が平和を取り戻したことについて、スパイダーマンにお礼を言いたい。', 'Saya ingin berterima kasih kepada Spider-Man karena telah kembali turun ke jalan dan membuat kota kita aman kembali.'),
  ('00000000-0000-4000-8000-000000002739', '不正をはたらいたのはだれですか。', 'Who did something dishonest?'),
  ('00000000-0000-4000-8000-000000002739', '中ごくからの不正アクセスにより、トーフグのSNSアカウントがぜんぶのっとられてしまった。', 'There was unauthorized access from China and all of Tofugu''s social media accounts were hacked.'),
  ('00000000-0000-4000-8000-000000002739', '俺の叔母は、いつも自分が今までにした不正やごまかしについて話をする。', 'My aunt always talks about her personal acts of injustice and deception.'),
  ('00000000-0000-4000-8000-000000002740', 'トランプをよく交ぜてください。', 'Tolong campur kartunya dengan baik.'),
  ('00000000-0000-4000-8000-000000002740', 'どうしてたくさんの男たちの中に女を一人交ぜたんだ？', 'Mengapa Anda menggabungkan seorang wanita ke dalam kelompok dengan sekelompok pria?'),
  ('00000000-0000-4000-8000-000000002740', '豆腐と河豚を交ぜるのは危険です。', 'Berbahaya mencampurkan tahu dan ikan buntal.'),
  ('00000000-0000-4000-8000-000000002741', '日よう日は、サッカーの大会に出じょうします。', 'I am participating in the soccer tournament on Sunday.'),
  ('00000000-0000-4000-8000-000000002741', '花火大会では、アイスクリームがよく売れます。', 'At fireworks events, ice cream sells well.'),
  ('00000000-0000-4000-8000-000000002741', '私がマラソン大会で優勝したのは、オナラを止めることができず、他のランナーがその臭いを嗅ぐたびにペースを落としていったからだ。', 'I won the marathon because I couldn’t stop farting and all the other runners slowed down whenever they smelled them.'),
  ('00000000-0000-4000-8000-000000002742', '日よう日に会う。', 'We’re meeting on Sunday.'),
  ('00000000-0000-4000-8000-000000002742', 'ポートランドくうこうでばったりコウイチに会いました。', 'I ran into Koichi at the Portland airport.'),
  ('00000000-0000-4000-8000-000000002742', '明日の午後、大好きな俳優に会えるんです！', 'I get to meet my favorite actor tomorrow afternoon.'),
  ('00000000-0000-4000-8000-000000002743', '太ようの光がまぶしいので、カーテンをしめてください。', 'Cahaya matahari menyilaukan, jadi harap tutup tirainya.'),
  ('00000000-0000-4000-8000-000000002743', '月の光にてらされて、かなえちゃんの歯がまるでパールのように見えるよ。', 'Di bawah sinar bulan, gigimu terlihat seperti mutiara, Kanae.'),
  ('00000000-0000-4000-8000-000000002743', '北朝鮮で行方不明になったあなたの子供には、まだ微かに希望の光が残っている。', 'Masih ada secercah harapan tersisa untuk anak Anda yang hilang di Korea Utara.'),
  ('00000000-0000-4000-8000-000000002744', 'ちきゅうから月までは、一おく分の四光年です。', 'Jaraknya empat per seratus juta tahun cahaya dari bumi ke bulan.'),
  ('00000000-0000-4000-8000-000000002744', 'ポートランドの中しんから北の方に四光年すすんだら、どこにつきますか。', 'Jika kita pergi ke utara dari pusat Portland sejauh empat tahun cahaya, di manakah kita akan berada?'),
  ('00000000-0000-4000-8000-000000002744', '光年とは、光の速度で1年間進み続け到達出来る距離だ。貴様が俺と対決しようなんて、一万光年早いわ。', 'Satu tahun cahaya adalah jarak yang dapat ditempuh cahaya dalam kurun waktu satu tahun. Anda 10.000 tahun cahaya terlalu dini untuk menghadapi saya.'),
  ('00000000-0000-4000-8000-000000002745', 'そのよるは、月光がとてもきれいでした。', 'Cahaya bulan sangat indah malam itu.'),
  ('00000000-0000-4000-8000-000000002745', '一りんの白い花に、月光がさえざえとふりそそいでいた。', 'Cahaya bulan yang terang menyinari bunga putih.'),
  ('00000000-0000-4000-8000-000000002745', '月光に照らされた彼女は、とても美しかった。', 'Dia tampak sangat cantik di bawah sinar bulan.'),
  ('00000000-0000-4000-8000-000000002746', '日光をあびすぎるのは体によくない。', 'Mandi terlalu lama di bawah sinar matahari tidak baik untuk tubuh Anda.'),
  ('00000000-0000-4000-8000-000000002746', 'できるだけちょくしゃ日光にさらされないよう気をつけています。', 'Saya berhati-hati agar tidak terkena sinar matahari langsung.'),
  ('00000000-0000-4000-8000-000000002746', '何故か日光を見るといつもくしゃみが出ます。', 'Melihat sinar matahari selalu membuatku bersin entah kenapa.'),
  ('00000000-0000-4000-8000-000000002747', '毎日、同じ人に会います。', 'I meet the same person every day.'),
  ('00000000-0000-4000-8000-000000002747', '今回のしけんは、ぜん回とほぼ同じ内ようでした。', 'This exam had almost the same questions as last time.'),
  ('00000000-0000-4000-8000-000000002747', 'あの店と同じ味のラーメンがどうしても作りたいんだ。', 'I want to make ramen that tastes the same as that shop’s no matter what.'),
  ('00000000-0000-4000-8000-000000002748', 'それらは、同日にはつばいされました。', 'Those were launched on the same day.'),
  ('00000000-0000-4000-8000-000000002748', 'すきなバンドのライブがちがうはこで同日にかぶっていて、どれにいこうかちょうぜつまよっています。', 'The bands I like have concerts in different music clubs on the same day and I''m really not sure which one I should go to.'),
  ('00000000-0000-4000-8000-000000002748', '父の死と同日に、アポロ11号が月面着陸に成功した。', 'On the same day of my father’s death, Apollo 11 succeeded in landing on the moon’s surface.'),
  ('00000000-0000-4000-8000-000000002749', '日本に一回行ったことがあります。', 'Saya pernah ke Jepang sekali.'),
  ('00000000-0000-4000-8000-000000002749', 'アメリカから日本までおよいでわたるけいかくを立てたが、もう八回ほどと中で中止になっている。', 'Saya sudah membuat rencana untuk berenang dari Amerika ke Jepang, tapi sekarang rencana itu ditunda delapan kali berbeda.'),
  ('00000000-0000-4000-8000-000000002749', '何回砂を食べたか自分でも数えきれないよ。', 'Saya tidak bisa menghitung berapa kali saya makan pasir.'),
  ('00000000-0000-4000-8000-000000002750', '今日は、おきゃくさんと１８ホールを回りました。', 'Saya berkeliling 18 lubang dengan pelanggan hari ini.'),
  ('00000000-0000-4000-8000-000000002750', '百円玉はまだつくえの上で回っています。', 'Koin 100 yen itu masih berputar di atas meja.'),
  ('00000000-0000-4000-8000-000000002750', '惑星が太陽の周りを回るように、その子猫たちが親猫の周りを回っている。', 'Anak-anak kucing itu berputar mengelilingi induknya seperti planet-planet berputar mengelilingi matahari.'),
  ('00000000-0000-4000-8000-000000002751', 'もう一回、言ってください。', 'Tolong ucapkan sekali lagi.'),
  ('00000000-0000-4000-8000-000000002751', '平日は一日に一回シャワーをあびますが、休日はぜんぜんあびません。', 'Saya mandi sekali sehari selama seminggu, tapi tidak sama sekali selama akhir pekan.'),
  ('00000000-0000-4000-8000-000000002751', 'もう一回欲しいのかい、ハニー？', 'Apakah kamu menginginkannya sekali lagi, sayang?'),
  ('00000000-0000-4000-8000-000000002752', '今回は、やめておきます。', 'Saya memutuskan untuk melewatkan kali ini.'),
  ('00000000-0000-4000-8000-000000002752', '今回のマラソン大会では一いでした。', 'Saya adalah pemenang pertama di maraton ini.'),
  ('00000000-0000-4000-8000-000000002752', '前回お前が運転した時は、岸にぶつかりそうになったじゃん。だから今回は俺が釣り船を運転するよ。', 'Saya akan mengemudikan perahu nelayan kali ini karena terakhir kali Anda mengendarainya, kita hampir menabrak pantai.'),
  ('00000000-0000-4000-8000-000000002753', 'このマラソン大会には、毎回出じょうしています。', 'Saya mengikuti maraton ini setiap saat.'),
  ('00000000-0000-4000-8000-000000002753', 'コウイチは毎回ミーティングのと中でクネクネうごく。', 'Koichi bergoyang selama setiap pertemuan.'),
  ('00000000-0000-4000-8000-000000002753', '笑おうとすると、毎回歯茎から血が出始める。', 'Setiap kali saya mencoba tersenyum, gusi saya mulai berdarah.'),
  ('00000000-0000-4000-8000-000000002754', 'このりょうりは多すぎます。', 'There is too much food.'),
  ('00000000-0000-4000-8000-000000002754', '「自分は正しい」とおもいこんでいる人は多い。', 'There are many people who firmly believe that they are right.'),
  ('00000000-0000-4000-8000-000000002754', '電車にはとても多くの乗客が乗っていたので、眠ることはできなかったが、大声で歌うことはできた。', 'I wasn’t able to sleep because there were far too many people on the train, so I just sang loudly instead.'),
  ('00000000-0000-4000-8000-000000002755', 'かさは、多分外にあります。', 'Maybe the umbrella is outside.'),
  ('00000000-0000-4000-8000-000000002755', '多分、レイヤーさんなのかもしれないよ。', 'Perhaps, she is a cosplayer.'),
  ('00000000-0000-4000-8000-000000002755', '明日の夜は多分雪になるから、雪だるまを作ろう。', 'It’s probably going to snow tomorrow, so let’s make a snowman.'),
  ('00000000-0000-4000-8000-000000002756', '自分の予想が当たって、嬉しいです。', 'Saya senang tebakan saya benar.'),
  ('00000000-0000-4000-8000-000000002756', '人に石が当たったらどうするんだ。', 'Jika seseorang dipukul dengan batu, apa yang akan kamu lakukan?'),
  ('00000000-0000-4000-8000-000000002756', 'まんいんでん車で、手がとなりの女のしりに当たってしまい、ちかんにまちがえられたらどうしようと不あんでいっぱいになった。', 'Di dalam kereta yang penuh sesak, tanganku tanpa sengaja menyentuh pantat wanita di sebelahku dan aku sangat khawatir hingga disangka penganiaya.'),
  ('00000000-0000-4000-8000-000000002757', 'たからくじで当たりが出るかくりつはとてもひくいです。', 'Peluang memenangkan lotre sangat rendah.'),
  ('00000000-0000-4000-8000-000000002757', 'あんなしょぼい当たりのゴロでヒットになるわけがない。', 'Grounder dengan pukulan lemah seperti itu tidak mungkin menjadi pukulan.'),
  ('00000000-0000-4000-8000-000000002757', '僕が開いた父さんの５０歳の誕生日パーティーは大当たりで、父さんはそこで新しい彼女まで見つけてしまった。', 'Pesta yang saya adakan untuk ulang tahun ayah saya yang ke-50 sukses dan dia bahkan menemukan pacar baru di sana.'),
  ('00000000-0000-4000-8000-000000002758', 'うちの学こうでは、毎月テストがあります。', 'There is a test at my school every month.'),
  ('00000000-0000-4000-8000-000000002758', 'ゆうふくないえではありませんでしたが、わたしが大学生のとき、りょうしんは毎月生かつひをしおくりしてくれました。', 'Although my family wasn''t rich, my parents sent a living allowance to me when I was in university.'),
  ('00000000-0000-4000-8000-000000002758', '毎月どのくらい家賃を払っていますか？', 'How much do you pay for rent each month?'),
  ('00000000-0000-4000-8000-000000002759', 'わたしは日本ご学こうで、毎日べんきょうしています。', 'I study every day at a Japanese language school.'),
  ('00000000-0000-4000-8000-000000002759', '名古やから、大さかにあるアメリカ村に毎日かよっています。', 'I''m commuting from Nagoya to Americamura in Osaka every day.'),
  ('00000000-0000-4000-8000-000000002759', '毎日17から21個のチーズバーガーを食べます。', 'I eat anywhere between 17-21 cheeseburgers every day.'),
  ('00000000-0000-4000-8000-000000002760', '山田さんは、毎年どこにりょ行に行きますか？', 'Where does Yamada go for her trip every year?'),
  ('00000000-0000-4000-8000-000000002760', 'あのか手は毎年引たいを口にしているので、きっと今回もただのつりでしょう。', 'That singer hints at retiring every year, so he must be saying it again this time just to get people to react.'),
  ('00000000-0000-4000-8000-000000002760', '私は、ジョンソンさん一家のために、10年間毎年新しい扉を建てている。どうしてジョンソンさんたちはトロールに扉を使わせないようにしないのだろうか。', 'I’ve built a new door for the Johnson family every year for the past decade. Why don’t they just stop letting the troll use it?'),
  ('00000000-0000-4000-8000-000000002761', 'この池は大きすぎる。', 'Kolam ini terlalu besar.'),
  ('00000000-0000-4000-8000-000000002761', '池に竹の矢をおとしたら、中からかみさまがあらわれて、「おまえがおとしたのはこの竹の矢か、それともこの金の矢か。」ときかれたので、正じきに「竹の矢ですが、その金の矢もほしいです。」といった。', 'Ketika saya menjatuhkan anak panah bambu ke dalam kolam, Tuhan keluar dari kolam dan bertanya kepada saya, "Apakah kamu menjatuhkan anak panah bambu ini atau anak panah emas ini?" Jadi aku menjawab dengan jujur, “Aku menjatuhkan panah bambu itu, tapi aku ingin panah emasnya juga.”'),
  ('00000000-0000-4000-8000-000000002761', 'うちのご近所さんは、鳥を撃ち落としては、うちの池に投げ入れる。', 'Tetangga saya terus melemparkan bangkai burung yang ia tembak ke dalam kolam saya.'),
  ('00000000-0000-4000-8000-000000002762', '米をかうのをわすれてしまいました。', 'Saya lupa membeli beras.'),
  ('00000000-0000-4000-8000-000000002762', '１おく円のおもさはやく１０キロときいたので、１０キロのお米のふくろをだきしめながら、１おく円をもっているところをそうぞうしてみた。', 'Saya dengar berat 100 juta yen itu sekitar 10kg, jadi saya mencoba membayangkan bagaimana rasanya memegang 100 juta yen sambil memegang sekantong beras 10kg.'),
  ('00000000-0000-4000-8000-000000002762', '私の一番好きな朝ごはんは、生米と味噌汁です。', 'Sarapan favorit saya terdiri dari nasi mentah dan sup miso.'),
  ('00000000-0000-4000-8000-000000002763', '小とりは、羽をパタパタうごかしました。', 'Burung kecil itu mengepakkan sayapnya.'),
  ('00000000-0000-4000-8000-000000002763', '手羽先のからあげはたべたことがあるけど、ちょうちょうの羽のからあげはたべたことがありません。', 'Saya pernah makan sayap ayam goreng sebelumnya, tapi saya belum pernah makan sayap kupu-kupu goreng.'),
  ('00000000-0000-4000-8000-000000002763', '「この羽、どの鳥の羽か分かるかな？」と彼は自分の鼻毛を持ちながら聞いてきた。', '“Tahukah kamu jenis burung apa bulu ini?” dia bertanya padaku sambil mengulurkan sebagian bulu hidungnya sendiri.'),
  ('00000000-0000-4000-8000-000000002764', 'いつも自分の考えを上手くせつめいできません。', 'I can never explain my own thoughts well.'),
  ('00000000-0000-4000-8000-000000002764', 'あなたの考えはあますぎます。', 'Your thoughts are too optimistic.'),
  ('00000000-0000-4000-8000-000000002764', 'あなたの考えを百円で買わせてもらえませんか？', 'Can I buy your thoughts for 100 yen?'),
  ('00000000-0000-4000-8000-000000002765', '少し考えさせてください。', 'Please let me think about it a little.'),
  ('00000000-0000-4000-8000-000000002765', '考えるな！かんじろ！', 'Don''t think. Just feel!'),
  ('00000000-0000-4000-8000-000000002765', '私の娘は、もしタイタニック号が沈まなければ、みんなその代わりにディズニーランドに行くことができて、もっといい映画になったのにと考える。', 'My daughter believes that the movie Titanic would have been better if the ship never sank and everyone went to Disneyland instead.'),
  ('00000000-0000-4000-8000-000000002766', '考え方は、人それぞれです。', 'People have their own way of thinking.'),
  ('00000000-0000-4000-8000-000000002766', 'そもそも、父と母は考え方がまったくちがうんです。', 'My mom and dad''s thought processes are totally different to begin with.'),
  ('00000000-0000-4000-8000-000000002766', '自分のことを悪い人間だと思うのは、もし自分が実際に悪女だったとしても、良くない考え方です。', 'Even if you really are an awful woman, thinking badly about yourself still isn’t a healthy way to think.'),
  ('00000000-0000-4000-8000-000000002767', '水よう日は、肉がやすいです。', 'On Wednesday, meat is cheap.'),
  ('00000000-0000-4000-8000-000000002767', '牛肉とぶた肉ととり肉の中ではどれが一ばんすきですか。', 'Among beef, pork, and chicken, which meat do you like the best?'),
  ('00000000-0000-4000-8000-000000002767', 'お肉は、二枚の食パンに挟まれる、もっとも重要な具材です。', 'Meat is the most important component between two slices of bread.'),
  ('00000000-0000-4000-8000-000000002768', 'いえのちかくのえきででんしゃをおりて、スーパーに牛肉をかいに行きました。', 'I got off the train at a station near my home and went to the grocery store to buy beef.'),
  ('00000000-0000-4000-8000-000000002768', '去年、えいこくさん牛肉のゆ入がさいかいされました。', 'Last year, the import of UK beef was resumed.'),
  ('00000000-0000-4000-8000-000000002768', '牛肉はありえないくらい生焼けだ。この牛肉のせいで今夜はキッチンの悪夢を見ることになりそうだ。', 'The beef is so undercooked. I may have a kitchen nightmare tonight because of this.'),
  ('00000000-0000-4000-8000-000000002769', 'まったく皮肉なものですね。', 'Sungguh ironis bukan?'),
  ('00000000-0000-4000-8000-000000002769', 'あの肉やさんは、大した皮肉やだよ。', 'Tukang daging itu adalah orang yang sangat sarkastik.'),
  ('00000000-0000-4000-8000-000000002769', '「Ironic」という曲の中に、うまい皮肉はひとつも見当たらなかった。', 'Tidak ada satu hal pun dalam lagu "Ironis" yang merupakan contoh ironi yang tepat.'),
  ('00000000-0000-4000-8000-000000002770', 'ちゃんと自分でしゅくだいをしました。', 'I finished the homework perfectly all by myself.'),
  ('00000000-0000-4000-8000-000000002770', '自分に自しんがないとえらべない色だよね。', 'That''s the color you can only choose if you are confident with yourself, isn''t it?'),
  ('00000000-0000-4000-8000-000000002770', 'もちろん私は自分と話しますよ。だって、時には専門家の意見が必要ですもの。', 'Of course I talk to myself. Sometimes I need expert advice.'),
  ('00000000-0000-4000-8000-000000002771', 'むすこもようやく自立しはじめました。', 'My son is finally starting to be self reliant.'),
  ('00000000-0000-4000-8000-000000002771', '自立しんけいしっちょうしょうがなおったら、自立しようとおもっています。', 'I''m thinking of being on my own, if I recover from autonomic dysfunction.'),
  ('00000000-0000-4000-8000-000000002771', 'もしあなたが強くて自立した日本人女性で、男なんて必要ないというなら、これをシェアしてください。', 'Share this if you are a strong, independent Japanese woman who doesn’t need a man.'),
  ('00000000-0000-4000-8000-000000002772', '何色がすきですか。', 'What color do you like?'),
  ('00000000-0000-4000-8000-000000002772', 'ピーマンはうれるとみどり色から赤色になります。', 'Bell peppers turn from green to red when they ripen.'),
  ('00000000-0000-4000-8000-000000002772', '僕は色盲なので、赤色はオレンジ色に、青色は黒色のように見えます。', 'I’m color blind, so my reds appear orange and my blues appear black.'),
  ('00000000-0000-4000-8000-000000002773', '色々な小せつをよみました。', 'I’ve read various types of novels.'),
  ('00000000-0000-4000-8000-000000002773', '色々考えたけっか、日よう日にたこやきパーティーをすることにしました。', 'After thinking about various things, I''ve decided to hold a takoyaki party on Sunday.'),
  ('00000000-0000-4000-8000-000000002773', '私のベッドの下に住んでいるトロールには色々な種類がいます。', 'There are various species of trolls that live under my bed.'),
  ('00000000-0000-4000-8000-000000002774', 'あの水色のバッグがほしいんですが。', 'I want that light blue bag.'),
  ('00000000-0000-4000-8000-000000002774', 'トーフグのTシャツは、さわやかな水色です。', 'Tofugu T-shirt is breezy sky blue.'),
  ('00000000-0000-4000-8000-000000002774', 'どうして今日の空は水色なんだろう？', 'Why is the sky light blue today?'),
  ('00000000-0000-4000-8000-000000002775', '今から、かいものに行きます。', 'I''m about to go shopping. '),
  ('00000000-0000-4000-8000-000000002775', 'ようじができて、行けなくなってしまいました。', 'Something came up, so I''m not able to make it.'),
  ('00000000-0000-4000-8000-000000002775', 'タコベルが無いので火星には行きたくない。', 'I wouldn’t want to go to Mars because they don’t have Taco Bell there.'),
  ('00000000-0000-4000-8000-000000002776', '雨さえなければ、七月四日に花火大会を行うつもりです。', 'As long as it doesn''t rain, we intend to hold the fireworks display on July 4th.'),
  ('00000000-0000-4000-8000-000000002776', '来年の五月に学生が地方のさくらめぐりを行うらしいです。', 'Apparently the students are holding a regional cherry blossom tour in May of next year.'),
  ('00000000-0000-4000-8000-000000002776', 'いつもはサヤカがうどん切りを行うのだが、休みをとってしばらくはいないので、私がそれを行わなければならなくなったけど、どうもうまくいかない。', 'Sayaka usually performs the udon noodle cutting, however she''s on vacation and won''t be around for a while, so I''ve ended up having to do it, but it''s just not going well.'),
  ('00000000-0000-4000-8000-000000002777', 'しん大さか行きのしんかんせんのきっぷをください。', 'One shinkansen ticket for Shin-Osaka, please.'),
  ('00000000-0000-4000-8000-000000002777', '行きもかえりもあるくつもりです。', 'I''m thinking of walking both ways.'),
  ('00000000-0000-4000-8000-000000002777', 'この電車は、トーフグオフィス行きです。', 'This train is bound for Tofugu Office Station.'),
  ('00000000-0000-4000-8000-000000002778', 'びょういんの西のたてものがわたしのアパートです。', 'The building on the west side of the hospital is my apartment.'),
  ('00000000-0000-4000-8000-000000002778', 'ダリンは、西にむかっています。', 'Darin is heading west.'),
  ('00000000-0000-4000-8000-000000002778', 'その頃、西ポートランドでは、鰐蟹がその道を渡っていた。', 'Meanwhile in West Portland, the Crabigator was crossing the road.'),
  ('00000000-0000-4000-8000-000000002779', 'ひこうきは、北西にむかっています。', 'The airplane is heading northwest.'),
  ('00000000-0000-4000-8000-000000002779', 'ポートランドから車で一じかん半ほど北西の方にいくと、シーサイドというまちにつきます。', 'If you drive about an hour and a half northwest from Portland, you will arrive at a city called Seaside.'),
  ('00000000-0000-4000-8000-000000002779', 'ここから北西の方角のどこかに、パンストを落とした。', 'I lost my pantyhose somewhere northwest of here.'),
  ('00000000-0000-4000-8000-000000002780', '何千回も、れんしゅうしました。', 'I’ve practiced thousands of times.'),
  ('00000000-0000-4000-8000-000000002780', 'とつぜん、何千ものベーコンがそらからふってきた。', 'Suddenly, thousands of bacon strips dropped from sky. '),
  ('00000000-0000-4000-8000-000000002780', '巨人攻撃の被害者は、何千人にものぼった。', 'Victims of the titan attack numbered in the thousands.'),
  ('00000000-0000-4000-8000-000000002780', '何千円ですか？', 'How many thousand yen?'),
  ('00000000-0000-4000-8000-000000002781', '何と言いますか。', 'What would you say?'),
  ('00000000-0000-4000-8000-000000002781', 'あなた、何さまのつもりですか。', 'Who do you think you are?'),
  ('00000000-0000-4000-8000-000000002781', '僕達がタイのホテルで飲んだ飲み物の名前は何？', 'What was the name of that drink we had at the hotel in Thailand?'),
  ('00000000-0000-4000-8000-000000002782', 'そのパーティーには、何人の人がさんかしましたか。', 'How many people participated in the party?'),
  ('00000000-0000-4000-8000-000000002782', '今までこの池で何人の人々がさつ人ぎょにころされましたか。', 'How many people have been killed by the killer fish in this pond?'),
  ('00000000-0000-4000-8000-000000002782', '夕食にはいったい何人の人がやって来るんですか？', 'How many people will be joining us for dinner?'),
  ('00000000-0000-4000-8000-000000002783', '学こうは何月にはじまりますか。', 'What month do you start school?'),
  ('00000000-0000-4000-8000-000000002783', 'それって何年何月何日何びょう、ちきゅうが何回回ったとき？', 'When did it happen? What year, what month, what day, what time, what second was it? How many times did Earth spin when it happened?'),
  ('00000000-0000-4000-8000-000000002783', '田中さんは何月生まれですか？', 'What month were you born in, Ms. Tanaka?'),
  ('00000000-0000-4000-8000-000000002784', 'アルバイト、何日休むんですか。', 'How many days will you take off from your part-time job?'),
  ('00000000-0000-4000-8000-000000002784', '何日がいい？', 'What day''s good for you?'),
  ('00000000-0000-4000-8000-000000002784', 'エレベーターから何日出られなかったんですか。', 'How many days were you stuck in the elevator?'),
  ('00000000-0000-4000-8000-000000002785', '何年生まれですか。', 'What year were you born?'),
  ('00000000-0000-4000-8000-000000002785', 'おたくのお子さんは、何年に大学に入りましたか。', 'What year did your kid enter college?'),
  ('00000000-0000-4000-8000-000000002785', 'アメリカの南北戦争は、何年間続いたんですか？', 'How many years did the American Civil War last?'),
  ('00000000-0000-4000-8000-000000002786', '日本へ来るのは、今回で何回目ですか。', 'Termasuk kali ini sudah berapa kali datang ke Jepang?'),
  ('00000000-0000-4000-8000-000000002786', 'このビデオ、おもしろすぎて何回も見てしまうわ。', 'Video ini sangat lucu sehingga saya harus menontonnya berkali-kali.'),
  ('00000000-0000-4000-8000-000000002786', '事をはっきりさせるまでに、いったい何回この会話を繰り返さないといけねえんだよ？だから俺はリューク・スカイウォーカーじゃねえんだよ。映画でその役を演じただけだっつーの。俺の名前はマークだ。シカゴに住んでる。', 'Berapa kali kita harus melakukan percakapan ini sampai akhirnya benar-benar meresap? Saya bukan Luke Skywalker. Saya memerankannya dalam sebuah film. Nama saya Markus. Saya tinggal di Chicago.'),
  ('00000000-0000-4000-8000-000000002787', 'わたしは、どく学で日本ごを学んでいます。', 'I’m learning Japanese through self-study.'),
  ('00000000-0000-4000-8000-000000002787', '日本ごをべんきょうするのはやめて、トーフグといっしょにへんがおとへんなポーズを学びませんか？', 'Why don''t you learn how to make weird faces and poses with Tofugu, instead of studying Japanese?'),
  ('00000000-0000-4000-8000-000000002787', '学ぶことは大切だけど、おそらくもっと大切なのはどのように学ぶかということじゃないだろうか。', 'Learning is important, but perhaps what’s more important is how you learn.'),
  ('00000000-0000-4000-8000-000000002788', '学生は今日、うちでどこをべんきょうしますか。', 'Which parts will students study at home today?'),
  ('00000000-0000-4000-8000-000000002788', '学生わり引ってありますか？', 'Do you have student discount?'),
  ('00000000-0000-4000-8000-000000002788', '「我々はみな人生の学生だ。」と言いながら、父はおならをした。', '"We are all students of life," my dad said while farting.'),
  ('00000000-0000-4000-8000-000000002789', 'かれは、兄と同じ学年です。', 'He is in the same year as my older brother.'),
  ('00000000-0000-4000-8000-000000002789', 'トーフグには、小学こうてい学年のファンもいれば、１００才をこえるファンもいる。', 'Tofugu not only has fans in early elementary school, but also elderly fans over 100 years old.'),
  ('00000000-0000-4000-8000-000000002789', 'あの給食の後、三年生の学年の三分の一が吐いた。', 'One third of the third grade threw up after school lunch.'),
  ('00000000-0000-4000-8000-000000002790', 'これは、入学のおいわいのプレゼントです。', 'Here is a congratulatory present for getting into school.'),
  ('00000000-0000-4000-8000-000000002790', '父が入学金をはらうのをわすれてしまったんです。', 'My father forgot to pay the enrollment fee.'),
  ('00000000-0000-4000-8000-000000002790', 'トムはオックスフォード大学に入学できたと思っていたんだけど、どうもその合格証明書はトムの両親がエイプリルフールのジョークとして作ったものだったようだぜ。', 'Tom thought he got into Oxford, but apparently the acceptance letter was an April Fool’s joke his parents made.'),
  ('00000000-0000-4000-8000-000000002791', 'わたしのせんもんは、工学です。', 'My specialization is engineering.'),
  ('00000000-0000-4000-8000-000000002791', 'ハーバード大学の工学のクラスは目玉がとび出るほどむずかしかった。', 'The engineering class at Harvard University was excessively difficult.'),
  ('00000000-0000-4000-8000-000000002791', '僕はこの仕事にぴったりだと思うんだけど、応募するには工学の学位がいるんだ。', 'I’d be perfect for this job, but I need an engineering degree in order to apply.'),
  ('00000000-0000-4000-8000-000000002792', 'わたしの大学には、中ごく人がたくさんいます。', 'There are a lot of Chinese people in my university.'),
  ('00000000-0000-4000-8000-000000002792', 'アメリカの大学と日本の大学の主なちがいはなんですか。', 'What are the main differences between American universities and Japanese universities?'),
  ('00000000-0000-4000-8000-000000002792', '大学で解剖学を勉強したが、教科書は一度も開かなかった。', 'I studied anatomy in college, but I never opened a textbook.'),
  ('00000000-0000-4000-8000-000000002793', '大学を一年かん休学していたんです。', 'I’m taking a one year leave of absence from university.'),
  ('00000000-0000-4000-8000-000000002793', 'ビエトは大学のとき、学こうを一年かん休学してじ分さがしのたびに出た。', 'When Viet was a college student, he took a year of leave from school and went on a journey of self discovery.'),
  ('00000000-0000-4000-8000-000000002793', '「どうしてケリーが三週間も休学しているか知ってる？」「知ってるよ。ケリーは結膜炎がひどいらしいよ。」', '"Do you know why Kelly has been absent from school for the past three weeks?" "Yes, apparently she has a really serious case of pink eye."'),
  ('00000000-0000-4000-8000-000000002794', '毎あさ、林をさんぽしています。', 'Setiap pagi saya berjalan di hutan.'),
  ('00000000-0000-4000-8000-000000002794', '林先生が早足で林をあるいているのを見ちゃった。', 'Saya kebetulan melihat Nyonya Hayashi sedang berjalan cepat di hutan.'),
  ('00000000-0000-4000-8000-000000002794', '家に帰るまで待てずに、林の中に濡れた靴下を残した。', 'Saya tidak sabar menunggu sampai di rumah, jadi saya meninggalkan kaus kaki saya yang basah di hutan.'),
  ('00000000-0000-4000-8000-000000002795', 'ちょっとは空気をよんでください。', 'Please just take the hint.'),
  ('00000000-0000-4000-8000-000000002795', '冬のあさの空気はつめたい。', 'The morning winter air is cold.'),
  ('00000000-0000-4000-8000-000000002795', '海賊の宇宙船に乗っている猿は、三時間後に大気圏に突入する予定だ。猿は、肺に好きなだけ空気を吸い込むことが待ちきれない。', 'The monkey in the pirate’s space ship will be reentering the atmosphere in 3 hours. He can’t wait to draw as much air into his lungs as possible.'),
  ('00000000-0000-4000-8000-000000002796', '空にきれいなにじがかかっている。', 'There is a beautiful rainbow in the sky.'),
  ('00000000-0000-4000-8000-000000002796', '女心とあきの空といいますが、男心だってかわりやすいんですよ。', 'They say that women''s minds and the autumn skies change quickly, but men''s minds change quickly too.'),
  ('00000000-0000-4000-8000-000000002796', '今夜映画E.T.の有名なシーンがちゃんと見れるくらい、空が晴れ渡っているといいんだが。', 'I hope the sky tonight is clear enough for us to see the famous scene from the movie E.T.'),
  ('00000000-0000-4000-8000-000000002797', '金のネックレスをプレゼントしました。', 'I gave her a gold necklace.'),
  ('00000000-0000-4000-8000-000000002797', 'お金があったら、金正ウンとおそろいの、金のロレックスをかいたいとおもっています。', 'If I had money, I would like to buy the gold Rolex that Kim Jong-un has.'),
  ('00000000-0000-4000-8000-000000002797', 'この毛糸は24時間後に金に変わるんだけど、クリスマスプレゼントとして少しあんたにあげるよ。感謝しろよな。', 'This yarn will turn into gold in 24 hours and I’ll give you some as a Christmas present, so you should appreciate me more.'),
  ('00000000-0000-4000-8000-000000002798', '金玉がヒリヒリするんです。', 'Testisku perih.'),
  ('00000000-0000-4000-8000-000000002798', 'おれの金玉はぜったい他の男のばいはたらいてるとおもうぜ。', 'Saya yakin testis saya bekerja dua kali lebih keras dibandingkan pria lain.'),
  ('00000000-0000-4000-8000-000000002798', '金玉を金色にする手術は、六ヶ月先まで予約がいっぱいです。', 'Operasi untuk membuat testis berwarna emas sudah dipesan penuh untuk enam bulan ke depan.'),
  ('00000000-0000-4000-8000-000000002799', 'この写しんは、お金よりも大切です。', 'This photo is more important than money.'),
  ('00000000-0000-4000-8000-000000002799', 'お金をなめているとバチが当たるよ！', 'If you''re careless with money, it''s going to bite you in the butt.'),
  ('00000000-0000-4000-8000-000000002799', 'この機械は、お金を取りあげるけどなんの見返りもくれないから、気をつけた方がいいよ。', 'You should be aware that this machine takes your money and gives you nothing in return.'),
  ('00000000-0000-4000-8000-000000002800', '雨はまだふっていません。', 'It hasn’t rained yet.'),
  ('00000000-0000-4000-8000-000000002800', '一年中雨がふるくにの王子として生まれたことをくいています。', 'Unfortunately, I was born prince of a country that has rain all year long.'),
  ('00000000-0000-4000-8000-000000002800', '私は雨の臭いが好きで、あなたはそんな臭いがする。だからあなたのことが大好きなの。', 'I like the smell of rain and you smell like it. That’s why I love you.'),
  ('00000000-0000-4000-8000-000000002801', '青いとりがいます。', 'There is a blue bird.'),
  ('00000000-0000-4000-8000-000000002801', 'そのリンゴ、まだ青いんじゃないの。', 'That apple hasn''t ripened enough yet, has it?'),
  ('00000000-0000-4000-8000-000000002801', 'うわっ、この青いペンキ、あの赤いペンキと全く同じ臭いがする。', 'Wow, this blue paint smells exactly like the red paint.'),
  ('00000000-0000-4000-8000-000000002802', 'とてもさわやかな青年でした。', 'He was a very invigorating young man.'),
  ('00000000-0000-4000-8000-000000002802', 'その青年は、ぼう走ぞくの一いんです。', 'That young man is a member of a motorcycle gang.'),
  ('00000000-0000-4000-8000-000000002802', 'どうして日本の青年は、下心があっていやらしい笑みを浮かべていることを隠そうとするのか？', 'Why do youths in Japan try to hide their nasty smiles when they’re up to something?')
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES
  ('00000000-0000-4000-8000-000000002803', 'そろそろ草をからなくてはなりません。', 'Anda harus segera memotong rumput.'),
  ('00000000-0000-4000-8000-000000002803', 'お金がないから草をたべて生きています。', 'Saya tidak punya uang, jadi saya hidup dengan makan rumput.'),
  ('00000000-0000-4000-8000-000000002803', 'どうして隣の人の草はあんなに青いんだろう。どうして彼の家はあんなに大きいんだろう。', 'Mengapa tetangga saya memiliki rumput yang begitu hijau? Dan mengapa rumahnya begitu besar?'),
  ('00000000-0000-4000-8000-000000002804', '二かいから、大きな音がしました。', 'There was a loud noise upstairs.'),
  ('00000000-0000-4000-8000-000000002804', 'となりのいえから、すごく上手なリコーダーの音が聞こえてきます。', 'I can hear the sounds of a very good recorder coming from next door.'),
  ('00000000-0000-4000-8000-000000002804', '金魚が泣いている音を聞いたことはある？', 'Have you ever heard the sound that a goldfish makes when it cries?'),
  ('00000000-0000-4000-8000-000000002805', '今日は、ばんごはんにやきそばを作ります。', 'Today, I will make yakisoba for supper.'),
  ('00000000-0000-4000-8000-000000002805', 'フェイスブックのアカウントをふくすう作る方ほうをおしえてください。', 'Can you teach me how to create multiple Facebook accounts, please?'),
  ('00000000-0000-4000-8000-000000002805', 'テスラ・コイルをどうやって作るのかを知っていたら良かったんだけどな。', 'I wish I knew how to make a Tesla coil.'),
  ('00000000-0000-4000-8000-000000002806', 'おふろに入ると、はじめに体をあらいます。', 'When I take a bath, I wash my body first.'),
  ('00000000-0000-4000-8000-000000002806', 'ジャマルって何でそんなに体がやわらかいの？', 'Jamal, why is your body so flexible?'),
  ('00000000-0000-4000-8000-000000002806', 'なぜだか、体中がかゆいんだ。', 'My entire body is so itchy for some reason.'),
  ('00000000-0000-4000-8000-000000002807', 'わたしは体力があまりありません。', 'I have practically no physical strength.'),
  ('00000000-0000-4000-8000-000000002807', 'コウイチには、うで立てふせを八十回する体力はありません。', 'Koichi doesn''t have stamina to do 80 push-ups.'),
  ('00000000-0000-4000-8000-000000002807', 'その熱が彼の体力を弱めたが、まだ自分で水を飲む体力は残っていた。', 'The fever weakened his body, but he was still strong enough to drink water by himself.'),
  ('00000000-0000-4000-8000-000000002808', 'ちが、体内でどんなはたらきをしているのかしっていますか。', 'Tahukah Anda apa fungsi darah dalam tubuh?'),
  ('00000000-0000-4000-8000-000000002808', 'カボチャに多くふくまれるβカロテンは体内でビタミンAにかわります。', 'Labu kabocha kaya akan beta-karoten dan diubah menjadi vitamin A di dalam tubuh.'),
  ('00000000-0000-4000-8000-000000002808', '人間の体か吸血鬼の体かにかかわらず、血液は体内を循環する。', 'Darah beredar ke seluruh tubuh tak peduli apakah itu tubuh manusia atau tubuh vampir.'),
  ('00000000-0000-4000-8000-000000002809', 'この作文を、中川先生にわたしてください。', 'Please hand this essay in to professor Nakagawa.'),
  ('00000000-0000-4000-8000-000000002809', '作文のテストで百てんをもらいました。', 'I got 100 percent on the essay exam.'),
  ('00000000-0000-4000-8000-000000002809', '僕の作文は、まだ間違いだらけです。', 'My essays are still full of mistakes.'),
  ('00000000-0000-4000-8000-000000002810', 'アルコールの作用をおしえてください。', 'Teach me about the effects of alcohol.'),
  ('00000000-0000-4000-8000-000000002810', '今日、学こうで、作用・はん作用のほうそくを学んだ。', 'I learned Newton''s third law of motion at school today.'),
  ('00000000-0000-4000-8000-000000002810', 'このケーキの味がする薬には、副作用はありませんか？', 'Does this cake-flavored medicine have any side effects?'),
  ('00000000-0000-4000-8000-000000002811', '工作はとくいではありません。', 'Handicraft is not my strong point.'),
  ('00000000-0000-4000-8000-000000002811', 'アリバイ工作にしっぱいした。', 'I failed to concoct a reasonable alibi.'),
  ('00000000-0000-4000-8000-000000002811', '私は小学生の頃、夏休みの自由工作の宿題で、アイスクリームを作る機械を作った。', 'When I was in elementary school, I made a machine that makes ice cream for my school craft project over summer break.'),
  ('00000000-0000-4000-8000-000000002812', 'このえいがは、ヒッチコックの大作だ。', 'This movie is a Hitchcock epic.'),
  ('00000000-0000-4000-8000-000000002812', '今世き一ばんの大作ともいわれているえいがのタイトルは「フグの一生」です。', 'The title of the most epic film this century is said to be, "A Life of Fugu."'),
  ('00000000-0000-4000-8000-000000002812', 'ベートーベンが作曲した曲は、どれも大作だった。', 'Every score that Beethoven wrote was a masterpiece.'),
  ('00000000-0000-4000-8000-000000002813', '下の図を見てください。', 'Please look at the diagram below.'),
  ('00000000-0000-4000-8000-000000002813', 'クリックすると、かく大図がひょうじされます。', 'If you click it, an enlarged view will appear.'),
  ('00000000-0000-4000-8000-000000002813', 'あなたのお兄さんは、自分と彼女の関係を簡単な図に表しました。', 'Your brother drew a simple diagram of the relationship between him and his girlfriend.'),
  ('00000000-0000-4000-8000-000000002814', 'はし本さんの声は、とてもひくいです。', 'Suara Hashimoto sangat pelan.'),
  ('00000000-0000-4000-8000-000000002814', '友人の声とその子どもの声がそっくりだ。', 'Suara teman saya dan suara anaknya sangat mirip.'),
  ('00000000-0000-4000-8000-000000002814', 'あんたの声、ひどいな！', 'Suaramu terdengar buruk!'),
  ('00000000-0000-4000-8000-000000002815', 'そんな大声を出さないでください。', 'Tolong jangan gunakan suara sekeras itu.'),
  ('00000000-0000-4000-8000-000000002815', 'おもわず大声を出してわらってしまった。', 'Aku tidak bisa menahan tawa.'),
  ('00000000-0000-4000-8000-000000002815', 'クリスティーナは大声の持ち主で、残念なことにそれを使うのを全くはばからない。', 'Christina memiliki suara yang nyaring, dan sayangnya dia tidak takut untuk menggunakannya.'),
  ('00000000-0000-4000-8000-000000002816', 'ここに、日本ごのじしょは売っていますか。', 'Are Japanese dictionaries sold here?'),
  ('00000000-0000-4000-8000-000000002816', 'この村では、人々は大麦を売って生けいを立てています。', 'In this village, people make a living by selling barley.'),
  ('00000000-0000-4000-8000-000000002816', '請求書の支払いをするために車を売る必要があるが、そうすれば今度は仕事にいけなくなってしまう。', 'I need to sell my car to pay the bills, but if I do that I won’t be able to get to work.'),
  ('00000000-0000-4000-8000-000000002820', 'わたしの弟は、テレビを見ない。', 'My little brother doesn’t watch TV.'),
  ('00000000-0000-4000-8000-000000002820', 'その青いかみの青年はぼくの弟です。', 'That young man with blue hair is my younger brother.'),
  ('00000000-0000-4000-8000-000000002820', '弟がビリヤードのボールを頭に投げつけてきたので、昨夜僕は病院に行くはめになった。', 'I ended up going to the hospital last night because my younger brother threw a pool ball at my head.'),
  ('00000000-0000-4000-8000-000000002821', 'わたしには、兄弟が二人います。', 'I have two siblings.'),
  ('00000000-0000-4000-8000-000000002821', 'マリオとルイージって兄弟だったの！？', 'Were Mario and Luigi brothers!?'),
  ('00000000-0000-4000-8000-000000002821', 'あの兄弟は好きだけど、あいつらのもっているぬいぐるみは好きじゃない。', 'I like those brothers, but I hate their stuffed animals.'),
  ('00000000-0000-4000-8000-000000002822', 'つまとそうだんして、形より内ようをおもんじたけっか、この形にきめました。', 'Saya berbicara dengan istri saya dan kami memutuskan untuk memilih bentuk ini, karena kami lebih menghargai substansi daripada bentuk.'),
  ('00000000-0000-4000-8000-000000002822', 'これでなんとか形がつきました。', 'Dengan ini, entah bagaimana aku bisa menjaga penampilan.'),
  ('00000000-0000-4000-8000-000000002822', 'ねえ、私の、お尻の形をしたお腹、撫でたい？', 'Hei, apakah kamu ingin menggosok perutku yang berbentuk pantat?'),
  ('00000000-0000-4000-8000-000000002823', 'ネイル用に、ハート形のストーンをさがしています。', 'Saya mencari batu berbentuk hati untuk digunakan pada kuku palsu saya.'),
  ('00000000-0000-4000-8000-000000002823', 'クリスティンは、くぎをくわえながら、ハート形のハンマーをふり回していた。', 'Kristen sedang mengayunkan palu berbentuk hati sambil memegang paku di mulutnya.'),
  ('00000000-0000-4000-8000-000000002823', 'フラミンゴがキスをする時、二羽の頭と首がハート形を描く。', 'Saat flamingo berciuman, kepala dan lehernya membentuk bentuk hati.'),
  ('00000000-0000-4000-8000-000000002824', 'アメリカから来ました。', 'I came from America.'),
  ('00000000-0000-4000-8000-000000002824', '来る、きっと来る。', 'She will come. I''m sure she will come.'),
  ('00000000-0000-4000-8000-000000002824', '二度と戻って来るんじゃねーぞ！', 'Never come back!'),
  ('00000000-0000-4000-8000-000000002825', '来月たん生日会をするので、かなえさんも来てください。', 'I am having a birthday party next month, so please come too, Kanae.'),
  ('00000000-0000-4000-8000-000000002825', '花火大会の日は来月の何日でしたっけ？', 'What day next month is the day of the fireworks display?'),
  ('00000000-0000-4000-8000-000000002825', '今日海に落とした眼鏡を探すために、来月スキューバダイビングを始めることにしたよ。', 'Next month I’ll start scuba diving to find the glasses I lost at sea today.'),
  ('00000000-0000-4000-8000-000000002826', '来年はアメリカにかえるつもりです。', 'I’m thinking of going back to America next year.'),
  ('00000000-0000-4000-8000-000000002826', '今年も来年もさ来年もわたしはニートをつづけるつもりです。', 'I plan to continue being a NEET this year, next year, and the year after that.'),
  ('00000000-0000-4000-8000-000000002826', '来年の今頃に来てくれよ。ハウストレーラー用のキャンプ場で、一番でかいトレーラーが俺のだよ。', 'Come at this time next year. I’ll have the biggest trailer in the trailer park.'),
  ('00000000-0000-4000-8000-000000002827', 'カッパは、日本古来のようかいです。', 'The kappa is an ancient Japanese yokai.'),
  ('00000000-0000-4000-8000-000000002827', '古来、この池は、「ワニカニの池」という名まえでしられていました。', 'In ancient times, this pond was known as "WaniKani Pond."'),
  ('00000000-0000-4000-8000-000000002827', 'トイレは、古来から現代へと受け継がれてきた素晴らしい発明品だ。', 'The toilet is a wonderful invention that has been handed down since ancient times to the present-day.'),
  ('00000000-0000-4000-8000-000000002828', '外来の言ばは、カタカナでかきます。', 'Imported words are written with katakana.'),
  ('00000000-0000-4000-8000-000000002828', '毎日外来に来ていたかんじゃさんが、来なくなったので心ぱいしています。', 'I''m worried because the patient who would come to the outpatient clinic every day stopped coming.'),
  ('00000000-0000-4000-8000-000000002828', '日本のものと全然違うので、私はとても外来品に興味がある。', 'I’m really interested in foreign things because they’re so different from what’s in Japan.'),
  ('00000000-0000-4000-8000-000000002829', 'かれは、わたしの三十年来の友人です。', 'He’s been my friend for thirty years.'),
  ('00000000-0000-4000-8000-000000002829', 'わたしの年来のきぼうがついにかないました。', 'My long-cherished wish has finally come true.'),
  ('00000000-0000-4000-8000-000000002829', '数年来彼女をデートに誘っているんだが、いつも「髪の毛を洗うのに忙しいから」と断られる。', 'I’ve been trying to ask her out for a few years now, but she always says she will be busy washing her hair.'),
  ('00000000-0000-4000-8000-000000002830', 'つぎの日よう日に、社内のバスケットボール大会があります。', 'Minggu depan akan ada turnamen bola basket internal.'),
  ('00000000-0000-4000-8000-000000002830', '花さんは、社内けっこんをしてたいしょくしました。', 'Hana keluar dari perusahaan tersebut setelah ia menikah dengan pria yang bekerja di perusahaan yang sama.'),
  ('00000000-0000-4000-8000-000000002830', '最近、社内で変なことが流行っている。従業員が、会社の冷蔵庫の中の食べ物に名前をつけるのだ。今日は、俺は、「鈴木」と名付けられたオニギリを食べた。', 'Baru-baru ini, ada tren baru yang aneh di perusahaan kami. Para pekerja memberi nama pada makanan di lemari es perusahaan. Hari ini, saya makan nasi kepal bernama "Suzuki".'),
  ('00000000-0000-4000-8000-000000002831', 'この会社には、四月に入社しました。', 'I joined this company in April.'),
  ('00000000-0000-4000-8000-000000002831', 'トーフグの入社しけんはグーグルの入社しけんよりもむずかしい。', 'Tofugu''s employment exam is more difficult than Google''s.'),
  ('00000000-0000-4000-8000-000000002831', '大学を卒業したらすぐに、大きな金融機関に入社するか、アメリカ合衆国の大統領になれたらいいなと思っている。', 'As soon as I graduate from college, I hope to either join a big financial firm or be the president of the United States.'),
  ('00000000-0000-4000-8000-000000002832', 'たしか、かれは公社ではたらいています。', 'If I remember correctly, he works for a goverment-run company.'),
  ('00000000-0000-4000-8000-000000002832', 'このりょきゃくてつどうは、みなみアフリカりょきゃくてつどう公社がうんえいしています。', 'These passenger rail services were operated by the Passenger Rail Agency of South Africa.'),
  ('00000000-0000-4000-8000-000000002832', '4月1日に国営公社である日本郵政公社が業務を開始したが、エイプリルフールのジョークではなかった。', 'On April 1st, a goverment-owned company called Japan Post opened for business and it wasn’t an April Fools’ joke.'),
  ('00000000-0000-4000-8000-000000002833', '本社はとうきょうにあります。', 'The headquarters are in Tokyo.'),
  ('00000000-0000-4000-8000-000000002833', '月よう日に、トーフグの本社におじゃましてきました。', 'On Monday, I visited Tofugu HQ.'),
  ('00000000-0000-4000-8000-000000002833', '今日は本社がやけに静かだな。俺が働いていない音まで聞こえるぜ。', 'It’s so quiet in the head office today, I can hear myself not working.'),
  ('00000000-0000-4000-8000-000000002834', '会社へは、何で行っていますか。', 'How do you go to your company?'),
  ('00000000-0000-4000-8000-000000002834', 'トーフグは日本ごの学しゅうきょうざいをつくったり、日本についてのじょうほうをはいしんしたりする会社です。', 'Tofugu is a company that deals with things like developing Japanese language learning materials and delivering Japanese-related information. '),
  ('00000000-0000-4000-8000-000000002834', '私が働く会社の社長は、ハムスターのような容貌をしている。', 'The president of the company I work for looks like a hamster.'),
  ('00000000-0000-4000-8000-000000002835', 'つぎの角を、左にまがってください。', 'Silakan belok kiri di tikungan berikutnya.'),
  ('00000000-0000-4000-8000-000000002835', 'あの先生は、とうふの角にあたまをぶつけて気ぜつしたらしい。', 'Saya mendengar bahwa guru itu pingsan karena kepalanya terbentur sudut balok tahu.'),
  ('00000000-0000-4000-8000-000000002835', '正三角形では，三つの角の大きさがみんな同じです。', 'Ketiga sudut dalam suatu segitiga sama sisi adalah sama besar.'),
  ('00000000-0000-4000-8000-000000002836', '三角のクラッカーをかってきてください。', 'Silakan beli kerupuk segitiga.'),
  ('00000000-0000-4000-8000-000000002836', '今、三角かんけいになっちゃってるんだよね。', 'Aku terjebak dalam cinta segitiga sekarang.'),
  ('00000000-0000-4000-8000-000000002836', 'カナダ人はピカソにかなり刺激を受けたに違いない。四角い箱に、丸いピザ、三角のピザスライスがあちこちにある。', 'Orang Kanada pasti banyak terinspirasi oleh Picasso. Kotak persegi, pizza bulat, dan irisan pizza segitiga ada dimana-mana.'),
  ('00000000-0000-4000-8000-000000002837', 'じゃがいもを、四角に切ってください。', 'Tolong potong kentang menjadi kubus.'),
  ('00000000-0000-4000-8000-000000002837', 'ツイッターのアイコンの形を今の丸から四角にもどしてほしい。', 'Saya ingin ikon twitter kembali dari bentuk bulat ke persegi.'),
  ('00000000-0000-4000-8000-000000002837', 'どうしてほとんどの窓は真四角か長四角なんだろう。イタリア型の窓とかも作ったらいいのに。', 'Mengapa sebagian besar jendela berbentuk persegi atau persegi panjang? Mereka harus mulai membuat jendela berbentuk seperti Italia.'),
  ('00000000-0000-4000-8000-000000002838', 'ゆっくり言ってください。', 'Please say it slowly.'),
  ('00000000-0000-4000-8000-000000002838', 'いつもありがとうってえいごで何て言うの？', 'How can I say, "Thank you always," in English?'),
  ('00000000-0000-4000-8000-000000002838', 'ジェイクに、足を踏んでごめんって言うつもりなの？', 'Are you going to say sorry to Jake for stepping on his foot?'),
  ('00000000-0000-4000-8000-000000002839', 'あそこの谷で、くまを見ました。', 'Saya melihat beruang di lembah itu.'),
  ('00000000-0000-4000-8000-000000002839', 'はこねには大わく谷というむかし「じごく谷」といわれた谷があって、かんこうの名しょになっています。', 'Di Hakone terdapat sebuah lembah bernama Owakudani yang dulu disebut "Lembah Kematian" dan menjadi tempat wisata terkenal saat ini.'),
  ('00000000-0000-4000-8000-000000002839', '死の谷で自殺した男は、ダース・ベイダーのコスプレをしていた。', 'Orang yang bunuh diri di Death Valley berpakaian seperti Darth Vader.'),
  ('00000000-0000-4000-8000-000000002840', 'えいがにおくれそうだったので、走りました。', 'I ran because I was almost late for the movie.'),
  ('00000000-0000-4000-8000-000000002840', 'コウイチはカメよりもはやく走れる。', 'Koichi can run faster than a turtle.'),
  ('00000000-0000-4000-8000-000000002840', '人生走り続けるより、侍に首をはねられる方がずっとましだという結論に達しました。', 'I’ve come to the conclusion that having my head cut off by a samurai would be much better than running for my life.'),
  ('00000000-0000-4000-8000-000000002841', 'あなたの車の走行マイルをおしえてください。', 'Can you tell me the mileage of your car?'),
  ('00000000-0000-4000-8000-000000002841', 'バスの走行中にせきを立つのはきけんです。', 'Leaving your seat while the bus is moving is dangerous.'),
  ('00000000-0000-4000-8000-000000002841', 'その電車は、ストライキが終わり次第、ホグワーツ魔法魔術学校への走行を再開する。', 'The train will start running to Hogwarts School of Witchcraft and Wizardry again as soon as the strike is over.'),
  ('00000000-0000-4000-8000-000000002842', 'わたしのいえはえきから近いです。', 'My house is close to the station.'),
  ('00000000-0000-4000-8000-000000002842', '今日は、ほぼすっぴんに近いです。', 'I''m wearing close to no makeup today.'),
  ('00000000-0000-4000-8000-000000002842', 'アメリカのビールって、カヌーの上ででんぐり返しをするみたいなものだよね。超水に近いんだもん。', 'Drinking American beer is like doing somersaults in a canoe. It’s too close to water.'),
  ('00000000-0000-4000-8000-000000002843', 'このゲームは、近日はつばいよていです。', 'This game is scheduled to be released soon.'),
  ('00000000-0000-4000-8000-000000002843', '田中さんがたのしみにしていたえいがが、ついに近日こうかいします。', 'The movie Mr. Tanaka was looking forward to will finally be released in a few days.'),
  ('00000000-0000-4000-8000-000000002843', '近日中にお会いして、ネットで見たことを一緒に語り合いましょう。', 'Let’s hang out in person soon and talk about things we saw online.'),
  ('00000000-0000-4000-8000-000000002844', '近年、日本しゅがまたブームになっています。', 'There has been another boom in Japanese alcohol in recent years.'),
  ('00000000-0000-4000-8000-000000002844', '近年のディズニーランドは、あまりこんざつしていないというのはかんぜんなるデマです。', 'It''s a total lie that Disneyland hasn''t been that packed in recent years.'),
  ('00000000-0000-4000-8000-000000002844', '豆腐を食べている河豚の存在が、近年徐々に明らかとなってきた。', 'The existence of a tofu-eating fugu has slowly been coming to light in recent years.'),
  ('00000000-0000-4000-8000-000000002845', 'わたしは、麦アレルギーがあります。', 'Saya memiliki alergi gandum.'),
  ('00000000-0000-4000-8000-000000002845', '大麦と小麦のちがいは何ですか。', 'Apa perbedaan antara jelai dan gandum?'),
  ('00000000-0000-4000-8000-000000002845', '「スクワット、スクワット、スクワット、麦とスクワット♪」屈伸をしながら彼は歌った。', '“Jongkok, jongkok, jongkok, jongkok, oat dan jongkok,” nyanyinya sambil jongkok.'),
  ('00000000-0000-4000-8000-000000002846', '日本の文化にきょうみがあります。', 'Saya tertarik dengan budaya Jepang.'),
  ('00000000-0000-4000-8000-000000002846', 'この国の文化にはなれましたか？', 'Apakah Anda sudah beradaptasi dengan budaya negara ini?'),
  ('00000000-0000-4000-8000-000000002846', 'コスプレは日本の文化の一つですか？', 'Apakah cosplay merupakan bagian dari budaya Jepang?'),
  ('00000000-0000-4000-8000-000000002847', '一まいのはっぱが、ひらりと地におちた。', 'One leaf fell lightly to the ground.'),
  ('00000000-0000-4000-8000-000000002847', 'コウイチはむかしはおおものだったけど、イノシシとのたたかいにまけてから、ひょうばんが地におちたよね。', 'Koichi used to be a big shot, but his reputation hit rock bottom after he lost a battle against a wild boar.'),
  ('00000000-0000-4000-8000-000000002847', 'しかし、コウイチ氏は意外と地に足をしっかりつけ続けています。', 'And yet, Koichi himself remains charmingly down-to-earth.'),
  ('00000000-0000-4000-8000-000000002848', 'このたてものの地下に、トイレがあります。', 'There is a restroom in the basement of this building.'),
  ('00000000-0000-4000-8000-000000002848', 'デパ地下でたくさんし食をしました。', 'I ate a lot of food samples at the food section of the department store basement.'),
  ('00000000-0000-4000-8000-000000002848', 'ヨハネの黙示録がもうすぐ実現されるから、私は地下室を建設しているのだよ。', 'The Apocalypse is coming soon so I’m building an underground cellar.'),
  ('00000000-0000-4000-8000-000000002849', 'ここは、あなたの土地ではありません。', 'This isn’t your land.'),
  ('00000000-0000-4000-8000-000000002849', 'コウイチはマインクラフトに広大な土地をもっている。', 'Koichi owns a vast tract of land in Minecraft.'),
  ('00000000-0000-4000-8000-000000002849', 'もし自分の土地があれば、ようやくそこに自分のベッドルームを手に入れることができるぜ！', 'If I had some land of my own, I’d finally get my own bedroom.'),
  ('00000000-0000-4000-8000-000000002850', 'スマートフォンで地図を出しました。', 'I got out the map on my smartphone.'),
  ('00000000-0000-4000-8000-000000002850', '地図をかた手に東京を歩きました。', 'I walked around Tokyo with a map.'),
  ('00000000-0000-4000-8000-000000002850', '先生、もし世界地図を忘れたのなら、私の額にタトゥーの世界地図がありますよ。', 'Teacher, if you forget your world map I have one tattoo''d on my forehead.'),
  ('00000000-0000-4000-8000-000000002851', '両手を上げて、バンザイをしました。', 'Mereka mengangkat kedua tangan dan meneriakkan banzai.'),
  ('00000000-0000-4000-8000-000000002851', '女の子は両手を広げてストレッチをした。', 'Gadis itu merentangkan tangannya dan meregangkan tubuh.'),
  ('00000000-0000-4000-8000-000000002851', 'バランスの良い食事とは、両手にチョコレートクッキーを持つことです。', 'Diet seimbang adalah kue coklat di kedua tangan.'),
  ('00000000-0000-4000-8000-000000002852', '両日とも、会ぎが入っています。', 'Saya akan menghadiri pertemuan kedua hari itu.'),
  ('00000000-0000-4000-8000-000000002852', 'とうふまつりは、両日ともせい天にめぐまれた。', 'Festival tahu memiliki cuaca yang bagus untuk kedua hari tersebut.'),
  ('00000000-0000-4000-8000-000000002852', 'iPadの使い方についての講義に両日とも参加したが、まだ使い方が分からない。', 'Saya menghadiri sesi kuliah iPad pada kedua hari tersebut, namun saya masih belum tahu cara menggunakannya.'),
  ('00000000-0000-4000-8000-000000002853', '姉も妹も、両方とも大さかにすんでいます。', 'Kakak dan adik perempuan saya tinggal di Osaka.'),
  ('00000000-0000-4000-8000-000000002853', 'じかんはあるんだから、両方やってみたら？', 'Anda punya waktu, jadi mengapa Anda tidak mencoba keduanya?'),
  ('00000000-0000-4000-8000-000000002853', 'ダメだよ！両方とも僕のだよ。', 'Tidak. Keduanya milikku.'),
  ('00000000-0000-4000-8000-000000002854', '全てうまく行きました。', 'Semuanya berjalan lancar.'),
  ('00000000-0000-4000-8000-000000002854', '申しわけございませんが、げんざい全てのおせきがうまっているじょうきょうでして...。', 'Maaf, tapi saat ini semua kursi sudah terisi penuh, jadi...'),
  ('00000000-0000-4000-8000-000000002854', '僕が先だよ。ウィキペディアが僕の宿題を全て真似したんだ。', 'Saya orang pertama yang melakukannya. Wikipedia menyalin seluruh pekerjaan rumah saya setelahnya.'),
  ('00000000-0000-4000-8000-000000002855', 'えきまで、全力で走りました。', 'Aku berlari sekuat tenaga menuju stasiun.'),
  ('00000000-0000-4000-8000-000000002855', 'その中国人の女は、王子が自分とけっこんしてくれるよう全力でせっとくしたが、しっぱいにおわった。', 'Wanita Tionghoa itu berusaha sekuat tenaga membujuk pangeran untuk menikahinya, tetapi dia gagal.'),
  ('00000000-0000-4000-8000-000000002855', 'そのゾンビは、死から蘇ろうと全力を尽くしていた。', 'Zombi itu menggunakan seluruh kekuatannya untuk mencoba bangkit dari kematian.'),
  ('00000000-0000-4000-8000-000000002856', 'これは、全日本バレーボール大会のしあいの写しんです。', 'Ini adalah gambar pertandingan turnamen Bola Voli Nasional Jepang.'),
  ('00000000-0000-4000-8000-000000002856', 'コウイチは、けん道の全日本せん手けんのしあいを見るために、日本に行っています。', 'Koichi berada di Jepang untuk menonton Kejuaraan Kendo Seluruh Jepang.'),
  ('00000000-0000-4000-8000-000000002856', '全日本が生クリームに包まれている。', 'Seluruh Jepang dilapisi krim kocok.'),
  ('00000000-0000-4000-8000-000000002857', 'ここまで来れば、安全です。', 'Jika saya datang ke sini, saya aman.'),
  ('00000000-0000-4000-8000-000000002857', 'ゆっくりでかまいませんので、安全うんてんでおねがいします。', 'Saya tidak keberatan jika kami sedikit lambat, jadi harap berkendara dengan aman.'),
  ('00000000-0000-4000-8000-000000002857', '安全第一が私のモットーです。', 'Motto saya adalah keselamatan yang utama.'),
  ('00000000-0000-4000-8000-000000002858', 'わたしは、方向が分からなくなりました。', 'Aku kehilangan arah.'),
  ('00000000-0000-4000-8000-000000002858', 'めっちゃ方向音ちなんですよ。', 'Saya sangat buruk dengan petunjuk arah!'),
  ('00000000-0000-4000-8000-000000002858', 'こっちの方向であってるの？チャッキー・チーズは反対方向だと思ってたんだけど。', 'Apakah kita menuju ke arah yang benar? Saya pikir Chuck E. Cheese adalah yang sebaliknya.'),
  ('00000000-0000-4000-8000-000000002859', 'そして、でん車は安い方がいいです。', 'Also, the cheap train is better.'),
  ('00000000-0000-4000-8000-000000002859', 'タイのぶっかはアメリカよりも安いです。', 'Prices in Thailand are cheaper than America.'),
  ('00000000-0000-4000-8000-000000002859', 'アパートの屋根から投げて粉々になるのを見てみたかったので、昨日すごく安いラジオを買った。', 'I bought a very cheap radio yesterday just so I could throw it off the roof of my apartment and watch it shatter.'),
  ('00000000-0000-4000-8000-000000002860', 'これで安心です。', 'That’s a relief.'),
  ('00000000-0000-4000-8000-000000002860', 'あの子は次の行どうがよそくできないから、安心できないのよね。', 'I never know what that kid will do next, so I can''t get peace of mind.'),
  ('00000000-0000-4000-8000-000000002860', 'お父さんの癌が無くなったことを聞いて、とても安心した。', 'I feel so relieved now that I know my dad no longer has cancer.'),
  ('00000000-0000-4000-8000-000000002861', 'ごうかくしているか不安です。', 'I’m anxious about passing.'),
  ('00000000-0000-4000-8000-000000002861', '出さんを目前に不安な気もちでいっぱいです。', 'I''m so nervous about the impending childbirth.'),
  ('00000000-0000-4000-8000-000000002861', 'あの殺人事件を目撃してからというもの、不安を取り除くことができない。', 'Since I witnessed the murder, I haven''t been able to rid myself of these feelings of anxiety.'),
  ('00000000-0000-4000-8000-000000002862', '平安じだいはいつですか。', 'Kapankah zaman Heian?'),
  ('00000000-0000-4000-8000-000000002862', '平安をみだす人がいないワニカニフォーラムは、わたしの心に平安をあたえてくれる。', 'Forum WaniKani tidak memiliki troll apa pun, jadi ini memberi saya ketenangan pikiran.'),
  ('00000000-0000-4000-8000-000000002862', 'ブリティッシュコロンビアの古の森を歩く時、心に平安を感じる。', 'Berjalan melalui hutan tua di British Columbia sungguh damai.'),
  ('00000000-0000-4000-8000-000000002863', 'ニューヨーク州の出しんです。', 'Saya dari negara bagian New York.'),
  ('00000000-0000-4000-8000-000000002863', 'アメリカがっしゅう国には、五十の州があります。', 'Ada lima puluh negara bagian di Amerika Serikat.'),
  ('00000000-0000-4000-8000-000000002863', 'オレゴン州ポートランド市には、トーフグの本社がある。', 'Kantor pusat Tofugu terletak di Portland, Oregon.'),
  ('00000000-0000-4000-8000-000000002864', '九州のりょうりはおいしいです。', 'Masakan Kyushu enak.'),
  ('00000000-0000-4000-8000-000000002864', '九州までは、フェリーでかた道一じかんです。', 'Dibutuhkan satu jam untuk sampai ke Kyushu dengan feri.'),
  ('00000000-0000-4000-8000-000000002864', '九州には、綺麗な女性が多い。', 'Ada banyak wanita cantik di Kyushu.'),
  ('00000000-0000-4000-8000-000000002865', 'この後、本州に行くつもりです。', 'Setelah ini saya berencana pergi ke Honshu.'),
  ('00000000-0000-4000-8000-000000002865', '本州とは、いったいぜんたい日本のどこにあるんですか？', 'Dimana sih Honshu di Jepang?'),
  ('00000000-0000-4000-8000-000000002865', '本州がどこか分からなければ、パソコンでしらべたらどうですか？', 'Jika Anda tidak tahu di mana letak Honshu, mengapa Anda tidak mencarinya di komputer Anda?'),
  ('00000000-0000-4000-8000-000000002866', 'その曲の名まえ、何だったっけ。', 'Apa nama lagu itu?'),
  ('00000000-0000-4000-8000-000000002866', '何かおすすめの曲はありますか？', 'Apakah ada lagu yang kamu rekomendasikan?'),
  ('00000000-0000-4000-8000-000000002866', '彼がピアノで一曲弾いてくれたんですが、何故かそのピアノはギターの様な音がしたんです。', 'Dia memainkan sebuah lagu untuk kami di piano, tapi entah kenapa, pianonya terdengar seperti gitar.'),
  ('00000000-0000-4000-8000-000000002867', 'クリスマスソングの名曲といえば、何だと思いますか。', 'Berbicara tentang lagu-lagu Natal yang terkenal, bagaimana menurut Anda?'),
  ('00000000-0000-4000-8000-000000002867', 'この曲は名曲だと言われているけど、わたしには他の曲と大してかわりない。', 'Ini dikenal sebagai karya musik yang luar biasa, tetapi bagi saya itu sama seperti musik lainnya.'),
  ('00000000-0000-4000-8000-000000002867', 'ベートーベンの「スモークサーモン」は名曲だ。', '"Smoked Salmon" karya Beethoven adalah sebuah mahakarya.'),
  ('00000000-0000-4000-8000-000000002868', 'マヨネーズなら、まだ少し有ります。', 'We still have a little mayonnaise.'),
  ('00000000-0000-4000-8000-000000002868', '一じかんに一本しかでん車は有りません。', 'There is only one train per hour.'),
  ('00000000-0000-4000-8000-000000002868', '彼の家には金も有るが、屋根の上に銀も有る。', 'There is gold in his house as well as silver on his roof.'),
  ('00000000-0000-4000-8000-000000002869', 'いえの近くに、有名なすしやがあります。', 'There is a famous sushi restaurant near my house.'),
  ('00000000-0000-4000-8000-000000002869', 'このきじはトーフグを一やくちょう有名にした。', 'This article suddenly made Tofugu super popular.'),
  ('00000000-0000-4000-8000-000000002869', '俺は有名だけど、お前はどうよ？', 'I’m famous, are you?'),
  ('00000000-0000-4000-8000-000000002870', '次のでん車にのりましょう。', 'Ayo naik kereta berikutnya.'),
  ('00000000-0000-4000-8000-000000002870', '次のよていは、決まり次だいお知らせします。', 'Saya akan memberi tahu Anda setelah kami memutuskan rencana selanjutnya.'),
  ('00000000-0000-4000-8000-000000002870', 'このバスツアーの次の目的地は、マイケル・ジャクソンの家です。', 'Destinasi selanjutnya dalam bus tour ini adalah rumah Michael Jackson.'),
  ('00000000-0000-4000-8000-000000002871', '次回の作ひんも、たのしみにしています。', 'Saya menantikan produksi berikutnya.'),
  ('00000000-0000-4000-8000-000000002871', '次回なんてないんだよ。人生は一どきりなんだから。', 'Tidak ada waktu berikutnya. Kita hanya hidup sekali.'),
  ('00000000-0000-4000-8000-000000002871', '兄貴、心配するなよ。次回は絶対あいつらを仕留めてやろうぜ。', 'Jangan khawatir, kawan. Kami akan mendapatkannya lain kali, yo.'),
  ('00000000-0000-4000-8000-000000002872', '目次のページがやぶれています。', 'Halaman daftar isi robek.'),
  ('00000000-0000-4000-8000-000000002872', '先ずはじめに、目次をごせつ明いたします。', 'Pertama, saya ingin menjelaskan daftar isi.')
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES
  ('00000000-0000-4000-8000-000000002872', 'この本全部読まないとだめ？目次だけ読むってことは無理かな？', 'Apakah saya harus membaca keseluruhan buku ini? Tidak bisakah saya membaca daftar isi saja?'),
  ('00000000-0000-4000-8000-000000002873', '今年の年次けいかくを立てましょう。', 'Mari kita putuskan proyek tahunan tahun ini.'),
  ('00000000-0000-4000-8000-000000002873', 'マリ子は年次有きゅう休か、何日もらえるの？', 'Berapa cuti tahunan yang kamu dapat, Mariko?'),
  ('00000000-0000-4000-8000-000000002873', '生徒たちの日本語がどれだけ上達したかに関する年次報告書を作成する。', 'Kami menulis laporan tahunan tentang seberapa besar kemajuan siswa bahasa Jepang kami.'),
  ('00000000-0000-4000-8000-000000002874', '死ぬかと思いました。', 'I thought I would die.'),
  ('00000000-0000-4000-8000-000000002874', 'わたしのそ母は、がんで死にました。', 'My grandmother died from cancer.'),
  ('00000000-0000-4000-8000-000000002874', '私は絶対に死なないと約束するよ。', 'I promise you that I will never die.'),
  ('00000000-0000-4000-8000-000000002875', 'だれが死体を見つけましたか。', 'Who found the dead body?'),
  ('00000000-0000-4000-8000-000000002875', 'だれが死体いきのようぎでたいほされたって？', 'Who did you say was arrested for abandoning a corpse?'),
  ('00000000-0000-4000-8000-000000002875', '私が初めて死体を見たのは、六歳の時です。', 'The first time I saw a dead body was when I was six years old.'),
  ('00000000-0000-4000-8000-000000002876', 'やさいをたくさん食べると、死亡リスクがへるそうです。', 'Saya mendengar bahwa jika Anda makan banyak sayuran, Anda dapat menurunkan risiko kematian.'),
  ('00000000-0000-4000-8000-000000002876', '山田さんの弟さんの死亡のげんいんはなんですか？', 'Apa penyebab kematian adik Pak Yamada?'),
  ('00000000-0000-4000-8000-000000002876', 'チーズバーガーの発明により、全先進国の死亡率が三倍に跳ね上がった。', 'Sejak ditemukannya burger keju, angka kematian di semua negara maju meningkat tiga kali lipat.'),
  ('00000000-0000-4000-8000-000000002877', 'どうぶつえんで、羊にえさをやりました。', 'Saya harus memberi makan domba di kebun binatang.'),
  ('00000000-0000-4000-8000-000000002877', 'いつ何がおこるか分からないんだから、羊がかいたいなら、かいたいと思ったときにかった方がいいよ。', 'Apa pun bisa terjadi kapan saja, jadi jika Anda menginginkan seekor domba, dapatkanlah.'),
  ('00000000-0000-4000-8000-000000002877', '毛を刈られた時、羊も恥ずかしい思いをしていると思う？', 'Apakah menurut Anda domba merasa malu ketika bulunya dicukur?'),
  ('00000000-0000-4000-8000-000000002878', 'クリスマスプレゼントに、羊毛のブランケットをもらいました。', 'Saya mendapat selimut wol sebagai hadiah Natal.'),
  ('00000000-0000-4000-8000-000000002878', 'この羊毛フェルトの人形に出会えて本当によかった。', 'Saya sangat senang bisa menemukan boneka wol ini.'),
  ('00000000-0000-4000-8000-000000002878', '羊毛の手袋は、枕の詰め物に適している。', 'Sarung tangan wol sangat bagus untuk mengisi bantal.'),
  ('00000000-0000-4000-8000-000000002879', 'シャツに血がついていますよ。', 'Ada darah di bajumu.'),
  ('00000000-0000-4000-8000-000000002879', 'うんちをするときにおしりから血が出るのはなぜなんだ！', 'Mengapa pantat saya berdarah saat buang air besar?'),
  ('00000000-0000-4000-8000-000000002879', '血が滴るぐらいのステーキが好きです。', 'Saya suka steak yang masih banyak darahnya.'),
  ('00000000-0000-4000-8000-000000002880', 'なかなか出血が止まりません。', 'Pendarahannya tidak berhenti.'),
  ('00000000-0000-4000-8000-000000002880', 'トーフグはぜっさん出血大サービス中です。', 'Tofugu memberi Anda diskon besar!'),
  ('00000000-0000-4000-8000-000000002880', '指を抜いていれば、鼻からの出血は止まると思います。', 'Saya pikir hidung saya akan berhenti mengeluarkan darah jika saya tidak mengeluarkan jari saya.'),
  ('00000000-0000-4000-8000-000000002881', 'お国はどちらですか。', 'Which country are you from?'),
  ('00000000-0000-4000-8000-000000002881', 'この国は安全だと思っていたのに、がっかりです。', 'I thought this country was safe, but now I''m disappointed.'),
  ('00000000-0000-4000-8000-000000002881', '私の国には、猫が焼くアップルパイのお店がある。', 'In my country, there is a shop that sells apple pies made by a cat.'),
  ('00000000-0000-4000-8000-000000002882', '来月は、出ちょうで中国に行きます。', 'Next month I’m traveling to China on business.'),
  ('00000000-0000-4000-8000-000000002882', '冬休みに、中国でりゅう星ぐんを見ました。', 'During winter break, I watched the meteor shower in China.'),
  ('00000000-0000-4000-8000-000000002882', 'どうして日本人は中国を支那と呼ぶことをやめて中国と呼び始めたんだろう。', 'Why did Japanese people stop calling China "Shina" and start calling it "Chuugoku?"'),
  ('00000000-0000-4000-8000-000000002883', 'ポチはきっと天国にいるんだよ。', 'Poochie is definitely in heaven.'),
  ('00000000-0000-4000-8000-000000002883', '天国がこんなとこだったなんて、本当にがっかりです。', 'I am so disappointed to learn the Kingdom of Heaven is that kind of place.'),
  ('00000000-0000-4000-8000-000000002883', 'タバコを天国で吸いましょう。', 'Let’s smoke cigarettes in Heaven.'),
  ('00000000-0000-4000-8000-000000002884', '全国でインフルエンザがはやっています。', 'Flu menyebar secara nasional.'),
  ('00000000-0000-4000-8000-000000002884', 'リンゴのしゅうかくりょうが全国で一ばん多いけんはどこですか？', 'Prefektur manakah yang merupakan penghasil apel terbesar secara nasional?'),
  ('00000000-0000-4000-8000-000000002884', '彼は全国規模のサイバーいじめのスキャンダルに関与していた。', 'Dia terlibat dalam skandal cyberbullying nasional.'),
  ('00000000-0000-4000-8000-000000002885', '四国にはまだ行ったことがありません。', 'I still haven’t been to Shikoku.'),
  ('00000000-0000-4000-8000-000000002885', '四国での生活にはなれましたか？', 'Have you gotten used to life in Shikoku yet?'),
  ('00000000-0000-4000-8000-000000002885', '最高の饂飩の作り方を求めて、四国を旅していた。', 'I was traveling through Shikoku to learn how to make the best udon noodles.'),
  ('00000000-0000-4000-8000-000000002886', 'わたしたちはまだ外国に行ったことがありません。', 'We haven’t gone to other countries yet.'),
  ('00000000-0000-4000-8000-000000002886', '外国へでんわをするのはこれがはじめてです。', 'This is my first time making an overseas call.'),
  ('00000000-0000-4000-8000-000000002886', 'もし外国にいるなら、有名人になっても構わない。', 'I wouldn’t mind being a celebrity if I was in a foreign country.'),
  ('00000000-0000-4000-8000-000000002887', '今日、外国人の友だちと、かいものに行きました。', 'Today, I went shopping with my foreign friends.'),
  ('00000000-0000-4000-8000-000000002887', 'その外国人の目は血走っていた。', 'That foreigner''s eyes were bloodshot.'),
  ('00000000-0000-4000-8000-000000002887', 'いいえ、私は人種差別主義者ではありません。世界中の全ての外国人に会って、それぞれ個人的に嫌いになっただけです。', 'No, I’m not racist. I’ve met every kind of foreign person on the planet and I just hate each of them equally.'),
  ('00000000-0000-4000-8000-000000002888', '米国の大とうりょうの名まえを知っていますか。', 'Tahukah Anda nama presiden Amerika Serikat?'),
  ('00000000-0000-4000-8000-000000002888', '米国には元々何もきたいなんてしてなかったよ。', 'Saya tidak pernah mengharapkan apa pun dari AS.'),
  ('00000000-0000-4000-8000-000000002888', '多くの人は、単にマクドナルドのスーパーサイズコンボのために米国に移住する。', 'Banyak orang berimigrasi ke Amerika Serikat hanya untuk menikmati kombo ukuran super di McDonald''s.'),
  ('00000000-0000-4000-8000-000000002889', 'きのうの夜、パーティーに行きました。', 'I went to a party last night.'),
  ('00000000-0000-4000-8000-000000002889', 'きのうの夜は、こうふんしてほとんどねむれませんでした。', 'Last night, I was so excited that I barely slept.'),
  ('00000000-0000-4000-8000-000000002889', '夜には、モンスターたちが床から這い上がり、私のベッドの下でお茶会を開くんだよ。', 'Night is the time when monsters crawl up through the floor to have tea parties under my bed.'),
  ('00000000-0000-4000-8000-000000002890', '今夜、いっしょにのみに行きませんか。', 'Would you like to go out for drinks with me tonight?'),
  ('00000000-0000-4000-8000-000000002890', '明日しけんがあるから、今夜はてつ夜でがんばります。', 'The exam is coming up tomorrow, so I am gonna burn the midnight oil tonight.'),
  ('00000000-0000-4000-8000-000000002890', '今夜は晩ご飯に手羽先が食べたい気分だ。', 'I feel like eating chicken wings for dinner tonight.'),
  ('00000000-0000-4000-8000-000000002891', '二人の姉妹はとてもよくにています。', 'Those two sisters look so alike.'),
  ('00000000-0000-4000-8000-000000002891', '何か、二人って姉妹みたいだよね。', 'Hey, you two kinda look like sisters.'),
  ('00000000-0000-4000-8000-000000002891', '単なる女友達には無い絆が、姉妹の間にはある。', 'There is a bond between sisters that isn’t shared between girls who are just friends.'),
  ('00000000-0000-4000-8000-000000002892', '田中さんの妹はどの人ですか。', 'Who is Tanaka’s younger sister?'),
  ('00000000-0000-4000-8000-000000002892', '妹にうら切られた気分です。', 'I feel betrayed by my little sister.'),
  ('00000000-0000-4000-8000-000000002892', '私の妹は、バービー人形にウィッグを作ってあげたいからと、自分の髪の毛を切った。', 'My younger sister just cut off all of her hair so she could make wigs for her Barbie dolls.'),
  ('00000000-0000-4000-8000-000000002893', 'みどりちゃんのお姉さんはめがねをかけています。', 'Midori’s older sister is wearing glasses.'),
  ('00000000-0000-4000-8000-000000002893', 'あなたのこと、てっきりビエトくんのお姉さんだと思ってたんですが、ちがったんですね。', 'I totally thought you were Viet''s older sister, but you aren''t, eh?'),
  ('00000000-0000-4000-8000-000000002893', '私のお姉さんは、バイクを買うことが彼氏を見つけることに繋がると考えています。', 'My older sister thinks that buying a motorcycle will help her get a boyfriend.'),
  ('00000000-0000-4000-8000-000000002894', 'えきからその店までの地図をかいてください。', 'Please draw a map from the station to the store.'),
  ('00000000-0000-4000-8000-000000002894', 'この店は年内はすでにずっとよやくでいっぱいだ。', 'The restaurant is already fully booked for the rest of the year.'),
  ('00000000-0000-4000-8000-000000002894', 'この店のこと絶対気に入るぜ。世界一うまいミートローフがあるんだよ。', 'You’re going to love this shop. They have the best meatloaf in the world.'),
  ('00000000-0000-4000-8000-000000002895', 'このへやは明るい。', 'This room is bright.'),
  ('00000000-0000-4000-8000-000000002895', 'トーフグのみんなは明るい。', 'Everyone at Tofugu is cheerful.'),
  ('00000000-0000-4000-8000-000000002895', '未来はまだまだ明るいよ、おじいちゃん。', 'Your future is still bright, Grandpa.'),
  ('00000000-0000-4000-8000-000000002896', 'このはなしの作しゃは不明です。', 'The author of this story is unknown.'),
  ('00000000-0000-4000-8000-000000002896', 'この牛にゅうのしょうみきげんは不明です。', 'This milk doesn''t have an expiration date on it.'),
  ('00000000-0000-4000-8000-000000002896', 'え？寝る時、玉ねぎを枕にしたの？あんたの言ってること、意味不明なんだけど。', 'Huh? When you were sleeping you used an onion for a pillow? I don’t really get what you’re saying.'),
  ('00000000-0000-4000-8000-000000002897', 'この男は、東方の国から来たらしい。', 'Apparently this man is from a country in the East.'),
  ('00000000-0000-4000-8000-000000002897', 'その宝は、東方の地のどこかにあるそうだ。', 'The treasure is said to be somewhere in the lands to the east.'),
  ('00000000-0000-4000-8000-000000002897', 'マルコ・ポーロの『東方見聞録』はもう読みましたか？', 'Have you read "The Travels of Marco Polo" by Marco Polo?'),
  ('00000000-0000-4000-8000-000000002898', '東北で、ボランティアをしていました。', 'I was volunteering in Tohoku.'),
  ('00000000-0000-4000-8000-000000002898', '東北で一人ぐらしをしています。', 'I''m living by myself in Tohoku now.'),
  ('00000000-0000-4000-8000-000000002898', 'マグニチュード8.9の地震が、日本の東北地方の海岸を襲った。', 'A magnitude 8.9 earthquake slammed into Japan’s northeastern coast.'),
  ('00000000-0000-4000-8000-000000002899', 'けさ、テレビで中東のニュースを見ました。', 'I watched the news on the Middle East on TV this morning.'),
  ('00000000-0000-4000-8000-000000002899', 'きんきゅうじたいで中東に行かなくてはいけなかったんだから、けっこんしきに来れなかったのは仕方がないよ。', 'You can''t help it that you couldn''t make it to the wedding because you had to go to the Middle East for an emergency.'),
  ('00000000-0000-4000-8000-000000002899', '中東で一番楽しまれているゲームは何ですか？', 'What is the most played game in the Middle East?'),
  ('00000000-0000-4000-8000-000000002900', '車は、南東に向かってすすみました。', 'The car continued heading southeast.'),
  ('00000000-0000-4000-8000-000000002900', 'てっきり今日は日が南東にしずむもんだとおもっていたよ。', 'I totally thought the sun would set in the southeast today.'),
  ('00000000-0000-4000-8000-000000002900', '南東の方角に、流れ星を見た。', 'I saw a shooting star in the southeast.'),
  ('00000000-0000-4000-8000-000000002901', '学こうまで歩くつもりです。', 'I’m planning to walk to school.'),
  ('00000000-0000-4000-8000-000000002901', 'あなたと手をつないで歩くなんて、何年ぶりかしら。', 'It''s the first time we''ve walked holding hands in a long time.'),
  ('00000000-0000-4000-8000-000000002901', '私はとても太いので、私が道を歩いている時にペニーを踏んだら、女王様の鼻から鼻くそが飛び出ます。', 'I’m so fat that when I walk down the street and step on a penny, I squeeze a booger out of the Queen’s nose.'),
  ('00000000-0000-4000-8000-000000002902', 'パソコンがこわれたんですが、直せますか。', 'PC saya rusak. Bisakah Anda memperbaikinya?'),
  ('00000000-0000-4000-8000-000000002902', '考え直した方がいいですよ。', 'Sebaiknya Anda memikirkannya lagi.'),
  ('00000000-0000-4000-8000-000000002902', 'もし壊れていなければ、それを直そうとする必要はないよ。', 'Anda tidak perlu memperbaiki sesuatu jika tidak rusak.'),
  ('00000000-0000-4000-8000-000000002903', 'こしょうした車が直るのはいつですか。', 'Kapan saya bisa memperbaiki mobil saya yang rusak?'),
  ('00000000-0000-4000-8000-000000002903', 'それでアヤの気げんが直るなら、おれはぜんぜんかまわないよ。', 'Kalau itu membuatmu merasa lebih baik, maka aku tidak keberatan sama sekali, Aya.'),
  ('00000000-0000-4000-8000-000000002903', '農夫の壊れたトラクターは直った。', 'Traktor milik petani yang rusak telah diperbaiki.'),
  ('00000000-0000-4000-8000-000000002904', '川田さんは、とても正直な人です。', 'Kawata adalah orang yang sangat jujur.'),
  ('00000000-0000-4000-8000-000000002904', 'かれの正直なところがすきなんです。', 'Saya suka kejujurannya.'),
  ('00000000-0000-4000-8000-000000002904', '僕は水中で息をしている火星からきた王子だし、他の人の模範となる必要があるので、いつも正直でいようと心がけています。', 'Saya berusaha jujur ​​sepanjang waktu karena saya adalah pangeran Mars yang bernapas di bawah air dan saya perlu memberi contoh kepada orang-orang.'),
  ('00000000-0000-4000-8000-000000002905', 'このひ行きは、東京に直行します。', 'Pesawat ini nonstop ke Tokyo.'),
  ('00000000-0000-4000-8000-000000002905', '今日は、日本との会ぎの後、トーフグとのアポに直行します。', 'Hari ini setelah pertemuan dengan Jepang, saya akan langsung pergi ke janji temu dengan Tofugu.'),
  ('00000000-0000-4000-8000-000000002905', 'ごめんなさい、今は話せません。トイレへ直行しているところなのです。', 'Maaf, saya tidak bisa bicara sekarang. Saya sedang dalam perjalanan tanpa henti ke kamar mandi.'),
  ('00000000-0000-4000-8000-000000002906', 'このえいがは長かったです。', 'This movie was long.'),
  ('00000000-0000-4000-8000-000000002906', 'あそこのドアの近くに立ってるかみの長い女性が、たん当しゃの方です。', 'That lady with long hair standing by the door is the one in charge.'),
  ('00000000-0000-4000-8000-000000002906', '長い距離のランニングを避けるため、自分の足の骨を折ってしまおうと思っている。', 'I''m thinking about breaking my own legs to avoid going long distance running.'),
  ('00000000-0000-4000-8000-000000002907', '社長は会ぎ中です。', 'The company president is in a meeting.'),
  ('00000000-0000-4000-8000-000000002907', 'あの人気サービスのねだんを下げるなんて、トーフグの社長はどうかしてるよ。', 'The president of Tofugu is insane to lower the price of that popular service.'),
  ('00000000-0000-4000-8000-000000002907', '全社員は社長のことを嫌っているが、私は単に彼は少し意地悪なだけだと思っている。', 'All my coworkers hate my boss, but I just think he’s a little mean.'),
  ('00000000-0000-4000-8000-000000002908', '前は花やで、花やのとなりはさかなやです。', 'In front is a flower shop and next door to it is a fish shop.'),
  ('00000000-0000-4000-8000-000000002908', '毎あさ、会社に行く前に、スクワットを五百回します。', 'Every morning I do 500 squats before leaving for work.'),
  ('00000000-0000-4000-8000-000000002908', '赤信号の前にいる時、「もうすぐ青に変わるぞ！」と思うとかなり興奮する。', 'When I’m in front of a red light, I get very excited at the thought of it turning green soon.'),
  ('00000000-0000-4000-8000-000000002909', 'このデパートは、午前十じにひらきます。', 'This department store opens at 10:00 am.'),
  ('00000000-0000-4000-8000-000000002909', 'わたしのむす子は、まだ午前中にあさねをするひつようがあります。', 'My son still needs to take a nap in the morning.'),
  ('00000000-0000-4000-8000-000000002909', '今日は午前9時にテレパシーで投稿する予定にしているので、もし君がその時何か面白いことを考えたら、それは私の仕業だから。', 'I’ll be posting telepathically at 9AM today, so if you think of something funny, that was me.'),
  ('00000000-0000-4000-8000-000000002910', 'としょかんの南に、交ばんがあります。', 'There is a police station on the south side of the library.'),
  ('00000000-0000-4000-8000-000000002910', 'どうして東日本りょかくてつ道と西日本りょかくてつ道はあるのに、北日本りょかくてつ道と南日本りょかくてつ道はないんだ？', 'Why isn''t there a North Japan Railway Company and a South Japan Railway Company, even though there''s an East Japan Railway Company and a West Japan Railway Company?'),
  ('00000000-0000-4000-8000-000000002910', '南球場でブラッド・ピットを見た。', 'I saw Brad Pitt at the south baseball stadium.'),
  ('00000000-0000-4000-8000-000000002911', 'あなたの後ろのドアをしめてください。', 'Please close the door behind you.'),
  ('00000000-0000-4000-8000-000000002911', 'チャイルドシートは、かならず後ろのざせきにせっちしてください。', 'You must install the child carseat on the rear seat of the car.'),
  ('00000000-0000-4000-8000-000000002911', '振り返って後ろを見た後、さらにもう一度振り返ったら、僕のことが見えるよ。', 'If you turn around to look behind you and then do it again, you’ll see me.'),
  ('00000000-0000-4000-8000-000000002912', '後でいっしょにお茶でもしませんか。', 'Why don’t we have some tea together later?'),
  ('00000000-0000-4000-8000-000000002912', '後で、「言わんこっちゃない」って言わせないでよ。', 'Don''t make me say, "I told you so," later.'),
  ('00000000-0000-4000-8000-000000002912', 'その映画を見終わった後で、もう一度それを見るために違う映画館へ向かった。', 'After the movie, we headed across town to watch it again in another theater.'),
  ('00000000-0000-4000-8000-000000002913', '女の人は、あしたの午後、何をしますか。', 'What are the women going to do tomorrow afternoon?'),
  ('00000000-0000-4000-8000-000000002913', '直近の午後で空いているじかんは何じですか？', 'What''s the closest time in the afternoon that''s available for an appointment?'),
  ('00000000-0000-4000-8000-000000002913', '午後三時に、足の巻き爪を取り除くためのお医者さんの予約がある。', 'I have an appointment with my doctor at 3PM to remove an ingrown toenail.'),
  ('00000000-0000-4000-8000-000000002914', 'かれも来ると思いますよ。', 'I think he’s coming too.'),
  ('00000000-0000-4000-8000-000000002914', 'ハリケーンのきせつはメキシコに行くのをさけた方がいいと思いますか。', 'Do you think I should avoid going to Mexico during hurricane season?'),
  ('00000000-0000-4000-8000-000000002914', '思うだけならまだ違法じゃないよ。', 'The simple act of thinking is not illegal, yet.'),
  ('00000000-0000-4000-8000-000000002915', '夜には、星がとてもきれいでした。', 'Malam itu bintang-bintang sangat cantik.'),
  ('00000000-0000-4000-8000-000000002915', '今夜はたくさんながれ星が見れるといいんですが。', 'Saya harap kita bisa melihat banyak bintang jatuh malam ini.'),
  ('00000000-0000-4000-8000-000000002915', 'お父さん、どうして今日は星型のメガネをかけているの？', 'Ayah, kenapa hari ini ayah memakai kacamata berbentuk bintang?'),
  ('00000000-0000-4000-8000-000000002916', 'アメリカと日本の生活のちがいをおしえてください。', 'Tolong beritahu saya perbedaan antara kehidupan Amerika dan Jepang?'),
  ('00000000-0000-4000-8000-000000002916', 'あなたとの生活をもう一どやり直したいんです。', 'Aku ingin kembali bersama dan tinggal bersamamu lagi.'),
  ('00000000-0000-4000-8000-000000002916', '毎日の生活でアニメを見ながらマシュマロを食べることができたら、とても幸せです。', 'Saya akan sangat senang jika saya bisa menonton kartun dan makan marshmallow setiap hari dalam hidup saya.'),
  ('00000000-0000-4000-8000-000000002917', '海で泳ぎました。', 'I went swimming in the sea.'),
  ('00000000-0000-4000-8000-000000002917', '海の公えんで、先生が学生に話しています。', 'The teacher is talking to her students in Marine Park.'),
  ('00000000-0000-4000-8000-000000002917', '映画「水の世界」は、実は、海の底に住んでいる超頭のいい魚によって書かれた作品だ。', 'The movie Water World was actually written by a race of super-intelligent fish that live at the bottom of the ocean.'),
  ('00000000-0000-4000-8000-000000002918', 'しょう来は、海外ではたらきたいです。', 'I want to work overseas in the future.'),
  ('00000000-0000-4000-8000-000000002918', 'ほけんぎょうかいに八年つとめた後、アメリカへ海外りゅう学しました。', 'After having worked in the insurance industry for eight years, I went to America to study abroad.'),
  ('00000000-0000-4000-8000-000000002918', '私はどこか海外で住みたいと思っているが、旅行は嫌いだ。', 'I want to live somewhere overseas, but I hate traveling.'),
  ('00000000-0000-4000-8000-000000002919', 'ねつが、三十八点九どあります。', 'Saya demam 38,9 derajat.'),
  ('00000000-0000-4000-8000-000000002919', 'このクローゼットにある二点五ばいのりょうのふくが他のへやにもちらばっています。', 'Dibandingkan dengan yang ada di lemari ini, pakaian saya 2,5 kali lebih banyak berserakan di ruangan lain.'),
  ('00000000-0000-4000-8000-000000002919', 'あの映画が駄作だったという点ではあなたに同意しますが、時間の無駄だったと気づいたのは映画が終わってからでした。', 'Saya setuju dengan pendapat Anda bahwa filmnya sangat buruk, tetapi saya tidak menyadari bahwa itu hanya membuang-buang waktu sampai film itu selesai.'),
  ('00000000-0000-4000-8000-000000002920', 'かの女のせんもんは、科学です。', 'Jurusannya adalah sains.'),
  ('00000000-0000-4000-8000-000000002920', '日本は科学ぎじゅつというめんにおいてとてもすぐれています。', 'Jepang sangat maju dalam bidang ilmu pengetahuan dan teknologi.'),
  ('00000000-0000-4000-8000-000000002920', '我々に蚊除け剤を作らせてくれる科学は、本当に偉大だ。', 'Ilmu pengetahuan sungguh menakjubkan karena memungkinkan kita membuat obat nyamuk.'),
  ('00000000-0000-4000-8000-000000002921', 'わたしはお茶をのみませんでした。', 'I didn’t drink tea.'),
  ('00000000-0000-4000-8000-000000002921', '死ぬ前に、ベーコンのお茶づけが食べたい。', 'I want to eat bacon rice covered in tea before I die.'),
  ('00000000-0000-4000-8000-000000002921', '何故かおならがしたくなるので、もうお茶を飲むことはできない。', 'I can’t drink tea anymore because it makes me fart.'),
  ('00000000-0000-4000-8000-000000002922', '★に入るばんごうを、茶色にぬります。', 'Please color the number that best matches the ★ with brown.'),
  ('00000000-0000-4000-8000-000000002922', '明るい茶色にカラーリングしてください。', 'I''d like to dye my hair light brown, please.'),
  ('00000000-0000-4000-8000-000000002922', '私の白いTシャツ全ての脇のところに、茶色のシミがある。', 'All of my white t-shirts have brown armpit stains on them.'),
  ('00000000-0000-4000-8000-000000002923', '毎あさ、なっとうを食べます。', 'I eat natto every morning.'),
  ('00000000-0000-4000-8000-000000002923', 'いつも、けんこうにいいものを食べるじかんがないんです。', 'I never have enough time to eat healthy foods.'),
  ('00000000-0000-4000-8000-000000002923', '私は、寝ながら食べるのが好きだ。夢遊病のような感じで、それは夢遊食事病と呼ばれる。', 'I like to eat while I’m sleeping. It’s just like sleepwalking, but it’s called sleep-eating.'),
  ('00000000-0000-4000-8000-000000002924', 'パソコンのしすぎで、首がいたいです。', 'Saya terlalu sering menggunakan komputer sehingga leher saya sakit.'),
  ('00000000-0000-4000-8000-000000002924', '首をねちがえました。', 'Aku menekuk leherku dalam tidurku.'),
  ('00000000-0000-4000-8000-000000002924', '腺ペストって、首から胸が生えてくる病気のことですか？', 'Apakah penyakit pes adalah penyakit yang membuat orang memiliki payudara di lehernya?'),
  ('00000000-0000-4000-8000-000000002925', '足首をひねってしまいました。', 'Aku memutar pergelangan kakiku.'),
  ('00000000-0000-4000-8000-000000002925', '右の足首がすごくいたいんです！', 'Pergelangan kaki kanan saya sangat sakit.'),
  ('00000000-0000-4000-8000-000000002925', '宙に舞う羽から逃げる途中で、足首を捻挫した。', 'Pergelangan kakiku terkilir saat melarikan diri dari bulu yang melayang di udara.'),
  ('00000000-0000-4000-8000-000000002926', '先月、会社を首になりました。', 'Saya dipecat dari perusahaan bulan lalu.'),
  ('00000000-0000-4000-8000-000000002926', 'しゅう金したお金をつかいこんだら、首になるに決まってるじゃん！', 'Tentu saja kalian akan dipecat, jika uang yang terkumpul sudah habis.'),
  ('00000000-0000-4000-8000-000000002926', 'マーチングバンドを職場に引き連れてきたことが理由で、私は昨日首になりました。', 'Saya dipecat kemarin karena membawa marching band ke tempat kerja bersama saya.'),
  ('00000000-0000-4000-8000-000000002927', 'だれだって、何かしらの欠点をもってるものさ。', 'Setiap orang mempunyai kelemahan.'),
  ('00000000-0000-4000-8000-000000002927', 'そうだ、ちょっと思い出したんだけど、かの女って欠点がないんだよ。', 'Oh, aku baru ingat, dia tidak punya kesalahan apa pun.'),
  ('00000000-0000-4000-8000-000000002927', '私は欠点がありすぎるので、絶対にプロのサッカー選手にはなれません。たとえば、私には足がありません。', 'Saya tidak akan pernah menjadi pemain sepak bola profesional karena saya mempunyai terlalu banyak kekurangan, misalnya saja saya tidak mempunyai kaki.'),
  ('00000000-0000-4000-8000-000000002928', 'やはり、アベ氏のはつげんはいつも全くブレませんね。', 'Seperti kita ketahui bersama, pernyataan Pak Abe tidak pernah berubah.'),
  ('00000000-0000-4000-8000-000000002928', 'コウイチ氏とビエト氏はとても気が合う。', 'Pak Koichi dan Pak Viet punya chemistry yang bagus.'),
  ('00000000-0000-4000-8000-000000002928', 'おお、ホワイト氏、ちょっと座れば？', 'Yo, Tuan White, kenapa Anda tidak duduk saja?'),
  ('00000000-0000-4000-8000-000000002929', '自分の氏名ぐらいは、日本ごでかけるようになりたいよね。', 'Anda setidaknya ingin bisa menulis nama lengkap Anda dalam bahasa Jepang, bukan?'),
  ('00000000-0000-4000-8000-000000002929', 'ごさん考までに、わたしの氏名は、高 一子です。', 'Sekadar informasi, nama saya Ichiko Ko.'),
  ('00000000-0000-4000-8000-000000002929', 'そちらの誓約書に氏名をご記入頂ければ、大砲で貴方の頭の上の林檎を撃ちぬいて差し上げます。', 'Jika Anda berkenan menuliskan nama depan dan belakang Anda di surat pernyataan, kami akan melanjutkan dengan menembakkan sebuah apel dari kepala Anda dengan meriam.'),
  ('00000000-0000-4000-8000-000000002930', '一人ぐらしをはじめて、自由なじかんができました。', 'Saya mulai hidup sendiri dan memiliki waktu luang.'),
  ('00000000-0000-4000-8000-000000002930', '自由になるための道のりはまだまだとおいですが、ぜったいにあきらめません。', 'Untuk memperoleh kebebasan, perjalanan kita masih panjang, namun kita tidak akan pernah menyerah.'),
  ('00000000-0000-4000-8000-000000002930', '日本のサラリーマンが自由に使えるお金は、毎月平均たった三万五千円だ。', 'Uang yang dapat digunakan secara bebas oleh pegawai gaji Jepang setiap bulan rata-rata biasanya hanya 35.000 yen.'),
  ('00000000-0000-4000-8000-000000002931', 'とくに理由はありません。', 'Saya tidak punya alasan khusus.'),
  ('00000000-0000-4000-8000-000000002931', '未だけいひのせいさんをしてないのには、何か理由があるんですか？', 'Apakah Anda punya alasan untuk belum melunasi pengeluaran bisnis Anda?'),
  ('00000000-0000-4000-8000-000000002931', '論理的な理由から、彼は行方不明になったゴム手袋の事件の犯人が風船屋であることを導いた。', 'Untuk alasan yang logis, dia dituntun untuk percaya bahwa pelaku dalam kasus hilangnya sarung tangan karet adalah si penerbang balon.'),
  ('00000000-0000-4000-8000-000000002932', '一万円札を小ぜににくずしてもらえませんか？', 'Bisakah Anda memberi saya kembalian uang 10.000 yen?'),
  ('00000000-0000-4000-8000-000000002932', 'この二千円札、千円札二枚と両がえしてくれない？', 'Bisakah Anda membagi uang 2.000 yen ini menjadi dua lembar uang 1.000 yen?'),
  ('00000000-0000-4000-8000-000000002932', 'トーフグのオフィスのあちこちに、百ドル札が隠されているらしいぜ。', 'Rupanya, ada banyak uang kertas ratusan dolar yang disembunyikan di seluruh kantor Tofugu.'),
  ('00000000-0000-4000-8000-000000002933', '千円札のおつりが不足しています。', 'Saya tidak punya uang kembalian untuk uang seribu yen.'),
  ('00000000-0000-4000-8000-000000002933', 'これは、水そうから紙のひしゃくで千円札をすくうゲームです。', 'Ini adalah permainan di mana Anda mengambil uang ribuan yen dengan sendok kertas dari tangki air.'),
  ('00000000-0000-4000-8000-000000002933', '「千ドル札を燃やしてるの？」「いや、ただの千円札だよ。」', '"Apakah kamu membakar uang seribu dolar?" "Tidak, ini hanya uang seribu yen."'),
  ('00000000-0000-4000-8000-000000002934', '本当に国民はわれわれにさんせいしてくれるのでしょうか。', 'Akankah masyarakat benar-benar memberikan persetujuannya kepada kita?'),
  ('00000000-0000-4000-8000-000000002934', 'どうすれば日本国民になれますか。', 'Bagaimana cara menjadi warga negara Jepang?'),
  ('00000000-0000-4000-8000-000000002934', '昨夜、PS4の新ゲームを買うために並んでいた国民たちは、凍って死にました。', 'Orang-orang yang mengantri untuk game baru PS4 tadi malam membeku sampai mati.'),
  ('00000000-0000-4000-8000-000000002935', '辺りはしーんとしずまりかえっていた。', 'Daerah itu menjadi sunyi.'),
  ('00000000-0000-4000-8000-000000002935', 'そうだ、ちょっと言いわすれていたんだけど、この辺りにえきはないからね。', 'Oh, aku lupa memberitahumu bahwa tidak ada stasiun di lingkungan ini.'),
  ('00000000-0000-4000-8000-000000002935', '彼のトイレはこの辺りに違いない。', 'Kamar mandinya pasti ada di sekitar sini.'),
  ('00000000-0000-4000-8000-000000002936', 'この辺は、人が少ないのでしずかです。', 'Tidak banyak orang di sekitar sini, jadi sepi.'),
  ('00000000-0000-4000-8000-000000002936', 'この辺に、スタバはありますか？', 'Apakah ada Starbucks di sekitar sini?'),
  ('00000000-0000-4000-8000-000000002936', 'この辺では、言葉に気をつけた方がいいぜ。町のこちら側に住んでいるやつらは、口笛を吹いただけでも顔に唾をぶっかけてきやがるからな。', 'Anda harus berhati-hati dengan apa yang Anda katakan di sini. Orang-orang di sisi kota ini akan meludahi wajah Anda hanya karena bersiul.'),
  ('00000000-0000-4000-8000-000000002937', 'グリルドチーズにはケチャップを付けるはですか？', 'Apakah Anda salah satu orang yang memasukkan saus tomat ke dalam keju panggangnya?'),
  ('00000000-0000-4000-8000-000000002937', 'どうしてワンちゃんに、ニッカって名前を付けたんですか？', 'Mengapa kamu menamai anjingmu Nikka?'),
  ('00000000-0000-4000-8000-000000002937', 'どうして頭に蛭を付けているんですか？', 'Mengapa kamu menempelkan lintah di kepalamu?'),
  ('00000000-0000-4000-8000-000000002938', 'ビール以外ならなんでもいいです。', 'I’m okay with anything other than beer.'),
  ('00000000-0000-4000-8000-000000002938', 'マンガ以外は何もよみません。', 'I read nothing but manga.'),
  ('00000000-0000-4000-8000-000000002938', '式の間中新郎が花嫁の胸元を上から眺めていたこと以外は、とても素敵な結婚式でした。', 'Other than the groom looking down the front of the bride’s dress during the ceremony, it was a nice wedding.'),
  ('00000000-0000-4000-8000-000000002939', 'このえいがは、十八才以上しか見れません。', 'Only people 18 or older can watch this movie.')
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES
  ('00000000-0000-4000-8000-000000002939', '手つづきは以上です。', 'That''s all for the paperwork.'),
  ('00000000-0000-4000-8000-000000002939', '１００歳以上の人は、必ずブラジャーを着用し無くてはならない。', 'People who are 100 years old or older must wear bras.'),
  ('00000000-0000-4000-8000-000000002940', '以前、パーティーで一どお会いしましたよね。', 'I met you once before at a party, right?'),
  ('00000000-0000-4000-8000-000000002940', '以前はよく船よいしていたんですが、今はさっぱりなくなりました。', 'I used to get seasick all the time, but not anymore.'),
  ('00000000-0000-4000-8000-000000002940', '私の親友は、以前は天文学者に知られていなかった惑星の出身です。', 'My best friend is from a planet that was previously unknown to astronomers.'),
  ('00000000-0000-4000-8000-000000002941', 'もうおれには失うものが何もないんだ。', 'Saya sudah tidak akan rugi apa-apa.'),
  ('00000000-0000-4000-8000-000000002941', 'トーフグがギャンブルで全ざいさんを失ったというじょうほうは、しんぴょうせいに欠けている。', 'Informasi bahwa Tofugu mempertaruhkan seluruh asetnya tidak dapat diandalkan.'),
  ('00000000-0000-4000-8000-000000002941', '人生最悪の日は、私がAKB48のフィギュアを失った日です。', 'Hari terburuk dalam hidupku adalah ketika aku kehilangan boneka Barbie AKB48 milikku.'),
  ('00000000-0000-4000-8000-000000002942', '失礼ですが、日本ごははなせますか。', 'Permisi, tapi bisakah Anda berbicara bahasa Jepang?'),
  ('00000000-0000-4000-8000-000000002942', 'じっさいの会話で「あなた」という言ばを使うと、失礼にきこえることが多いです。', 'Jika Anda menggunakan "anata" dalam percakapan sebenarnya, sering kali terdengar tidak sopan.'),
  ('00000000-0000-4000-8000-000000002942', 'もし私があなたに太いと言えば、失礼だと思いますか？', 'Apakah menurutmu aku tidak sopan jika kubilang kamu gemuk?'),
  ('00000000-0000-4000-8000-000000002943', 'かれは必ずもどってくるので、大じょうぶです。', 'Dia pasti akan kembali, jadi aku baik-baik saja.'),
  ('00000000-0000-4000-8000-000000002943', '必ずねる前にコンタクトを外した方がいいよ。でないとし力がさらにおちるよ。', 'Anda harus selalu melepas kontak Anda sebelum tidur. Jika tidak, penglihatan Anda akan bertambah buruk.'),
  ('00000000-0000-4000-8000-000000002943', '何があっても必ずさい後までワニカニをやりとげます。', 'Saya pasti akan menyelesaikan WaniKani apapun yang terjadi.'),
  ('00000000-0000-4000-8000-000000002944', '必死にがんばっても、どうにもならないこともある。', 'Sekalipun aku berusaha mati-matian, itu mungkin tetap sia-sia.'),
  ('00000000-0000-4000-8000-000000002944', 'わたしのそ父は、必死のかくごでせんじょうに向かったそうです。', 'Saya mendengar bahwa kakek saya pergi ke medan perang dan bersiap untuk mati.'),
  ('00000000-0000-4000-8000-000000002944', '「隊長、私はどうしても火星に戻る必要があるんです。アイフォンを忘れてしまったのです。」彼は必死に頼んだ。', '"Kapten, aku benar-benar harus kembali ke Mars. iPhone-ku tertinggal di sana," ucapnya putus asa.'),
  ('00000000-0000-4000-8000-000000002945', '未だ二百才まで生きた人げんはいない。', 'Masih belum pernah ada orang yang hidup sampai usia dua ratus tahun.'),
  ('00000000-0000-4000-8000-000000002945', '未だに、時さボケがあるんですよね。', 'Saya masih jet-lag.'),
  ('00000000-0000-4000-8000-000000002945', '仕事が決まったのかどうかは未だに分からないんだ。', 'Saya tidak yakin apakah saya sudah mendapatkan pekerjaan itu.'),
  ('00000000-0000-4000-8000-000000002946', 'タイムスリップできるなら、未来に行きたいな。', 'Jika saya bisa melakukan perjalanan waktu, saya ingin pergi ke masa depan.'),
  ('00000000-0000-4000-8000-000000002946', '週末は、未来とか去を行ったり来たりしていました。', 'Pada akhir pekan, saya melakukan perjalanan bolak-balik melintasi waktu.'),
  ('00000000-0000-4000-8000-000000002946', 'コウイチにはうちゅうひ行しとしての大きな未来があるんだから、たのむからじゃましないでやってくれよ。', 'Koichi memiliki masa depan cerah sebagai astronot, jadi tolong jangan ganggu dia.'),
  ('00000000-0000-4000-8000-000000002947', 'こんなあそびがはやるとは、世も末だな。', 'Jika permainan seperti ini populer, maka itu adalah akhir dunia.'),
  ('00000000-0000-4000-8000-000000002947', 'おたくのむす子さんは末が本当にたのしみですね。', 'Anda pasti menantikan untuk melihat seperti apa putra Anda nantinya di masa depan.'),
  ('00000000-0000-4000-8000-000000002947', '激しい口論の末、末息子は私の金をどこかに埋めるために出て行ってしまいました。', 'Setelah berdiskusi dengan sengit, putra bungsu saya pergi untuk mengubur emas saya di suatu tempat.'),
  ('00000000-0000-4000-8000-000000002948', 'すみませんが、年末は、ちょっとバタバタしてじかんがとれなさそうです。', 'Maaf, tapi saya akan sangat sibuk sekitar akhir tahun ini dan mungkin saya tidak punya waktu untuk itu.'),
  ('00000000-0000-4000-8000-000000002948', 'マイケルは、年末にトーフグのだい二えいぎょうぶにいどうになりました。', 'Michael dipindahkan ke Divisi Penjualan II Tofugu pada akhir tahun.'),
  ('00000000-0000-4000-8000-000000002948', '年末までには、氷中毒から立ち直れるといいんだけど。', 'Saya berharap bisa mengatasi kecanduan saya terhadap es batu sebelum akhir tahun.'),
  ('00000000-0000-4000-8000-000000002949', '月末までに五キロやせます。', 'Saya akan kehilangan lima kilogram pada akhir bulan ini.'),
  ('00000000-0000-4000-8000-000000002949', 'ここ、ブラックきぎょうすぎるから、月末ににげ出すわ。', 'Perusahaan ini terlalu banyak mengeksploitasi karyawannya, jadi saya akan memberikan dana talangan pada akhir bulan!'),
  ('00000000-0000-4000-8000-000000002949', '私の上司は、コアラで給料を払います。毎月末、わたしには二匹のコアラが支払われます。', 'Bos saya membayar saya dengan beruang koala. Saya mendapat dua di akhir setiap bulan.'),
  ('00000000-0000-4000-8000-000000002950', '高校まで、車で行けば十分ですよ。', 'It only takes 10 minutes to get to the high school if you drive.'),
  ('00000000-0000-4000-8000-000000002950', '高校ではいつも、おひるにどんなものを食べていますか？', 'What kind of food do you guys usually have for lunch in high school?'),
  ('00000000-0000-4000-8000-000000002950', '高校に行って初めて話をし始めたんです。そして、今は、話を止めることができません。', 'I didn’t start talking until I went to high school. Now I can’t shut up.'),
  ('00000000-0000-4000-8000-000000002951', 'わたしは歩いて学校に行っています。', 'I go to school on foot.'),
  ('00000000-0000-4000-8000-000000002951', '学校にてい出するので、ちえんしょう明しょを下さい。', 'I have to submit an absentee notice to my school, so can I have one, please?'),
  ('00000000-0000-4000-8000-000000002951', '今日はどうして学校で授業中にホットドッグをバーベキューするの？', 'Why are we barbecuing hot dogs at school during class today?'),
  ('00000000-0000-4000-8000-000000002952', '今年の夏は、さく年よりもあついです。', 'This summer is hotter than last year.'),
  ('00000000-0000-4000-8000-000000002952', '近いうちに夏ワンピをかいに行きたいんだよね。', 'I want to go buy some summer dresses sometime soon.'),
  ('00000000-0000-4000-8000-000000002952', '夏にして楽しいことは三つだけだ。映画、ビデオゲーム、それから木彫の鴨を作ること。', 'Summer is only good for three things. Movies, video games, and duck carving.'),
  ('00000000-0000-4000-8000-000000002953', '夏休みは、一ヶ月あります。', 'Summer vacation is one month long.'),
  ('00000000-0000-4000-8000-000000002953', '夏休みにおきなわでダイビングをした時、しんじられないくらいたく山のしゅるいの魚を見ることができました！', 'I can''t believe all the different kinds of fish we saw when diving in Okinawa during summer break.'),
  ('00000000-0000-4000-8000-000000002953', '小さいころ、夏休みに両親がディズニーランドに連れて行ってくれました。でも、帰り際、両親は何と私のことを忘れて帰ってしまったのです。あの時だけは、迷子になったことを嬉しく思いましたね。', 'When I was a kid, my parents took me to Disney Land for summer vacation, but they forgot me there when they left. It was the only time I was happy to be lost.'),
  ('00000000-0000-4000-8000-000000002954', 'みなさん、家にあそびに来てください。', 'Everyone, please stop by my house.'),
  ('00000000-0000-4000-8000-000000002954', 'いいかげん、家をかた付けた方がいいよ。', 'You really need to clean your house.'),
  ('00000000-0000-4000-8000-000000002954', '家とは、みんなの心と食べ物がある場所です。', 'Home is where the heart is. And the food.'),
  ('00000000-0000-4000-8000-000000002955', 'あこがれの作家さんから、サインをもらいました。', 'I got an autograph from an aspiring author.'),
  ('00000000-0000-4000-8000-000000002955', 'この作家、ずいぶん思い切ったね。', 'This novelist pushed things pretty far, eh?'),
  ('00000000-0000-4000-8000-000000002955', 'あのベストセラー作家の趣味はサッカーだ。', 'That best-selling author’s hobby is playing soccer.'),
  ('00000000-0000-4000-8000-000000002956', 'わたしは、あさに弱いです。', 'Saya bukan orang yang suka bangun pagi.'),
  ('00000000-0000-4000-8000-000000002956', 'ユイは体は弱いけど、人のいたみがわかる人げんです。', 'Yui secara fisik lemah, tapi dia adalah orang yang memahami penderitaan orang lain.'),
  ('00000000-0000-4000-8000-000000002956', 'インフルエンザにかかると、スーパーマンでさえもとても弱くなります。', 'Bahkan superman menjadi sangat lemah saat terkena flu.'),
  ('00000000-0000-4000-8000-000000002957', 'ついにアイツの弱点を見つけたぜ！', 'Saya akhirnya menemukan titik lemahnya!'),
  ('00000000-0000-4000-8000-000000002957', 'あの体そうせん手の弱点は、せいかくがじゅうなんせいに欠けているところだ。', 'Kelemahan pesenam itu adalah kepribadiannya yang kurang fleksibel.'),
  ('00000000-0000-4000-8000-000000002957', '私の従業員としての弱点は、恐らく弱点が一つも無いことです。', 'Kelemahan saya sebagai karyawan mungkin adalah saya tidak mempunyai kelemahan.'),
  ('00000000-0000-4000-8000-000000002958', 'れいぼうをつける時は、白いボタンをおしてください。', 'When you want to turn on the air conditioning, please press the white button.'),
  ('00000000-0000-4000-8000-000000002958', '時がかい決してくれるのをまつしかないよ。', 'We can do nothing but wait for time to solve this.'),
  ('00000000-0000-4000-8000-000000002958', '幸せな時、いつも時が止まればいいのに、と思う。', 'Whenever I’m happy, I always think it would be nice if I could stop time.'),
  ('00000000-0000-4000-8000-000000002959', '毎日一時にランチを食べます。', 'I eat lunch at one o''clock every day.'),
  ('00000000-0000-4000-8000-000000002959', '一時までにおもちゃをかたづけなさい。', 'Put your toys away by one o''clock.'),
  ('00000000-0000-4000-8000-000000002959', 'もし私のところで働くなら、あなたのシフトは午後一時から遅くとも三時までになりますが、よろしいですか？', 'If you worked for me, your shift would start at one o’clock in the afternoon and end at three o’clock at latest. Sound good?'),
  ('00000000-0000-4000-8000-000000002960', 'そのえいがのかいえん時かんは二時半です。', 'The film begins at two-thirty.'),
  ('00000000-0000-4000-8000-000000002960', '二時半に大じなやくそくがあるのにねぼうしちゃって、ちょっと今かなりテンパってます。', 'I have an important appointment at 2:30, but I overslept and now I''m freaking out.'),
  ('00000000-0000-4000-8000-000000002960', '「私は明日午後二時半に、私のお母さんのお父さんの娘の姪っ子に会います。」「なんで、単にお姉ちゃんとランチに行くって言わないの？ありえないんだけど！」', '"I’m meeting my mom’s father’s daughter’s niece tomorrow at two-thirty in the afternoon." "Why didn’t you just say you’re meeting your older sister for lunch tomorrow? Jeez!"'),
  ('00000000-0000-4000-8000-000000002961', '何時のひ行きにのるんですか？', 'What time will your plane leave?'),
  ('00000000-0000-4000-8000-000000002961', '目まいをかんじはじめたのは何時ですか？', 'What time did you start to feel dizzy?'),
  ('00000000-0000-4000-8000-000000002961', '今夜何時にボーリングに行くの？', 'What time are you going bowling tonight?'),
  ('00000000-0000-4000-8000-000000002962', '先生が教室に入ってきたと同時に、しぎょうのチャイムがなりました。', 'At the same time teacher came in the classroom, the bell rang.'),
  ('00000000-0000-4000-8000-000000002962', 'でん子レンジとトースターを同時につかったから、ブレーカーがおちちゃったんだ。', 'I was using the microwave and the toaster at the same time, and the circuit breaker tripped.'),
  ('00000000-0000-4000-8000-000000002962', '「今日はよくできましたね。それではまた来週同じ時間に。」と、コスプレのプロとアニメオタクが同時に言った。', '"Good lesson today. I’ll see you this time next week," the professional cosplayer and the anime nerd said at the same time.'),
  ('00000000-0000-4000-8000-000000002963', '紙とえんぴつとけしゴムをつくえに出してください。', 'Please put some paper, a pencil, and an eraser on your desk.'),
  ('00000000-0000-4000-8000-000000002963', 'あたらしい紙をかうのがたのしみでしかたがない。', 'I''m so looking forward to buying a new piece of paper.'),
  ('00000000-0000-4000-8000-000000002963', '昨日、紙の切れ端に詩を書いている狼を見かけた。', 'Yesterday, I saw a wolf writing a poem on a piece of paper.'),
  ('00000000-0000-4000-8000-000000002964', '外国に手紙を出しました。', 'I sent a letter to a foreign country.'),
  ('00000000-0000-4000-8000-000000002964', 'その金正日からの手紙、ネットオークションに出しちゃえば？きっとだれかしらかうと思うよ。', 'Why don''t you put up the letter from Kim Jong Il for online auction? I think somebody would buy it.'),
  ('00000000-0000-4000-8000-000000002964', '私はコカコーラ宛に、心のこもった手紙を書いて、どうして彼らの製品にたくさん砂糖が入っているのかについて尋ねたいと思います。', 'I’m going to write a very heated letter to Coca-Cola and ask why there is so much sugar in their products.'),
  ('00000000-0000-4000-8000-000000002965', 'あなたの日記も、この本と一しょにここにおいておきます。 ', 'Saya akan meninggalkan buku harian Anda dengan buku ini di sini.'),
  ('00000000-0000-4000-8000-000000002965', '北米には、こうかん日記みたいな文化はないんだよ。', 'Kami tidak memiliki budaya pertukaran buku harian di Amerika Utara.'),
  ('00000000-0000-4000-8000-000000002965', '昨日の夜、フグの日記を読んだんだけどさ、実はとても悲しい日記だったんだよね。', 'Saya membaca jurnal Fugu tadi malam dan sejujurnya, itu sangat menyedihkan.'),
  ('00000000-0000-4000-8000-000000002966', 'このみちは、ほそくて通りにくいです。', 'This road is narrow and difficult to pass through.'),
  ('00000000-0000-4000-8000-000000002966', '日本ごがペラペラになるなんてありえないと思うかもしれませんが、それはあたらしい言ごを学ぶだれもが通る道です。', 'It seems impossible to become fluent in Japanese, but everybody who learns a new language travels along the same road.'),
  ('00000000-0000-4000-8000-000000002966', 'お茶会のためのメープルシロップを買うために、カナダを通ってイギリスに行った。', 'I stopped by Canada on the way to England to get some maple syrup for the tea party.'),
  ('00000000-0000-4000-8000-000000002967', 'ここでは、交通じこがよくおきるんです。', 'Kecelakaan lalu lintas banyak terjadi di sini.'),
  ('00000000-0000-4000-8000-000000002967', '交通安全のためにシートベルトをしてください。', 'Harap kenakan sabuk pengaman Anda untuk keselamatan lalu lintas.'),
  ('00000000-0000-4000-8000-000000002967', 'こうきょう交通きかんに乗れる時はマスクをした方がいいよ。', 'Saat Anda menggunakan sistem angkutan umum, Anda harus mengenakan masker.'),
  ('00000000-0000-4000-8000-000000002968', 'この店は、高いですがおいしいです。', 'This restaurant is expensive, but delicious.'),
  ('00000000-0000-4000-8000-000000002968', 'わたしには高すぎてとどかないので、とてもせが高いジェームズ・ステュアートを天国からよんできました。', 'That is too high for me to reach, so I''ve brought James Stewart, who is very tall, down from Heaven.'),
  ('00000000-0000-4000-8000-000000002968', 'どうして、「ビッグアンドトール」のスーツはあんなに値段が高いんだ？', 'Why are suits from the "Big and Tall" store so expensive?'),
  ('00000000-0000-4000-8000-000000002969', 'この中で一ばん強いのはだれですか。', 'Who is the strongest among these people?'),
  ('00000000-0000-4000-8000-000000002969', 'クチバシと羽の色からさっするに、こいつはおそらくめちゃくちゃ強いカラスだね。', 'By the shape of the beak and color of the feathers, this would probably be a very strong crow.'),
  ('00000000-0000-4000-8000-000000002969', '海流はとても強く、その猫を川まで運んだ。', 'The ocean''s currents were too strong for the cat and it was carried away.'),
  ('00000000-0000-4000-8000-000000002970', 'このボンドは、かなり強力なので気をつけてください。', 'This glue is pretty strong, so please be careful.'),
  ('00000000-0000-4000-8000-000000002970', '強力なミニウォーターポンプの作り方をおしえてもらいました。', 'I was taught how to make a powerful, mini water pump.'),
  ('00000000-0000-4000-8000-000000002970', '彼女を見つめると、まるで十人力ぐらい強力になったように感じる。', 'When I look at her, I feel as though I have the strength of ten men.'),
  ('00000000-0000-4000-8000-000000002971', 'こたえ方を教えてください。', 'Please teach me how to answer.'),
  ('00000000-0000-4000-8000-000000002971', 'ワニカニで日本ごを教える人の中には、「鬼コーチ」はいないよね？', 'There aren''t any "demon coaches" among people who teach Japanese on WaniKani, are there?'),
  ('00000000-0000-4000-8000-000000002971', '皆さん、お早うございます。今日は、皆さんに、茄子を食べることの危険性について教えたいと思います。', 'Good morning, class. Today I’m going to teach you about the dangers of eating eggplant.'),
  ('00000000-0000-4000-8000-000000002972', '学生は、教室ではじめに何をしますか。', 'What will the students do in the classroom first?'),
  ('00000000-0000-4000-8000-000000002972', 'かれは教室でタバコをくわえたところを、先生に目げきされました。', 'The teacher witnessed him putting a cigarette in his mouth in the classroom.'),
  ('00000000-0000-4000-8000-000000002972', '先生がいなくなったのはたったの五分間だけだったが、大学生たちは完璧に教室を滅茶苦茶にしてしまった。', 'The teacher had only been gone for five minutes, but the university students had completely trashed the classroom.'),
  ('00000000-0000-4000-8000-000000002973', 'えいぎょうをするなら、心理学を学んだ方がいいよ。', 'You should study psychology if you work in sales.'),
  ('00000000-0000-4000-8000-000000002973', '心理学のせつ明によると「あい手にひどいことが言えるということは、その人にいぞんしてるということ」らしいです。', 'According to the psychology explanation, it looks like when you are able to say something mean to a person, you''re actually being dependent on them.'),
  ('00000000-0000-4000-8000-000000002973', '私は大学で犯罪心理学を専攻していました。', 'My major was criminal psychology in college.'),
  ('00000000-0000-4000-8000-000000002974', '一人で地理のべん強をするのもすきですが、友だちとべん強する方がたのしいです。', 'I like studying geography by myself too, but it’s more fun to study with my friend.'),
  ('00000000-0000-4000-8000-000000002974', 'アメリカ人の友人は地理が全くのにが手で、さい近まで日本が中国の首とだとおもっていたらしい。', 'My American friend is not good at geography at all, so I heard that she used to think Japan was the capital of China until very recently.'),
  ('00000000-0000-4000-8000-000000002974', '俺たちが道に迷ったってどういうことだよ？お前、地理の先公じゃねえのかよ？', 'What do you mean we’re lost? Aren’t you a geography teacher?'),
  ('00000000-0000-4000-8000-000000002975', 'これから、みなさんを二組に分けます。', 'Setelah ini, kami akan dibagi menjadi dua tim.'),
  ('00000000-0000-4000-8000-000000002975', 'オレたちの組はこの辺じゃ有名なんだぜ。', 'Grup kami terkenal di sekitar sini.'),
  ('00000000-0000-4000-8000-000000002975', '三年二組のコウイチくん、またこく白されたらしいよ。', 'Kudengar Koichi di kelas 3 kelas 2 diajak kencan lagi.'),
  ('00000000-0000-4000-8000-000000002976', '次の船は、何時に出ぱつしますか。', 'Jam berapa kapal selanjutnya berangkat?'),
  ('00000000-0000-4000-8000-000000002976', '船にのると必ず船よいしちゃうんだよね。', 'Saya selalu merasa mual ketika berada di atas kapal.'),
  ('00000000-0000-4000-8000-000000002976', '俺様が船のすべてを取り仕切る船長だ。', 'Saya kaptennya dan saya menjalankan seluruh kapal ini sendirian.'),
  ('00000000-0000-4000-8000-000000002977', 'あのピエロが、風船で犬を作ってくれたんだ。', 'Badut itu membuatkan seekor anjing dari balon untukku.'),
  ('00000000-0000-4000-8000-000000002977', 'ひ行きによったば合は、この風船をエチケットぶくろの代わりにごしようください。', 'Silakan gunakan balon ini sebagai tas mabuk perjalanan ketika Anda merasa mabuk udara.'),
  ('00000000-0000-4000-8000-000000002977', '風船を使って実際に空飛ぶ家を作った人たちがいます。', 'Beberapa orang justru membuat rumah terapung dengan menggunakan balon.'),
  ('00000000-0000-4000-8000-000000002978', '先週は学校はお休みでした。', 'School was out last week.'),
  ('00000000-0000-4000-8000-000000002978', '大きくなったねー。先週はまだあんなに小さかったのに。', 'You sure have grown a lot! You were still tiny last week though.'),
  ('00000000-0000-4000-8000-000000002978', '先週出席した経済相互援助会議で、喋る犬にインタビューされたんだが、あいつは本当に嫌なやつだった。', 'I was interviewed by a talking dog about the Comecon convention I attended last week. He was so insulting.'),
  ('00000000-0000-4000-8000-000000002979', '今週は仕ごとがたくさんあります。', 'There is a lot of work to do this week.'),
  ('00000000-0000-4000-8000-000000002979', '今週の火よう日の午前十一じに、しぶ谷のハチ公前でまち合わせをしましょう。', 'Let''s meet up in front of the Hachiko statue at 11 a.m. this Tuesday.'),
  ('00000000-0000-4000-8000-000000002979', '新しいゲームを４つ買ったので、今週はかなり忙しくなる。', 'This week is going to be really busy because I just bought four new video games.'),
  ('00000000-0000-4000-8000-000000002980', '週末は、おきなわにりょ行に行っていました。', 'Saya berada di Okinawa selama akhir pekan.'),
  ('00000000-0000-4000-8000-000000002980', 'せん週末、雪が十センチつもりました。', 'Kami mendapat salju setinggi 10 sentimeter akhir pekan lalu.'),
  ('00000000-0000-4000-8000-000000002980', '宝くじに当たったんだけど、週末ローマにピザでも食べに行かない？', 'Kami baru saja memenangkan lotre, jadi apakah Anda ingin pergi ke Roma akhir pekan ini untuk makan pizza?'),
  ('00000000-0000-4000-8000-000000002981', '日本でも、雪がふりますか？', 'Apakah di Jepang juga turun salju?'),
  ('00000000-0000-4000-8000-000000002981', 'そっちも雪、つもった？', 'Apakah kamu juga mendapat salju di sana?'),
  ('00000000-0000-4000-8000-000000002981', '私が初めて雪を見たのは、四十六歳の時でした。', 'Pertama kali saya melihat salju adalah ketika saya berumur 46 tahun.'),
  ('00000000-0000-4000-8000-000000002982', '魚はすきですが、生魚はにが手です。', 'I like fish, but I don’t like it raw.'),
  ('00000000-0000-4000-8000-000000002982', 'バランスのいいちょう食をとるために、いつもグラノーラと魚を食べます。', 'I always eat granola and fish for a well-balanced breakfast.'),
  ('00000000-0000-4000-8000-000000002982', 'もう絶対にメキシコの軽トラの積み荷から魚を買うもんか。', 'I’ll never buy fish from the back of a pickup truck in Mexico again.'),
  ('00000000-0000-4000-8000-000000002983', 'これは、五年前の夏まつりの金魚すくいですくった金魚です。', 'I scooped this goldfish at a goldfish scooping booth during a summer festival five years ago.'),
  ('00000000-0000-4000-8000-000000002983', '金魚もかぜをひくんですか？', 'Can goldfish get colds, too?'),
  ('00000000-0000-4000-8000-000000002983', '金魚は、三秒間しか記憶がないので、自分たちがお城に住んでいることに気がつく度に驚いています。', 'Goldfish only have three second memories so they’re always surprised when they realize that they live in a castle.'),
  ('00000000-0000-4000-8000-000000002984', 'さけは海魚ですか？それとも川魚ですか？', 'Is salmon a saltwater fish? Or is it a freshwater fish?'),
  ('00000000-0000-4000-8000-000000002984', '海中には、色とりどりの海魚がおよいでいました。', 'In the sea, there were a lot of colorful ocean fish swimming around.'),
  ('00000000-0000-4000-8000-000000002984', '水族館には沢山の種類の海魚がいますが、スタッフは僕達に一匹も食べてはいけませんと言いました。', 'There is a wide variety of saltwater fish at the aquarium, but the staff said we’re not allowed to eat any of them.'),
  ('00000000-0000-4000-8000-000000002985', 'この公えんには、きれいな鳥がたくさんいます。', 'There are a lot of beautiful birds in this park.'),
  ('00000000-0000-4000-8000-000000002985', 'けさカーテンをあけたら、何もかもが鳥のふんにおおわれていました。', 'When I opened my curtain this morning, everything was covered with bird poop.'),
  ('00000000-0000-4000-8000-000000002985', '自分が鳥だったらいいのになと思うよ。だって、そうすればもう鳥みたいに歩いているとからかわれないだろうからね。', 'I wish I was a bird because then I wouldn’t get made fun of for walking like one.'),
  ('00000000-0000-4000-8000-000000002986', '自どりをするためだけに白鳥をみずうみから引きずり出すなんてひどすぎるよ。', 'Pulling a swan out of the lake just to take a selfie with it is too cruel.'),
  ('00000000-0000-4000-8000-000000002986', '白ワインは魚りょうりに合うっていうけど、白鳥りょうりに合うワインは何か知っていますか？', 'They say that white wine goes well with fish, but do you know what kind of wine would go well with swan?'),
  ('00000000-0000-4000-8000-000000002986', '白鳥はとても美しいが、汚らしい言葉遣いをする。', 'Swans are so pretty, but they use foul language.'),
  ('00000000-0000-4000-8000-000000002987', '黄色かみどり色のペンはありますか？', 'Apakah ada pulpen kuning atau hijau?'),
  ('00000000-0000-4000-8000-000000002987', 'アメリカのカラスは、美しい黄色の羽をもっていることで有名です。', 'Burung gagak Amerika terkenal dengan keindahan sayap kuningnya.'),
  ('00000000-0000-4000-8000-000000002987', 'もし尿のいろが透明から黄色に変わってしまったら、もっと水を飲んだ方が良いという合図です。', 'Jika urin Anda berubah dari bening menjadi kuning, Anda harus minum lebih banyak air.'),
  ('00000000-0000-4000-8000-000000002988', 'その上の、黒いぼう子をとってください。', 'Can you get me the black hat up there?'),
  ('00000000-0000-4000-8000-000000002988', 'あの黒ひげの男ははら黒いことで有名です。', 'That man with the black goatee is notorious for being black-hearted.'),
  ('00000000-0000-4000-8000-000000002988', '私の一番好きなテレビ番組は、「黒い画面」です。この番組は、停電になった時だけ放送されます。', 'My favorite channel on TV is called "Black Screen." It only airs when the power goes off.'),
  ('00000000-0000-4000-8000-000000002989', 'なぜ未だに黒人をさべつする人がいるのか、りかいできません。', 'I can’t understand how there are still people who discriminate against black people.'),
  ('00000000-0000-4000-8000-000000002989', 'おれは黒人であいつは白人だけど、それがどうしたの？', 'I''m black, he''s white. What''s wrong with that?'),
  ('00000000-0000-4000-8000-000000002989', 'ピーナッツバターは、ジョージ・ワシントン・カーヴァーという名の黒人によって発明された。', 'Peanut butter was invented by a black person named George Washington Carver.'),
  ('00000000-0000-4000-8000-000000002990', 'あの馬に、ニンジンやリンゴをあげてもいいですか？', 'Bolehkah memberi wortel dan apel pada kuda itu?'),
  ('00000000-0000-4000-8000-000000002990', 'わたしの馬は、また一つこんなんをのりこえました。', 'Kudaku telah mengatasi kesulitan lainnya.'),
  ('00000000-0000-4000-8000-000000002990', 'お年寄りたちが次から次へと馬から落ちたの、めちゃくちゃ面白いと思うんだけど〜！', 'Saya merasa sangat lucu ketika orang-orang tua jatuh dari kuda satu demi satu.'),
  ('00000000-0000-4000-8000-000000002991', '自どう車の馬力を上げるには、どうすればいいですか。', 'Apa cara terbaik untuk meningkatkan tenaga kuda mobil?'),
  ('00000000-0000-4000-8000-000000002991', 'アサヒのじいちゃんって、本当に馬力があるよね。', 'Asahi, kakekmu adalah orang yang sangat energik, bukan?'),
  ('00000000-0000-4000-8000-000000002991', '約四年間いじくり回したおかげで、今俺の芝刈り機は450馬力もあるんだぜ。', 'Saya mengutak-atik mesin pemotong rumput saya selama sekitar empat tahun dan sekarang memiliki 450 tenaga kuda.'),
  ('00000000-0000-4000-8000-000000002992', 'やっぱり、おれのしゅう入だけで、一家を支えるのはきびしいよ。', 'Lagi pula, sulit untuk menghidupi keluarga hanya dengan penghasilan saya.'),
  ('00000000-0000-4000-8000-000000002992', 'アメリカのけいざいは、トーフグによって支えられている。', 'Perekonomian Amerika Serikat didukung oleh Tofugu.'),
  ('00000000-0000-4000-8000-000000002992', '壁に寄りかかって体を支えるのがとても楽しかった。', 'Sangat menyenangkan bagi saya untuk menopang diri saya sendiri ke dinding.'),
  ('00000000-0000-4000-8000-000000002993', 'わたしのおっとは、大さか支店の支店長をつとめています。', 'Suami saya adalah manajer cabang di cabang Osaka.'),
  ('00000000-0000-4000-8000-000000002993', 'この支店には、一人で行どうすることがすきな人もはたらいている。', 'Di toko cabang ini, ada juga pekerja yang suka melakukan sesuatu sendirian.'),
  ('00000000-0000-4000-8000-000000002993', '支店長の髭は少し長すぎる。', 'Kumis manajer cabang kami agak terlalu panjang.'),
  ('00000000-0000-4000-8000-000000002994', 'わたしは、父と母と一しょに住んでいます。', 'I live with my father and mother.'),
  ('00000000-0000-4000-8000-000000002994', '青木ヶ原のじゅ海は、住むにはおそろしすぎる場所です。', 'Aokigahara''s Jukai is a terrifying place to live.'),
  ('00000000-0000-4000-8000-000000002994', 'ホビットの穴に住んでみたいのですが、どうやって掘ればいいのか分かりません。', 'I want to live in a hobbit hole, but I don’t know how to dig.'),
  ('00000000-0000-4000-8000-000000002995', 'こんなしん夜に大声でけんかをしたら、近りんの住人にめいわくだろう。', 'If you argue loudly so late at night, you’ll bother your neighbors.'),
  ('00000000-0000-4000-8000-000000002995', '話し合いの末、森の住人とみずうみの住人は、一しょに百本のけんを買うことにした。', 'After talking it over, forest-dwellers and lake-dwellers agreed to buy 100 swords together.'),
  ('00000000-0000-4000-8000-000000002995', '私は地球の住人です。パーティーにようこそ。', 'I am a resident of planet Earth. Welcome to the party.'),
  ('00000000-0000-4000-8000-000000002996', '市はひなん所をかいせつして、住民にひなんをよびかけています。', 'Pihak kota mendirikan tempat perlindungan dan mengimbau warganya untuk mengungsi.'),
  ('00000000-0000-4000-8000-000000002996', '住民たちは、みんなすぐに打ちとけました。', 'Warga langsung rukun satu sama lain.'),
  ('00000000-0000-4000-8000-000000002996', 'あのアパートの住民には無料のエアコンが与えられるが、何故か冬の間だけなのである。', 'Penghuni apartemen itu diberikan AC gratis, namun hanya pada musim dingin karena alasan tertentu.'),
  ('00000000-0000-4000-8000-000000002997', 'ワニカニとトーフグがおぼれていたらどちらを助ける？', 'Jika WaniKani dan Tofugu tenggelam, manakah yang akan kamu selamatkan?'),
  ('00000000-0000-4000-8000-000000002997', 'このかわいそうなすて犬ちゃんを助けてあげることができる人はいませんか？', 'Adakah orang yang bisa menyelamatkan anak anjing malang yang terlantar ini?'),
  ('00000000-0000-4000-8000-000000002997', 'チリチーズブリトーを食べるのを助けて欲しい人はいますか？私はそれがとても得意ですよ！', 'Adakah yang butuh bantuan untuk memakan burrito cabai dan keju? Saya sangat ahli dalam hal itu!'),
  ('00000000-0000-4000-8000-000000002998', 'そのせつは、ご助力をたまわりかんしゃ申し上げます。', 'Terima kasih atas bantuan Anda saat ini.'),
  ('00000000-0000-4000-8000-000000002998', 'YouTubeのどうがさい生カウントをのばすため、コウイチは助力をもとめてタランティーノに電話をかけた。', 'Koichi menelepon Quentin Tarantino untuk mencari bantuan untuk meningkatkan jumlah penayangan YouTube-nya.'),
  ('00000000-0000-4000-8000-000000002998', 'スパイダーマンの助力を求める必要はない。', 'Anda tidak perlu meminta bantuan Spider-Man.'),
  ('00000000-0000-4000-8000-000000002999', 'ワトソンはかせは、シャーロック・ホームズの助手ではなく、あくまで友人です。', 'Dr Watson bukan hanya asisten Sherlock Holmes, dia adalah temannya sampai akhir.'),
  ('00000000-0000-4000-8000-000000002999', 'わたしの助手は、年末に肉ばなれになりました。', 'Ajudan saya mengalami cedera otot pada akhir tahun.'),
  ('00000000-0000-4000-8000-000000002999', 'もし私が今首になった助手の助手だとしたら、それってつまり私も首になっちゃったってこと？', 'Jika saya asisten dari asisten yang baru saja dipecat, apakah itu berarti saya juga dipecat?'),
  ('00000000-0000-4000-8000-000000003000', 'あなたの助言、ぜんぜん役に立たなかったんだけど。', 'Tapi saran Anda tidak membantu sama sekali.'),
  ('00000000-0000-4000-8000-000000003000', 'かの女の助言にしたがって、コウイチはついにタバコをやめたんだよ。', 'Sesuai dengan saran pacarnya, Koichi akhirnya berhenti merokok.'),
  ('00000000-0000-4000-8000-000000003000', 'そのチョコレートをくれたら、助言をあげるわ。', 'Aku akan memberimu saran, jika kamu memberiku coklat itu.'),
  ('00000000-0000-4000-8000-000000003001', 'わたしは、医大を目ざしてべん強しています。', 'I’m studying to get into medical school.'),
  ('00000000-0000-4000-8000-000000003001', '医者のたまごをかれ氏にするため、医大生のふりをして、医大にせん入してみました。', 'I pretended to be a med student and snuck into med school to find a future doctor boyfriend.'),
  ('00000000-0000-4000-8000-000000003001', '私は、ポケモンコレクションを売って、医大の学費を払った。', 'I paid my tuition for med school by selling my Pokémon collection.'),
  ('00000000-0000-4000-8000-000000003001', 'わたしは、医大を目ざしてべん強しています。', 'I’m studying to get into medical school.'),
  ('00000000-0000-4000-8000-000000003001', '医者のたまごをかれ氏にするため、医大生のふりをして、医大にせん入してみました。', 'I pretended to be a med student and snuck into med school to find a future doctor boyfriend.'),
  ('00000000-0000-4000-8000-000000003001', '私は、ポケモンコレクションを売って、医大の学費を払った。', 'I paid my tuition for med school by selling my Pokémon collection.'),
  ('00000000-0000-4000-8000-000000003002', 'さい近は、医学の本を月に三さつぐらいよんでいます。', 'Lately, I’ve been reading about three medical science books a month.'),
  ('00000000-0000-4000-8000-000000003002', 'わたしの兄は、医学ぶを目ざしています。', 'My older brother is trying to get into a medical school.'),
  ('00000000-0000-4000-8000-000000003002', '医学はいつも最新の薬を発見し続けている。昨日は、医者が皿洗いをするようになる薬を私にくれたよ。', 'Medical science is always discovering new medications. Just yesterday, my doctor gave me a pill that makes it so I can wash dishes.'),
  ('00000000-0000-4000-8000-000000003003', '今日は医者に行かなくちゃいけない。', 'I have to go see a doctor today.'),
  ('00000000-0000-4000-8000-000000003003', 'ある夜、とあるあやしいレストランに、もくもくとサメを食べる三人の医者がいました。', 'One night, in a shady restaurant, there were three doctors stuffing themselves with shark.'),
  ('00000000-0000-4000-8000-000000003003', '僕は医者になりたいけど、人に触ることが嫌いなんだ。それってやっぱり問題かな？', 'I want to be a doctor, but I hate touching people. Do you think that will be a problem?'),
  ('00000000-0000-4000-8000-000000003004', '天のうのいる日本は君主国ですか、それとも民主国ですか？', 'Jepang punya kaisar, jadi monarki atau demokrasi?'),
  ('00000000-0000-4000-8000-000000003004', 'やっとこの君主国にもどって来たぜ！', 'Ah, saya akhirnya kembali ke monarki ini!'),
  ('00000000-0000-4000-8000-000000003004', 'イギリス君主国は、別のラップ音楽のビデオを作る締め切りをまた大幅に過ぎている。', 'Kerajaan Inggris sudah lama tertunda untuk membuat video musik rap lainnya.')
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES
  ('00000000-0000-4000-8000-000000003005', '君とぼくは、いつもいっしょだよ。', 'Kamu dan aku akan selalu bersama.'),
  ('00000000-0000-4000-8000-000000003005', '君はけっこうせがひくいから、シャワーヘッドをフックから外せるか心ぱいです。', 'Kamu cukup pendek, jadi aku khawatir jika kamu bisa meraih kepala pancuran dan melepaskannya.'),
  ('00000000-0000-4000-8000-000000003005', '君は、エレベーターで一緒に閉じ込められたくない人ナンバーワンだ。', 'Anda adalah orang terburuk yang terjebak di dalam lift.'),
  ('00000000-0000-4000-8000-000000003006', '今年の夏、私は山田君と、ディズニーランドの中にあるホテルにとまりました。', 'Musim panas ini, saya menginap di sebuah hotel di Disney Land bersama Yamada.'),
  ('00000000-0000-4000-8000-000000003006', 'ビエト君って、せんたくきを一日に七十七回も回すらしいよ！', 'Saya mendengar bahwa Viet menjalankan mesin cuci tujuh puluh tujuh kali sehari.'),
  ('00000000-0000-4000-8000-000000003006', '日本の男の子の名前の後ろには「君」という言葉が付けられるそうだが、ラという名前の男の子があまりいないというのは残念ですね。', '"Kun" digunakan sebagai akhiran untuk nama anak laki-laki di Jepang. Sayang sekali tidak banyak anak yang bernama "Ra".'),
  ('00000000-0000-4000-8000-000000003007', 'たまごの白身の黄身に対するわり合は、２対１です。', 'Perbandingan putih dan kuning telur adalah 2:1.'),
  ('00000000-0000-4000-8000-000000003007', 'お前って、両しんに対する思いやりに欠けてるよね。', 'Kamu kurang mempertimbangkan orang tuamu, bukan?'),
  ('00000000-0000-4000-8000-000000003007', 'あいつらの関係が修復不可能だってことは明らかだね。だって、スタートレックに対する意見が全く違っているんだから。', 'Sekarang jelas bahwa hubungan mereka tidak akan berhasil karena pendapat mereka tentang Star Trek adalah kebalikannya.'),
  ('00000000-0000-4000-8000-000000003008', 'せん後、日本の対外せいさくはどのようにかわっていったのでしょうか。', 'Bagaimana kebijakan luar negeri Jepang berubah pascaperang?'),
  ('00000000-0000-4000-8000-000000003008', '日本の対外せいさくについてのポッドキャストをレコーディングしています。', 'Kami merekam podcast tentang kebijakan luar negeri Jepang.'),
  ('00000000-0000-4000-8000-000000003008', 'アメリカの対外債務が5000億ドルを突破した時に、俺の個人負債が500万ドルを突破したのは、単なる偶然なのか？', 'Apakah hanya suatu kebetulan bahwa utang pribadi saya melonjak melewati $5 juta ketika utang luar negeri Amerika melonjak melewati $500 miliar?'),
  ('00000000-0000-4000-8000-000000003009', 'あととりあらそいで、兄と弟は対立してしまったんです。', 'Kakak laki-laki dan adik laki-laki berselisih mengenai perselisihan suksesi.'),
  ('00000000-0000-4000-8000-000000003009', '対立するんじゃなく、一しょにきょう力してがんばろうよ！', 'Mengapa kita tidak bekerja sama dan bekerja keras bersama-sama, bukan bersaing?'),
  ('00000000-0000-4000-8000-000000003009', 'もう一回俺のことを対立を避けるような人間だと言ってみろ！お前の顔面をぶん殴ってやる。', 'Saya akan meninju wajah Anda sekali lagi jika Anda mengatakan saya orang yang tidak konfrontatif.'),
  ('00000000-0000-4000-8000-000000003010', 'その考えには反対です。', 'Saya menentang gagasan itu.'),
  ('00000000-0000-4000-8000-000000003010', '不自由の男神は、アッパーわんをはさんで、自由の女神の反対がわに立っています。', 'Patung Pembatasan berdiri di seberang Patung Liberty di tengah Teluk Atas.'),
  ('00000000-0000-4000-8000-000000003010', 'チェンジビルに引っ越してからというもの、あいつは昔のあいつとは正反対の人間になっちまったんだ。', 'Dia sangat bertolak belakang dengan keadaannya dulu sejak dia pindah ke Changeville.'),
  ('00000000-0000-4000-8000-000000003011', 'ゆうびん局とびょういんもあります。', 'Ada kantor pos dan rumah sakit juga.'),
  ('00000000-0000-4000-8000-000000003011', 'あのテレビ局、のっとっちゃおうぜ！', 'Ayo ambil alih stasiun TV itu!'),
  ('00000000-0000-4000-8000-000000003011', '彼は、マクドナルドのドライブスルーで待たされすぎたからといって、アメリカ連邦捜査局に電話をかけようとした。', 'Dia mencoba menelepon Biro Investigasi Federal karena dia harus menunggu terlalu lama di drive-thru di McDonald''s.'),
  ('00000000-0000-4000-8000-000000003012', '千ば支局にてんきんすることになりました。', 'Saya dipindahkan ke kantor cabang Chiba.'),
  ('00000000-0000-4000-8000-000000003012', 'FBI東京支局の支局員のたこやきパーティーによんでもらった。', 'Saya diundang ke pesta takoyaki untuk agen kantor lapangan FBI di Tokyo.'),
  ('00000000-0000-4000-8000-000000003012', 'テレビ大阪京都支局の前でくしゃみが出た。', 'Aku bersin di depan Television Osaka, Inc. cabang Kyoto'),
  ('00000000-0000-4000-8000-000000003013', 'コウイチが、クママン役でドラマに出えんすることになりました。', 'Koichi memainkan peran Kumaman dalam drama tersebut.'),
  ('00000000-0000-4000-8000-000000003013', 'コウイチは役作りのために、一年間ホームレスになってみました。', 'Untuk mempersiapkan peran tersebut, Koichi menjadi tunawisma selama setahun.'),
  ('00000000-0000-4000-8000-000000003013', 'マイケル、めちゃくちゃ役になりきってるじゃん。', 'Michael memerankan peran itu dengan sangat baik, bukan?'),
  ('00000000-0000-4000-8000-000000003014', 'せいじ家や役人には下手にさからわない方がいい。', 'Anda tidak boleh sembarangan membangkang terhadap politisi atau pejabat publik.'),
  ('00000000-0000-4000-8000-000000003014', 'コウイチはトーフグの社長であるだけでなく、文ぶ科学しょうの役人でもある。', 'Koichi bukan hanya presiden Tofugu tapi juga pejabat di Kementerian Pendidikan.'),
  ('00000000-0000-4000-8000-000000003014', '私の街の役人の一人が、カメラの前で嘘をついたということで、調べを受けている。', 'Salah satu pejabat publik kota saya sedang diselidiki karena berbohong di depan kamera.'),
  ('00000000-0000-4000-8000-000000003015', '日本ごのべん強の役に立つサイトを見つけました。', 'Saya menemukan situs web yang berguna untuk belajar bahasa Jepang.'),
  ('00000000-0000-4000-8000-000000003015', 'ハンガリーには、にげるははじだが役に立つ、ということわざがあります。', 'Di Hungaria ada pepatah yang artinya, “Melarikan diri itu memalukan, tapi berguna.”'),
  ('00000000-0000-4000-8000-000000003015', 'ゾンビがいっぱいの町を歩くなら、銃よりも剣の方が役に立つだろうか？', 'Akankah pedang lebih berguna daripada senjata untuk berjalan melewati kota yang penuh dengan zombie?'),
  ('00000000-0000-4000-8000-000000003016', 'この大役をしっかりはたせるよう、一生けんめいがんばります！', 'Saya akan berusaha sekuat tenaga untuk berhasil menyelesaikan tugas penting ini.'),
  ('00000000-0000-4000-8000-000000003016', 'ずい分とまた大役を買って出たものだね。', 'Anda mengajukan diri untuk tugas yang begitu besar, bukan?'),
  ('00000000-0000-4000-8000-000000003016', 'ロード・オブ・ザ・リングでフロドは大役を任されたが、靴も履かずに見事にやってのけた。', 'Frodo, sang Lord of the Rings, diberi tugas paling penting dan dia melakukan semuanya tanpa mengenakan sepatu.'),
  ('00000000-0000-4000-8000-000000003017', 'それでは、決をとりたいと思います。', 'Kalau begitu saya pikir itulah keputusan yang ingin saya ambil.'),
  ('00000000-0000-4000-8000-000000003017', 'なかなか決が出ないみたいだね。', 'Tampaknya butuh waktu lama untuk mengambil keputusan, bukan?'),
  ('00000000-0000-4000-8000-000000003017', 'ジョン、ホットドッグアイスなんてものを作り始める決を下したのはお前だろう？だから首になったんだよ。', 'John, Anda membuat keputusan untuk mulai membuat es krim hotdog dan itulah mengapa Anda dipecat.'),
  ('00000000-0000-4000-8000-000000003018', '大学をそつぎょうしたら何をするか、もう決めましたか。', 'Sudahkah Anda memutuskan apa yang akan Anda lakukan setelah lulus dari universitas?'),
  ('00000000-0000-4000-8000-000000003018', 'おなかが空きすぎてて何食べるか決められないから、よかったらユイちゃんが決めちゃって。', 'Aku terlalu lapar untuk memutuskan apa yang kita makan, jadi kamulah yang menentukan kemana kita pergi, Yui.'),
  ('00000000-0000-4000-8000-000000003018', '残りの人生をどう過ごすか、みんなは一体どうやって決めるんだい？選びきれないほど仕事があるじゃないか。', 'Bagaimana orang memutuskan apa yang akan mereka lakukan seumur hidup? Ada begitu banyak pekerjaan yang bisa dipilih.'),
  ('00000000-0000-4000-8000-000000003019', 'あなたのおかげで、せい形手じゅつをする決心がつきました。', 'Berkatmu, aku memutuskan untuk menjalani operasi plastik.'),
  ('00000000-0000-4000-8000-000000003019', 'インスタセレブになるというトーフグの決心はトウフと同じぐらいかたい。', 'Resolusi Tofugu untuk menjadi selebriti Instagram sama kuatnya dengan Tofu.'),
  ('00000000-0000-4000-8000-000000003019', 'ついに、あなたに、どこから私の誕生日プレゼントの酒を買ってきてもらうか決心したよ。それは…日本だ。楽しんできてね！', 'Aku akhirnya memutuskan di mana kamu akan membelikanku minuman untuk ulang tahunku... Di Jepang. Menikmati!'),
  ('00000000-0000-4000-8000-000000003020', 'しょうさいは未決です。', 'Detailnya masih belum diputuskan.'),
  ('00000000-0000-4000-8000-000000003020', '未決しょるいは、コウイチのデスクの上の赤いトレイに入れてください。', 'Silakan letakkan dokumen yang tertunda di baki merah di meja Koichi.'),
  ('00000000-0000-4000-8000-000000003020', '彼女の裁判はもう十三年近くも未決となっています。そんなに待たなくてはいけないなんて、とても不公平です。', 'Kasus pengadilannya telah tertunda selama hampir 13 tahun. Sangat tidak adil harus menunggu selama itu.'),
  ('00000000-0000-4000-8000-000000003021', 'あのさむらいは自決した。', 'Samurai itu bunuh diri.'),
  ('00000000-0000-4000-8000-000000003021', 'コウイチ社長は、トーフグは自決けんを強く心からしじするということを、何どもくりかえした。', 'Presiden Koichi menegaskan kembali dukungan Tofugu yang kuat dan sepenuh hati terhadap hak kita untuk menentukan nasib sendiri.'),
  ('00000000-0000-4000-8000-000000003021', '彼は、獄中で絶望し、自決してしまったんです。', 'Dia mengalami depresi selama dipenjara dan bunuh diri.'),
  ('00000000-0000-4000-8000-000000003022', 'お前は本当にしんそうを究明するつもりがあるのか？', 'Are you really going to investigate the truth?'),
  ('00000000-0000-4000-8000-000000003022', 'コウイチのおかしな言どうのしんのどうきはまだ究明されていない。', 'The true motive behind Koichi''s strange words and deeds have not yet been brought to light.'),
  ('00000000-0000-4000-8000-000000003022', '私が大学で取っている授業の一つで、現在「鳥が先か卵が先か」について究明しているんです。', 'One of the classes I’m taking in college is currently investigating whether the chicken or the egg came first.'),
  ('00000000-0000-4000-8000-000000003023', '研究にねっ中しすぎて、気がついたら12時をすぎていました。', 'I was so absorbed in my research that when I noticed it was already past 12 o''clock.'),
  ('00000000-0000-4000-8000-000000003023', 'わたしは、トーフグの研究者で、バイオ医やくひんのせいぞう研究にたずさわっています。', 'I''m a Tofugu researcher taking part in the study of biopharmaceutical production.'),
  ('00000000-0000-4000-8000-000000003023', '現在、我々の巨人に関する研究に参加を希望する申込者を受付けている。', 'We are currently accepting applicants to participate in our research study of Titans.'),
  ('00000000-0000-4000-8000-000000003024', 'わたしは子どもの時、研究室ではたらくのがゆめでした。', 'When I was a child, my dream was to work at a laboratory.'),
  ('00000000-0000-4000-8000-000000003024', 'くどいようですが、山田さんのかつらについて話すのは、この研究室ではタブーですからね。', 'Excuse me for repeating myself, but talking about Mr.Yamada''s wig is a big no no in this study room, okay?'),
  ('00000000-0000-4000-8000-000000003024', '蛙の解剖を始めるので、皆さんには研究室に移動して頂きたいと思います。', 'I’d like everyone to move into the laboratory now so that we can start dissecting the frogs.'),
  ('00000000-0000-4000-8000-000000003025', 'このあたらしいボールは、とても投げやすいです。', 'Bola baru ini sangat mudah untuk dilempar.'),
  ('00000000-0000-4000-8000-000000003025', 'どうしてあの人たちは、かんそうした大ずを投げているんですか？', 'Mengapa orang-orang itu membuang kacang kedelai kering?'),
  ('00000000-0000-4000-8000-000000003025', 'ピッチャーがボールを投げたんですけど、ちょうどバッターの前を飛んでいた鳩に当たったんですよね。', 'Pelempar melempar bola dan mengenai seekor merpati yang terbang di depan pemukul.'),
  ('00000000-0000-4000-8000-000000003026', 'かれは、心身ともに、つかれきっていたんだと思います。', 'I think his body and mind were both worn out.'),
  ('00000000-0000-4000-8000-000000003026', '取りえは、心身ともにけん全であることだけです。', 'My only strength is being of sound mind and body.'),
  ('00000000-0000-4000-8000-000000003026', 'ヨガは、心身共にとても健康にしてくれる。', 'Yoga is excellent for the health of your body and mind.'),
  ('00000000-0000-4000-8000-000000003027', '明日は、学校で身体そくていがあります。', 'There will be body measurements tomorrow at school.'),
  ('00000000-0000-4000-8000-000000003027', 'この図しょかんには、身体しょうがいしゃがつかえるトイレはありますか？', 'Is there a handicap accessible restroom in this library?'),
  ('00000000-0000-4000-8000-000000003027', '空こうで、まやくをかくしもっていないか、身体けんさをされました。', 'At the airport, they searched me for hidden drugs.'),
  ('00000000-0000-4000-8000-000000003028', 'わたし、全身毛むくじゃらのワイルドな男せいがすきなんです。', 'Saya suka pria yang seluruh tubuhnya ditutupi rambut tebal dan liar.'),
  ('00000000-0000-4000-8000-000000003028', 'コウイチは全身にタトゥーを入れようと思っているみたいなんだけど、どう思う？', 'Rupanya Koichi ingin menato seluruh tubuhnya. Bagaimana menurut kalian?'),
  ('00000000-0000-4000-8000-000000003028', '昨日七ヶ月ぶりにランニングしたから、今日は全身筋肉痛だよ。', 'Saya berlari untuk pertama kalinya dalam tujuh bulan kemarin dan sekarang seluruh tubuh saya sakit.'),
  ('00000000-0000-4000-8000-000000003029', '土よう日に、森でピクニックをしました。', 'Pada hari Sabtu, kami piknik di hutan.'),
  ('00000000-0000-4000-8000-000000003029', 'お母さんは木を見て森を見ずなんだよ！', 'Kamu tidak bisa melihat kayu di balik pepohonan, Bu!'),
  ('00000000-0000-4000-8000-000000003029', '赤ずきんちゃんが森の中を歩いていると、死んだ狼に出くわしました。赤ずきんちゃんはその場を立ち去り、訪れたおばあさんの家で素晴らしい時間を過ごしました。', 'Little Red Riding Hood sedang berjalan melewati hutan ketika dia menemukan seekor serigala mati. Kemudian dia melanjutkan perjalanannya dan mengunjungi neneknya.'),
  ('00000000-0000-4000-8000-000000003030', 'それは、両者にひがあると思うよ。', 'Saya pikir mereka berdua bersalah dalam hal ini.'),
  ('00000000-0000-4000-8000-000000003030', 'コウイチせん手とマイケルせん手、今のところ両者のじつ力はほぼご角のようです。', 'Pemain Koichi dan Pemain Michael keduanya nampaknya cukup seimbang sejauh ini.'),
  ('00000000-0000-4000-8000-000000003030', '車両事故に関与している両者は、共に衝突時に携帯電話で話をしていた。', 'Kedua orang yang terlibat dalam kecelakaan mobil sedang berbicara di ponsel mereka pada saat kecelakaan terjadi.'),
  ('00000000-0000-4000-8000-000000003031', 'この小せつの作者の名前がどうしても思い出せません。', 'I just can’t remember this novel’s author’s name.'),
  ('00000000-0000-4000-8000-000000003031', 'ついにテキストフグの作者に会えました。', 'We could finally meet with the writers of TextFugu.'),
  ('00000000-0000-4000-8000-000000003031', '俺の兄貴がギリシャ神話の作者だったんだが、今は失業している。', 'My brother was an author of Greek mythology, but now he’s unemployed.'),
  ('00000000-0000-4000-8000-000000003032', 'かれのお父さんは、立ぱな学者です。', 'His father is a splendid scholar.'),
  ('00000000-0000-4000-8000-000000003032', 'あの学者はけいれきさしょうをしています。', 'That scholar is a resume faker. '),
  ('00000000-0000-4000-8000-000000003032', '私は世界でも有名なハロー・キティ学者です。', 'I am a world renowned scholar of Hello Kitty.'),
  ('00000000-0000-4000-8000-000000003033', '「ルンバ」をはつ明したロボット工学者はだれですか？', 'Who’s the robotics engineer that invented the Roomba?'),
  ('00000000-0000-4000-8000-000000003033', 'あの工学者のことはきらいですが、そうするべきだと思ったから、助けてあげました。', 'I helped that engineer, even though I don''t like him, because I thought it was the right thing to do.'),
  ('00000000-0000-4000-8000-000000003033', '工学者になるためには、長期間勉強をする必要があります。', 'To become an engineer, you have to put in long hours of studying.'),
  ('00000000-0000-4000-8000-000000003035', 'いつもは教室にあつまりますが、明日は場所がちがうので、まちがえないでくださいね。', 'Biasanya kita berkumpul di dalam kelas, namun besok lokasinya berbeda, jadi pastikan kalian tidak salah tempat.'),
  ('00000000-0000-4000-8000-000000003035', '自分がたたかうべき場所をきちんと知っておくべきだ。', 'Anda harus mengetahui medan perang Anda sendiri.'),
  ('00000000-0000-4000-8000-000000003035', 'この場所は私が初めてローズに会った場所です。でも、あの日どうして靴を脱いだのかは思い出せません。', 'Di sinilah aku pertama kali bertemu Rose. Tapi, aku lupa kenapa aku melepas sepatuku hari itu.'),
  ('00000000-0000-4000-8000-000000003036', '会場に入場するには、チケットが必ようです。', 'You need a ticket to enter the venue.'),
  ('00000000-0000-4000-8000-000000003036', 'さいしゅう入場時かんは午後五時です。', 'Last admission is at 5 pm.'),
  ('00000000-0000-4000-8000-000000003036', 'ちくしょう！「確実な死への部屋」への入場門が塞がれている。', 'Damn it! The entrance to the "Room of Certain Death" is blocked.'),
  ('00000000-0000-4000-8000-000000003037', 'トヨタの工場に行きたいんですけど、何で行くのがべんりですか。', 'I’d like to go to the Toyota factory - which way would be the most convenient?'),
  ('00000000-0000-4000-8000-000000003037', '毎ばん、ベーコン工場のせじょうをするのは、わたしの主人の役目です。', 'It''s my husband''s job to lock up the bacon factory every night.'),
  ('00000000-0000-4000-8000-000000003037', '私が働きたいと思う唯一の工場は、クッキー工場です。', 'The only factory I would want to work in is a factory that makes cookies.'),
  ('00000000-0000-4000-8000-000000003038', '分からない所があれば、手を上げてください。', 'Jika ada bagian yang tidak Anda mengerti, silakan angkat tangan.'),
  ('00000000-0000-4000-8000-000000003038', 'まだおとし所をさがしていると中です。', 'Kami masih mencari titik temu.'),
  ('00000000-0000-4000-8000-000000003038', '七十二回も同じ所を歩いているので、私達は道に迷ったんだと思います。', 'Saya pikir kita tersesat karena kita telah melewati tempat yang sama sebanyak 72 kali sekarang.'),
  ('00000000-0000-4000-8000-000000003039', 'わたしの母は、来年のはるから、かいごしせつに入所することになりました。', 'Ibuku akan dirawat di panti jompo musim semi mendatang.'),
  ('00000000-0000-4000-8000-000000003039', 'こちらに入所年月日を記入してください。', 'Silakan tulis tanggal penerimaan Anda di sini.'),
  ('00000000-0000-4000-8000-000000003039', '俺の兄貴は今入所中だ。', 'Bos yakuza saya dipenjara sekarang.'),
  ('00000000-0000-4000-8000-000000003040', 'ジェニーの出所はいつですか？', 'Kapan Jenny akan dibebaskan dari penjara?'),
  ('00000000-0000-4000-8000-000000003040', '出所したら、ちゃんとかしをかえしてくれよな。', 'Saat kamu keluar dari penjara, tolong balas budi, oke?'),
  ('00000000-0000-4000-8000-000000003040', '引用部分の出所を明示してください。', 'Silakan tunjukkan sumber dari bagian yang dikutip.'),
  ('00000000-0000-4000-8000-000000003041', 'ここじゃなくて、どこか他所の店に行こうよ。', 'Jangan di sini, ayo pergi ke toko lain di tempat lain.'),
  ('00000000-0000-4000-8000-000000003041', '他所は他所、家は家！', 'Jangan bandingkan kami dengan keluarga lain.'),
  ('00000000-0000-4000-8000-000000003041', '私は暴力夫から逃れるために、他所に移り住んだ。', 'Saya pindah ke tempat lain untuk melarikan diri dari suami saya yang kasar.'),
  ('00000000-0000-4000-8000-000000003042', 'ポートランドのかん光名所を教えてください。', 'Bisakah Anda ceritakan tentang beberapa tempat wisata Portland?'),
  ('00000000-0000-4000-8000-000000003042', '名所めぐりの日にちが近くなってきたら、またれんらくするね。', 'Saya akan menghubungi Anda ketika kita mendekati hari kita mengunjungi tempat-tempat terkenal.'),
  ('00000000-0000-4000-8000-000000003042', '私は、スターバックスやデニーズ、それからニューヨーク郵便局など数々の名所を見るために、ニューヨークへ行きます。', 'Saya akan ke New York untuk melihat semua tempat terkenal seperti Starbucks, Denny''s, dan kantor pos Kota New York.'),
  ('00000000-0000-4000-8000-000000003043', 'こちらにあなたの家の住所をかいてください。', 'Silakan tulis alamat rumah Anda di sini.'),
  ('00000000-0000-4000-8000-000000003043', 'クリスマスカードをおくりたいので住所をおしえてくれませんか？', 'Bisakah Anda memberi saya alamat Anda sehingga saya bisa mengirimi Anda kartu Natal?'),
  ('00000000-0000-4000-8000-000000003043', '私が月に購入した土地には、住所はありますか？自分宛に酸素を送りたいので、よろしくお願い致します。', 'Apakah tanah yang saya beli di Bulan mempunyai alamat? Saya ingin mengirimkan sendiri beberapa tangki oksigen.'),
  ('00000000-0000-4000-8000-000000003044', '朝のあいさつをしてください。', 'Please say the morning greeting.'),
  ('00000000-0000-4000-8000-000000003044', '朝は毎日、トロトロの半じゅく目玉やきを食べます。', 'Every morning I eat over easy and sunny-side-up eggs.'),
  ('00000000-0000-4000-8000-000000003044', '明日の朝は早起きをしなくてはいけません。だって、Xboxをプレイしまくるという長い一日が待っているから。', 'I have to wake up early tomorrow morning because I have a long day of Xbox playing to do.'),
  ('00000000-0000-4000-8000-000000003045', '朝ごはんにパンとたまごをたべた。', 'I ate bread and eggs for breakfast.'),
  ('00000000-0000-4000-8000-000000003045', '朝ごはんにはベーコンに決まってるだろ？こんな当たり前のことも分からないのか。', 'Of course breakfast has to have bacon! Why can’t you understand something so obvious?'),
  ('00000000-0000-4000-8000-000000003045', '滅茶苦茶お腹が空いていて、朝ごはんに腐った卵を６つも食べてしまったこと、今までにある？', 'Have you ever been so hungry that you ate six rotten eggs for breakfast?'),
  ('00000000-0000-4000-8000-000000003046', '明日の朝、一しょに山にのぼって朝日を見ませんか？', 'Would you like to climb a mountain with me tomorrow morning to see the morning sun?'),
  ('00000000-0000-4000-8000-000000003046', 'どうしてあの朝日の絵をかべから外してしまったんですか？', 'Why did you take the picture of the rising sun off of the wall?'),
  ('00000000-0000-4000-8000-000000003046', '日本は「日出ずる国」として知られているが、それは「朝日国旗」に見事に描写されている。', 'Japan is known as "the Land of the Rising Sun," which is excellently depicted on its "Rising Sun" flag.'),
  ('00000000-0000-4000-8000-000000003047', 'あなたのじゅけん番号は何番ですか？', 'Berapa nomor ujianmu?'),
  ('00000000-0000-4000-8000-000000003047', '三十分で、この番号をおぼえてください。', 'Anda memiliki waktu 30 menit untuk menghafal serangkaian angka.'),
  ('00000000-0000-4000-8000-000000003047', '今、めちゃくちゃ落ち込んでるんだよ。だって、彼女に偽の電話番号を渡されたんだよ。', 'Saya sangat kecewa saat ini karena dia memberi saya nomor telepon palsu.'),
  ('00000000-0000-4000-8000-000000003048', 'イチゴあじのあめが、この中で一番すきです。', 'Saya paling suka permen rasa stroberi dari semua ini.'),
  ('00000000-0000-4000-8000-000000003048', 'わたしが人生で一番さいしょによんだ教かしょは、テキストフグです。', 'Buku teks pertama yang saya baca dalam hidup saya adalah TextFugu.'),
  ('00000000-0000-4000-8000-000000003048', 'シドニー・クロスビーは、世界で一番うまいホッケー選手だ。', 'Sidney Crosby adalah pemain hoki nomor satu di dunia.'),
  ('00000000-0000-4000-8000-000000003049', 'き末しけんで、学年で二番になりました。', 'Saya mendapat tempat kedua dalam ujian akhir untuk tahun saya.'),
  ('00000000-0000-4000-8000-000000003049', 'これは二番目に古いゴジラえいがです。', 'Ini adalah film Godzilla tertua kedua.'),
  ('00000000-0000-4000-8000-000000003049', 'カルロス・スリムは、世界大富豪番付けで二番に順位を下げた。', 'Carlos Slim turun ke posisi nomor dua dalam daftar orang terkaya di dunia.'),
  ('00000000-0000-4000-8000-000000003050', '交番で、大しかんまでの道をききました。', 'Saya menanyakan arah ke kedutaan di boks polisi.'),
  ('00000000-0000-4000-8000-000000003050', '新しく入って来たヒマリちゃんは、この交番のアイドルです。', 'Himari, gadis baru di kotak polisi ini, adalah Miss Popular.'),
  ('00000000-0000-4000-8000-000000003050', 'すみません、お巡りさん。一番近い交番はどこですか？ある男が私のことをデブと言ったので、警察を呼ぶ必要があるんです。', 'Permisi, petugas. Dimana boks polisi terdekat? Saya perlu menelepon polisi karena seseorang baru saja menyebut saya gemuk.'),
  ('00000000-0000-4000-8000-000000003051', '答えは、１、２、３、４から、一番いいものを一つえらんでください。', 'Please choose the best answer among 1, 2, 3, and 4.'),
  ('00000000-0000-4000-8000-000000003051', '山口さんの答えは、いつも通りでした。', 'Mr. Yamaguchi''s response was the same as usual.'),
  ('00000000-0000-4000-8000-000000003051', 'テストの最初の質問の答え、何て書いた？「名前をここに書きなさい」ってやつだよ。自分の名前を書き込んだ？それとも「名前」ってそこに書いた？', 'What did you write as an answer for the first question on the test? The one that said, "Write Name Here." Did you put down your own name or did you just write "name?"'),
  ('00000000-0000-4000-8000-000000003052', 'このもんだいに、じしょをつかって答えてください。', 'Please answer this question using a dictionary.'),
  ('00000000-0000-4000-8000-000000003052', 'どうしてしつもんに答えられないの？', 'Why can''t you respond to my questions?'),
  ('00000000-0000-4000-8000-000000003052', '面接官に今までに嘘をついたことがあるかどうか聞かれた時に、何て答えればいいのか分からなかったよ。', 'I didn’t know how to answer when the interviewer asked me if I have ever lied before.'),
  ('00000000-0000-4000-8000-000000003053', 'この絵は、クリックでかく大します。', 'Gambar menjadi lebih besar ketika Anda mengkliknya.'),
  ('00000000-0000-4000-8000-000000003053', 'この絵をかべにかけ直してくれませんか？', 'Bisakah Anda memasang kembali gambar ini di dinding?'),
  ('00000000-0000-4000-8000-000000003053', '昨夜美術館からピカソの絵が五枚も盗まれたが、誰も気にしていないようだ。', 'Lima lukisan Picasso dicuri dari museum tadi malam, tapi sepertinya tidak ada yang peduli.'),
  ('00000000-0000-4000-8000-000000003054', 'トイレットペーパーと肉とやさいとしょうゆを同じ日に買いたいです。', 'I want to buy toilet paper, meat, vegetables, and soy sauce on the same day.'),
  ('00000000-0000-4000-8000-000000003054', 'どうしてそのスマホを買うことにしたんですか？', 'Why did you end up buying the smartphone?'),
  ('00000000-0000-4000-8000-000000003054', 'コウイチのボブルヘッド人形を買うために、長い行列ができていた。', 'There was a long line of people waiting to buy the Koichi bobblehead.'),
  ('00000000-0000-4000-8000-000000003055', '男の人が、交番で道をたずねています。', 'A man is stopping by a police box for directions.'),
  ('00000000-0000-4000-8000-000000003055', 'ほら、千里の道も一歩からって言うでしょ？', 'They say a journey of a thousand miles begins with a single step, right?'),
  ('00000000-0000-4000-8000-000000003055', 'この道を車で20分ぐらい行けば、未確認動物ビッグフットが目撃された場所に辿り着くよ。', 'Drive down this road for about twenty minutes and you’ll come to the place where an unidentified creature was spotted.'),
  ('00000000-0000-4000-8000-000000003056', 'どうして自てん車が歩道を走ってはいけないんですか？', 'Why can’t bicycles travel on sidewalks?'),
  ('00000000-0000-4000-8000-000000003056', 'まもなくうごく歩道がおわりますので、足元にごちゅういください。', 'You are approaching the end of the moving walkway. Please watch your step.'),
  ('00000000-0000-4000-8000-000000003056', '自転車は、忙しい車道じゃなく、歩道を走るべきだ。', 'Bicycles should be ridden on sidewalks, not on busy city streets.'),
  ('00000000-0000-4000-8000-000000003057', '先生が、じゅう道のルールややり方を教えます。', 'The teacher is going to teach the rules and the methods of Judo.'),
  ('00000000-0000-4000-8000-000000003057', '北海道で、けん道をきわめるつもりです。', 'I''m gonna master the way of sword in Hokkaido.'),
  ('00000000-0000-4000-8000-000000003057', '武士道と騎士道の違いについて説明してください。', 'Could you please explain the difference between bushido and chivalry?'),
  ('00000000-0000-4000-8000-000000003058', 'たいてい、ねている間は、だんぼうを切ります。', 'Usually, I turn off the heater while I’m sleeping.'),
  ('00000000-0000-4000-8000-000000003058', 'その間に、いそいでひるごはんをかきこみました。', 'Meanwhile, I shoved my lunch in my mouth.'),
  ('00000000-0000-4000-8000-000000003058', '筏を作っている間に、俺達みんな餓死にしちまうよ！泳いで川を渡った方が無難なんじゃないか？', 'In the time it takes to build a raft we’ll die of starvation! Wouldn’t it be safer to just swim across the river?'),
  ('00000000-0000-4000-8000-000000003059', '先生はいつ時間がありますか。', 'When do you have time, professor?'),
  ('00000000-0000-4000-8000-000000003059', '今日の午後でしんさつしてもらえる時間ってありますか？', 'Are there any available spots for a checkup this afternoon?'),
  ('00000000-0000-4000-8000-000000003059', 'スーパーマンは、アクアマンに、最も真剣な質問をした。「もう一度、ウォータースライダー に乗る時間、ある？」', 'Superman then asked Aquaman the most serious question, "Do we have enough time to go on the waterslides again?"'),
  ('00000000-0000-4000-8000-000000003060', '気がついたら、五時間ぐらいねむっていました。', 'When I came to, I had been sleeping for almost five hours.'),
  ('00000000-0000-4000-8000-000000003060', 'たのむから三分間だけだまっててくれないか？', 'For heaven''s sake, can''t you just be quiet for three minutes?'),
  ('00000000-0000-4000-8000-000000003060', '試験の中に、一定時間息を止めるというものがありました。一番難しかったのは、三時間息を止めるというものだったけれど、私はなんとかやり切りました。', 'The test involved having to hold my breath for fixed intervals of time. The most difficult one was for 3 hours, but I did it.'),
  ('00000000-0000-4000-8000-000000003061', 'さっきカフェで、人間のようにコーヒーをのんでるしば犬を見かけたよ。', 'A while ago I saw a shiba inu drinking coffee like a human at a cafe.'),
  ('00000000-0000-4000-8000-000000003061', 'わたしのすきなしは、あい田みつをの、「つまづいたって　いいじゃないか　にんげんだもの」というしです。人間というかん字がひらがなでかかれているところがすきです。', 'My favorite poem is Mitsuo Aida''s, "It’s ok to stumble, isn’t it,we are humans after all." I like this because the kanji for humans is written in hiragana.'),
  ('00000000-0000-4000-8000-000000003061', '人間はいつも人生の目的について悩んでいる。でも、私はその答えを見つけた気がします。トーフグで勉強することです！', 'Humans have always wondered about the purpose of life. I believe I have found the answer: studying on Tofugu.'),
  ('00000000-0000-4000-8000-000000003062', '間もなくかいえんです！', 'The curtain rises soon.'),
  ('00000000-0000-4000-8000-000000003062', '大学いん研究生のしょう学金についてのへんじが、間もなく来るはずです。', 'I''ll probably get a reply regarding the postgraduate research scholarship before long.'),
  ('00000000-0000-4000-8000-000000003062', 'もう間もなく夕飯が出来上がる頃ですが、クッキーを食べる手が止まりません。', 'Supper will be ready really soon but I still can’t stop eating these cookies.'),
  ('00000000-0000-4000-8000-000000003063', 'あの人と同じ空間にいるだけで心がいやされるんです。', 'Just being in the same space as that person can heal your heart.'),
  ('00000000-0000-4000-8000-000000003063', '日本人の中には、ベビーカーは空間をたくさんとるので、まんいん電車ではきん止にするべきだとかんがえる人もいます。', 'Some Japanese people think that strollers should be banned in crowded trains because they take up a lot of space.'),
  ('00000000-0000-4000-8000-000000003063', '宇宙空間には空気がないけど、それでもやっぱり月に住みたい。', 'Even though there is no air in space, I still want to live on the moon.'),
  ('00000000-0000-4000-8000-000000003064', '雲一つない青空でした。', 'Itu adalah langit biru tanpa satupun awan.'),
  ('00000000-0000-4000-8000-000000003064', 'この間おごってくれたおかえしに、あそこの雲をあげるよ。', 'Aku akan memberimu awan di sana sebagai ucapan terima kasih ketika kamu mentraktirku makan.'),
  ('00000000-0000-4000-8000-000000003064', '飛行機は雲の後ろに消え、もう二度とその姿を現すことはなかった。', 'Pesawat itu menghilang di balik awan dan tidak pernah terlihat lagi.'),
  ('00000000-0000-4000-8000-000000003065', 'ねられないとき、羊を数えるのはなぜですか。', 'Ketika Anda tidak bisa tidur, mengapa Anda menghitung domba?'),
  ('00000000-0000-4000-8000-000000003065', 'いのちがおしけりゃ、十数えるうちにきえろ。', 'Jika Anda menghargai hidup Anda sendiri, tersesatlah dalam sepuluh detik.'),
  ('00000000-0000-4000-8000-000000003065', 'スミス先生、生徒が二人足りません。数えましたが38人しかいないんです。', 'Ada dua siswa yang hilang, Tuan Smith. Saya hanya menghitung tiga puluh delapan anak.'),
  ('00000000-0000-4000-8000-000000003066', 'おかしいわ、どうしても数が合わないのよ。', 'Oh aneh, jumlahnya tidak cocok karena suatu alasan.'),
  ('00000000-0000-4000-8000-000000003066', '1985年におきたニューヨーク大地しんの死しゃの数は何人でしたか？', 'Berapa jumlah korban tewas akibat gempa bumi New York tahun 1985?'),
  ('00000000-0000-4000-8000-000000003066', 'この映画には、数々の日本映画のお兄ちゃん役で知られているコウイチが、数を数えるのが得意な数学教師の役で出演しています。', 'Dalam film ini, peran guru matematika yang pandai berhitung diperankan oleh Koichi yang dikenal banyak berperan sebagai kakak laki-laki di banyak film Jepang.'),
  ('00000000-0000-4000-8000-000000003067', '数字がのびるからといって、下ひんなきじをけいさいするのはよした方がいい。', 'Terlepas dari peningkatan jumlahnya, Anda tidak boleh mempublikasikan berita vulgar.'),
  ('00000000-0000-4000-8000-000000003067', 'この子は、一万五千六百七十二けたの数字をあん記している天才じです。', 'Anak ini adalah seorang jenius yang hafal angka sebanyak 15.672 digit.'),
  ('00000000-0000-4000-8000-000000003067', '数字の十一は、私がバレーボールをする時にいつも身に付ける背番号です。', 'Sebelas adalah nomor yang selalu saya pakai saat bermain bola voli.'),
  ('00000000-0000-4000-8000-000000003068', '川下さんは、石田中学校で数学の先生をしています。', 'Ibu Kawashita adalah guru matematika di SMP Ishida.'),
  ('00000000-0000-4000-8000-000000003068', '数学のしけん、明日だっていうのに、海人はホントききかんがねーよな。', 'Besok ujian matematika, tapi Kaito sepertinya tidak punya perasaan mendesak.'),
  ('00000000-0000-4000-8000-000000003068', '数学さんよ、どうか大人になって自分の問題は自分で解決してくれよな。', 'Dear Math, tolong bertumbuhlah dan selesaikan masalahmu sendiri.'),
  ('00000000-0000-4000-8000-000000003069', 'カラオケに行く人数は全ぶで何人ですか。', 'Berapa jumlah orang yang pergi karaoke?'),
  ('00000000-0000-4000-8000-000000003069', 'トーフグのあたらしいライターのぼしゅう人数は何人ですか？', 'Berapa nomor rekrutmen penulis Tofugu baru?'),
  ('00000000-0000-4000-8000-000000003069', '沢山の人数の人が、この国の人は同じズボンを履くべきだという私の提案に反対しました。', 'Ada banyak orang yang tidak setuju dengan usulan saya bahwa setiap orang di negara ini harus memakai celana yang sama.'),
  ('00000000-0000-4000-8000-000000003070', 'ワニカニに百点まん点で点数をつけるなら、何点になると思いますか？', 'Jika Anda memberi WaniKani skor 100, berapa poin yang akan Anda berikan?'),
  ('00000000-0000-4000-8000-000000003070', 'この点数は、こないだくれたプレゼントのおかえしだよ。', 'Poin-poin ini adalah imbalan atas hadiah yang Anda berikan kepada saya.'),
  ('00000000-0000-4000-8000-000000003070', '「どうしてそのテストでこんなに低い点数をとったの？」「欠席のせい。つまり、僕の隣の席の子が休んでたんだよ。」', '“Mengapa kamu mendapat nilai rendah pada ujian itu?” “Karena ketidakhadiran. Maksudku, anak yang duduk di sebelahku tidak hadir.”'),
  ('00000000-0000-4000-8000-000000003071', 'このゲームは、とても楽しくて、おも白いです。', 'This game is really fun and interesting.'),
  ('00000000-0000-4000-8000-000000003071', 'テレビを見ながら食べる方が、しゃべりながら食べるより楽しいよ。', 'It''s more fun to eat while watching TV than it is to eat while chatting.'),
  ('00000000-0000-4000-8000-000000003071', '飛行機から飛び降りるって、物凄く楽しいよ！', 'Jumping out of an airplane is so much fun!'),
  ('00000000-0000-4000-8000-000000003072', 'べん強してから音楽をききます。', 'I’ll listen to music after I study.'),
  ('00000000-0000-4000-8000-000000003072', '音楽をききながら仕ごとをすることはよくないと思いますか？', 'Do you think it isn''t good to work while listening to music?')
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES
  ('00000000-0000-4000-8000-000000003072', '違ったタイプの音楽が創りだされることはもう無いのかなって思ったりするんだよね。あなたは、人類は既に全ジャンルの音楽を全て創りだしちゃったと思う？', 'I wonder if another type of music will be created. Do you think mankind already made every possible genre?'),
  ('00000000-0000-4000-8000-000000003073', 'あんたはそうやって楽することばっかり考えて！', 'You only think about taking the easy way out!'),
  ('00000000-0000-4000-8000-000000003073', 'このいすめっちゃ楽だわー。', 'This chair is very comfortable!'),
  ('00000000-0000-4000-8000-000000003073', '私は愛犬トトと一緒にいる時が一番楽です。', 'I am most at ease when I am with my dog, Toto.'),
  ('00000000-0000-4000-8000-000000003074', '女の人と男の人が写しんを見ながら話しています。', 'A woman and a man are talking while looking at a picture.'),
  ('00000000-0000-4000-8000-000000003074', '早く日本ごがうまく話せるようになりたいです。', 'I want to become fluent in Japanese soon.'),
  ('00000000-0000-4000-8000-000000003074', 'あなたが話すのを聞いていると、なぜかいつも、紐無しで橋からバンジー・ジャンプをしているような気になります。', 'Every time I hear you speak, I feel like jumping off of a bridge without a bungee cord for some reason.'),
  ('00000000-0000-4000-8000-000000003075', '電話で家ぞくと話しています。', 'I’m talking on the phone with my family.'),
  ('00000000-0000-4000-8000-000000003075', '夜おそくに電話してごめんね。', 'Sorry to call you so late at night. '),
  ('00000000-0000-4000-8000-000000003075', 'アレクサンダー・グラハム・ベルが自分の電話の着信音を何にしていたのかが気になります。', 'I wonder what ringtone Alexander Graham Bell had on his telephone.'),
  ('00000000-0000-4000-8000-000000003076', '男の人と女の人が、大学のろう下で会話をしています。', 'A man and a woman are having a conversation in the hallway of the university.'),
  ('00000000-0000-4000-8000-000000003076', 'ペースのはやい日本ごの会話は、まだりかい出来ません。', 'I can''t understand fast-paced Japanese dialogue yet.'),
  ('00000000-0000-4000-8000-000000003076', 'どうして私達の会話はいつも野球についてなのでしょうか？', 'Why are our conversations always about baseball?'),
  ('00000000-0000-4000-8000-000000003077', '下のひょうは、「電車の時間」と「バスの時間」です。', 'As for the chart below, it shows "train times" and "bus times."'),
  ('00000000-0000-4000-8000-000000003077', 'この電車にのって、トトロえきでおりて、ネコバスにのりかえてください。', 'Get on this train, get off at Totoro Station and transfer to the Catbus.'),
  ('00000000-0000-4000-8000-000000003077', 'ホグワーツ特急は電車じゃなくて汽車です。', 'The Hogwarts Express isn’t an electric train, it’s a steam train.'),
  ('00000000-0000-4000-8000-000000003078', '電気をつけてください。', 'Please turn on the light.'),
  ('00000000-0000-4000-8000-000000003078', '電気をつけっぱなしにしないでって言ったじゃん！かせぎが少ないんだから、ちゃんと電気代せつやくにきょう力してよ。', 'I told you not to leave lights on. You don''t earn very much, so you''d better cooperate to save on the electricity bill!'),
  ('00000000-0000-4000-8000-000000003078', '子供の頃は暗闇を恐れていたが、今は電気料金の請求書を受け取る度に、光が怖いと思うよ。', 'When I was little I was afraid of the dark. Now, when I get my electric bill I’m afraid of the light.'),
  ('00000000-0000-4000-8000-000000003079', 'このおもちゃの電車は、電池でうごきます。', 'Kereta mainan ini bergerak dengan baterai.'),
  ('00000000-0000-4000-8000-000000003079', 'ママ、見てー！電池が取れちゃった。', 'Bu, lihat! Baterainya lepas.'),
  ('00000000-0000-4000-8000-000000003079', '自作のロボット犬の電池を買いに、ちょっくら町へ行ってくるよ。', 'Saya menuju ke kota untuk membeli baterai untuk robot anjing yang saya buat.'),
  ('00000000-0000-4000-8000-000000003080', '電子のおもさはいくらですか？', 'How much does an electron weigh?'),
  ('00000000-0000-4000-8000-000000003080', 'その電子ピアノを直すのに、どれくらい時間がかかると思いますか？', 'How long do you think it will take to fix the electric piano?'),
  ('00000000-0000-4000-8000-000000003080', '母親が電子レンジを買ってくれました。', 'Mom bought me a microwave oven. '),
  ('00000000-0000-4000-8000-000000003081', '2016年4月から日本でスタートした、電力自由化についてくわしく教えてください。', 'Can you tell me everything you know about the Electricity Liberalization that started in Japan in April of 2016.'),
  ('00000000-0000-4000-8000-000000003081', 'あの電力会社には電気代をはらいたくないよ。', 'I don''t want to pay the bill to that electric company.'),
  ('00000000-0000-4000-8000-000000003081', '電力が約三時間で復旧したので、私は面接の前に電動バリカンで頭を刈って整えることができました。', 'Power was restored in roughly three hours and I was able to fix my hair with my electric hair clippers before the interview.'),
  ('00000000-0000-4000-8000-000000003082', 'スモモさんが、ピンク色のいしょうをきる事が多いのはなぜですか？', 'Why do you think Ms. Sumomo wears so many pink clothes?'),
  ('00000000-0000-4000-8000-000000003082', '後はいが言っている事がいつもよく分からなくてこまっています。', 'I often have trouble understanding what my junior colleague is saying.'),
  ('00000000-0000-4000-8000-000000003082', 'すまないが、ちょっと今はする事がたくさんあって、忙しいんだ。', 'I’m sorry but I’ve been busy recently because I have a lot of things to do.'),
  ('00000000-0000-4000-8000-000000003083', '用事をおねがいしてもいいですか。', 'Would you mind if I asked you to do some errands?'),
  ('00000000-0000-4000-8000-000000003083', 'ごめんなさい！ちょっと用事が出来てしまって、今日のレッスンをキャンセルしないといけなくなってしまいました。', 'Sorry! I have to take care of something and I have to cancel my lesson today.'),
  ('00000000-0000-4000-8000-000000003083', '大事な用事があるので、明日は出勤することができません。', 'I have an important matter to attend to so I will not be able to work tomorrow.'),
  ('00000000-0000-4000-8000-000000003084', 'きのうてつ夜で仕事だったんですが、朝から工事の音がうるさくてぜんぜんねむれてないんです。', 'I worked all night last night, but I haven’t been able to sleep at all because of the loud construction that started this morning.'),
  ('00000000-0000-4000-8000-000000003084', '町中で一日中工事しているので、通行止めだらけでいやになるよ。', 'Because there''s construction going on all day, all over town, there are roads closed everywhere and I''m sick and tired of it.'),
  ('00000000-0000-4000-8000-000000003084', 'この工事は今日終わったんですよね？', 'This construction finished today, right?'),
  ('00000000-0000-4000-8000-000000003085', '大事なのは、きちんとあいさつをすることです。', 'The important thing is to greet them properly.'),
  ('00000000-0000-4000-8000-000000003085', '日本ごのべんきょうのために、毎日ワニカニにログインしてレビューをするのはとても大事なことです。', 'Logging onto WaniKani and doing your reviews every day is very important for your Japanese learning.'),
  ('00000000-0000-4000-8000-000000003085', 'リラックスする時間をとることは、とても大事だよ。', 'Taking time to relax is important.'),
  ('00000000-0000-4000-8000-000000003086', 'まだ返事をおくっていません。', 'Saya belum menjawabnya.'),
  ('00000000-0000-4000-8000-000000003086', '出せきのお返事、ありがとうございます。', 'Terima kasih atas RSVP Anda.'),
  ('00000000-0000-4000-8000-000000003086', '私は、お金が欲しいというメールを百通以上ビル・ゲーツに送りましたが、まだ返事をもらっていません。', 'Saya mengirimi Bill Gates lebih dari seratus pesan tentang memberi saya uang, namun dia masih belum membalas.'),
  ('00000000-0000-4000-8000-000000003087', '今、食事中なので、後でまたかけます。', 'I’m in the middle of eating a meal, so I’ll call you back later.'),
  ('00000000-0000-4000-8000-000000003087', 'どうぞごゆっくりお食事をお楽しみください。', 'Please relax and enjoy your meal!'),
  ('00000000-0000-4000-8000-000000003087', 'もし残りの人生毎日同じ食事しか食べられないとしたら、何を選びますか？', 'If you could only have one meal every day for the rest of your life, what would you choose?'),
  ('00000000-0000-4000-8000-000000003088', '友だちのじしょを使いたいです。', 'I want to use my friend’s dictionary.'),
  ('00000000-0000-4000-8000-000000003088', 'いたいのはとても苦手なので、ますいを使ってください。', 'I''m not good with pain, so please use anesthetics.'),
  ('00000000-0000-4000-8000-000000003088', 'そんなに屁っ放り腰にならないで！知ってる日本語をできるだけ使うようにしなよ。', 'Don’t be afraid of that. You should use the Japanese you know as much as possible.'),
  ('00000000-0000-4000-8000-000000003089', 'これが、ロブさんがかりたいと言っていた道具です。', 'Ini adalah alat yang kamu bilang ingin kamu pinjam, Rob.'),
  ('00000000-0000-4000-8000-000000003089', 'ドラえもんの道具の中で一番使ってみたい道具は何ですか。やっぱりどこでもドアですか？', 'Dari semua alat Doraemon, mana yang paling ingin kamu gunakan? Jelas Pintu Kemana Saja kan?'),
  ('00000000-0000-4000-8000-000000003089', '昨日買った道具入れの中に、なんとベイブ・ルースのルーキーカードが一枚入っていたんだ！', 'Saya membeli kantong peralatan kemarin yang menyembunyikan kartu pemula Babe Ruth di dalamnya.'),
  ('00000000-0000-4000-8000-000000003090', '今週末は、新きょの家具を買いに行く予定です。', 'Saya berencana pergi membeli furnitur untuk rumah baru saya akhir pekan ini.'),
  ('00000000-0000-4000-8000-000000003090', '王女の家具は本当にすばらしいですね！さすがです！', 'Anda memiliki perabotan yang sangat bagus, Putri! Sangat mengesankan.'),
  ('00000000-0000-4000-8000-000000003090', '家具はあなたの家にお運びしましたが、もう少し腰を軽くして扉と窓を早く取り付ける方がいいのではないかと思います。', 'Kami memindahkan perabotan ke rumah baru Anda tetapi Anda harus bertindak cepat untuk memasang pintu dan jendela.'),
  ('00000000-0000-4000-8000-000000003091', 'しけんを受ける人は、13:00までに大学の受付に来てください。', 'Jika Anda mengikuti ujian, silakan datang ke resepsi di universitas paling lambat pukul 13:00.'),
  ('00000000-0000-4000-8000-000000003091', 'トーフグの言ばをまともに受ける必要はないよ。', 'Anda tidak harus menerima kata-kata Tofugu apa adanya.'),
  ('00000000-0000-4000-8000-000000003091', '僕の手は他の人のよりも15倍も大きいけど、それでも野球ボールをうまく受けることができないんだ。', 'Meskipun tanganku lima belas kali lebih besar daripada tangan orang lain, aku masih belum bisa menangkap bola bisbol dengan baik.'),
  ('00000000-0000-4000-8000-000000003092', '和風のあじ付けがすきなんですよ。', 'Saya suka rasa Jepang.'),
  ('00000000-0000-4000-8000-000000003092', 'かえりにスーパーで、和風ごまドレッシングを買ってきてください。', 'Bisakah Anda membeli saus wijen Jepang dari toko kelontong dalam perjalanan pulang?'),
  ('00000000-0000-4000-8000-000000003092', 'これが和風ホットドッグです。', 'Ini adalah hotdog gaya Jepang.'),
  ('00000000-0000-4000-8000-000000003093', 'いつになったら、世界は平和になるんだろうか。', 'Jadi menurut Anda kapan dunia akan menemukan kedamaian?'),
  ('00000000-0000-4000-8000-000000003093', '安全で平和な地いきに住みたいです。', 'Saya ingin hidup dalam komunitas yang aman dan harmonis.'),
  ('00000000-0000-4000-8000-000000003093', 'どうして日本ではみんなあの平和のシンボルを写真にかざすの？', 'Mengapa semua orang di Jepang menggunakan tanda perdamaian dalam gambar?'),
  ('00000000-0000-4000-8000-000000003094', '朝ごはんは、和食がいいですね。', 'Ya, saya suka sarapan ala Jepang.'),
  ('00000000-0000-4000-8000-000000003094', 'アメリカ人の中にもさい近、よう食よりも和食がすきな人がふえている。', 'Ada peningkatan orang Amerika yang lebih menyukai masakan Jepang daripada masakan Barat.'),
  ('00000000-0000-4000-8000-000000003094', '和食イコール寿司ってわけじゃない。', 'Makanan ala Jepang tidak selalu berarti sushi.'),
  ('00000000-0000-4000-8000-000000003095', '和室でねるのは、これがはじめてです。', 'Ini pertama kalinya aku tidur di kamar bergaya Jepang.'),
  ('00000000-0000-4000-8000-000000003095', 'この和室、ドッグフードとコウイチの足のにおいがまざったようなにおいがしない？', 'Bukankah ruangan bergaya Jepang ini berbau seperti campuran makanan anjing dan kakimu, Koichi?'),
  ('00000000-0000-4000-8000-000000003095', '私のお兄ちゃんは、和室で大きな蜘蛛を飼っています。', 'Kakak laki-laki saya memiliki seekor laba-laba peliharaan berukuran besar di kamarnya yang bergaya Jepang.'),
  ('00000000-0000-4000-8000-000000003096', '和服もに合ってるね。', 'Kamu juga terlihat bagus dengan pakaian gaya Jepang.'),
  ('00000000-0000-4000-8000-000000003096', '何ちゃく和服をもっていますか？', 'Berapa banyak pakaian gaya Jepang yang Anda miliki?'),
  ('00000000-0000-4000-8000-000000003096', '和服でマラソンをする日本人を見たことがありますか？', 'Pernahkah Anda melihat orang Jepang lari maraton dengan pakaian ala Jepang?'),
  ('00000000-0000-4000-8000-000000003097', '何から始めるのがいいのか、分かりません。', 'I don’t know what to start from.'),
  ('00000000-0000-4000-8000-000000003097', 'むすめさん、四年生になったら、何かならい事を始めるの？', 'Will your daughter start any extracurriculars when she reaches fourth grade?'),
  ('00000000-0000-4000-8000-000000003097', '生地をフライパンに流し始める前に、材料を全て混ぜる必要があります。', 'You need to mix all the ingredients together before you can start transferring the batter to the pans.'),
  ('00000000-0000-4000-8000-000000003100', 'ねえ、日よう日、予定を入れてもいい？', 'Hei, bolehkah aku membuat rencana di hari Minggu?'),
  ('00000000-0000-4000-8000-000000003100', 'その小わく星は地きゅうに向かっていて、北大西ようのどこかにしょうとつする予定だ。', 'Asteroid tersebut berada dalam jalur langsung menuju Bumi dan diperkirakan menghantam suatu tempat di Samudera Atlantik Utara.'),
  ('00000000-0000-4000-8000-000000003100', '私がせっかく予定を立てても、誰もその通りに動いてくれないことが嫌です。', 'Saya benci ketika saya menjadwalkan hari saya, tetapi tidak ada yang mengikuti naskahnya.'),
  ('00000000-0000-4000-8000-000000003101', 'クママンまんがの、アニメ化が決定しました！', 'Mereka memutuskan untuk mengubah manga Kumaman menjadi anime!'),
  ('00000000-0000-4000-8000-000000003101', 'これはさいしゅう決定になりますので、その後の変更はできませんが、よろしいでしょうか？', 'Ini akan menjadi keputusan akhir Anda dan tidak dapat diubah lagi nanti. Apakah itu oke?'),
  ('00000000-0000-4000-8000-000000003101', '君の妹の結婚式と俺の母さんの葬式、どちらに出席するかの決定は君に任せるよ。', 'Aku akan menyerahkan keputusan apakah kami akan menghadiri pernikahan adik perempuanmu atau pemakaman ibuku padamu.'),
  ('00000000-0000-4000-8000-000000003102', '実は、わたし、こうみえてもオリンピックに出たことがあるんです。', 'Sebenarnya, meskipun penampilanku tidak seperti itu, aku dulunya adalah seorang atlet Olimpiade.'),
  ('00000000-0000-4000-8000-000000003102', '実のところ、おれたちはお前の実のおやじゃないんだよ。', 'Sejujurnya, kami bukanlah orang tua kandung Anda.'),
  ('00000000-0000-4000-8000-000000003102', 'すまない、お前。実は、俺達の貯金を全部、プロ野球カードと風船ガムにはたいちまったんだ。', 'Maafkan aku, sayang. Sebenarnya saya menghabiskan seluruh tabungan kami untuk membeli kartu bisbol dan permen karet.'),
  ('00000000-0000-4000-8000-000000003103', '事実かもしれないけど、なっとくはできないな。', 'Itu mungkin benar, tapi saya masih belum yakin.'),
  ('00000000-0000-4000-8000-000000003103', 'あのせいじ家の言っていることは、事実に反します。', 'Apa yang dikatakan politisi tersebut bertentangan dengan fakta.'),
  ('00000000-0000-4000-8000-000000003103', '口髭を生やした男が気味悪く見えるのは、科学的な事実です。', 'Sudah menjadi fakta ilmiah bahwa pria berkumis terlihat menyeramkan.'),
  ('00000000-0000-4000-8000-000000003104', 'コウイチのフラダンスの実力は本物です。', 'Kemampuan menari hula Koichi memang asli.'),
  ('00000000-0000-4000-8000-000000003104', 'ビエトが本気の実力を出した所を見た人はまだだれもいません。', 'Belum ada orang yang menyaksikan kekuatan Viet yang sebenarnya.'),
  ('00000000-0000-4000-8000-000000003104', '運も実力のうちってよく言うだろ。', 'Mereka biasanya berkata, "keberuntungan adalah apa yang Anda peroleh."'),
  ('00000000-0000-4000-8000-000000003105', '服を引き出しの中に入れてください。', 'Please put your clothes in the drawer.'),
  ('00000000-0000-4000-8000-000000003105', 'かわいい！おそろいの服をきてるんですね。', 'How cute! They are wearing matching clothing.'),
  ('00000000-0000-4000-8000-000000003105', '今日はチョー暑くて、あなたはあまりにも多くの服を着ているよ。', 'It’s so hot today. You’re wearing too many clothes.'),
  ('00000000-0000-4000-8000-000000003106', 'ここで泳いではいけません。', 'Jangan berenang di sini.'),
  ('00000000-0000-4000-8000-000000003106', 'あんた、目が泳いでるよ。', 'Hei, matamu licik.'),
  ('00000000-0000-4000-8000-000000003106', '私はベッドの上にある見えないプールで泳いで運動しているんです。', 'Saya berolahraga dengan berenang di kolam tak kasat mata di tempat tidur saya.'),
  ('00000000-0000-4000-8000-000000003107', 'マサルさんが持っている物は何ですか。', 'What is that thing Masaru has?'),
  ('00000000-0000-4000-8000-000000003107', 'うちのワンちゃんを物あつかいしないでください！', 'Don''t treat my dog like a thing!'),
  ('00000000-0000-4000-8000-000000003107', '私の好きな物を三つ挙げるなら、チキンと揚げ物とご飯です。', 'My three favorite things are chicken, fried foods, and rice.'),
  ('00000000-0000-4000-8000-000000003109', 'ポートランドの名物は何ですか。', 'What is Portland’s specialty?'),
  ('00000000-0000-4000-8000-000000003109', 'トーフグの名物社長から、東京名物の東京ばななをおみやげにもらいました。', 'I got Tokyo''s famous "Tokyo Banana" from the Tofugu''s famous-for-being-unique president.'),
  ('00000000-0000-4000-8000-000000003109', 'たこ焼きは絶対に大阪名物の一つです。', 'Takoyaki is definitely one of the most famous foods in Osaka.'),
  ('00000000-0000-4000-8000-000000003110', 'このベーコン、なんか苦い。', 'Bacon ini sedikit pahit.'),
  ('00000000-0000-4000-8000-000000003110', 'このくすりはすっごく苦いから、気をつけてね。', 'Obat ini sangat pahit, jadi persiapkan dirimu!'),
  ('00000000-0000-4000-8000-000000003110', 'カラメルは、焦がさないように気を付けてください。でないと、苦い味になってしまいます。', 'Hati-hati jangan sampai karamel gosong karena akan terasa pahit.'),
  ('00000000-0000-4000-8000-000000003111', '食べすぎて苦しい。', 'Saya makan terlalu banyak dan itu menyakitkan.'),
  ('00000000-0000-4000-8000-000000003111', 'トーフグにあいをこく白できなくて苦しいよ！', 'Aku menderita karena kenyataan bahwa aku tidak bisa menyatakan cintaku pada Tofugu.'),
  ('00000000-0000-4000-8000-000000003111', '正直に言えば、それはかなり苦しい状況だ', 'Sejujurnya, ini adalah keadaan yang cukup menyedihkan.'),
  ('00000000-0000-4000-8000-000000003112', 'バスに乗って、海へ行きました。', 'Saya naik bus untuk pergi ke laut.'),
  ('00000000-0000-4000-8000-000000003112', '東京・しな川方めん行きではなくて、上野・池ぶくろ方めん行きに乗ってください。', 'Pastikan Anda naik kereta menuju Ueno dan Ikebukuro, bukan Tokyo dan Shinagawa.'),
  ('00000000-0000-4000-8000-000000003112', 'ジェットコースターに乗るのは大好きなんだけど、どの席もいつもゲロ臭いんだよね。', 'Saya suka naik roller coaster tetapi selalu berbau muntahan.'),
  ('00000000-0000-4000-8000-000000003113', '子どもを助手せきに乗せるのはきけんです。', 'Berbahaya membiarkan anak-anak duduk di kursi penumpang.'),
  ('00000000-0000-4000-8000-000000003113', '机に足を乗せるのは行ぎがわるいですよ。', 'Meletakkan kaki di atas meja adalah perilaku buruk.'),
  ('00000000-0000-4000-8000-000000003113', '男は、女性の自転車が完璧に壊れているのを見て、「町まで車に乗せてあげるよ」と言った。', 'Pria tersebut melihat sepeda wanita tersebut hancur total sehingga dia menawarkan untuk memberinya tumpangan kembali ke kota.'),
  ('00000000-0000-4000-8000-000000003115', 'お客さんが入ってくると、このベルがなります。', 'Saat pelanggan masuk, bel ini berbunyi.'),
  ('00000000-0000-4000-8000-000000003115', '東京えきで、お客さんと会いました。', 'Saya bertemu dengan tamu saya di Stasiun Tokyo.'),
  ('00000000-0000-4000-8000-000000003115', 'お客さんを獲得するにはどうすればいいと思いますか？', 'Menurut Anda apa yang harus saya lakukan untuk mendapatkan pelanggan?'),
  ('00000000-0000-4000-8000-000000003116', '大すきなアイドルと、ろ天ぶろ付の客室にとまることがゆめなんです。', 'Impianku adalah tinggal di kamar tamu yang terhubung dengan pemandian terbuka bersama idola yang kucintai.'),
  ('00000000-0000-4000-8000-000000003116', 'このホテルでは全ての客室にコンシェルジュサービスが付いてきます。', 'Di hotel ini, semua kamar memiliki layanan pramutamu.'),
  ('00000000-0000-4000-8000-000000003116', 'ちょうど客室のリフォームが終わったところなんですの。是非うちにいらして、ご意見を聞かせてくださいな。', 'Saya baru saja selesai merenovasi ruang tamu. Kemarilah dan beri tahu saya pendapat Anda.'),
  ('00000000-0000-4000-8000-000000003117', '近くにくすり屋と肉屋もあります。', 'There is a pharmacy and a butcher shop nearby too.'),
  ('00000000-0000-4000-8000-000000003117', '王女にてんしょくする前は花屋ではたらいていました。', 'Before I changed my job to being a princess, I was working at a flower shop.'),
  ('00000000-0000-4000-8000-000000003117', '焼肉屋さんを経営している人と結婚するのが夢です。', 'It’s my dream to marry someone who owns yakiniku restaurants.'),
  ('00000000-0000-4000-8000-000000003118', '妹は部屋のそうじをしました。', 'Adik perempuanku membersihkan kamar.'),
  ('00000000-0000-4000-8000-000000003118', 'わたしの学校には、音楽室の中に夜だけにあらわれる部屋があるそうです。', 'Kudengar ada ruangan yang hanya muncul pada malam hari di ruang musik sekolahku.'),
  ('00000000-0000-4000-8000-000000003118', '部屋を片付けようとすると、いつも途中で見つけた別のものに気を取られてしまって、片付けることができません。', 'Saya tidak dapat membersihkan kamar saya karena setiap kali saya mencoba, perhatian saya hanya terganggu oleh semua barang yang saya temukan.'),
  ('00000000-0000-4000-8000-000000003119', 'あそこの肉屋で、合いびき肉を100g買ってきてちょうだい。', 'Could you buy 100 grams of ground beef and pork from the butcher shop over there?'),
  ('00000000-0000-4000-8000-000000003119', 'あそこのお肉屋さん、新しいあじのビーガンとうふバーガーをかいはつしてるらしいよ。', 'I heard that butcher shop is creating a new flavor of vegan tofu burgers.'),
  ('00000000-0000-4000-8000-000000003119', '私の小さな町には「お肉屋さん」とい名前のレストランがあったんだけど、本当の「お肉屋さん」がどんなものかを知った時にはとてもショックでした。それで、今、私はベジタリアンなんです。', 'My small town had a restaurant called The Butcher Shop, so I was really surprised to learn what a real butcher shop is. I’m a vegetarian now.'),
  ('00000000-0000-4000-8000-000000003120', 'ポートランドでは、トーフグ茶屋の、ふぐもちが人気です。', 'The Tofugu tea shop in Portland has popular fugu mochi.'),
  ('00000000-0000-4000-8000-000000003120', 'きょうとにりょ行したとき、コウイチは毎ばん茶屋あそびを楽しみました。', 'When Koichi traveled to Kyoto, he enjoyed teahouse entertainment every night.'),
  ('00000000-0000-4000-8000-000000003120', '日本人は現代的なカフェを「カフェ」、昭和の香りのするコーヒーラウンジを「喫茶店」、伝統的なお茶屋さんを「茶屋」と呼びます。', 'Japanese people call modern cafes "Cafe," slightly old fashioned coffee lounges "Kissaten," and traditional tea shops "Chaya."'),
  ('00000000-0000-4000-8000-000000003121', '魚屋で金目だいを買ってきたの。', 'We went to buy splendid red bream at the fish store.'),
  ('00000000-0000-4000-8000-000000003121', 'この魚屋のゆかはすべりやすいから気を付けてね。', 'This fish shop floor is very slippery, so be careful.'),
  ('00000000-0000-4000-8000-000000003121', 'あの魚屋さんは百円おまけをしてくれた。', 'The fish shop gave me a 100 yen discount.'),
  ('00000000-0000-4000-8000-000000003122', '名古屋にはおいしいものがたくさんあります。', 'Nagoya has a lot of delicious food.'),
  ('00000000-0000-4000-8000-000000003122', '今日も名古屋で仕事があった。', 'I had work in Nagoya today again.'),
  ('00000000-0000-4000-8000-000000003122', '名古屋にいる友人を訪れた際、矢場とんというとても美味しいトンカツをご馳走してもらいました。', 'When I visited my friend in Nagoya, I was treated to a delicious pork cutlet called yabaton.'),
  ('00000000-0000-4000-8000-000000003123', 'じゃあ、やっぱり今度にしよう。', 'Okay, then let’s do it next time.'),
  ('00000000-0000-4000-8000-000000003123', '今度は本当に本気の本気で日本ごをべんきょうします！', 'I''m really, really serious about studying Japanese this time.'),
  ('00000000-0000-4000-8000-000000003123', '今度俺がお前を泣かせる時は、嬉し泣きだ。', 'The next time I make you cry it will be because you are happy.'),
  ('00000000-0000-4000-8000-000000003124', '丁度おふろから出たところです。', 'Saya baru saja keluar dari kamar mandi.'),
  ('00000000-0000-4000-8000-000000003124', '丁度いいゆかげんです。', 'Suhu mandinya pas.'),
  ('00000000-0000-4000-8000-000000003124', 'まあ、偶然！今丁度あなたに電話をしようと思っていたところよ！', 'Suatu kebetulan! Aku baru saja akan meneleponmu!'),
  ('00000000-0000-4000-8000-000000003125', '毎度おさわがせして、申しわけありません。', 'I’m sorry for all the times I’ve troubled you.'),
  ('00000000-0000-4000-8000-000000003125', '毎度のことだが、空は今日もちゅう文を決めるのがおそい。', 'Sora can''t make up his mind about which one to order, as usual.'),
  ('00000000-0000-4000-8000-000000003125', '毎度有難う御座います。', 'Thank you for your continued patronage.'),
  ('00000000-0000-4000-8000-000000003126', 'べつの角度から、もう一度見てみましょう。', 'Mari kita coba melihat lagi dari sudut yang berbeda.'),
  ('00000000-0000-4000-8000-000000003126', 'ピサのしゃとうはたしかにへんな角度で立っている。', 'Menara Miring Pisa memang berdiri pada sudut yang aneh.'),
  ('00000000-0000-4000-8000-000000003126', 'もしマイリー・サイラスが一番好きな歌を歌っているのをこの角度から見ることができたら、俺の夢を叶えてくれたってことで神様の存在を信じると思う。', 'Jika saya bisa melihat Miley Cyrus menyanyikan lagu favorit saya dari sudut ini, saya akan percaya kepada Tuhan karena itu berarti Dia membuat impian saya menjadi kenyataan.'),
  ('00000000-0000-4000-8000-000000003127', '弟は、かぜで38度のねつがあります。', 'My brother has a cold and a fever of 38 degrees Celsius.'),
  ('00000000-0000-4000-8000-000000003127', 'エアコンのおん度はいつも何度ぐらいにしていますか？', 'What temperature do you usually set the AC to?'),
  ('00000000-0000-4000-8000-000000003127', '２４度ぐらいがちょうどいいと思うんだけど。', 'I think about 24 degrees is just right for me.'),
  ('00000000-0000-4000-8000-000000003130', 'あらきさんは、けしゴムを持っていますか？', 'Do you have an eraser, Araki?'),
  ('00000000-0000-4000-8000-000000003130', 'コウイチは、実はなんしきやきゅうしんぱん員のしかくを持っています...というのは実はうそです。', 'Actually, Koichi has a license to be a soft baseball referee ...actually, that''s a lie.'),
  ('00000000-0000-4000-8000-000000003130', '一等に当選したことを知った時、宝くじを持つ手の震えが止まらなかった。', 'When I realized I won the grand prize, the hand I was holding the lottery ticket with couldn’t help but shake.'),
  ('00000000-0000-4000-8000-000000003133', 'しかし、この世界にはどちらもありません。', 'However, neither of them exist in this world.'),
  ('00000000-0000-4000-8000-000000003133', 'ふじ山は世界いさんにとうろくされています。', 'Mt. Fuji is registered as a World Heritage Site.'),
  ('00000000-0000-4000-8000-000000003133', 'あいつは自分の世界に閉じこもっていて、そこから出てこようとしないんだ。', 'He lives in his own world and doesn’t want to leave it.'),
  ('00000000-0000-4000-8000-000000003134', 'この夏、Tofuguから、「ベーコンとおこのみやきのチーズタルト」が発売されることが決定しました！', 'We’ve decided to sell bacon and okonomiyaki cheese tarts from Tofugu this summer.'),
  ('00000000-0000-4000-8000-000000003134', 'コウイチのつめのあかをせんじたポートランド名物トーフグ茶がトーフグのウェブサイトででぜっさん発売中です！', 'Portland''s famous Tofugu tea, with the dirt of Koichi''s nails, is now on sale on the Tofugu website!'),
  ('00000000-0000-4000-8000-000000003134', 'トーフグのデート用抱きまくらが発売されるのが待ち遠しい。', 'I can’t wait until the Tofugu dating pillows are on sale.'),
  ('00000000-0000-4000-8000-000000003135', 'このたんごの発音を教えてください。', 'Please teach me the pronunciation of this word.'),
  ('00000000-0000-4000-8000-000000003135', 'テイラーさんは日本ごの発音がとても上手ですね。', 'Taylor, your Japanese pronunciation is so good.'),
  ('00000000-0000-4000-8000-000000003135', 'わあ！スペイン語の小さな家って言葉の発音、日本語の「お腹すいた」にめちゃくちゃ似てる！', 'Wow, the pronunciation of the Spanish word "una casita" sounds similar to "I’m hungry" in Japanese.'),
  ('00000000-0000-4000-8000-000000003136', '自たくのベランダで、イモムシを発見しました。', 'I found hornworms on my balcony.'),
  ('00000000-0000-4000-8000-000000003136', 'がんは、早き発見することがひじょうに重ようです。', 'It’s very important to have early detection for cancer.'),
  ('00000000-0000-4000-8000-000000003136', 'Facebookでお金を稼ぐ方法を発見したぜ。しかも超簡単なの。まず、アカウント設定に行くだろ、それからアカウントを停止して、仕事に行くんだ！', 'I discovered how to make money from Facebook. It’s easy. Just go to your account settings, deactivate your account, and go to work.'),
  ('00000000-0000-4000-8000-000000003137', '相談の時間は、午後六時から午後九時です。', 'Waktu konsultasi adalah dari jam 6 sore. sampai jam 9 malam.'),
  ('00000000-0000-4000-8000-000000003137', 'こ人的に相談したいことがあるんですが、ちょっとお時間よろしいですか？', 'Jika Anda tidak keberatan, saya ingin mendiskusikan sesuatu dengan Anda secara pribadi. Apakah Anda punya waktu sebentar?'),
  ('00000000-0000-4000-8000-000000003137', '私は医者に痔の相談をした。', 'Saya berkonsultasi dengan dokter tentang wasir saya.'),
  ('00000000-0000-4000-8000-000000003138', 'まずは、相手の話をちゃんときいてあげようよ。', 'Pertama, Anda akan mendengarkan baik-baik apa yang dikatakan pasangan Anda.'),
  ('00000000-0000-4000-8000-000000003138', 'うらないによると、わたしのけっこん相手はどこかの国の王子さまだそうです。本当かな？', 'Menurut peruntunganku, calon pasanganku adalah seorang pangeran di suatu negara. Saya ingin tahu apakah itu benar.'),
  ('00000000-0000-4000-8000-000000003138', '馬鹿な話し相手は欲しくない。', 'Saya tidak ingin teman bicara yang bodoh.'),
  ('00000000-0000-4000-8000-000000003139', '何県の出身ですか。', 'Anda berasal dari prefektur mana?'),
  ('00000000-0000-4000-8000-000000003139', 'なら県の小学校では、せい服をきないといけない学校が多いです。', 'Ada banyak sekolah dasar di Nara yang mewajibkan siswanya mengenakan seragam.'),
  ('00000000-0000-4000-8000-000000003139', '今まで日本の何県に行ったことがあるの？', 'Prefektur mana di Jepang yang pernah kamu kunjungi?'),
  ('00000000-0000-4000-8000-000000003140', '美しいスカーフ、ありがとうございます。大切にします。', 'Terima kasih atas syal cantiknya. Saya akan menghargainya.'),
  ('00000000-0000-4000-8000-000000003140', 'クリステン王女の赤いかみ、ほんと、美しすぎてなみだが出る。', 'Rambut merah Putri Kristen sangat indah hingga membuatku menangis.'),
  ('00000000-0000-4000-8000-000000003140', 'なんてこった、君の目は宝石のように美しいよ、クリスティーン。', 'Ya ampun, matamu seindah permata, Christine.'),
  ('00000000-0000-4000-8000-000000003141', '美人だし、とてもエレガントですね。', 'Dia cantik dan sangat anggun.'),
  ('00000000-0000-4000-8000-000000003141', '美人ですねって言っておけばよかったんだよ。', 'Seharusnya kamu bilang padanya kalau dia cantik.'),
  ('00000000-0000-4000-8000-000000003141', '彼は誰の忠告も絶対に受けないなんて言っていたが、美人の忠告なら話は別だろう。', 'Dia bilang dia tidak pernah membutuhkan nasihat dari siapa pun, tapi begitu seorang wanita cantik menawarinya, dia mendengarkannya.'),
  ('00000000-0000-4000-8000-000000003142', 'すきなチームが負けたので、くやしいです。', 'Tim favoritku kalah, jadi aku frustasi dan patah hati.'),
  ('00000000-0000-4000-8000-000000003142', '食パンマンは、アンパンマンに、チェスでこてんぱんに負けました。', 'Breadman dikalahkan telak dalam permainan catur oleh Anpanman.'),
  ('00000000-0000-4000-8000-000000003142', '「今夜は、どこで食事したい？」「あなたが決めてよ。私はじゃんけんに負けたんだから。」', '"Di mana kamu ingin makan malam ini?" "Itu keputusanmu. Aku kehilangan batu-gunting-kertas."'),
  ('00000000-0000-4000-8000-000000003143', '勝負は引き分けにおわった。', 'Pertandingan berakhir seri.'),
  ('00000000-0000-4000-8000-000000003143', 'これは、一発勝負のコンテストです。', 'Ini adalah kontes yang ditentukan oleh satu putaran.'),
  ('00000000-0000-4000-8000-000000003143', 'この一年は、勝負の年だと思っています。', 'Saya pikir ini adalah tahun dimana banyak hal terjadi pada saya.'),
  ('00000000-0000-4000-8000-000000003144', 'サッカーのし合では、1対0で勝つことができました。', 'Pada pertandingan sepak bola, kami berhasil menang 1-0.'),
  ('00000000-0000-4000-8000-000000003144', '四才の時に、し合には勝ったが勝ぶに負けた。', 'Ketika saya berusia empat tahun, saya memenangkan pertandingan tetapi saya tetap merasa kalah.'),
  ('00000000-0000-4000-8000-000000003144', '明日のドッグ・レースにペットのウサギの参加を申し込むつもりなんだけど、確実に勝てると思うんだよね。', 'Saya mengikutsertakan kelinci peliharaan saya dalam perlombaan anjing besok dan saya jamin kelinci itu akan menang.'),
  ('00000000-0000-4000-8000-000000003145', '勝者だけが次のステージにすすめます。', 'Hanya pemenang yang akan maju ke tahap berikutnya.'),
  ('00000000-0000-4000-8000-000000003145', 'せんそうに勝者はいないのですから、どうかそんなむいみなたたかいは止めてください。', 'Tidak ada pemenang dalam perang, jadi tolong hentikan pertarungan yang tidak berarti ini.'),
  ('00000000-0000-4000-8000-000000003145', 'ビエトは、72時間耐久スクラブルゲームの勝者となった。', 'Viet muncul sebagai pemenang dalam permainan Scrabble 72 jam.'),
  ('00000000-0000-4000-8000-000000003146', 'じん社で必勝をきがんしてきました。', 'Saya berdoa untuk kemenangan tertentu di kuil.'),
  ('00000000-0000-4000-8000-000000003146', '空手のし合で、「必勝」とかかれたハチマキをしている人を見ました。', 'Saya melihat seseorang memakai ikat kepala bertuliskan "Pasti Kemenangan" di pertandingan karate.'),
  ('00000000-0000-4000-8000-000000003146', 'もし虎と七面鳥が戦争することになったら、それはもう虎の必勝になるだろうね。それから、ついでに、養鶏所で働く人も喜ぶだろうね。', 'Jika harimau berperang melawan kalkun, itu berarti kemenangan bagi harimau. Peternak ayam juga akan senang.'),
  ('00000000-0000-4000-8000-000000003147', '今回のテストは、楽勝だったね。', 'Tes ini sangat mudah.')
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES
  ('00000000-0000-4000-8000-000000003147', '「JLPT5はどうだった？」「ワニカニのおかげで、楽勝だったよ。」', '“Bagaimana JLPT5nya?” ''Berkat WaniKani, semuanya mudah sekali.'''),
  ('00000000-0000-4000-8000-000000003147', '戦争では、より高度な技術を持っている側が通常楽勝する。', 'Pihak yang memiliki teknologi lebih baik dalam berperang biasanya akan mendapatkan kemenangan mudah.'),
  ('00000000-0000-4000-8000-000000003148', 'スミスさんに手紙を送りました。', 'I sent a letter to Mr. Smith.'),
  ('00000000-0000-4000-8000-000000003148', '後で写しんLINEで送るね。', 'I''ll send you the photos later on LINE. '),
  ('00000000-0000-4000-8000-000000003148', '遅くなったね。今日はここまでにしよう。家まで送るよ。', 'It’s getting late. Let’s call it a day. I’ll walk you home.'),
  ('00000000-0000-4000-8000-000000003150', 'そのにもつは重そうですね。', 'That luggage looks heavy.'),
  ('00000000-0000-4000-8000-000000003150', 'この車、重すぎてうでがもげそう。', 'This car is so heavy that my arm is about to fall off. '),
  ('00000000-0000-4000-8000-000000003150', '「足を踏んでしまってごめんなさい。」「ちょっと重かったけど、どうってことないよ。」', '"I’m sorry I stepped on your foot." "No problem. It was a little heavy, but no harm done."'),
  ('00000000-0000-4000-8000-000000003151', '重要なしょるいなので、なくさないよう注意してください。', 'Itu adalah dokumen penting, jadi harap berhati-hati agar tidak hilang.'),
  ('00000000-0000-4000-8000-000000003151', 'この国にとって、国民一人当たり一羽の白鳥をかうことはとても重要なことなんです。', 'Bagi negara ini, sangat penting bagi setiap warga negara untuk memelihara satu ekor angsa.'),
  ('00000000-0000-4000-8000-000000003151', '私にとって人生で一番重要なものはビールですって？そんなこと言ってないわよ。言いもしないことを言ったなんて言わないでよ。', 'Hal terpenting dalam hidupku adalah bir? Aku tidak mengatakan itu! Jangan menaruh kata-kata di mulutku.'),
  ('00000000-0000-4000-8000-000000003152', 'アンナさんの体重は、何キロですか？', 'What is Anna’s body weight in kilograms?'),
  ('00000000-0000-4000-8000-000000003152', '次の身体そく定で体重をはかるのが待ちきれない。', 'I can’t wait to weigh myself at my next body measuring.'),
  ('00000000-0000-4000-8000-000000003152', 'どうして私があなたの体重を知っているのか聞かないで。ジェシカが口を滑らせたことは絶対に誰にも言わないって、あの子と約束したんだから。', 'Don’t ask me how I know your weight. I promised Jessica that I wouldn’t tell you that she told me.'),
  ('00000000-0000-4000-8000-000000003153', '分からないかん字の下に、二重せんを引いてください。', 'Please draw double lines under kanji you don’t know.'),
  ('00000000-0000-4000-8000-000000003153', '日本は二重国せきをみとめていません。', 'Japan doesn''t allow dual citizenship.'),
  ('00000000-0000-4000-8000-000000003153', '「それでは、世間話はそれぐらいにして、本題に入ろう。今日の議題は何だったかな？」「今日はあなたの二重あごについて話しをすることになっています。」「そうだったな。それでは始めようか。」', '"Well, let’s stop the small talk and cut to the chase. What was the topic of today’s meeting?" "We were going to talk about your double chin, sir." "Right, right. Let’s get started."'),
  ('00000000-0000-4000-8000-000000003154', 'バスをおりてから、少し歩く必要があります。', 'Saya harus berjalan sebentar setelah turun dari bus.'),
  ('00000000-0000-4000-8000-000000003154', 'JETのめんせつに合かくするために必要なことって何ですか。', 'Apa yang diperlukan untuk lulus wawancara JET?'),
  ('00000000-0000-4000-8000-000000003154', '日本に行ったら必要になるものって何だろう？', 'Apa yang saya perlukan jika saya pergi ke Jepang?'),
  ('00000000-0000-4000-8000-000000003155', 'もう少し要点をせいりしてからいけんをのべてください。', 'Silakan nyatakan pendapat Anda setelah mengatur ulang poin utama Anda sedikit lagi.'),
  ('00000000-0000-4000-8000-000000003155', 'ユウサクが要点をはあくしているとは思えないんだけど。', 'Menurutku Yusaku tidak mengerti maksudnya.'),
  ('00000000-0000-4000-8000-000000003155', 'いいから！早く要点を言ってよ！', 'Ayo! Langsung ke intinya!'),
  ('00000000-0000-4000-8000-000000003156', '仮にコウイチが『トーフグはめすだ』と言っても、多くのユーザーはそのいけんに反対するんじゃないだろうか。', 'Bahkan jika Koichi berkata, "Tofugu itu perempuan," saya yakin banyak pengguna akan memiliki pendapat yang berbeda.'),
  ('00000000-0000-4000-8000-000000003156', '仮にトーフグにさいあくのじたいがおきたとしたら、ライフタイムメンバーの人たちはどうなるんですか？', 'Seandainya hal terburuk terjadi pada Tofugu, apa yang akan terjadi pada anggota seumur hidup?'),
  ('00000000-0000-4000-8000-000000003156', 'え？あの娘の胸は風船で作られているって？仮にそうだとしても、だから何なんだよ！', 'Apa? Payudaranya terbuat dari balon? Seandainya itu benar, siapa yang peduli?'),
  ('00000000-0000-4000-8000-000000003157', 'まずは、仮名をかくれんしゅうから始めましょう。', 'Pertama, mari kita mulai dengan berlatih menulis kana.'),
  ('00000000-0000-4000-8000-000000003157', 'ワニカニでかん字をべん強するのに、まずは仮名を全部知っている必要がある。', 'Untuk mempelajari kanji di WaniKani, Anda harus mengetahui semua kana terlebih dahulu.'),
  ('00000000-0000-4000-8000-000000003157', 'この書類の漢字全部に、振り仮名を振ってもらえませんか？', 'Bisakah Anda menambahkan furigana ke semua kanji di dokumen ini?'),
  ('00000000-0000-4000-8000-000000003158', 'でも、それはたんなる仮定の話でしょう。', 'Tapi itu hanya asumsi, bukan?'),
  ('00000000-0000-4000-8000-000000003158', 'たとえば、一ドル百円と仮定すると、一本一ドルのコカコーラは百円になりますよね？', 'Misalnya, jika kita mengatakan satu dolar adalah seratus yen, maka satu kaleng coca cola seharga $1 adalah seratus yen, bukan?'),
  ('00000000-0000-4000-8000-000000003158', '彼女のベッドに積まれた札束のせいで、今とんでもない仮定が俺の頭の中を飛び交っている。', 'Sejak melihat tumpukan uang di tempat tidurnya, asumsi-asumsi gila terus bermunculan di kepala saya.'),
  ('00000000-0000-4000-8000-000000003159', '父は、毎朝六時に起きます。', 'My father gets up at six o’clock every morning.'),
  ('00000000-0000-4000-8000-000000003159', 'いつも朝起きるのめっちゃ早いですね。まだ四時ですよ。', 'You''re always up so early! It''s still 4 o''clock, you know.'),
  ('00000000-0000-4000-8000-000000003159', '三段腹を無くすために、毎朝起きたらすぐに100回腹筋をします。', 'I do 100 sit-ups every morning right after waking up to get rid of my three pack.'),
  ('00000000-0000-4000-8000-000000003160', '早速使わせていただきました。', 'Saya segera menggunakannya.'),
  ('00000000-0000-4000-8000-000000003160', '早速のごへんしん、ありがとうございます。', 'Terima kasih atas tanggapan langsung Anda.'),
  ('00000000-0000-4000-8000-000000003160', '私はその茄子を早速彼に送ります。', 'Saya akan segera mengirimkan terong kepadanya.'),
  ('00000000-0000-4000-8000-000000003161', 'インターネットの速度がおそすぎてイライラしています。', 'Kecepatan internetnya terlalu lambat dan itu membuatku kesal.'),
  ('00000000-0000-4000-8000-000000003161', 'もう少し速度をおとして走行してください。', 'Harap mengemudi sedikit lebih lambat.'),
  ('00000000-0000-4000-8000-000000003161', 'ドアを開けたら、冬の突風が物凄い速度で吹きこんできた。', 'Ketika saya membuka pintu, hembusan angin musim dingin menyerbu masuk dengan kecepatan dan kekuatan yang luar biasa.'),
  ('00000000-0000-4000-8000-000000003162', 'バレンタインデーには、友だちに、手作りのおかしを配るんです。', 'Untuk Hari Valentine kami akan membagikan manisan buatan tangan.'),
  ('00000000-0000-4000-8000-000000003162', 'しんぶんを配るバイトって月にいくらくらいかせげるのかな。', 'Saya bertanya-tanya berapa banyak yang bisa saya peroleh per bulan dari pekerjaan mengantarkan surat kabar.'),
  ('00000000-0000-4000-8000-000000003162', 'このパーティーマジでつまんない。道でティシュでも配ってる方がマシだよ。', 'Pesta ini meledak. Bahkan membagikan tisu saku di jalan akan lebih baik.'),
  ('00000000-0000-4000-8000-000000003163', 'わたしはパーティーでお酒を飲んだ。', 'Saya minum alkohol di pesta itu.'),
  ('00000000-0000-4000-8000-000000003163', '今、そのお酒はシーズンではないので、申しわけありませんがご用いできません。', 'Sake itu sedang tidak musimnya, jadi sayangnya tidak tersedia.'),
  ('00000000-0000-4000-8000-000000003163', '「割り勘にしよう。」「いや。今日は俺の奢りだよ。しかも、俺はお酒をたくさん飲んだけど、お前は一滴も飲まなかったじゃないか。」', '"Mari kita bagi tagihannya." "Tidak, kali ini aku yang melakukannya. Aku minum banyak alkohol, tapi kamu tidak minum apa pun"'),
  ('00000000-0000-4000-8000-000000003164', '日本酒はあまりすきではないんです。', 'Saya tidak terlalu suka alkohol Jepang.'),
  ('00000000-0000-4000-8000-000000003164', 'その日本酒のボトルから、値札を外してもらってもいいですか？', 'Bisakah Anda menghapus label harga dari botol sake Jepang untuk saya?'),
  ('00000000-0000-4000-8000-000000003164', '「何飲んでるの？」「日本酒だよ。一口飲んでみる？」「それじゃ、お言葉に甘えて一口もらってみようかな。」', '"Apa yang kamu minum?" "Anggur beras Jepang. Apakah kamu mau menyesapnya?" "Yah, kurasa aku akan mencobanya."'),
  ('00000000-0000-4000-8000-000000003165', '病院までタクシーで、千円ぐらいです。', 'It takes about a thousand yen to get to the hospital by taxi.'),
  ('00000000-0000-4000-8000-000000003165', 'この病院の院長は、九九もできない。', 'The head of this hospital can''t even do his multiplication tables.'),
  ('00000000-0000-4000-8000-000000003165', 'この病院で医者をすることには本当に嫌気が差すね。患者は馬鹿ばっかりなんだ。', 'I hate being a doctor in this hospital. The patients are all idiots.'),
  ('00000000-0000-4000-8000-000000003166', '2014年に、トーフグ学院をそつぎょうしました。', 'I graduated from Tofugu Academy in 2014.'),
  ('00000000-0000-4000-8000-000000003166', 'かん西学院大学の多くの学生はざい学中にりゅう学をけいけんします。', 'Many students from Kwansei Gakuin University get to study abroad while at college.'),
  ('00000000-0000-4000-8000-000000003166', 'やあ！こいつはワニカニ。あだ名はクラビゲーターだよ。トーフグ工業学院で働いてるんだ。', 'Hey! This guy is WaniKani, a.k.a. the Crabigator. He works for Tofugu Institute for Industrial Education.'),
  ('00000000-0000-4000-8000-000000003167', '学校が終わったら、買い物に行きます。', 'When school''s finished, I''ll go shopping.'),
  ('00000000-0000-4000-8000-000000003167', 'ギャンブルにまけて人生終わってしまった。', 'My life was over when I lost it all gambling.'),
  ('00000000-0000-4000-8000-000000003167', 'おい、こら！引っ込んでろ！原子爆弾の解体が終わるまでは、私に近づくなと言っただろ。', 'Hey, man! Back off! I told you to stay away from me until the atomic bomb has finished being dismantled.'),
  ('00000000-0000-4000-8000-000000003168', '電車でばくすいしてしまって、終点でうん転手さんに起こされたことはよくありますね。', 'Saya sering tertidur di kereta dan harus dibangunkan oleh pengemudi di pemberhentian terakhir.'),
  ('00000000-0000-4000-8000-000000003168', 'このシカゴ発のアムトラックの終点の駅は何て言う名前ですか。', 'Apa nama pemberhentian terakhir Amtrak yang berangkat dari Chicago?'),
  ('00000000-0000-4000-8000-000000003168', 'お願いがあるの。私がたとえ何と言っても、何をしようとも、終点に着くまで私が電車から降りないようにして。分かった？', 'Anda harus membantu saya. Apapun yang saya katakan, apapun yang saya lakukan, tolong jangan biarkan saya keluar dari kereta sampai kereta mencapai perhentian terakhir. Oke?'),
  ('00000000-0000-4000-8000-000000003169', '大さか公えん1日目終了しました！', 'Hari pertama pertunjukan Osaka telah berakhir!'),
  ('00000000-0000-4000-8000-000000003169', '主人公が死んでゲームが終了してしまいました。', 'Karakter utama meninggal dan permainan selesai.'),
  ('00000000-0000-4000-8000-000000003169', '「もし私がまたデブになったらどうする？」 「まぁ、俺達の関係が終了しないのは確実だね。」', '“Bagaimana kalau aku jadi gemuk lagi?” “Yah, hubungan kita tidak akan berakhir, itu sudah pasti.”'),
  ('00000000-0000-4000-8000-000000003170', '大すきなドラマの最終回を見のがして泣いた。', 'Saya melewatkan bagian terakhir dari drama favorit saya dan menangis.'),
  ('00000000-0000-4000-8000-000000003170', '今乗ってきた電車が最終だったから、もうかえれないよ。', 'Kereta yang baru kami naiki adalah yang terakhir hari ini, jadi kami tidak bisa kembali lagi.'),
  ('00000000-0000-4000-8000-000000003170', 'これが我が社の最終提案です。後はあなたの決断次第です。', 'Ini adalah tawaran terakhir kami. Sekarang bola ada di tangan Anda.'),
  ('00000000-0000-4000-8000-000000003171', '日本に来てから、日本語を習いました。', 'I’ve learned Japanese since coming to Japan.'),
  ('00000000-0000-4000-8000-000000003171', '姉は、ピアノを習っています。', 'My older sister is taking piano lessons.'),
  ('00000000-0000-4000-8000-000000003171', '今日は、世界一のフグクッキーの作り方を習いに行くのよ。', 'I’m going to learn how to make the world’s best fugu cookies today.'),
  ('00000000-0000-4000-8000-000000003172', 'あんたのけいたいなら、その辺に転がってたわよ。', 'Your cell phone was left somewhere around here.'),
  ('00000000-0000-4000-8000-000000003172', 'ダリンは、トーフグオフィスの前にフグの死体が転がっているのを発見しました。', 'Darin discovered the dead body of a blowfish, lying in front of the Tofugu office.'),
  ('00000000-0000-4000-8000-000000003172', '転がる石？イギリスのロックバンド、ザ・ローリング・ストーンズのことですか？', 'A rolling stone? Do you mean the English rock band The Rolling Stones?'),
  ('00000000-0000-4000-8000-000000003173', 'わたしは自転車で会社に行っています。', 'I go to work by bike.'),
  ('00000000-0000-4000-8000-000000003173', '自転車を買ってあげるよ。お返しは要らないからね！', 'I''ll buy you a new bicycle, no strings attached. '),
  ('00000000-0000-4000-8000-000000003173', '「ごめん。てっきり君が僕の自転車を壊したのかと思ってたよ。」 「何それ！ひどい。私がそんなことするはずないでしょ。」', '"I’m sorry. I thought for sure you were the one who broke my bike." "What? That’s awful. You know me better than that."'),
  ('00000000-0000-4000-8000-000000003174', '休日には、とくにあてもなく運転するのがすきなんだ。', 'I really like driving around aimlessly when I’m on holiday.'),
  ('00000000-0000-4000-8000-000000003174', '運転する時は、ぜっ対に後ろはふり返りません。サメと同じで、前しか見ないんです。', 'I never look back when I drive. I''m like a shark—only looking forward.'),
  ('00000000-0000-4000-8000-000000003174', 'このフグモデルの車は最高だね！とても気に入ったよ。毎日運転するのが待ち遠しいよ。', 'This Fugu model car is amazing! I love it! I can’t wait to start driving it every day.'),
  ('00000000-0000-4000-8000-000000003175', 'そのメール、私にも転送してくれない？', 'Could you forward that email to me?'),
  ('00000000-0000-4000-8000-000000003175', '海外に住んでいる日本人は、よく日本のウェブサイトから物を買って、海外の住所に転送しています。', 'Japanese people who reside overseas often buy things from Japanese websites and have them forwarded to the foreign addresses.'),
  ('00000000-0000-4000-8000-000000003175', '郵便物をこちら住所の方へ転送して頂きたいんですが。', 'Could you please forward my mail to this address?'),
  ('00000000-0000-4000-8000-000000003176', 'ペットのハムスターがものすごいいきおいで回し車を回転させています。', 'Hamster peliharaan saya sedang memutar roda hamsternya dengan penuh semangat.'),
  ('00000000-0000-4000-8000-000000003176', 'あそこの回転ずし、もう行った？なんか、そこのすししょく人は皿がきらいらしく、すしが回転してあつくなってるコンベアベルトの上に直でおかれているらしいよ。', 'Apakah Anda pernah ke restoran sushi ban berjalan di sana? Rupanya koki sushi mereka tidak menyukai piring di sana, jadi sushi langsung disajikan di ban berjalan yang berputar dan panas.'),
  ('00000000-0000-4000-8000-000000003176', '月は地球の周り回転していて、地球は太陽の周りを回転している。', 'Bulan berputar mengelilingi bumi dan bumi berputar mengelilingi matahari.'),
  ('00000000-0000-4000-8000-000000003177', '仕事は進んでいますか？', 'Apakah Anda membuat kemajuan dalam pekerjaan Anda?'),
  ('00000000-0000-4000-8000-000000003177', 'トーフグは、いつも一歩先を進んでいるよね。', 'Tofugu selalu selangkah lebih maju, bukan?'),
  ('00000000-0000-4000-8000-000000003177', 'お嬢さんは他の学生よりずっと進んでいる。', 'Putri Anda maju lebih cepat dibandingkan siswa lainnya.'),
  ('00000000-0000-4000-8000-000000003178', '日に日に進化してるのが実かんできて、うれしいです。', 'Saya senang bisa menyadari seberapa besar kemajuan saya setiap hari.'),
  ('00000000-0000-4000-8000-000000003178', 'みなさんのおかげで、トーフグは大きな進化をとげることができました。', 'Terima kasih kepada kalian semua, Tofugu mencapai kemajuan luar biasa.'),
  ('00000000-0000-4000-8000-000000003178', 'おい、お前って本当に阿呆だな。ダーウィンの進化論はディズニー映画のタイトルなんかじゃねえよ。', 'Astaga, kamu benar-benar bodoh. Teori evolusi Darwin bukanlah judul film Disney.'),
  ('00000000-0000-4000-8000-000000003179', 'げんざい、六つのプロジェクトが進行中です。', 'Enam proyek sedang berjalan.'),
  ('00000000-0000-4000-8000-000000003179', 'おいしゃさんに、進行がんがあると言われました。', 'Dokter memberi tahu saya bahwa saya menderita kanker stadium lanjut.'),
  ('00000000-0000-4000-8000-000000003179', 'フグエキスから作られた新しい薬がその病気の進行を抑えた。', 'Obat baru yang terbuat dari ekstrak Fugu telah menekan perkembangan penyakit ini.'),
  ('00000000-0000-4000-8000-000000003180', 'あなたのけしゴム、つくえの下に落ちていますよ。', 'Penghapusmu jatuh ke bawah meja.'),
  ('00000000-0000-4000-8000-000000003180', 'しけんに落ちた日に、ひろうから、はがぬけ落ちました。', 'Pada hari saya gagal dalam ujian, gigi saya rontok karena kelelahan.'),
  ('00000000-0000-4000-8000-000000003180', '「何してるの？私も入れて？」「本当？俺たち、ステアフォールっていう、棒人間がひたすら階段から落ちるゲームをしてるんだけど。」「おもしろそうじゃん。」', '"Apa yang sedang kalian mainkan? Biarkan aku masuk!" "Benarkah? Kami sedang memainkan permainan bernama Stair Fall di mana seorang stickman terus-menerus terjatuh dari tangga." "Kedengarannya menyenangkan!"'),
  ('00000000-0000-4000-8000-000000003181', '青葉が目にしみるきせつとなりました。', 'Saat itu adalah tahun dimana dedaunan membuat mataku terbakar.'),
  ('00000000-0000-4000-8000-000000003181', '家のにわの青葉に虫がいっぱい付いてる！', 'Ada banyak serangga pada daun muda di kebun kami!'),
  ('00000000-0000-4000-8000-000000003181', 'お前の頭、ちょっと変なにおいがするぞ。 乾燥した青葉か何かみたいな。', 'Kepalamu berbau sedikit aneh. Itu seperti daun kering atau semacamnya.'),
  ('00000000-0000-4000-8000-000000003182', 'このはこは、あのはこよりも軽い。', 'Kotak ini lebih ringan dari kotak itu.'),
  ('00000000-0000-4000-8000-000000003182', 'この毛ぬき、びっくりするぐらい軽いんだけど。', 'Pinset ini ternyata sangat ringan.'),
  ('00000000-0000-4000-8000-000000003182', '毎日軽い朝ごはんを食べる。', 'Setiap hari saya makan sarapan ringan.'),
  ('00000000-0000-4000-8000-000000003183', 'あ、それから、つくえを運ぶのをわすれないでください。', 'Oh, and don’t forget to move the desk.'),
  ('00000000-0000-4000-8000-000000003183', '私の父親としての役目は、食べ物をテーブルに運んで、娘と一緒にお茶会をすることだ。', 'My duty as a father is to put food on the table and have tea parties with my daughter.'),
  ('00000000-0000-4000-8000-000000003183', 'この教科書を運ぶための鞄がほしい。', 'I want a bag to carry these textbooks.'),
  ('00000000-0000-4000-8000-000000003184', '最近みょうに運がいいんだよな。', 'I’ve been really lucky lately for some reason.'),
  ('00000000-0000-4000-8000-000000003184', 'こんな美人のよめさんもらって、お前って本当に運がいいな。', 'You are so lucky to have such a beautiful wife.'),
  ('00000000-0000-4000-8000-000000003184', '日本語の授業でAが取れたんだけど、ただ単に運がよかっただけだと思うの。', 'I got an A in Japanese, but I think I was just lucky.'),
  ('00000000-0000-4000-8000-000000003185', '日本語のじしょを開けてください。', 'Please open your Japanese dictionary.'),
  ('00000000-0000-4000-8000-000000003185', 'わたしのかれ氏は、車に乗る時は、いつもドアを開けてくれるよ。', 'My boyfriend always opens the car door for me when I get in.'),
  ('00000000-0000-4000-8000-000000003185', '「ねぇ、このワインボトルを開けてもらえないかな？」「いいよ。朝飯前だよ。」', '"Can you open this bottle of wine for me?" "Of course. Piece of cake."'),
  ('00000000-0000-4000-8000-000000003186', 'どうがが公開されるのはいつですか？', 'When will the video be released to the public?'),
  ('00000000-0000-4000-8000-000000003186', 'Etoeto発売を記ねんして、コウイチの半生をドキュメンタリーにしたえいがが公開になりました。', 'A documentary movie of half of Koichi''s life has been opened to the public to commemorate Etoeto''s release.'),
  ('00000000-0000-4000-8000-000000003186', '「この写真を公開したのは、写真より実物の花子の方がずっと可愛いんだってことをみんなに教えたかったからだよ。」「あんたって本当口からでまかせばっかりよね！」', '"I only published that picture to show people that you look much better in person, Hanako." "That is such a lie!"'),
  ('00000000-0000-4000-8000-000000003187', 'うちも、開業当時はしゃっ金だらけだったんだよ。', 'We also had a ton of debt when we opened our business.'),
  ('00000000-0000-4000-8000-000000003187', 'この目医者は、今年で開業して三十五年になります。', 'As of this year, this eye doctor has been in practice for 35 years.'),
  ('00000000-0000-4000-8000-000000003187', 'コウイチの開業準備を手伝うために、昨日は学校をサボったんだ。', 'I blew off school yesterday to help Koichi prepare for the opening of his business.'),
  ('00000000-0000-4000-8000-000000003188', '開発チームがみなさんのごしつもんにお答えします。', 'The development team will answer everyone’s questions.'),
  ('00000000-0000-4000-8000-000000003188', 'トーフグの開発ひ話を教えてください。', 'Please tell us about the story behind Tofugu''s development.'),
  ('00000000-0000-4000-8000-000000003188', 'コウイチは新しい日本語学習サイトを開発するために徹夜をした。', 'Koichi pulled an all-nighter to develop a new Japanese learning site.'),
  ('00000000-0000-4000-8000-000000003189', '青いシャツをきている人を集めてください。', 'Please gather the people wearing blue shirts.'),
  ('00000000-0000-4000-8000-000000003189', 'ユーザーからのフィードバックを集めています。', 'We''ve been gathering feedback from users.'),
  ('00000000-0000-4000-8000-000000003189', '私は外国の食べ物の写真を集めている。', 'I am collecting pictures of foreign food.'),
  ('00000000-0000-4000-8000-000000003190', '会ぎに集中しすぎて終電をのがしてしまいました。', 'We were too concentrated on the meeting and we missed the last train.'),
  ('00000000-0000-4000-8000-000000003190', '集中集中！気合いを入れろ！', 'Concentrate! Focus! Give it your all!'),
  ('00000000-0000-4000-8000-000000003190', 'もう！まとわりつくのは止めてよ！集中できないでしょ。', 'Hey! Stop breathing down my neck. I can’t concentrate.'),
  ('00000000-0000-4000-8000-000000003191', 'みんなから集金して、花たばと色紙を買いました。', 'We collected money from everyone and bought a bunch of flowers and a message board.'),
  ('00000000-0000-4000-8000-000000003191', '集金のことはもう心配するなよ。なるようになるさ。', 'Don''t worry about collecting money anymore. What will be, will be. '),
  ('00000000-0000-4000-8000-000000003191', 'やらなければならない仕事が山のようにあるよ。とりあえず、お客さんから集金することから始めようかな。', 'I’ve got tons of work I have to catch up on. Anyway, maybe I should start collecting money from my clients.'),
  ('00000000-0000-4000-8000-000000003192', 'のどがかわいたので、何か飲みましょう。', 'I’m thirsty, so let’s drink something.'),
  ('00000000-0000-4000-8000-000000003192', 'この水道水は飲めますか？', 'Can you drink this tap-water?'),
  ('00000000-0000-4000-8000-000000003192', '「何をお飲みになりますか？ ジン、ウォッカ、ビール、ワイン、日本酒、それとも焼酎？  　何でもおっしゃってください。お酒なら何でも揃っていますから。」', 'What would you like to drink? Gin, vodka, beer, wine, sake, or shochu? You name it, we’ve got it, but only if it’s alcohol.'),
  ('00000000-0000-4000-8000-000000003193', '日本では工業が発たつしています。', 'Japan has an advanced industry.'),
  ('00000000-0000-4000-8000-000000003193', '工業デザイナーの中山さんは、ワニカニをストレス発さんに使っています。', 'The industrial designer, Mr. Nakayama, uses WaniKani for stress relief.'),
  ('00000000-0000-4000-8000-000000003193', '「工業技術プロジェクトの進み具合はどう？」「今のところは順調だよ。」', '"How is your industrial technology project going? " "So far, so good."'),
  ('00000000-0000-4000-8000-000000003194', 'わたしは漢字をかくのが下手です。', 'I’m bad at writing kanji.'),
  ('00000000-0000-4000-8000-000000003194', 'わたしの名前の漢字には、ウィスコンシン州でくらせますように、といういみが込められています。', 'The kanji for my name includes the meaning, "you may live in Wisconsin."'),
  ('00000000-0000-4000-8000-000000003194', '「これ、君への誕生日プレゼントだよ。」「わあ！漢字のテキストじゃない！どうもありがとう。あなたのおかげで本当に幸せな気分になったわ。」', '"Here is a gift for your birthday." "Wow! A Kanji textbook! Thank you so much. You really made my day."'),
  ('00000000-0000-4000-8000-000000003195', '大雪で、高速道路が通行止めになっているそうですよ。', 'Mereka mengatakan jalan raya ditutup karena salju lebat.'),
  ('00000000-0000-4000-8000-000000003195', 'ミネソタ州は夏に道路工事ばかりしています。', 'Begitu banyak jalan yang sedang dibangun di Minnesota selama musim panas.'),
  ('00000000-0000-4000-8000-000000003195', 'この町は本当につまらない。基本的に道路と家しかないし。あぁ〜もう！どこか楽しいところはないのかな？', 'Kota ini sungguh membosankan. Pada dasarnya hanya ada jalan beraspal dan rumah-rumah. Ugh! Di mana saya bisa mendapatkan tindakan?'),
  ('00000000-0000-4000-8000-000000003196', '大雨で、線路わきの土しゃがくずれ、線路が土しゃでうまってしまっているもよう。', 'Nampaknya tanah di samping rel kereta ambruk akibat hujan deras hingga menutupi rel.'),
  ('00000000-0000-4000-8000-000000003196', 'だれかが線路に立ち入ったため、電車が止まってしまった。', 'Kereta berhenti karena ada yang masuk tanpa izin di rel kereta.'),
  ('00000000-0000-4000-8000-000000003196', '「あぁ、ごめん。今はあんまりそういう気分じゃないんだ。」「あなた、どうしたの？」「実は、さっきそこの線路で男が飛び込み自殺をするのを目撃したんだ。」', '"Yah, maaf. Aku sedang tidak dalam mood seperti itu saat ini." “Sayang, apa yang terjadi?” “Yah, aku baru saja melihat seorang pria bunuh diri di rel kereta api di sana.”'),
  ('00000000-0000-4000-8000-000000003197', 'うちのお店は、ウェスタン通りから、少し路地に入ったところにあります。', 'Toko kami berada di gang tak jauh dari Western Street.'),
  ('00000000-0000-4000-8000-000000003197', 'その路地は、夜は少しきけんだから気を付けてね。', 'Jalan itu agak samar di malam hari, jadi berhati-hatilah.'),
  ('00000000-0000-4000-8000-000000003197', '警察官は、路地まで苺泥棒を追いかけた。', 'Polisi mengejar perampok yang mencuri stroberi di gang.'),
  ('00000000-0000-4000-8000-000000003199', 'え戸時代の農民でも、全てがまずしかったわけではないはずだ。', 'Hal ini tidak berarti semua petani pada zaman Edo miskin.'),
  ('00000000-0000-4000-8000-000000003199', 'この村の農民たちは、クロールの泳ぎ方を知りたがっている。', 'Para petani di desa ini ingin mengetahui cara berenang merangkak ke depan.'),
  ('00000000-0000-4000-8000-000000003199', 'おぉ！あの農民の腹筋すげぇな。', 'Wow! Petani itu memiliki perut yang luar biasa.'),
  ('00000000-0000-4000-8000-000000003200', 'わたしたちは、さく年、む人とうで農業を始めました。', 'Kami mulai bertani di pulau terpencil tahun lalu.'),
  ('00000000-0000-4000-8000-000000003200', '最近日本では、農業にきょうみのあるわか者がふえています。', 'Di Jepang, akhir-akhir ini terdapat lebih banyak generasi muda yang tertarik pada pertanian.'),
  ('00000000-0000-4000-8000-000000003200', '僕は今はセックスにあまり興味が無いんだよ。しばらくはただ農業に集中したいんだよね。', 'Saya tidak tertarik dengan seks saat ini. Saya hanya ingin fokus pada pertanian.'),
  ('00000000-0000-4000-8000-000000003201', '地下鉄に乗って行きます。', 'Saya akan naik kereta bawah tanah.'),
  ('00000000-0000-4000-8000-000000003201', '東京の地下鉄はかなりふくざつです。', 'Kereta bawah tanah Tokyo sangat kompleks.'),
  ('00000000-0000-4000-8000-000000003201', 'ああ、よかった！地下鉄に乗り遅れちゃうかと思ったよ。', 'Sungguh melegakan! Saya pikir saya ketinggalan kereta bawah tanah.'),
  ('00000000-0000-4000-8000-000000003202', 'うちの社長は、鉄人すぎます。', 'Presiden perusahaanku terlalu macho.'),
  ('00000000-0000-4000-8000-000000003202', 'わたしが一番すきな番組はりょうりの鉄人です。', 'Acara TV yang paling saya suka adalah Iron Chef.'),
  ('00000000-0000-4000-8000-000000003202', '私はスーパーで赤ちゃんに「いないいないばぁ」をしている鉄人を見た。', 'Saya melihat seorang pria tangguh bermain-main dengan bayi di toko kelontong.'),
  ('00000000-0000-4000-8000-000000003203', '東きゅう電鉄によりますと、東きゅう東よこ線は人身じこのえいきょうで、げんざい運転を見合わせています。', 'Menurut Tokyu Corporation, jalur Tokyu Toyoko saat ini telah menghentikan operasinya karena kecelakaan yang melibatkan cedera diri.'),
  ('00000000-0000-4000-8000-000000003203', '電鉄会社ではたらくのがゆめです。', 'Impian saya adalah bekerja di perusahaan kereta api listrik.'),
  ('00000000-0000-4000-8000-000000003203', '「はい、どうぞ。あなたが好きな阪急電鉄の写真よ。」「うわぁ！やったぁ！俺の大好きな阪急電鉄じゃん！」', '"Ini dia, sayang. Beberapa gambar Kereta Api Hankyu yang kamu suka." "Oh wow, saya sangat menyukai Kereta Hankyu!"'),
  ('00000000-0000-4000-8000-000000003204', 'でも、日本の歌はあまり知りません。', 'But I don’t know Japanese songs very well.'),
  ('00000000-0000-4000-8000-000000003204', 'これはたんなる歌じゃなく、ひみつのあん号でもあるんじゃないかという気がしています。', 'It feels like this isn''t just a song, but a secret code too.'),
  ('00000000-0000-4000-8000-000000003204', '「ジェイソン！あんた、アマンダのために歌を作ったの？」「えーと、これはそういうのじゃないんだ。」「もう！とぼけないでよ。」', '"Jason! You made a song for Amanda?" "Ah, this isn’t what it looks like." "Come on! Don’t give me that."'),
  ('00000000-0000-4000-8000-000000003205', '歌手になったのは、母のえいきょうが大きいです。', 'My mother had a large influence in my becoming a singer.'),
  ('00000000-0000-4000-8000-000000003205', 'あの歌手、かなり日やけしたね。', 'That singer got quite a tan, didn''t she?'),
  ('00000000-0000-4000-8000-000000003205', '子どもの頃は、歌手だったのよ。なんちゃってね。今でも歌手なんですけど。', 'I used to be a singer when I was kid. Well, who am I kidding, I’m still a singer now.'),
  ('00000000-0000-4000-8000-000000003206', '明日の算数のじゅぎょう、定ぎと分度きわすれずにね！', 'Jangan lupa penggaris dan busur derajat untuk pelajaran matematika besok.'),
  ('00000000-0000-4000-8000-000000003206', '立ち入ったことをお聞きしますが、よみ・かき・算数、どれが一番とくいですか？', 'Saya perlu menanyakan pertanyaan pribadi kepada Anda. Antara membaca, menulis, dan berhitung, manakah yang paling Anda kuasai?'),
  ('00000000-0000-4000-8000-000000003206', '「連絡するのに時間がかかっちゃってごめんなさい。最近、仕事で忙しかったものだから。」「君の仕事って何だっけ？」「小学校の算数の先生よ。」', '"Maaf, aku butuh waktu lama untuk menghubungimu kembali. Aku sedang sibuk dengan pekerjaan." "Apa pekerjaanmu tadi?" "Saya seorang guru matematika di sekolah dasar."'),
  ('00000000-0000-4000-8000-000000003207', '所とくぜいがくを算定するためのけいさんしきを知っていますか。', 'Tahukah Anda persamaan untuk menghitung pajak penghasilan Anda?'),
  ('00000000-0000-4000-8000-000000003207', 'ワニカニのユーザーのぞうげんを算定するAIをやといました。', 'Kami menyewa AI yang dapat menghitung penambahan dan pengurangan pengguna WaniKani.'),
  ('00000000-0000-4000-8000-000000003207', 'このプログラムは、該当ユーザーに選択されたバナー広告の掲示数に応じて、広告費用を算定するんだ。', 'Program ini menghitung biaya iklan sesuai dengan berapa kali iklan banner dipilih oleh pengguna.'),
  ('00000000-0000-4000-8000-000000003208', 'テキストを聞きます。', 'We are going to listen to the text.'),
  ('00000000-0000-4000-8000-000000003208', 'この日本語は分からないから先生に聞きましょう。', 'Let''s ask the teacher since we don''t understand this Japanese.'),
  ('00000000-0000-4000-8000-000000003208', 'ねえ、聞いて、エイミー。これはあなたのせいじゃないわ。だって、ケンカしたからって、他の人と寝ていい正当な理由にはならないでしょ。', 'Listen to me, Amy. This is not your fault. He is not justified in sleeping with someone else just because you two had a fight.'),
  ('00000000-0000-4000-8000-000000003209', '父は、毎朝新聞を読みます。', 'My father reads the newspaper every morning.'),
  ('00000000-0000-4000-8000-000000003209', '今朝の地元の新聞の一めんでトーフグとどーも君がコラボしていたよ。', 'Tofugu and Domo-kun were collaborating on the front page of the local newspaper this morning.'),
  ('00000000-0000-4000-8000-000000003209', 'この新聞すっげー専門用語だらけじゃん。スコットがこの新聞を何回も読まなきゃいけないのは当然だな。', 'This newspaper is so highbrow. No wonder Scott had to read it so many times.'),
  ('00000000-0000-4000-8000-000000003210', 'いいですか。英語じゃなくて日本語ですよ。', 'Okay? Not English, Japanese.'),
  ('00000000-0000-4000-8000-000000003210', '今ワニカニを買うと、もれなく日本語でかかれたトーフグのサインが付いてきますよ。', 'If you subscribe to WaniKani right now, it will come with Tofugu''s autograph in Japanese.'),
  ('00000000-0000-4000-8000-000000003210', '間違うことを恐れるなよ。日本語で喋ってみろって。やってみろよ。君ならできると思うよ。', 'Don’t be afraid of making mistakes. Speak in Japanese. Give it a shot. I think you can do it.'),
  ('00000000-0000-4000-8000-000000003211', 'わたしのむすめは、フランス語もえい語も話せます。', 'My daughter can speak both French and English.'),
  ('00000000-0000-4000-8000-000000003211', 'アフリカの多くの国では公用語にえい語とフランス語が使用されています。', 'In many African countries, both English and French are used as their official languages.'),
  ('00000000-0000-4000-8000-000000003211', 'フランス語の学習は僕には難しすぎるよ。もうたく山だ！勘弁してくれよ！', 'Learning French is too difficult! I can’t take it anymore. Give me a break!'),
  ('00000000-0000-4000-8000-000000003212', '明日はスペイン語の小テストだぜ！', 'There’s a Spanish quiz tomorrow!'),
  ('00000000-0000-4000-8000-000000003212', 'そのスペイン語のテキストは今売り切れているので、ご用いできません。', 'That Spanish textbook is currently sold out, so it''s not available.'),
  ('00000000-0000-4000-8000-000000003212', 'ニンニクはスペイン語で「ajo」っていうんだけど、「アホ」って発音されるんだよ。「アホ」は日本語で「stupid」って意味だよ。', 'Garlic in Spanish is "ajo," which is pronounced "aho." "Aho" means "stupid" in Japanese.'),
  ('00000000-0000-4000-8000-000000003214', '主語をハッキリさせてくれないかな。', 'Can you make the subject clear?'),
  ('00000000-0000-4000-8000-000000003214', 'この主語を明かくにする新サービスは、本当に役に立つ。', 'This new service that clarifies the subject is very useful.'),
  ('00000000-0000-4000-8000-000000003214', '日本語は、主語ー目的語ー動詞の言語ですが、英語は主語ー動詞ー目的語の言語です。', 'Japanese is a subject-object-verb language whereas English is a subject-verb-object language.'),
  ('00000000-0000-4000-8000-000000003215', '次の文を読んで、しつもんに答えてください。', 'Please read the following text and answer the questions.'),
  ('00000000-0000-4000-8000-000000003215', 'ビエトとコウイチのひみつの交かん日記を内しょで読んでしまいました。', 'I secretly read the hush-hush diary that is exchanged between Viet and Koichi.'),
  ('00000000-0000-4000-8000-000000003215', 'あんたの彼氏が書いた「旅の注意書き」読んだ？二、三本傘を持参するべきって書いてあるけど。', 'Did you read the note your boyfriend left you about your trip? It says that you should bring two or three umbrellas with you.'),
  ('00000000-0000-4000-8000-000000003216', '楽ふの読み方を知らない。', 'I can’t read sheet music.'),
  ('00000000-0000-4000-8000-000000003216', '三だんらく目の七行目のこのたん語の読み方は、なんですか？', 'How do you read this word in the 7th line of the 3rd paragraph?'),
  ('00000000-0000-4000-8000-000000003216', 'あなたの名前の漢字の読み方を教えてください。', 'Please tell me how to pronounce the kanji in your name.')
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES
  ('00000000-0000-4000-8000-000000003217', '子犬がワンワン鳴いています。', 'Anak anjing itu menggonggong.'),
  ('00000000-0000-4000-8000-000000003217', 'あそこでコケコッコーとおんどりが鳴くまねをしているのが、うちの社長です。', 'Orang yang menirukan ayam jago di sana adalah presiden kita.'),
  ('00000000-0000-4000-8000-000000003217', '今夜、あの新しい洒落た日本食レストランに行こうよ。知ってた？あそこには、ホーホケキョと美しい声で鳴く鶯も何羽かいるんだぜ。', 'Ayo pergi ke restoran Jepang baru yang keren malam ini. Tahukah Anda bahwa ada beberapa burung pengicau semak Jepang yang lucu bernyanyi dengan suara indah mereka?'),
  ('00000000-0000-4000-8000-000000003218', '分数をかく時にまん中に引く線の名前は、かつ線です。', 'Garis di tengah pecahan disebut “vinculum”.'),
  ('00000000-0000-4000-8000-000000003218', 'しぶ谷で山手線に乗ってください。', 'Silakan naik Jalur Yamanote di Shibuya.'),
  ('00000000-0000-4000-8000-000000003218', '本当にこの線が完璧だって思ったの？しかも、全然真っ直ぐじゃないじゃない！', 'Anda benar-benar berpikir baris ini sempurna? Itu bahkan tidak mendekati lurus!'),
  ('00000000-0000-4000-8000-000000003219', 'きっ茶店の横に、食どうがあります。', 'Ada restoran di sebelah kafe.'),
  ('00000000-0000-4000-8000-000000003219', 'もし強とうがトーフグのオフィスにやって来たら、コウイチのデスクまで走ってその横にしゃがみこむんだ。そこが最も安全な場所だからね。', 'Jika perampok masuk ke kantor Tofugu, lari saja ke meja Koichi dan berjongkok di sebelahnya karena itu tempat paling aman.'),
  ('00000000-0000-4000-8000-000000003219', '午後の仮眠の間に横向きに寝る。', 'Saat tidur siang, saya tidur miring.'),
  ('00000000-0000-4000-8000-000000003220', 'この調子でがんばるぞ！', 'Saya akan terus melakukan yang terbaik!'),
  ('00000000-0000-4000-8000-000000003220', '最近、トーフグの調子はどう？', 'Bagaimana kabar Tofugu akhir-akhir ini?'),
  ('00000000-0000-4000-8000-000000003220', 'あの男はみんなに調子のいいことばかり言うから嫌いよ。', 'Aku benci pria itu karena dia hanya mengatakan hal-hal yang menyanjung pendengarnya.'),
  ('00000000-0000-4000-8000-000000003221', 'トーフグの記事は超ドきゅうにおもしろくて役に立つことを強調しておきたい。', 'Saya ingin menekankan bahwa artikel Tofugu berkualitas super tinggi, menarik, dan bermanfaat.'),
  ('00000000-0000-4000-8000-000000003221', '大事な用語は、けい光ペンで強調するとおぼえやすいよ。', 'Menyorot kata-kata penting dengan stabilo membantu Anda menghafalnya.'),
  ('00000000-0000-4000-8000-000000003221', 'この仕事では身支度をきちんとしていることと礼儀正しいことが重要になることを改めて強調させて頂きます。', 'Saya hanya ingin menekankan lagi bahwa berpakaian rapi dan sopan sangat penting untuk pekerjaan ini.'),
  ('00000000-0000-4000-8000-000000003222', '今日の午後は、としょかんでせんそうについて調べました。', 'Sore ini, aku mencari informasi tentang perang di perpustakaan.'),
  ('00000000-0000-4000-8000-000000003222', 'けいさつがコウイチの車の中を調べると、中から酒によったフグが出てきました。', 'Ketika polisi menyelidiki bagian dalam mobil Koichi, seekor ikan buntal mabuk keluar.'),
  ('00000000-0000-4000-8000-000000003222', 'カピバラが食べられるのかどうか、ちょっと調べてくれない？', 'Bisakah Anda meneliti kapibara dan melihat apakah kapibara dapat dimakan?'),
  ('00000000-0000-4000-8000-000000003223', 'わたしの親は、先週病院の近くに引っこしました。', 'My parents moved near the hospital last week.'),
  ('00000000-0000-4000-8000-000000003223', 'うちの親、かほごすぎると思うんだよね。', 'I think my parents are overprotective.'),
  ('00000000-0000-4000-8000-000000003223', 'これって、すごく不公平だわ！ ミドリは私が欲しいものを全部手に入れて、その上私のパパとママが親じゃないなんて！', 'This is so unfair! Midori gets everything that I want. And, on top of that, she doesn’t have my mom and dad for parents.'),
  ('00000000-0000-4000-8000-000000003224', 'まだ親しい友人にしか話してないの。', 'I''ve only told this to close friends.'),
  ('00000000-0000-4000-8000-000000003224', '「親しき仲にも礼ぎあり」って言うでしょ？いくら親しいからってトイレはのぞかないで！', 'They say, "A hedge between keeps friendship green," right? We''re good friends, but don''t peek at me when I''m on the toilet.'),
  ('00000000-0000-4000-8000-000000003224', 'ちょっと、コウイチ。落ち着いてよ。 親しい友人たちに誰か80セント貸してあげれる人がいないか聞いてみてあげるから。', 'Oh Koichi. Calm down. I’ll ask my close friends if anyone can lend you the 80 cents.'),
  ('00000000-0000-4000-8000-000000003225', 'いつも親切にしていただいて、ありがとうございます。', 'Thank you for always being kind.'),
  ('00000000-0000-4000-8000-000000003225', 'トーフグのような親切な会社と出会ったのははじめてです。', 'I''ve never seen a company as kind as Tofugu.'),
  ('00000000-0000-4000-8000-000000003225', '今まで食べた中で一番のチーズケーキだわ。 あなたってとても親切だから、きっと最後の一切れは私にくれちゃうわよね？', 'Oh my gosh, this is the best cheesecake I have ever had. You''re so kind, so I''m sure you''ll give me the last piece, right? '),
  ('00000000-0000-4000-8000-000000003226', 'ま、親友には反対されたんですけどね。', 'Well, I was objected to by a close friend.'),
  ('00000000-0000-4000-8000-000000003226', 'コウイチとビエトは親友で、友だち以上、こい人未まんのかんけいです。', 'Koichi and Viet are good friends. They are more than friends, but not lovers.'),
  ('00000000-0000-4000-8000-000000003226', '「ねぇ、知ってる？サラがベスと付き合ってるのよ。」「え、知らなかった。サラのこと親友だと思ってたけど、私そのこと何も聞いてないわ。」', '"Hey, you know what? Sara is going out with Beth." "What? I didn’t know that. I thought she was my best friend but she never told me about that."'),
  ('00000000-0000-4000-8000-000000003227', '頭をあらってあげましょう。', 'Aku akan mencuci kepalamu.'),
  ('00000000-0000-4000-8000-000000003227', 'ひるねをすると、いつも頭がすっきりします。', 'Tidur siang biasanya menyegarkan pikiran saya.'),
  ('00000000-0000-4000-8000-000000003227', '頭が痛いので、喋らないでください。', 'Saya sakit kepala jadi tolong berhenti bicara.'),
  ('00000000-0000-4000-8000-000000003228', 'きのう会ったりょ行会社の人の顔をもうわすれました。', 'Saya sudah lupa wajah agen perjalanan yang saya temui kemarin.'),
  ('00000000-0000-4000-8000-000000003228', 'コウイチって、顔がこいよね？', 'Koichi memiliki fitur wajah yang sangat jelas, bukan begitu?'),
  ('00000000-0000-4000-8000-000000003228', '「おい、お前。何か文句でもあんのか？ジロジロ見てんじゃねぇぞコラ。」「えっと、あなたの顔、かなり青く見えるんですが、大丈夫ですか？」', '"Hei, sobat. Apakah kamu ingin bertengkar denganku? Kenapa kamu menatapku seperti itu?" "Wah, wajahmu terlihat sangat pucat. Apa kamu baik-baik saja?"'),
  ('00000000-0000-4000-8000-000000003229', 'このころのたえ子ちゃんは、まだ顔付きが子どもっぽいね。', 'Taeko masih terlihat seperti anak kecil saat itu.'),
  ('00000000-0000-4000-8000-000000003229', 'あのミニチュアハスキーは、とてもりりしい顔付きをしているね。', 'Miniatur Husky itu memiliki ekspresi wajah yang begitu gagah.'),
  ('00000000-0000-4000-8000-000000003229', 'うわぁ、すっかり大きくなったね！顔付きはお父さんそっくりそのままだ。', 'Wah, apakah kamu sudah dewasa, anak muda. Anda adalah gambaran meludah dari ayah Anda.'),
  ('00000000-0000-4000-8000-000000003230', '母の病気は、まだよくなりません。', 'My mother’s illness still hasn’t improved.'),
  ('00000000-0000-4000-8000-000000003230', 'おしりからおならが止まらない病気にかかってしまい、外に出られなくなってしまいました。', 'I got a disease that makes me fart all the time, so I''ve haven''t been able to go outside.'),
  ('00000000-0000-4000-8000-000000003230', '「先生、僕のママの病気、直せるの？」「やってみるけど、当てにしないでね。」', '"Can you fix my mom’s illness, doctor?" "I’ll give it a try, but don’t count on it."'),
  ('00000000-0000-4000-8000-000000003231', 'メニエール病をわずらっているので、よくめまいが起きるんです。', 'I suffer from Ménière’s disease, so I often get dizzy.'),
  ('00000000-0000-4000-8000-000000003231', 'ぼくがワニカニレベル1から全ぜん進めないのはきっと外国語できない病にかかったからにちがいない。', 'The reason I haven''t been able to get further than Level 1 on WaniKani must be because I have "can''t-learn-foreign-language" syndrome.'),
  ('00000000-0000-4000-8000-000000003231', '彼の言ったことを大袈裟に考えないで。難病で苦しんでるなんて明らかに嘘なんだから。', 'Don’t make a big deal out of what he said. It’s definitely a lie that he’s suffering from an incurable disease.'),
  ('00000000-0000-4000-8000-000000003232', 'うつったらいやだから、病人には近よりたくない。', 'If you don’t want to catch something, you shouldn’t go near sick people.'),
  ('00000000-0000-4000-8000-000000003232', 'うらないしに、前世は病人だったと言われました。', 'The fortuneteller told me that my previous life was as a sick person.'),
  ('00000000-0000-4000-8000-000000003232', '「調子はどうだい？」「絶好調だよ。」「それは良かった。病人からその言葉を聞けるとは思ってもみなかったがな。」', '"How’s it going?" "Couldn’t be better." "Good. I’m surprised to hear that from a sick person though."'),
  ('00000000-0000-4000-8000-000000003233', 'げしとは、一年で最も夜がみじかくなる日のことだ。', 'Titik balik matahari musim panas adalah malam terpendek dalam setahun.'),
  ('00000000-0000-4000-8000-000000003233', 'ふじ山は日本で最も高い山です。', 'Gunung Fuji adalah gunung tertinggi di Jepang.'),
  ('00000000-0000-4000-8000-000000003233', '彼、今日の夜何食べたか知ってる？焼き肉食べ放題に行ったんだよ。最も臭いおならに備えておいた方が身のためだよ。用心に越したことはないんだから。', 'Tahukah kamu apa yang dia makan malam ini? Dia pergi ke restoran yakiniku sepuasnya. Sebaiknya kita bersiap menghadapi kentut paling bau yang bisa dibayangkan. Lebih baik aman daripada menyesal.'),
  ('00000000-0000-4000-8000-000000003234', '仕事終わりのビールは最高だな。', 'Bir saat pekerjaan berakhir adalah yang terbaik.'),
  ('00000000-0000-4000-8000-000000003234', '東京わんの夜けいを見ながら最高の一時を楽しんでいます。', 'Saya menikmati momen terbaik, memandangi pemandangan malam Teluk Tokyo.'),
  ('00000000-0000-4000-8000-000000003234', '「うわ！あんたの作ったの、今までで最高のチョコレートケーキだわ。でも、一体どうしちゃったの？お菓子作りなんてしたことなかったじゃない。」「別に。何か新しいことをしてみたかっただけだよ。」', '"Wow, kamu membuat kue coklat paling enak. Tapi, apa yang merasukimu? Kamu belum pernah membuat kue sebelumnya." "Tidak ada, aku hanya ingin melakukan sesuatu yang baru."'),
  ('00000000-0000-4000-8000-000000003235', 'お前に金をやるのは、これが最後だ。', 'Ini terakhir kalinya aku memberimu uang.'),
  ('00000000-0000-4000-8000-000000003235', 'うちのつま、いつも最後に一言多いんですよね。', 'Istri saya selalu berakhir dengan satu kata yang terlalu banyak.'),
  ('00000000-0000-4000-8000-000000003235', 'とにかく、最後まで聞いてよ。そうすれば分かるから。', 'Bagaimanapun, dengarkan saja sampai akhir. Maka Anda akan mengerti.'),
  ('00000000-0000-4000-8000-000000003236', '女の人は、最近、どのぐらい本を読んでいますか。', 'Berapa banyak buku yang dia baca akhir-akhir ini?'),
  ('00000000-0000-4000-8000-000000003236', '最近のトレンドファッションにはもう付いていけません。', 'Saya tidak bisa lagi mengikuti tren fesyen terkini.'),
  ('00000000-0000-4000-8000-000000003236', '「ござる」という言葉は最近はあまり使われなくなったようだ。', 'Istilah "Gozaru" sepertinya tidak banyak digunakan belakangan ini.'),
  ('00000000-0000-4000-8000-000000003237', 'とうなんアジアを、四十二日かんりょこうしました。', 'I took a forty-two day trip around Southeast Asia.'),
  ('00000000-0000-4000-8000-000000003237', 'フランス人グルメは五月だけでさらうどんを四十二さらたべた。', 'The French gourmet had 42 plates of Sara udon in May only.'),
  ('00000000-0000-4000-8000-000000003237', 'そぼがトイレットペーパーを四十二ロールもかってきた。', 'My grandma bought forty-two rolls of toilet paper.'),
  ('00000000-0000-4000-8000-000000003402', '人口のはんぶんはだんせいです。', 'Half the population is male.'),
  ('00000000-0000-4000-8000-000000003402', 'このむらの人口はたったの二十三にんです。', 'This village''s population is only 23.'),
  ('00000000-0000-4000-8000-000000003402', 'じぶんのまちの人口をしらないにほんじんはおおい。', 'Many Japanese people don’t know the population of their own town.'),
  ('00000000-0000-4000-8000-000000003403', '白い子牛をかっているんです。', 'We have a white calf.'),
  ('00000000-0000-4000-8000-000000003403', 'この子牛は、とても元気です。', 'This calf is very energetic.'),
  ('00000000-0000-4000-8000-000000003403', 'お父さん！サンタ・クロースが昨夜子牛をくれたわ！', 'Daddy! Santa Claus gave me a calf last night!'),
  ('00000000-0000-4000-8000-000000003404', 'それから、ゆうびんきょくへいって、切手をかいます。', 'Then I’m going to go to the post office and buy stamps.'),
  ('00000000-0000-4000-8000-000000003404', 'あの外人さんは切手を一万まいもかっていったよ。', 'That foreigner bought 10,000 postage stamps.'),
  ('00000000-0000-4000-8000-000000003404', '彼女を失ってから、切手集めへの興味も失ってしまった。', 'Since I lost her, I''ve lost interest in stamp collecting.'),
  ('00000000-0000-4000-8000-000000003405', 'バスケのしあいは、引き分けでした。', 'Pertandingan bola basket itu seri.'),
  ('00000000-0000-4000-8000-000000003405', 'アメリカのベストピックアップトラックをきめるたたかいは、今のところトヨタとフォードの引き分けのじょうたいがつづいている。', 'Pertarungan untuk menentukan truk pickup terbaik di Amerika saat ini adalah hasil imbang antara Toyota dan Ford.'),
  ('00000000-0000-4000-8000-000000003405', '私は、じゃんけんが三対三の引き分けに終わったことにとても腹を立てた。', 'Saya sangat kesal karena permainan batu-gunting-kertas kami berakhir seri tiga arah.'),
  ('00000000-0000-4000-8000-000000003406', 'まつ本さんが、亡くなったそうです。', 'Saya mendengar bahwa Matsumoto meninggal.'),
  ('00000000-0000-4000-8000-000000003406', 'わたしの妹は、五才のときに、はいえんで亡くなりました。', 'Adik perempuan saya meninggal karena pneumonia ketika dia berusia lima tahun.'),
  ('00000000-0000-4000-8000-000000003406', 'もし母さんが亡くなったら、僕の料理を作ってくれる人がいなくなってしまう。', 'Jika ibuku meninggal, orang yang membuatkan makanan untukku juga akan tiada.'),
  ('00000000-0000-4000-8000-000000003407', '人生ってすばらしい。', 'Life is wonderful.'),
  ('00000000-0000-4000-8000-000000003407', '人生オワタ ＼(＾o＾)／　', 'My life is over. ＼(＾o＾)／　'),
  ('00000000-0000-4000-8000-000000003407', '人生はバナナのようなものさ。どれだけながいのかだれもしらないのさ。', 'Life is like a banana, you never know how long it will be.'),
  ('00000000-0000-4000-8000-000000003408', 'まえにいる男の子は、おか田さんの子どもです。', 'The boy in front of them is Okada’s child.'),
  ('00000000-0000-4000-8000-000000003408', 'おめでとうございます、お母さん。かわいい男の子ですよ。', 'Congratulation, mom. It''s a cute baby boy!'),
  ('00000000-0000-4000-8000-000000003408', 'あの男の子は元気が良すぎる。今さっきも叔母さんの頭に卵を二十個投げつけて、うまく逃げ切ったんだ。', 'That boy has so much energy. He just threw twenty eggs at his aunt’s head and managed to run away.'),
  ('00000000-0000-4000-8000-000000003409', 'キャベツに毛虫がついていました。', 'Ada ulat di kubis.'),
  ('00000000-0000-4000-8000-000000003409', '毛虫かと思ったら妹のつけまだった。', 'Kupikir itu ulat bulu, tapi ternyata itu bulu mata palsu adikku.'),
  ('00000000-0000-4000-8000-000000003409', '私は巨大な毛虫と巨大なムカデが戦っているところをビデオに収めた。', 'Saya merekam ulat raksasa melawan kelabang raksasa.'),
  ('00000000-0000-4000-8000-000000003410', 'わたしは、下町でそだちました。', 'I grew up downtown.'),
  ('00000000-0000-4000-8000-000000003410', 'とうきょうの下町にあるむかしながらのさかばに行ってみたいです。', 'I''d like to go to a good old fashioned saloon in the backstreet areas of the old cities of Tokyo.'),
  ('00000000-0000-4000-8000-000000003410', '下町とは、日本の古いスタイルのダウンタウンのことで、現代のものとは異なっている。', 'A shitamachi is an old Japanese style of downtown; it isn’t the same as the downtown we think of today.'),
  ('00000000-0000-4000-8000-000000003411', 'どうやって小文字と大文字を切りかえますか。', 'How do you switch from lowercase to uppercase?'),
  ('00000000-0000-4000-8000-000000003411', 'パスワードには、かならず大文字、小文字、すう字を一つい上つかってください。', 'Passwords must contain at least one uppercase letter, one lowercase letter and a number.'),
  ('00000000-0000-4000-8000-000000003411', '君のEメールアドレスって、全部小文字なの？本当に？ちょっとおかしいんじゃないの？', 'Is your email address in all lowercase letters? Is it really? Are you crazy?'),
  ('00000000-0000-4000-8000-000000003412', 'ああ！この男の人が、すず木さんですか。', 'Ah! Is that guy Suzuki?'),
  ('00000000-0000-4000-8000-000000003412', 'あそこに立っている外人の男の人のとなりにいる女の人があのゆう名なまつい一代さんです。', 'The lady next to the foreign guy standing over there is THE famous Kazuyo Matsui.'),
  ('00000000-0000-4000-8000-000000003412', '背の高い男の人はTシャツを着ていて、背の低い男の人はセーターを着ています。', 'The tall guy is wearing a T-shirt and the short guy is wearing a sweater.'),
  ('00000000-0000-4000-8000-000000003413', 'どうぞよいお年をおむかえください。', 'I hope you have a happy New Year!'),
  ('00000000-0000-4000-8000-000000003413', '今年もぶじに年をとりました。', 'Once again, I was able to age this year without issue.'),
  ('00000000-0000-4000-8000-000000003413', 'あくる年、エリカは白い牛に乗った王子様に出会いました。', 'The next year, Erika met a prince riding a white cow.'),
  ('00000000-0000-4000-8000-000000003414', '今まで何をしていたんですか。', 'What have you been doing until now?'),
  ('00000000-0000-4000-8000-000000003414', 'コウイチが今まで付きあったかの女は百万人に上るが、ようやく一人の女の人におちつきつつある。', 'Koichi had a million girlfriends up until now, but he is finally about to settle down with one woman.'),
  ('00000000-0000-4000-8000-000000003414', 'お前が今までの中では一番の彼女だよ。', 'You are the best girlfriend I’ve had so far.'),
  ('00000000-0000-4000-8000-000000003415', '冬休みに、かぞくで山の中のホテルにとまりました。', 'During winter break my family stayed in a hotel in the mountains.'),
  ('00000000-0000-4000-8000-000000003415', '冬休みは子どもたちがいえで兄弟げんかばっかりしていて大へんでした。', 'Winter holiday was pretty tough because my sons fight so often at home.'),
  ('00000000-0000-4000-8000-000000003415', '冬休みは、毎日一日中ジョギングをしていました。', 'During winter vacation, I jogged everyday, all day long.'),
  ('00000000-0000-4000-8000-000000003416', 'みどり色の毛糸はありますか。', 'Apakah Anda memiliki benang hijau?'),
  ('00000000-0000-4000-8000-000000003416', '今日はとてもさむいので、友人があんでくれた毛糸のセーターをきています。', 'Hari ini sangat dingin, jadi saya mengenakan sweter wol yang dirajut oleh teman saya untuk saya.'),
  ('00000000-0000-4000-8000-000000003416', '「毛糸の玉をほどいてください。お願いします。お願いします。」と、その幽霊は何度も私に頼んできた。', '"Tolong lepaskan gulungan benangnya. Tolong. Tolong!" hantu itu bertanya padaku berulang kali.'),
  ('00000000-0000-4000-8000-000000003417', '今すぐ、会いに行きましょう。', 'Let''s go meet them right away.'),
  ('00000000-0000-4000-8000-000000003417', 'いいから黙って今すぐ来い!', 'Be quiet and come over at once!'),
  ('00000000-0000-4000-8000-000000003417', '花火は今すぐにでもスタートするよ。', 'The fireworks will start any minute now.'),
  ('00000000-0000-4000-8000-000000003418', 'やっとJLPTN1にごうかくすることが出来ました。', 'I was finally able to pass JLPT N1.'),
  ('00000000-0000-4000-8000-000000003418', 'ディナーが出来たよ。', 'Dinner''s ready!'),
  ('00000000-0000-4000-8000-000000003418', 'もちは米から出来る。', 'Mochi are made from rice.'),
  ('00000000-0000-4000-8000-000000003419', '方言のじしょを作っています。', 'I’m making a dialect dictionary.'),
  ('00000000-0000-4000-8000-000000003419', 'ああっもうっ！かれしの方言がうつっちゃってるずら。', 'Damn! My boyfriend''s dialect has rubbed off on me.'),
  ('00000000-0000-4000-8000-000000003419', '私の国の東側出身の人達は変わった方言で喋るので、彼らが何を言っているのか全く分かりません。', 'People from the eastern part of my country use such an odd dialect that they are impossible to understand.'),
  ('00000000-0000-4000-8000-000000003420', 'たん生日プレゼントに、人形をもって行きます。', 'Aku akan membawakan boneka untuk hadiah ulang tahunnya.'),
  ('00000000-0000-4000-8000-000000003420', 'その人形、ちゃんと元のところにもどしておいてね。', 'Kembalikan boneka itu ke tempat Anda menemukannya.'),
  ('00000000-0000-4000-8000-000000003420', '17歳まで、私の親友は靴下で作った腕人形だった。', 'Sampai umur 17 tahun, sahabatku adalah boneka kaus kaki.'),
  ('00000000-0000-4000-8000-000000003421', 'げんざいの中国語では、たくさんの日本語が外来語として使われています。', 'Many Japanese words are used as loanwords in modern day Chinese.'),
  ('00000000-0000-4000-8000-000000003421', 'リュックサックは、外来語ですか？それとも和せいえい語ですか？', 'Is rucksack a foreign word, or Engrish?'),
  ('00000000-0000-4000-8000-000000003421', 'ねえ、煙草って外来語なのに漢字があるって知ってた？', 'Hey, did you know that there''s kanji for the word tobacco even though it’s a loanword?'),
  ('00000000-0000-4000-8000-000000003422', 'このテーブルは、林さんの手作りです。', 'This table was handmade by Hayashi.'),
  ('00000000-0000-4000-8000-000000003422', '毎日手作りのバランスのいい食じをとるようにしています。', 'I try to have a homemade, well-balanced diet every day.'),
  ('00000000-0000-4000-8000-000000003422', '手作りのプレゼントは、どれだけ暇な時間があるかってことがバレてしまうので、結構怖い。', 'Handmade presents are pretty scary because they reveal that you have too much free time.'),
  ('00000000-0000-4000-8000-000000003423', '東京えきから中川えきまででんしゃで行って、中川えきからみかん山までバスで行きます。', 'We will take a train from Tokyo station to Nakagawa station, and then we will take a bus from Nakagawa station to Mikan mountain.'),
  ('00000000-0000-4000-8000-000000003423', '今から東京に行かなくてはいけないので、そろそろお会けいおねがいします。', 'I have to go to Tokyo now, so may I have the bill, please?'),
  ('00000000-0000-4000-8000-000000003423', '東京についてすぐに、マクドナルドに行った。', 'As soon as I arrived in Tokyo, I went to McDonald’s.'),
  ('00000000-0000-4000-8000-000000003425', '外では、つめたい風がふいていました。', 'Cold winds were blowing outside.'),
  ('00000000-0000-4000-8000-000000003425', '風が強くなってきましたね。', 'The wind is picking up, isn''t it?'),
  ('00000000-0000-4000-8000-000000003425', '風が彼女のカツラを吹き飛ばした時に、私は自分が坊主の女性にとても魅力を感じることに気が付きました。', 'When the wind blew the wig off of her head, I realized that I’m really attracted to bald women.'),
  ('00000000-0000-4000-8000-000000003426', '「リキュール」には、「利休酒」という当て字が使われます。', '"利休酒" adalah kanji fonetik yang digunakan untuk "minuman keras".'),
  ('00000000-0000-4000-8000-000000003426', '近ごろは、当て字を使ったキラキラネームを持つ子どもがたくさんいます。', 'Akhir-akhir ini banyak sekali anak-anak dengan nama aneh yang menggunakan kanji fonetik.'),
  ('00000000-0000-4000-8000-000000003426', '時々、漢字は、亜米利加 (アメリカ)のようにそれぞれの意味を無視して、読み方だけで選ばれます。これらの漢字を当て字と言います。', 'Terkadang kanji dipilih hanya karena bunyinya dan artinya diabaikan seperti dalam 亜米利加 (アメリカ). Ini disebut kanji fonetik.'),
  ('00000000-0000-4000-8000-000000003427', 'しんじられないような出来ごとが次々とおこったんです。', 'Peristiwa yang tampaknya sulit dipercaya terjadi satu demi satu.'),
  ('00000000-0000-4000-8000-000000003427', 'コウイチかんとくは、さく夜、Youtubeで次々とヒット作を生み出すゆめを見ました。', 'Tadi malam, Sutradara Koichi bermimpi bahwa dia membuat YouTube menjadi hit demi hit.'),
  ('00000000-0000-4000-8000-000000003427', 'ヨーロッパの街は、次々と疫病に侵されていった。', 'Satu demi satu, kota-kota di Eropa dilanda wabah penyakit.'),
  ('00000000-0000-4000-8000-000000003428', '向こうのパンやで、パンを買いましょう。', 'Ayo beli roti di toko roti sebelah sana.'),
  ('00000000-0000-4000-8000-000000003428', '一花は、向こうの世界からやって来たのかもしれない。', 'Ichika mungkin datang dari belahan dunia lain.'),
  ('00000000-0000-4000-8000-000000003428', 'もし君が道路の向こう側に立つのであれば、私の秘密を君に打ち明けるよ。', 'Aku akan memberitahumu rahasiaku jika kamu berdiri di seberang jalan.'),
  ('00000000-0000-4000-8000-000000003429', '三つ目のしんごうを、右に曲がってください。', 'Silakan belok kanan pada lampu ketiga.'),
  ('00000000-0000-4000-8000-000000003429', 'そのカレー色のネクタイ、ちょっと曲がってるよ。', 'Dasi berwarna kari Anda agak bengkok.'),
  ('00000000-0000-4000-8000-000000003429', '野球のボールが当たってから、僕の小指はちょっとだけ左に曲がっています。', 'Sejak dipukul dengan bola baseball, jari kelingkingku sedikit menekuk ke kiri.'),
  ('00000000-0000-4000-8000-000000003430', '学生時代に、バックパッカーとして南米をりょ行しました。', 'Di masa sekolah saya, saya melakukan perjalanan backpacking ke Amerika Selatan.'),
  ('00000000-0000-4000-8000-000000003430', 'このホテルの水道水は、南米で今までのんだ水の中で一番おいしい。', 'Air keran hotel ini adalah air terbaik yang pernah saya miliki di Amerika Selatan.'),
  ('00000000-0000-4000-8000-000000003430', 'ごめんなさい。南米はアメリカの一部だと思っていました。', 'Saya minta maaf. Saya pikir Amerika Selatan adalah bagian dari Amerika Serikat.'),
  ('00000000-0000-4000-8000-000000003431', 'これは、全米がなみだした、大ヒットチョ～大作えいがです。', 'Ini adalah blockbuster mega-hit yang membuat seluruh Amerika menangis.'),
  ('00000000-0000-4000-8000-000000003431', 'まつ山ひできは、2017年の全米オープンで二いに入った。', 'Hideki Matsuyama finis kedua di AS Terbuka 2017.'),
  ('00000000-0000-4000-8000-000000003431', '全米ヒットチャートで今一位の曲は何ですか？', 'Apa lagu No. 1 di tangga lagu AS saat ini?'),
  ('00000000-0000-4000-8000-000000003432', 'そこに行くなら、南口から出るのが一番近いです。', 'If you’re going there, leaving from the south exit is the fastest.'),
  ('00000000-0000-4000-8000-000000003432', 'このモールの南口で今UFOが見られるよ！', 'You can see a UFO at the southern entrance of this mall right now!'),
  ('00000000-0000-4000-8000-000000003432', '新宿南口でナンパされた。', 'I was hit on at the south exit of Shinjuku station.'),
  ('00000000-0000-4000-8000-000000003433', '思い出って、むねにそっとしまっておくものなんじゃないの？', 'Aren’t memories things you lock safely away in your chest?'),
  ('00000000-0000-4000-8000-000000003433', '子どものころ、日がくれるまで友だちとあそんでいたことは、今となってはとてもなつかしいいい思い出です。今はもうかん全ボッチですからね。', 'I used to play with my friends until it got dark. It''s a really great, nostalgic memory now especially because I don''t have any friends anymore.'),
  ('00000000-0000-4000-8000-000000003433', '私のお父さんが毎週日曜日の朝にチョコレートでコーティングされたベーコンを作ってくれたのは、とてもいい思い出です。', 'My dad making chocolate covered bacon for us every Sunday morning is such a good memory of mine.'),
  ('00000000-0000-4000-8000-000000003434', 'カメラマンが近づくとカメはにげてしまった。', 'When the cameraman approached it, the turtle ran away.'),
  ('00000000-0000-4000-8000-000000003434', 'おれの女に近づくな！', 'Don''t go anywhere near my girlfriend!'),
  ('00000000-0000-4000-8000-000000003434', '私達に今近づいてきているゾンビ、めちゃくちゃ私のタイプなんだけど。', 'Strange as it is, the zombie approaching us right now is actually my type.'),
  ('00000000-0000-4000-8000-000000003435', 'わたしは、家を出る時、いつも家の前でひかれた子犬のことを思い出します。', 'When I leave home, I always remember my puppy that got run over in front of the house.'),
  ('00000000-0000-4000-8000-000000003435', '四けたのあんしょう番号が思い出せなくて、めっちゃあせったよ。', 'I was so panicked because I couldn''t recall my 4 digit PIN code.'),
  ('00000000-0000-4000-8000-000000003435', '人に思い出してもらう一番の方法は、その人たちからお金を借りることだ。', 'The best way to make somebody remember you is to borrow money from them.'),
  ('00000000-0000-4000-8000-000000003436', '男の大学生と女の大学生がはなしています。', 'A male university student and a female university student are talking.'),
  ('00000000-0000-4000-8000-000000003436', 'あの大学生の女せいは、ダイエット中です。', 'That college girl is on a diet.'),
  ('00000000-0000-4000-8000-000000003436', 'マカロニチーズしか食べていないっていうのに、いったいどうして大学生は一日中勉強して夜中中お酒を飲む元気があるっていうんだ？', 'How do university students have the energy to study all day and drink all night when all they eat is macaroni and cheese?'),
  ('00000000-0000-4000-8000-000000003437', 'そうは言っても、言い方ってもんがあるだろ！', 'That makes sense, but you should think about the way you say things!'),
  ('00000000-0000-4000-8000-000000003437', 'そうだ、話はかわるんだけど、コウイチのネコって言ばの言い方、めっちゃかわいくない？', 'Oh, sorry for changing the subject, but don''t you think the way Koichi says the word cat is so cute?'),
  ('00000000-0000-4000-8000-000000003437', 'あなたの物の言い方はとても馬鹿です。', 'Your way of saying that is so stupid.'),
  ('00000000-0000-4000-8000-000000003438', '先回りして、まちぶせしよう！', 'Ayo maju dan serang mereka!'),
  ('00000000-0000-4000-8000-000000003438', 'リクはとてもせっかちで、いつも人の話をかっ手によそうして先回りして話すから、すごくイライラするんだよね。', 'Riku sangat tidak sabar, dan selalu berusaha mengantisipasi apa yang akan kukatakan sebelum aku mengatakannya, dan itu sangat menggangguku.'),
  ('00000000-0000-4000-8000-000000003438', '彼は先回りをして富士山の頂上に着いており、私のことをのろまと笑った。', 'Dia mengalahkan saya sampai ke puncak Gunung Fuji dan kemudian menertawakan saya karena lambat.'),
  ('00000000-0000-4000-8000-000000003439', 'わたしの兄は、とても早口です。', 'My older brother is a really fast talker.'),
  ('00000000-0000-4000-8000-000000003439', 'お前のことが一ばん大すきだよって、何でそんなに早口で言ったの？', 'Why did you say that you love me the most so quickly?'),
  ('00000000-0000-4000-8000-000000003439', 'こんなに早口の赤ん坊なんて見たことないよ。', 'I’ve never seen such a fast talking baby before.'),
  ('00000000-0000-4000-8000-000000003440', 'お金が十円足りないんです。', 'I’m ten yen short.'),
  ('00000000-0000-4000-8000-000000003440', 'もしスペースが足りなければ、べつの用しについきして、それをてんぷしてください。', 'If there is insufficient space, attach a separate sheet with additional information.'),
  ('00000000-0000-4000-8000-000000003440', 'ビル・ゲイツは私の息子なのだが、それを証明するための証拠がまだ足りない。', 'Bill Gates is my son, but there isn’t enough evidence to prove it yet.'),
  ('00000000-0000-4000-8000-000000003441', '年上の人と、デートするのははじめてです。', 'This is my first date with an older person.'),
  ('00000000-0000-4000-8000-000000003441', '人生はよそく不かのうだ。お前が年上のび人とけっこんするかのうせいだってゼロパーセントではない。', 'Life is unpredictable. It''s not a zero percent chance that you will get married with a beautiful older woman.'),
  ('00000000-0000-4000-8000-000000003441', 'お父さんが、お母さんのお母さんはピラミッドよりも年上だと言うんだよ。', 'My dad says that my mom’s mom is older than the pyramids.'),
  ('00000000-0000-4000-8000-000000003442', 'この世の中には、色んな人がいます。', 'There are many types of people in the world.'),
  ('00000000-0000-4000-8000-000000003442', '世の中には、しんじつを知らない方がいいことだってあるんだよ。', 'In this society, not knowing the truth is sometimes better.'),
  ('00000000-0000-4000-8000-000000003442', '我々は、警察よりも先にピザが家に到着するような素晴らしい世の中に住んでいる。', 'We live in a great society where pizza gets to your house before the police.'),
  ('00000000-0000-4000-8000-000000003443', '代わりの先生をさがしています。', 'We’re looking for a substitute teacher.'),
  ('00000000-0000-4000-8000-000000003443', 'この世のどこにも、かれの代わりはいないんです。', 'There is no replacement for him anywhere in the world.'),
  ('00000000-0000-4000-8000-000000003443', '日本語を教わる代わりに、英語を教えることができますよ。', 'I can teach you English and in exchange you can teach me Japanese.'),
  ('00000000-0000-4000-8000-000000003444', '山下さんのかぞくは、今年の冬休みはどこに行きますか？', 'Where is your family going to go on winter vacation this year, Yamashita?'),
  ('00000000-0000-4000-8000-000000003444', 'おきなわのせい人しきは今年も大あれだった。', 'The coming-of-age ceremony in Okinawa went wild again this year.'),
  ('00000000-0000-4000-8000-000000003444', 'ようやく今年の年を2013年と書くことを覚えたところで、年が2014年に変わった。', 'As soon as I got used to writing 2013 as the date for this year, 2014 arrived.'),
  ('00000000-0000-4000-8000-000000003445', 'かんとくは、ピッチャーを代えるだろう。', 'The coach is replacing the pitcher, I think.'),
  ('00000000-0000-4000-8000-000000003445', 'ふだんは、ヨーグルトをサワークリームに代えてつかっています。', 'I usually substitute yogurt for sour cream.'),
  ('00000000-0000-4000-8000-000000003445', 'この指輪をお金に代えることはできません。', 'I can’t exchange this ring for money.'),
  ('00000000-0000-4000-8000-000000003446', 'もり田さんには、年下のかの女がいます。', 'Morita has a younger girlfriend.'),
  ('00000000-0000-4000-8000-000000003446', 'コウイチはアーノルドシュワルツネッガーより三十八才年下だ。', 'Koichi is 38 years younger than Arnold Schwarzenegger.'),
  ('00000000-0000-4000-8000-000000003446', 'あの子は年下なのにとても大人びている。', 'Even though that kid is younger, he’s really mature.'),
  ('00000000-0000-4000-8000-000000003447', 'それについては、近々はっぴょうがあると思いますよ。', 'I think there will be an announcement about it soon.'),
  ('00000000-0000-4000-8000-000000003447', '近々雪がふるはずなので、たくさんつもったらかまくらを作ります。', 'We''re supposed to get snow soon, so if we get a lot, I will make a snow igloo.'),
  ('00000000-0000-4000-8000-000000003447', 'もしタバコを吸い続けるなら、あなたは近々癌を発症するでしょう。', 'You’ll get cancer before long if you keep smoking.'),
  ('00000000-0000-4000-8000-000000003448', '青空のせいで海は青いの？', 'Is the ocean blue because of the blue sky?'),
  ('00000000-0000-4000-8000-000000003448', '未来の子どもたちに、今と同じくらいうつくしい青空をのこしてあげましょうよ。', 'Let our future generations have the same beautiful sky as we do.')
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES
  ('00000000-0000-4000-8000-000000003448', '今日は一日中晴れて、青空が広がっていました。', 'Today, it was sunny all day and the blue sky was above us.'),
  ('00000000-0000-4000-8000-000000003449', '小学生だからって、あまく見てるとけがするぜ！', 'I may just be an elementary school student, but if you underestimate me, you''ll regret it!'),
  ('00000000-0000-4000-8000-000000003449', 'きょうしつのドアをあけると、一人の小学生が石ころみたいにぐっすりねむっていました。', 'When I opened the classroom door, there was a grade schooler sleeping like a rock.'),
  ('00000000-0000-4000-8000-000000003449', '小学生の頃、いつもコインを投げて自分の行動を決めていました。', 'When I was an elementary school student, I always made my decisions by flipping a coin.'),
  ('00000000-0000-4000-8000-000000003450', 'おいしいマカロニチーズの作り方を教えてください。', 'Please teach me how to make delicious macaroni and cheese.'),
  ('00000000-0000-4000-8000-000000003450', '麦茶の作り方には、おゆでわかしながらに出す方ほう、ふっとうさせたおゆでジワジワおゆ出しする方ほう、つめたい水でジワジワ水出しする方ほうの三しゅるいありますが、それぞれメリットデメリットがあります。', 'There are three ways to make barley tea; steeping it in boiling water, steeping it slowly in boiled water, and steeping it slowly in cold water, and each comes with pros and cons.'),
  ('00000000-0000-4000-8000-000000003450', '手裏剣の作り方を知りたいですか？', 'Do you want to know how to make a ninja star?'),
  ('00000000-0000-4000-8000-000000003451', '中学生にもなって、まだお母さんといっしょにおふろに入ってるんですか？', 'You are a middle schooler now, but you''re still taking baths with your mom?'),
  ('00000000-0000-4000-8000-000000003451', 'かち目のないたたかいはしない方がいいということは、中学生でも知っているよ。', 'Even a junior high student knows that you should choose your battles wisely.'),
  ('00000000-0000-4000-8000-000000003451', '中学生の頃、自分自身に、「書かなくても覚えられるから大丈夫」という大法螺をふいてしまいました。', 'When I was a middle school student, the biggest lie I said to myself was, "I can remember that without writing it down."'),
  ('00000000-0000-4000-8000-000000003452', '今年、もっとも不人気だったアニメは何だと思いますか。', 'What do you think is the most unpopular anime this year?'),
  ('00000000-0000-4000-8000-000000003452', 'コウイチたいマイケルのすもうのし合は、Youtubeで見るとはく力に欠けるので不人気です。', 'The Koichi vs Michael sumo match is unpopular because it lacks the intensity when you watch it on YouTube.'),
  ('00000000-0000-4000-8000-000000003452', '「お前の母ちゃんに言ってやる」が口癖だったため、彼はクラスメートに不人気だった。', 'He was unpopular among his classmates because his favorite phrase was, "I’m gonna tell your mom."'),
  ('00000000-0000-4000-8000-000000003453', 'もう一ど、けいかくを見直しましょう。', 'Mari kita lihat rencananya sekali lagi.'),
  ('00000000-0000-4000-8000-000000003453', 'この間のはいひん回しゅうの日、主人が思ったよりたよりになって、ちょっと見直しちゃった。', 'Pada hari terakhir pembuangan sampah, suami saya jauh lebih bisa diandalkan daripada yang saya harapkan dan itu membuat saya memandangnya secara berbeda.'),
  ('00000000-0000-4000-8000-000000003453', '大学の授業の選択を見直す方がいいと思うよ。だって、愚鳩を捕まえるのが、いいキャリアになるとは思えないもん。', 'Saya pikir Anda harus mengevaluasi kembali pilihan Anda di kelas universitas. Menurut saya, menangkap burung dodo bukanlah jalur karier yang baik.'),
  ('00000000-0000-4000-8000-000000003454', 'これじゃあ、全く話にならないよ。', 'Jika kamu akan menjadi seperti ini, maka aku tidak bisa menganggapnya serius.'),
  ('00000000-0000-4000-8000-000000003454', 'コウイチは、全く見かえりをもとめずに人助けをします。', 'Koichi tidak pernah meminta imbalan apa pun ketika dia membantu orang.'),
  ('00000000-0000-4000-8000-000000003454', 'コンドームも全く安全だって訳はない。俺の友達はゴムを着けてたけど、軽トラにはねられたしな。', 'Kondom tidak sepenuhnya aman. Teman saya memakainya dan tertabrak truk pickup.'),
  ('00000000-0000-4000-8000-000000003455', 'おかしいなー、ちゃんと長さをはかったつもりなんだけどなー。', 'Weird, I was sure I measured the length properly.'),
  ('00000000-0000-4000-8000-000000003455', 'こちらのヘビは3センチたんいの長さで切り売りはん売しています。', 'This snake is sold in three centimeter long pieces.'),
  ('00000000-0000-4000-8000-000000003455', '僕がよろめいてしまった主な原因は橋の長さです。僕にはちょっと長すぎました。', 'The length of the bridge was one of the main reasons why I faltered. It was just too long for me.'),
  ('00000000-0000-4000-8000-000000003457', 'そういえば、この前、しょうてんがいでさくら子ちゃんとバッタリ会ったよ。', 'That reminds me, last time I was at the shopping district I ran into Sakurako.'),
  ('00000000-0000-4000-8000-000000003457', 'この前、日本ごの曲のCDを買ったんだよね。', 'I recently bought a Japanese music CD.'),
  ('00000000-0000-4000-8000-000000003457', 'この前に赤色の花を置くのはどう？', 'What about putting red flowers in front of this?'),
  ('00000000-0000-4000-8000-000000003458', 'えきの東口で大道げいをしている人がいたよ。', 'There’s someone doing a street performance at the station’s east exit.'),
  ('00000000-0000-4000-8000-000000003458', '東口でとった写しん、たぶん手ブレしたみたいで、ちょっとブレちゃってる。', 'The photo taken at the east gate is a bit blurry, probably from the camera shaking.'),
  ('00000000-0000-4000-8000-000000003458', '緊急の際には、このビルの東口から避難してください。そこでは、コーヒーとドーナツが支給される予定です。', 'In the case of an emergency, please evacuate the building through the east exit. There will be coffee and donuts waiting for you there.'),
  ('00000000-0000-4000-8000-000000003459', 'あのう、お知らせしたいことがあるんですが、今、いいですか？', 'Excuse me, I have something that I’d like to tell you - do you have some time now?'),
  ('00000000-0000-4000-8000-000000003459', '学校からのお知らせはもうよみましたか？', 'Did you read the notice from the school already?'),
  ('00000000-0000-4000-8000-000000003459', '残念なお知らせがあります。昨夜誰かがこの家に侵入し、冷凍庫に入っていたアイスクリームを全部盗んでしまいました。', 'I have some bad news. Someone broke into our home last night and stole all the ice cream we had stored in our freezer.'),
  ('00000000-0000-4000-8000-000000003460', 'あの人の名前は何ですか。', 'What is that person’s name?'),
  ('00000000-0000-4000-8000-000000003460', '名前はきいたことがあるけど、あまりよく知らないかな。', 'I''ve heard the name, but I don''t know much about it.'),
  ('00000000-0000-4000-8000-000000003460', '私は名前を「ああ」に、名字を「そうそう」に変えたい。', 'I want to change my first name to "Ah" and my last name to "Soso."'),
  ('00000000-0000-4000-8000-000000003461', 'おいしいカレーが出来上がりました。', 'The delicious curry was finished.'),
  ('00000000-0000-4000-8000-000000003461', '日本りょ行のけいかくは、ギリギリになってようやく出来上がりました。', 'Our Japan travel plans were finished at the last minute.'),
  ('00000000-0000-4000-8000-000000003461', '豆腐と河豚のハンバーガーが出来上がりました。', 'The tofu and fugu hamburgers are done!'),
  ('00000000-0000-4000-8000-000000003462', '次は、右足のひざを90ど曲げてください。', 'Selanjutnya silahkan tekuk lutut kanan dengan sudut 90 derajat.'),
  ('00000000-0000-4000-8000-000000003462', 'このYoutubeビデオでは、コウイチがスプーンを百本ひたすら曲げつづけます。', 'Dalam video Youtube ini, Koichi hanya terus membengkokkan 100 sendok.'),
  ('00000000-0000-4000-8000-000000003462', 'スーパーマンはなんでも曲げられます。すでに曲がっているものでさえも。', 'Superman bisa membengkokkan apapun, bahkan sesuatu yang sudah bengkok.'),
  ('00000000-0000-4000-8000-000000003463', '空と海が交じるところが、世かいのはてなのさ。', 'Tempat bertemunya langit dan laut adalah ujung dunia.'),
  ('00000000-0000-4000-8000-000000003463', 'きたいと不安が交じった気もちです。', 'Kecemasanku bercampur dengan kegembiraan.'),
  ('00000000-0000-4000-8000-000000003463', 'わたしのさいふをすった後、そのスリはす早く人ごみに交じってきえました。', 'Setelah merampas dompet saya, pencopet itu dengan cepat berbaur dengan kerumunan dan menghilang.'),
  ('00000000-0000-4000-8000-000000003464', 'ニッカはいつもオフィス内を走り回っています。', 'Nikka selalu berlarian di kantor.'),
  ('00000000-0000-4000-8000-000000003464', 'うちの子なら、あの交通じこからもうすっかり立ち直って、元気に走り回っていますよ。', 'Anak saya benar-benar pulih dari kecelakaan lalu lintas dan sekarang dia bisa berlari, penuh energi.'),
  ('00000000-0000-4000-8000-000000003464', 'コウイチが蜂の巣を撃った後、蜂から逃げるために約十分間走り回った。', 'Setelah Koichi menembak sarang lebah, kami berlari selama hampir sepuluh menit mencoba melarikan diri dari semua lebah.'),
  ('00000000-0000-4000-8000-000000003465', 'この貝がら、耳に当てるとなみの音がするの。', 'Letakkan cangkang ini di telinga Anda dan Anda akan mendengar suara ombak.'),
  ('00000000-0000-4000-8000-000000003465', 'ひる休みに、だれがうそをついているのかを当てるゲームをしました。', 'Kami memainkan permainan mencoba menebak siapa yang berbohong saat istirahat makan siang.'),
  ('00000000-0000-4000-8000-000000003465', 'ボールをバットに上手く当てたと言いたかったんだけど、間違えてお尻に当てたと言ってしまった。', 'Saya ingin mengatakan, "Saya memukul bola dengan sangat baik dengan tongkat saya," tetapi saya tidak sengaja mengatakan pantat.'),
  ('00000000-0000-4000-8000-000000003466', 'オレンジとあい色が交わる、夕ぐれの空が大すきなの。', 'Saya suka langit malam ketika warna oranye bertemu dengan warna biru nila.'),
  ('00000000-0000-4000-8000-000000003466', 'このオフィスでは、時々、日本とアメリカの文化が交わります。', 'Di kantor ini, budaya Jepang dan Amerika terkadang bersinggungan.'),
  ('00000000-0000-4000-8000-000000003466', '婆ちゃんの乳はとても長いので、たまに相互に交わることすらできる。', 'Payudara nenek saya sangat panjang sehingga terkadang saling bersilangan.'),
  ('00000000-0000-4000-8000-000000003467', 'かの女は、化しょうをすれば、び人に化けることで有名です。', 'Dia terkenal karena mengubah dirinya menjadi wanita cantik dengan riasan.'),
  ('00000000-0000-4000-8000-000000003467', 'あのようかいは、人間に化けることができる。', 'Yokai itu bisa mengubah dirinya menjadi seseorang.'),
  ('00000000-0000-4000-8000-000000003467', '私の家はリフォームの後で全く違う家に化けてしまったので、息子は学校が終わった後にどの家に帰るのか分からなくなってしまいました。', 'Rumah saya berubah total setelah renovasi sehingga anak saya tidak tahu rumah mana yang harus dia tinggali sepulang sekolah.'),
  ('00000000-0000-4000-8000-000000003468', 'きのうは一日中、人さしゆびでピザを回すれんしゅうをしていました。', 'Saya berlatih memutar pizza dengan jari telunjuk saya sepanjang hari kemarin.'),
  ('00000000-0000-4000-8000-000000003468', 'ドアノブを回す音で、赤ちゃんの目がさめてしまいました。', 'Suara kenop pintu yang diputar membuat bayi itu terbangun.'),
  ('00000000-0000-4000-8000-000000003468', '私がこの一ドル硬貨を十分速く回したら、もしかすると百ドル札になるかもしれない。', 'Jika saya memutar koin satu dolar dengan cukup cepat, mungkin koin itu akan berubah menjadi uang seratus dolar.'),
  ('00000000-0000-4000-8000-000000003469', '小学校で、小さな子どもたちに、色々な絵本をよんであげています。', 'I''m reading various picture books to little children in elementary schools.'),
  ('00000000-0000-4000-8000-000000003469', 'あの小学校には、コウイチ気取りの六年生の男の子がいます。', 'In that elementary school, there is a sixth grade boy who is a Koichi wannabe.'),
  ('00000000-0000-4000-8000-000000003469', '小学校の頃から、君のことずっと気になっていたんだ。', 'I’ve had feelings for you since I was in elementary school.'),
  ('00000000-0000-4000-8000-000000003470', 'この通りをまっすぐに行って、三つ目のしん号を左に曲がってください。', 'Please go straight on this street and turn left at the third light.'),
  ('00000000-0000-4000-8000-000000003470', 'この通りでは、一日中車が行き交っています。', 'This road is busy all day long.'),
  ('00000000-0000-4000-8000-000000003470', 'チーズベーコンバーガー通りには、ガソリンスタンドってあったっけ？', 'Were there any gas stations on Bacon Cheeseburger Avenue?'),
  ('00000000-0000-4000-8000-000000003471', 'あぶらを使ったちょうりをするさいは、火事にならないよう、気を付けてください。', 'Saat Anda memasak menggunakan minyak, berhati-hatilah agar tidak menyalakan api.'),
  ('00000000-0000-4000-8000-000000003471', 'このマグカップ、あついから、気を付けてね。', 'Mug ini panas. Hati-hati.'),
  ('00000000-0000-4000-8000-000000003471', 'これから雪を食べる時はもっと気を付けてよ。色盲だから、色が黄色でも分かんないんだから。', 'Anda harus lebih berhati-hati saat makan salju mulai sekarang. Anda buta warna, jadi Anda tidak bisa membedakannya meskipun warnanya kuning.'),
  ('00000000-0000-4000-8000-000000003472', '新しいえんぴつですね。', 'This pencil is new, isn’t it?'),
  ('00000000-0000-4000-8000-000000003472', 'じゃあ、あの新しいスタバでね！', 'I''ll see you at the new Starbucks!'),
  ('00000000-0000-4000-8000-000000003472', 'あの男、バンジージャンプするのに私の新しいスカーフを使うなんて、信じられない！', 'I can’t believe he used my new scarf to bungee jump!'),
  ('00000000-0000-4000-8000-000000003473', '今日は、高校生たちが、このパン工場の見学に来ます。', 'Today, high school students are coming to this bread factory on a field trip.'),
  ('00000000-0000-4000-8000-000000003473', 'わたしは高校生の時、毎日のように海に行っては魚をとって食べていました。', 'When I was a high school student, I would go to the sea every day to catch fish and eat them.'),
  ('00000000-0000-4000-8000-000000003473', 'あいつはただの高校生デビューだよ。', 'He''s just trying to look cool because he’s in high school now.'),
  ('00000000-0000-4000-8000-000000003474', 'それより、中学校の前でとった写しんがいいよ。', 'All that aside, you should choose the photo taken in front of the junior high school.'),
  ('00000000-0000-4000-8000-000000003474', 'ちょっとまってて。その中学校のば所を今しらべてあげる。', 'Give me a sec, I''ll look up the location of the middle school for you.'),
  ('00000000-0000-4000-8000-000000003474', 'ええっと、私は中学校の教師ですよね。そこで、時間を無駄にしないためにも、とりあえず私は絶対に間違ったことを言わない、ということにしておいてください。', 'I’m a middle school teacher, right? To save time, let’s just always assume that I am never wrong, okay?'),
  ('00000000-0000-4000-8000-000000003475', '今このパソコンを買うと、オマケが付くので、おとくですよ。', 'Jika Anda membeli komputer ini sekarang, Anda akan mendapatkan sesuatu, jadi ini adalah kesepakatan.'),
  ('00000000-0000-4000-8000-000000003475', 'マイケルのTシャツにはドレッシングのしみがたくさん付いています。', 'Kaos Michael banyak noda saus saladnya.'),
  ('00000000-0000-4000-8000-000000003475', 'あなたの耳たぶに付いてるそれ、何？', 'Benda apa yang menempel di daun telingamu itu?'),
  ('00000000-0000-4000-8000-000000003476', 'むしさされって、見付けるととたんにかゆくなるよな。', 'Saat Anda menemukan gigitan serangga, itu membuat Anda gatal, bukan?'),
  ('00000000-0000-4000-8000-000000003476', 'このぼう子は、コウイチのかつらを見付けるための手がかりになるかもしれません。', 'Topi ini mungkin bisa membantu kita menemukan wig Koichi.'),
  ('00000000-0000-4000-8000-000000003476', '私は今朝、虹の端にあると言われている金の壺を見付けるために四時間以上も費やしました。', 'Saya menghabiskan lebih dari empat jam pagi ini untuk mencoba menemukan pot emas yang menurut mereka ada di ujung pelangi.'),
  ('00000000-0000-4000-8000-000000003477', 'あんなに弱虫でなき虫だったむす子も、もう一人前の大人です。', 'Anakku, yang lemah dan cengeng, sudah dewasa.'),
  ('00000000-0000-4000-8000-000000003477', '多くのアメリカ人はなっとうごときが食べられない弱虫です。', 'Banyak orang Amerika pengecut yang bahkan tidak bisa makan sedikit pun natto.'),
  ('00000000-0000-4000-8000-000000003477', '弱虫毛虫は、挟んで捨てろ！', 'Pengecut harus diperlakukan seperti ulat berbulu - diambil dan dibuang!'),
  ('00000000-0000-4000-8000-000000003478', 'なんか、弱々しいうたごえだったから、ちょっと心ぱいになっちゃった。', 'Aku mulai mengkhawatirkanmu karena suara nyanyianmu lemah.'),
  ('00000000-0000-4000-8000-000000003478', 'むかしは強く見えた父が年とともにだんだん弱々しく見えてきました。', 'Ayah saya, yang dulunya terlihat kuat, lambat laun mulai terlihat semakin lemah dari tahun ke tahun.'),
  ('00000000-0000-4000-8000-000000003478', 'その弱々しい患者は河豚の毒で苦しんでいた。', 'Pasien yang tampak lemah itu menderita racun ikan buntal.'),
  ('00000000-0000-4000-8000-000000003479', '自てん車でこけて、前ばが欠けてしまった。', 'Saya terjatuh dari sepeda dan gigi depan saya patah.'),
  ('00000000-0000-4000-8000-000000003479', 'その予定は確実性に欠けています。', 'Rencana itu kurang dapat diandalkan.'),
  ('00000000-0000-4000-8000-000000003479', '私には、セーラームーンを見るのを止めるための強い意志が欠けている。', 'Saya tidak memiliki kemauan untuk berhenti menonton Sailor Moon.'),
  ('00000000-0000-4000-8000-000000003480', 'きのう目がいたくなって、目医者に行ったら、ものもらいだった。', 'My eye started hurting yesterday, I went to the eye doctor, and it was a sty.'),
  ('00000000-0000-4000-8000-000000003480', '週末も開いている目医者をさがしています。', 'I''m looking for an eye doctor who is open on weekends.'),
  ('00000000-0000-4000-8000-000000003480', '「よお、目医者さん。もう何もかもばれているんだよ。だから、目について何も知らないふりをする必要はないぜ。」', 'Listen, Mr. Eye Doctor. The cat''s out of the bag, so there''s no need to pretend you don’t know anything about eyes.'),
  ('00000000-0000-4000-8000-000000003481', 'このごうかな朝食を食べ終わって、一番目のかんそうは、やっぱりベーコンはおいしい、です。', 'Hal pertama yang terlintas dalam pikiran setelah menyelesaikan sarapan yang luar biasa ini adalah bahwa bacon itu enak, seperti yang kita semua tahu.'),
  ('00000000-0000-4000-8000-000000003481', '一番目のらんには、すきな人の名前をかいてください。', 'Silakan tulis nama orang yang Anda sukai di kolom pertama.'),
  ('00000000-0000-4000-8000-000000003481', '「僕は毎朝一番目に、5キロのランニングをするんだぜ。」「大したことないよ！僕は10キロ走るよ。」', '"Hal pertama yang saya lakukan setiap pagi adalah berlari sejauh lima kilometer." "Itu bukan masalah besar! Aku lari sepuluh!"'),
  ('00000000-0000-4000-8000-000000003483', 'あいつのテンションの高さはやばいよな。', 'His excitement levels are dangerously high, right?'),
  ('00000000-0000-4000-8000-000000003483', 'トーフグのサボテンは、1.5メートルの高さにまでせい長しました。', 'Tofugu''s cactus has grown to a height of 1.5 meters.'),
  ('00000000-0000-4000-8000-000000003483', '「この建物の高さについてどう思いますか？少し高すぎますかねえ？」「申し訳ありませんが、分かりません。私には難しすぎます。」', '"What do you think about the height of this building? Is it too high?" "Sorry, but I don’t know. It’s over my head."'),
  ('00000000-0000-4000-8000-000000003484', 'あなたに会うのが楽しみです。', 'I’m looking forward to seeing you.'),
  ('00000000-0000-4000-8000-000000003484', '夏休みの楽しみと言えば、海にキャンプに色々あると思いますよ。', 'I think there are lots of different fun activities during summer break, like going to beach and camping and stuff.'),
  ('00000000-0000-4000-8000-000000003484', '私達、みんな亀を燃やすのを楽しみにしているんだよね？', 'We are all looking forward to burning turtles, aren’t we?'),
  ('00000000-0000-4000-8000-000000003485', 'これは子ども向けの作ひんではないですよね。', 'Karya ini tidak ditujukan untuk anak-anak.'),
  ('00000000-0000-4000-8000-000000003485', 'このカレーは、日本人向けのあじですね。', 'Kari ini dibuat untuk selera orang Jepang.'),
  ('00000000-0000-4000-8000-000000003485', 'コウイチが履いてるパンツは、子供向けなんじゃないのか？ツンツルテンだよ。', 'Bukankah celana dalam yang dipakai Koichi untuk anak-anak? Pakaiannya sudah kebesaran.'),
  ('00000000-0000-4000-8000-000000003486', 'とあるアメリカの研究所が、日本語がペラペラになるくすりを開発したそうだ。', 'Saya mendengar bahwa laboratorium Amerika tertentu telah membuat pil yang akan membuat Anda fasih berbahasa Jepang.'),
  ('00000000-0000-4000-8000-000000003486', '今日は、みそしる研究所で、ぼうさいくんれんがあります。', 'Ada latihan darurat di Fasilitas Penelitian Sup Miso hari ini.'),
  ('00000000-0000-4000-8000-000000003486', '私はバーガーキング研究所で働いています。私の仕事は、フライドポテトを食べ、その後自分の体重を測ることです。', 'Saya bekerja di Institut Penelitian Burger King. Pekerjaan saya terdiri dari makan kentang goreng dan kemudian menimbang badan saya.'),
  ('00000000-0000-4000-8000-000000003487', '上手な絵をも写する事は、上たつの近道です。', 'Tracing a good picture is a shortcut for improvement.'),
  ('00000000-0000-4000-8000-000000003487', 'ワニカニで漢字をおぼえることは、本当に日本語習とくの近道になると思いますか？', 'Do you really think memorizing kanji on WaniKani is actually a shortcut to Japanese acquisition?'),
  ('00000000-0000-4000-8000-000000003487', '「ありえねぇ！お前って本当脳みそ無いのな。なんで一方通行を逆走してるんだよ。」「近道になると思ったんだよ。」', '"Oh my God! You are such an airhead! Why are we going down a one-way street?" "I thought it would be a shortcut!"'),
  ('00000000-0000-4000-8000-000000003488', 'まだ助かる見こみはあるんですか。', 'Apakah masih ada kemungkinan untuk diselamatkan?'),
  ('00000000-0000-4000-8000-000000003488', 'コウイチ先生にもらったれんあいのアドバイスのおかげで、助かりました。', 'Saya terselamatkan oleh nasihat hubungan yang diberikan guru saya Koichi.'),
  ('00000000-0000-4000-8000-000000003488', '「で、私達付き合ってるのよね？どうなの？はっきりさせてよ。」「えーと…」＜その時、インターホンが鳴った。:ピンポーン＞「ふぅ、間一髪で助かった。」', '"Jadi, kita akan keluar atau bagaimana? Jelaskan!" "Um..." (Bel pintu depan berbunyi: dering-dering.) "Fiuh, terselamatkan oleh bel."'),
  ('00000000-0000-4000-8000-000000003491', 'まどから、海の美しいけ色を楽しむことができます。', 'You can enjoy the beautiful ocean view from the window.'),
  ('00000000-0000-4000-8000-000000003491', 'このプロジェクト、みんなすごく楽しみながらやってます。', 'We are having a lot of fun with this project.'),
  ('00000000-0000-4000-8000-000000003491', 'うさぎちゃん、いい加減目を覚ましなって。タキシード仮面のことなんか忘れて、うさぎちゃんはうさぎちゃんの人生を楽しんだらいいんだよ！', 'Snap out of it, Usagi. Forget Tuxedo Mask and enjoy your life!'),
  ('00000000-0000-4000-8000-000000003492', '仕事が決まってからは、きょうみがなくなりました。', 'Sejak saya mendapat pekerjaan itu, saya kehilangan minat.'),
  ('00000000-0000-4000-8000-000000003492', 'コウイチは毎朝かみがたが決まらないせいで会社にちこくする。', 'Setiap pagi Koichi terlambat ke kantor karena dia belum memutuskan gaya rambutnya.'),
  ('00000000-0000-4000-8000-000000003492', '「それは本当にいい考えだね。そうしよう。」「よし、じゃあ、それで話は決まりだ。」', '“Itu ide yang sangat bagus. Ayo kita lakukan.” "Oke, kalau begitu sudah diputuskan."'),
  ('00000000-0000-4000-8000-000000003493', 'むすめから、頭に花びんを投げ付けられて、七はりをぬう大けがを負いました。', 'Putri saya melemparkan vas ke kepala saya dan menyebabkan saya mengalami luka serius sehingga memerlukan tujuh jahitan.'),
  ('00000000-0000-4000-8000-000000003493', 'せつ分の日にコウイチにまめを投げ付けてじゃ気をはらいました。', 'Di Setsubun, kami melemparkan kacang kering ke arah Koichi dan mengusir roh jahat tersebut.'),
  ('00000000-0000-4000-8000-000000003493', '「サーモン、僕は君に夢中なんだ。」「フグ、私はあんたに怒り心頭よ。どうして私に向かってニンニクなんて投げ付けるのよ！」「ご…ごめん。鮭はニンニクの臭いが好きって聞いたことがあったんだ。」', '"Salmon, aku tergila-gila padamu." "Fugu, sebenarnya aku marah padamu! Kenapa kamu melempar bawang putih ke arahku? M..maaf aku dengar salmon itu suka bau bawang putih."'),
  ('00000000-0000-4000-8000-000000003494', 'たぬきやきつねは、人間を化かすのがとくいだ。', 'Tanuki dan rubah pandai menyihir manusia.'),
  ('00000000-0000-4000-8000-000000003494', 'わたしの友人はいつも化しょうで男の人を化かしています。', 'Teman saya selalu memikat pria dengan riasan.'),
  ('00000000-0000-4000-8000-000000003494', '「遅くなってすみません。いやあ、きつねに化かされちまってねえ。」「心配しないでください。それはどうしようもないことですからね。」', '“Maaf aku terlambat. Aku disihir oleh seekor rubah.” "Jangan khawatir. Hal seperti itu mau bagaimana lagi."'),
  ('00000000-0000-4000-8000-000000003495', 'それから話を聞いて、もんだい用紙の１から４の中から、一番いいものを一つえらんでください。', 'And then you will listen to the story and choose the best answer between 1-4 on the answer sheet.'),
  ('00000000-0000-4000-8000-000000003495', '話がちがうよ！', 'I didn''t sign up for this!'),
  ('00000000-0000-4000-8000-000000003495', '「それから、私、他にも言いたいことがあるのよ、ブリタニー！」「ジェレミー、いい加減黙ってくれないか！君の話はもう聞き飽きたよ。」', '"Now, I’d also like to say something else, Brittany!" "Jeremy! Give it a rest! I’m tired of listening to you."'),
  ('00000000-0000-4000-8000-000000003496', 'こっちを向いてください。', 'Tolong belok ke sini.'),
  ('00000000-0000-4000-8000-000000003496', 'このへやは、南を向いているので日当たりがいい。', 'Ruangan ini menghadap ke Selatan, jadi cuacanya sangat cerah.'),
  ('00000000-0000-4000-8000-000000003496', '今度は、お父さんの方を向いて、どうして赤ちゃんの格好をしているのか聞いてみましょう。', 'Sekarang, mari kita menghadap ayahmu dan bertanya mengapa dia mengenakan kostum bayi.'),
  ('00000000-0000-4000-8000-000000003501', 'この花の名をおしえてください。', 'Please tell me the name of this flower.'),
  ('00000000-0000-4000-8000-000000003501', 'きょ年のなつ、「きみの名は。」というえいがが日本ではやりました。', 'Last summer, the movie "Your Name" became popular in Japan.'),
  ('00000000-0000-4000-8000-000000003501', 'まだ彼女の名も知らない。', 'I still don’t know her name.'),
  ('00000000-0000-4000-8000-000000003506', 'わたしたち、ちょっと出会うのが早すぎたみたいね。', 'It looks like we happened to run into each other a little too early.'),
  ('00000000-0000-4000-8000-000000003506', 'きのうの夜、クラブで、れんあいかんじょうぬきでただ楽しみたいっていう男に出会ってさ、ハマっちゃいけないのは分かってるけど、めちゃくちゃタイプだったんだよね。', 'Last night, I met a guy who''s looking for no strings attached fun at a club and I know I shouldn''t be into him, but he was really my type.'),
  ('00000000-0000-4000-8000-000000003506', '「ニコールって、今、付き合っている人いるの？」「ええ。エリックと1年間付き合っているわ。」「そうなんだ！彼とは、どこで出会ったの？」', '"Are you seeing anyone now, Nicole?" "Yes, I’ve been seeing Eric for a year." "Wow, where did you guys meet?"'),
  ('00000000-0000-4000-8000-000000003514', '白黒ハッキリさせようぜ。', 'Let’s make it clearly black and white.'),
  ('00000000-0000-4000-8000-000000003514', 'この白黒の写しん、すてきですね。', 'This black and white photo is very lovely.'),
  ('00000000-0000-4000-8000-000000003514', 'カナエちゃんがいつもオシャレな服装をしているってことは認めるけどさ、今日の白黒のドレスはちょっとなんかパンダみたいじゃない？', 'I agree that Kanae always wears very chic clothes, but today that black and white dress just makes her look like a panda, doesn’t it?'),
  ('00000000-0000-4000-8000-000000003522', 'えきの東がわにあるきっ茶店で会いましょう。', 'Let’s meet in the cafe that''s on the east side of the station.'),
  ('00000000-0000-4000-8000-000000003522', 'どっちの方角が東？', 'Which direction is east?'),
  ('00000000-0000-4000-8000-000000003522', '空港の東側に住んでいます。', 'I live on the east side of the airport.'),
  ('00000000-0000-4000-8000-000000003523', '今日、としょかんに本を返しに行かなくちゃいけないんです。', 'Hari ini saya harus pergi ke perpustakaan untuk mengambil kembali buku.'),
  ('00000000-0000-4000-8000-000000003523', '返す言ばが見当たらないよ。', 'Saya tidak punya apa-apa untuk dikatakan kembali kepada Anda.'),
  ('00000000-0000-4000-8000-000000003523', '「昨日あげたクッキー返してくれない？」「えっ、吐きだせってこと？」', '"Bisakah kamu mengembalikan kue yang kuberikan padamu kemarin?" "Hah? Maksudmu, aku harus membuangnya?"'),
  ('00000000-0000-4000-8000-000000003564', 'かれが元気がないのはめずらしいので心配です。', 'Saya khawatir karena tidak biasa dia begitu sedih.'),
  ('00000000-0000-4000-8000-000000003564', 'この船の進行方向が西なのか東なのか心配になった。', 'Saya khawatir apakah kapal itu menuju ke timur atau barat.'),
  ('00000000-0000-4000-8000-000000003564', '心配しないで。すべて上手くいくよ。私の言うことを信じて。', 'Jangan khawatir, semuanya akan baik-baik saja. Anda bisa percaya apa yang saya katakan.'),
  ('00000000-0000-4000-8000-000000003647', '里にクマが出たぞ！', 'There''s a bear in the village!'),
  ('00000000-0000-4000-8000-000000003647', 'そんな言ばづかいをしていると、お里がしれますよ。', 'If you use language like that, you''ll give away where you''re from.'),
  ('00000000-0000-4000-8000-000000003647', 'このおやつの名前は「たけのこの里」です。', 'This candy is called "Bamboo Shoot Village".'),
  ('00000000-0000-4000-8000-000000003648', 'ちょっと里心がついちゃったんです。', 'I’m a bit homesick.'),
  ('00000000-0000-4000-8000-000000003648', 'なつかしいメロディーに、里心がわいた。', 'The nostalgic melody made me homesick.'),
  ('00000000-0000-4000-8000-000000003648', 'この仔犬は里心がついて泣いているのかもしれないけど、そんなのかまうもんか。', 'This puppy may be crying because he is homesick, but who cares?'),
  ('00000000-0000-4000-8000-000000003707', 'トーフグは、ポーカーフェイスができる人を求めています。', 'Tofugu menginginkan seseorang yang memiliki wajah poker face.'),
  ('00000000-0000-4000-8000-000000003707', '時々、返金を求めるメールがとどきます。', 'Terkadang kami menerima email yang meminta pengembalian dana.'),
  ('00000000-0000-4000-8000-000000003707', 'トーフグの顧客は、ますます環境に優しい日本語学習製品を求めるようになってきている。', 'Semakin banyak klien Tofugu yang menuntut produk pembelajaran bahasa Jepang yang ramah lingkungan.'),
  ('00000000-0000-4000-8000-000000003708', '求人については、後ほどあらためてせつ明をいたします。', 'Kami akan menjelaskan tawaran pekerjaan nanti.'),
  ('00000000-0000-4000-8000-000000003708', '近年は、ほぼ全てのき業が求人にインターネットを使います。', 'Saat ini, hampir semua perusahaan menggunakan Internet untuk merekrut.'),
  ('00000000-0000-4000-8000-000000003708', 'トーフグのブログで拝見した求人の件でお電話しました。プログラマー職に応募したいのですが、ビエトさんはまだ生きていらっしゃいますか？今朝方刺客を送り込んでおいたのですが。', 'Saya menelepon mengenai posisi yang diiklankan di blog Tofugu. Saya ingin melamar posisi programmer, tapi apakah Pak Viet masih hidup? Saya mengirim seorang pembunuh untuk mengejarnya pagi ini.'),
  ('00000000-0000-4000-8000-000000003709', 'ねこの心理を思うがままにあやつれるようになりたい。', 'I want to be able to manipulate cats'' minds as much as I want.'),
  ('00000000-0000-4000-8000-000000003709', '春人には、理子の心理が分からなかった。', 'Haruto didn''t understand what Riko was thinking about.'),
  ('00000000-0000-4000-8000-000000003709', 'サーモンと彼女に翻弄される人々の心理を、君の小説で描いてみてもらえないかな？人気が出ると思うんだけど。', 'Can you depict the mental state of Salmon and those she deceives in your novel? I think people would love it.'),
  ('00000000-0000-4000-8000-000000003714', 'メーリングリストから私を外してください。', 'Please remove me from your email list.'),
  ('00000000-0000-4000-8000-000000003714', '私がえいぎょう部のせきにん者です。', 'I''m the director of the sales division.'),
  ('00000000-0000-4000-8000-000000003714', '昨日の夜、バーデビューしちゃった。私もちょっとずつ大人の階段登ってるって感じ？', 'I went to a bar for the first time last night. I feel like I’m slowly becoming an adult.'),
  ('00000000-0000-4000-8000-000000003715', 'コウイチの私生活は、ひみつのベールにつつまれています。', 'Kehidupan pribadi Koichi terselubung dalam kerahasiaan.'),
  ('00000000-0000-4000-8000-000000003715', '生まれつき人よりめんえき力が弱いので、私生活ではいつもマスクをしています。', 'Sistem kekebalan tubuh saya lebih lemah dibandingkan kebanyakan orang sejak saya lahir, jadi saya biasanya memakai masker saat sendirian.'),
  ('00000000-0000-4000-8000-000000003715', 'コウイチ、仕事で相当ストレスがたまっているみたいで、私生活が荒れてきてるんだよね。ちょっと相談相手になってあげてくれないかな。誰か聞いてくれる人が必要だと思うんだよね。', 'Koichi mendapat banyak stres karena pekerjaan dan kehidupan pribadinya semakin kacau. Bisakah Anda menasihatinya? Saya yakin dia membutuhkan seseorang untuk mendengarkannya.'),
  ('00000000-0000-4000-8000-000000003716', '私立のようちえんはクリスマスの日はお休みだよ。', 'The private kindergartens are closed on Christmas Day.'),
  ('00000000-0000-4000-8000-000000003716', 'ここを出て、前の通りを左の方へ三つ目の交さ点まで歩くと、その私立病院に着きますよ。', 'Go out of here and walk left along the street until you come to the third intersection and you''ll get to the private hospital.'),
  ('00000000-0000-4000-8000-000000003716', 'コウイチがカフェでこっそり会っていた男の人は、私立探偵だったということが判明しました。', 'I found out that the guy Koichi secretly met at the cafe was a private detective.'),
  ('00000000-0000-4000-8000-000000003717', '東京の私鉄はふくざつでよく分かりません。', 'Kereta api swasta di Tokyo terlalu rumit untuk dipahami.'),
  ('00000000-0000-4000-8000-000000003717', 'JRで新宿駅まで行ったら私鉄に乗りかえてください。', 'Ketika Anda tiba di Stasiun Shinjuku dengan JR, silakan transfer ke kereta pribadi.'),
  ('00000000-0000-4000-8000-000000003717', '私は、とある日本の大手私鉄会社で働いております。', 'Saya bekerja di salah satu perusahaan kereta api swasta besar di Jepang.'),
  ('00000000-0000-4000-8000-000000003803', 'コウイチは何かの世界記録保持者だと聞きました。', 'Kudengar Koichi adalah pemegang rekor dunia.'),
  ('00000000-0000-4000-8000-000000003803', 'かくへい器の保持についてどうお考えですか？', 'Apa pendapat Anda tentang retensi senjata nuklir?'),
  ('00000000-0000-4000-8000-000000003803', 'トーフグは、火星の治安を保持することに、微力ながら貢献したいと思います。', 'Tofugu akan menyumbangkan upaya sederhana kami untuk menjaga perdamaian Mars.'),
  ('00000000-0000-4000-8000-000000003806', '生保はもちろんつみ立てですよね？', 'Tentu saja asuransi jiwa Anda berjenis cadangan bukan?'),
  ('00000000-0000-4000-8000-000000003806', '日本ではけんこう保険のせい度が整っているんだから、わざわざ生保に入る必要はあまりないよ。', 'Di Jepang, sistem asuransi kesehatan bersifat all-inclusive, sehingga Anda tidak perlu membeli asuransi jiwa secara terpisah.'),
  ('00000000-0000-4000-8000-000000003806', '日本では、女性の生命保険販売員は「生保レディ」と呼ばれます。', 'Penjual asuransi jiwa disebut "wanita seiho" di Jepang.'),
  ('00000000-0000-4000-8000-000000003807', 'わかさを保つひけつは何ですか？', 'Apa rahasia melestarikan masa muda Anda?'),
  ('00000000-0000-4000-8000-000000003807', 'ビエトのおかげで、コウイチはメンツを保つことができた。', 'Berkat Viet, Koichi mampu menjaga mukanya.'),
  ('00000000-0000-4000-8000-000000003807', 'あのお医者さんに、「体調を保つためには、日々の運動が大切だよ」なんて言われたけど、そのお医者さん自体がすっごく太ってるんだよね。', 'Dokter memberi tahu saya bahwa penting untuk berolahraga secara teratur untuk menjaga kesehatan fisik, tetapi dia sangat gemuk.'),
  ('00000000-0000-4000-8000-000000003864', '私自身は、その動物園の問題にはあまり関心がないんです。', 'Personally, I''m indifferent to the zoo''s issues.'),
  ('00000000-0000-4000-8000-000000003864', '私自身は、そんなにきょくたんなことじゃなければ、どんな食生活でも良いと思っています。', 'As for me, as long as it isn''t too extreme, I think any kind of diet is okay.'),
  ('00000000-0000-4000-8000-000000003864', 'あなたがもし私自身よりも私のことを知っていると思ったら、 それはとんだ大間違いよ。', 'You’re way off base if you think you know me better than I know myself.'),
  ('00000000-0000-4000-8000-000000003918', '私立大学は公立大学よりじゅ業料が高いです。', 'Tuition for private universities is more expensive than that of public universities.'),
  ('00000000-0000-4000-8000-000000003918', 'わせ田大学は日本の有名な私立大学です。', 'Waseda University is a famous, private university in Japan.'),
  ('00000000-0000-4000-8000-000000003918', 'あの出火した私立大学は、私が通っている学校だよ。', 'The private college that’s on fire is the college I’m currently attending.'),
  ('00000000-0000-4000-8000-000000003924', '労働者たちは、ちん上げを要求した。', 'Buruh menuntut upah yang lebih tinggi.'),
  ('00000000-0000-4000-8000-000000003924', '会社からの要求が前近代的すぎて気持ち悪いんだけど。', 'Tuntutan perusahaan bersifat feodalistik dan membuat saya muak.'),
  ('00000000-0000-4000-8000-000000003924', 'この要求はいくらなんでも無茶だ。', 'Persyaratan ini tidak masuk akal!'),
  ('00000000-0000-4000-8000-000000003936', 'あの鼻すじの通ったイギリス人は、鼻にかかった声で話します。', 'That British person with the straight nose speaks in a nasal voice.'),
  ('00000000-0000-4000-8000-000000003936', 'このイギリス人は、梅ずを飲んだことがないそうです。', 'Apparently, this British person hasn''t tried ume vinegar before.'),
  ('00000000-0000-4000-8000-000000003936', '知らないイギリス人から友達申請が来たよ。', 'I got a friend request from a Brit I don''t know.'),
  ('00000000-0000-4000-8000-000000004129', '私大の授業料は高いもんね。', 'Private college tuition sure is expensive.')
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES
  ('00000000-0000-4000-8000-000000004129', 'とある大阪の私大で英語を教えています。', 'I''m teaching English at a private uni in Osaka.'),
  ('00000000-0000-4000-8000-000000004129', 'こないだ言ってた私大の学園祭の件なんだけど、今回は私の事数にいれないで。ごめん。でも悪く思わないでね。時間ができたら連絡するから。', 'As for the school festival at the private university you told me about the other day, could you count me out this time? I’m sorry, don’t get mad at me. I’ll contact you when I have free time.'),
  ('00000000-0000-4000-8000-000000004147', 'ビエトに言われた方法を五度試みたんですが、ダメでした。', 'I''ve attempted the method that Viet told me about five times, but it never worked.'),
  ('00000000-0000-4000-8000-000000004147', 'ビエトの手下が、けいむ所からのだっ走を試みたらしい。', 'Apparently Viet''s follower tried to escape from prison.'),
  ('00000000-0000-4000-8000-000000004147', 'トーフグは、常に新しい事を試みる人を探しています。', 'Tofugu is looking for someone who always tries to do something new.'),
  ('00000000-0000-4000-8000-000000004150', '文句を言う前に、試食してみてよ。', 'Try a sample before you complain about it.'),
  ('00000000-0000-4000-8000-000000004150', 'コウイチの昔なつかしいソフトクリームチーズ商店の試食会におよばれしました。', 'I was invited to the sample party for Koichi’s Old-Timey Soft Serve Cream Cheese Emporium.'),
  ('00000000-0000-4000-8000-000000004150', 'スーパーで試食販売をしている人は、日本の食品業界では「マネキンさん」と呼ばれる。', 'The person who offers food samples in grocery stores is called "Ms. Mannequin" in the Japanese food industry.'),
  ('00000000-0000-4000-8000-000000004162', 'いねかり体験教室への応募者は、五百人に達しました。', 'The number of applicants for the rice harvesting experience activity reached five hundred.'),
  ('00000000-0000-4000-8000-000000004162', '日本では戦争体験をした人の数が年々少なくなっています。', 'In Japan, the number of people who have experienced war has been decreasing year after year.'),
  ('00000000-0000-4000-8000-000000004162', 'これは、コウイチ自身が日本へ留学した時の体験を元にした作品です。', 'This is a story based on Koichi’s own experiences from when he studied abroad in Japan.'),
  ('00000000-0000-4000-8000-000000004163', '兄は来年大学受験です。', 'Kakak laki-laki saya akan mengikuti ujian masuk universitas tahun depan.'),
  ('00000000-0000-4000-8000-000000004163', '最近は、毎日朝から晩までずっと受験勉強をしています。', 'Saya telah belajar untuk mengikuti ujian dari pagi hingga malam setiap hari belakangan ini.'),
  ('00000000-0000-4000-8000-000000004163', '私は受験票を持って行くのを忘れてしまいましたが、母が届けてくれました。', 'Aku lupa mengambil slip penerimaan ujian, tapi ibuku menitipkannya untukku.'),
  ('00000000-0000-4000-8000-000000004164', '実験のために、車を一台借りました。', 'Saya meminjam mobil untuk percobaan.'),
  ('00000000-0000-4000-8000-000000004164', 'どんなことを言ったらビエトがおこるのか、実験してみた。', 'Kami bereksperimen untuk mencari tahu hal-hal apa yang bisa kami katakan untuk membuat Viet marah.'),
  ('00000000-0000-4000-8000-000000004164', '私達の新製品「フグ風味の豆腐」の実験台になりたい人はいますか？', 'Siapa yang ingin menjadi kelinci percobaan dalam eksperimen proyek tahu rasa fugu baru kami?'),
  ('00000000-0000-4000-8000-000000004165', 'おっと！明日試験だっけ？忘れるところだったよ。', 'Oh! Is tomorrow examination day? I almost forgot about it.'),
  ('00000000-0000-4000-8000-000000004165', '何度か試験してみたんですが、まだ一度も成功してないんですよ。', 'We made several tests, but none of them have gone well yet.'),
  ('00000000-0000-4000-8000-000000004165', '「ところで、試験はどうだった？」「パパ、その話はやめてよ。」', '"By the way, how was the exam?" "Stop talking about that, dad."'),
  ('00000000-0000-4000-8000-000000004375', 'このゲームは、明日はいしん開始です。', 'This game will be released tomorrow.'),
  ('00000000-0000-4000-8000-000000004375', '先行予やく受付を開始しました。', 'We''ve started accepting preorders.'),
  ('00000000-0000-4000-8000-000000004375', '現在、トーフグは枕業界で巻き返しを図っており、新しいモデルの枕の販売を開始した。', 'Tofugu is currently still working to catch up in the pillow market, so they started selling new models.'),
  ('00000000-0000-4000-8000-000000004376', '今夜、コウイチから、重大な発表があります。', 'Malam ini akan ada pengumuman penting dari Koichi.'),
  ('00000000-0000-4000-8000-000000004376', 'ピカチュウは、今朝、ポケモンから引たいすることを発表した。', 'Pikachu mengumumkan pengunduran dirinya dari Pokemon pagi ini.'),
  ('00000000-0000-4000-8000-000000004376', '明日、みんなの前でSNSの研究成果について発表をしなければならないので、緊張しています。', 'Saya gugup karena saya harus memberikan presentasi tentang hasil penelitian media sosial saya di depan semua orang besok.'),
  ('00000000-0000-4000-8000-000000004377', 'でも、ろこつに不かいかんを表すのはよくないよ。', 'Namun tidak baik jika Anda mengungkapkan ketidaknyamanan Anda secara blak-blakan.'),
  ('00000000-0000-4000-8000-000000004377', '国民はみんな、高がくのぜい金に不まんを表していますよ。', 'Semua warga negara menyatakan ketidakpuasannya terhadap tingginya pajak.'),
  ('00000000-0000-4000-8000-000000004377', 'このアップルシナモンウィスキーがどれだけ美味しいかを言葉で表すことはできない。', 'Saya tidak dapat mengungkapkan betapa enaknya wiski kayu manis apel ini.'),
  ('00000000-0000-4000-8000-000000004378', 'ごめんなさい。ジーンズのせいで私の足はこれ以上広がりません。', 'Sorry, my jeans won’t allow my legs to spread any further.'),
  ('00000000-0000-4000-8000-000000004378', 'この山火じは、今しゅうまつにもオレゴンしゅうまで広がってしまうかもしれない。', 'This wildfire might spread to the state of Oregon by the end of this week.'),
  ('00000000-0000-4000-8000-000000004378', '見わたす限りラベンダ畑が広がっていた。', 'The lavender field stretched out as far as the eye could see.'),
  ('00000000-0000-4000-8000-000000004379', 'このドレスは、曲線を美しく出してくれます。', 'Gaun ini memberiku lekuk tubuh yang indah.'),
  ('00000000-0000-4000-8000-000000004379', 'ブーメランパンツから出てるコウイチのおしりの曲線…いいね！', 'Lekukan pantat Koichi yang menonjol dari speedo sangat... bagus!'),
  ('00000000-0000-4000-8000-000000004379', 'あなたが怒った時の、ほおの柔らかく歪んだ曲線が好きよ。', 'Aku sangat menyukai lekuk pipimu yang lembut dan miring saat kamu marah.'),
  ('00000000-0000-4000-8000-000000004380', '出発まで五分です。', 'There are five minutes until departure.'),
  ('00000000-0000-4000-8000-000000004380', '二週間後に、東京に出発する予定です。', 'I''m going to leave for Tokyo in two weeks.'),
  ('00000000-0000-4000-8000-000000004380', 'ほとんど喋ったことのない同僚の出発の門出を祝う飲み会にお誘い頂き、どうも有難う御座います。', 'Thank you so much for inviting me to a drinking party to celebrate the departure of a co-worker that I rarely spoke to.'),
  ('00000000-0000-4000-8000-000000004848', '前回のじゅぎょうでは、カエルのかいぼうをしました。', 'Kelas terakhir kita membedah seekor katak.'),
  ('00000000-0000-4000-8000-000000004848', 'それでは、前回のつづきからはじめたいと思います。', 'Oke jadi... kita akan melanjutkan dari apa yang kita akhiri terakhir kali.'),
  ('00000000-0000-4000-8000-000000004848', '前回のレッスンの復習は家でちゃんとやってきましたか？', 'Apakah kalian meninjau pelajaran terakhir di rumah dengan benar?'),
  ('00000000-0000-4000-8000-000000004849', '今の時代は、インターネットで何でもかうことができます。', 'In this era, you can buy anything on the Internet.'),
  ('00000000-0000-4000-8000-000000004849', '明里は、わたしの大学時代の友人です。', 'Akari is my friend from college.'),
  ('00000000-0000-4000-8000-000000004849', '紫式部は、平安時代中期の女性作家かつ歌人です。', 'Murasaki Shikibu was a female writer and poet from the mid–Heian period.'),
  ('00000000-0000-4000-8000-000000004876', 'それは本当ですか？', 'Apakah itu benar?'),
  ('00000000-0000-4000-8000-000000004876', 'さいきんの大学生はスマホでレポートをかくってきいたけど、本当かなあ。', 'Saya mendengar bahwa saat ini mahasiswa menulis esai di ponsel pintar mereka, tetapi saya bertanya-tanya apakah itu benar.'),
  ('00000000-0000-4000-8000-000000004876', '本当に下手なのです。', 'Aku sangat buruk dalam hal itu.'),
  ('00000000-0000-4000-8000-000000004877', '日本の人たちは、本当にやさしいです。', 'Orang Jepang sungguh baik hati.'),
  ('00000000-0000-4000-8000-000000004877', 'このせいひん、本当に高くなっちゃったねー。', 'Produk ini menjadi sangat mahal.'),
  ('00000000-0000-4000-8000-000000004877', '本当にこの道であっていますか？', 'Apakah ini benar-benar jalannya?'),
  ('00000000-0000-4000-8000-000000005389', 'はこの内がわをピンクいろにぬってください。', 'Silakan cat bagian dalam kotak dengan warna merah muda.'),
  ('00000000-0000-4000-8000-000000005389', 'てきは内にあり。', 'Ada musuh di dalam.'),
  ('00000000-0000-4000-8000-000000005389', '内にひめたおもいを、日きにつづった。', 'Pikiran yang aku sembunyikan di dalam diriku dijabarkan dalam buku harianku.'),
  ('00000000-0000-4000-8000-000000005503', 'リストラで、身も心もズタズタです。', 'Because of my layoff, physically and mentally I''m torn apart.'),
  ('00000000-0000-4000-8000-000000005503', 'この魚の身はたん白でおいしいね。', 'This fish meat is light and delicious, isn''t it?'),
  ('00000000-0000-4000-8000-000000005503', '現金は常に身につけておく方がいい。', 'You should always carry cash on you.'),
  ('00000000-0000-4000-8000-000000005631', '宝をどこにかくしたんだ？', 'Di mana kamu menyembunyikan harta karun itu?'),
  ('00000000-0000-4000-8000-000000005631', 'この宝のちず、三ばいにかくだいしてプリントアウトしておいてくれない？', 'Bisakah Anda memperbesar peta harta karun ini tiga kali dan mencetaknya untuk saya?'),
  ('00000000-0000-4000-8000-000000005631', '宝箱に隠しておいたサマージャンボ宝くじがなくなってる！', 'Tiket Lotere Jumbo Musim Panas yang saya sembunyikan di peti harta karun hilang!'),
  ('00000000-0000-4000-8000-000000005632', 'あの赤い宝石のゆびわは、だれかのわすれものです。', 'Cincin dengan permata merah itu adalah barang milik seseorang yang hilang.'),
  ('00000000-0000-4000-8000-000000005632', 'あの大ふごうは、メイドに宝石があしらわれたそうじどうぐをつかわせている。', 'Miliarder itu menyuruh pembantunya menggunakan alat pembersih yang dihias dengan permata.'),
  ('00000000-0000-4000-8000-000000005632', 'お姫様は美しい宝石のついた腕輪を時計回りに回しました。', 'Sang putri memutar gelang permata indah itu searah jarum jam.'),
  ('00000000-0000-4000-8000-000000005633', '私のきおくが正しければ、これは国宝ではありません。', 'Jika saya ingat dengan benar, ini bukanlah harta nasional.'),
  ('00000000-0000-4000-8000-000000005633', '「どうしてこのそうじきは国宝なんですか？」「ニコラス・ケイジがつかったことがあるからだよ。」', '“Mengapa penyedot debu ini menjadi harta nasional?” "Karena Nic Cage pernah menggunakannya sebelumnya."'),
  ('00000000-0000-4000-8000-000000005633', 'crabigator.churchに国宝が隠されている。', 'Harta nasional tersembunyi di crabigator.church.'),
  ('00000000-0000-4000-8000-000000005717', '今家を出ても、社会のじゅぎょうに間にあわないと思います。', 'Even if I leave home right now, I think I’ll probably be late for social studies.'),
  ('00000000-0000-4000-8000-000000005717', '国さい社会の一員として、めしテロにはだんじてくっしません。', 'As a member of the international society, I will not yield to food porn.'),
  ('00000000-0000-4000-8000-000000005717', '社会問題として、若者がお葬式で自分撮りをすることについて考える必要がある。', 'As a society, we need to be concerned about youths taking ’selfies’ at funerals.'),
  ('00000000-0000-4000-8000-000000005846', '「妹が宝くじに当たったのよ。」「すごいね！で、いくら？」「一万円。」', '"Adik perempuanku memenangkan lotre." "Oh keren! Berapa?" “10.000 yen.”'),
  ('00000000-0000-4000-8000-000000005846', 'きぼうてきかんそくでは、来年あたりに宝くじに当たるはずです。', 'Itu hanya angan-angan saja, tapi saya mungkin akan memenangkan lotre tahun depan.'),
  ('00000000-0000-4000-8000-000000005846', '父親の秘書が宝くじに当たったんだけど、それをフェイスブックに書いた時に秘書を秘密と書き間違えてしまい、みんなが勘違いしてたくさんおめでとうコメントを残してくれました。', 'Sekretaris ayah saya memenangkan lotre, tetapi saya membuat kesalahan ejaan saat mempostingnya di Facebook. Sekretaris dieja secara diam-diam. Itu membingungkan orang dan saya mendapat banyak ucapan selamat.'),
  ('00000000-0000-4000-8000-000000005934', '明日、びょういんへ行きましょう。', 'Let’s go to the hospital tomorrow.'),
  ('00000000-0000-4000-8000-000000005934', '明日は明日の風がふく。', 'Tomorrow is another day. '),
  ('00000000-0000-4000-8000-000000005934', '一ヶ月イタリアに行くことを知らせるために、明日学校に電話しなくてはいけません。', 'I need to call the school tomorrow to inform them that I’m going to Italy for a month.'),
  ('00000000-0000-4000-8000-000000005935', 'タクシーのひょうじが「空車」となっているときは、おきゃくさんはだれものっていません。', 'When a taxi is displaying "Open Taxi," there are no customers aboard.'),
  ('00000000-0000-4000-8000-000000005935', 'この辺りのコインパーキングがいつも空車なのがふしぎでしょうがない。', 'I''m really curious why the parking lots around here are always empty.'),
  ('00000000-0000-4000-8000-000000005935', '空車のタクシーが全然通らない。', 'No empty taxis have passed us.'),
  ('00000000-0000-4000-8000-000000006237', 'ぼくのかの女は、同じ町の二丁目にすんでいるミイコちゃんです。', 'Pacarku Miiko juga tinggal di 2-chome.'),
  ('00000000-0000-4000-8000-000000006237', 'その台風で、一丁目と二丁目がしん水してしまいました。', 'Topan membanjiri 1-chome dan 2-chome.'),
  ('00000000-0000-4000-8000-000000006237', 'この桃、三丁目の田中さんから頂いたの。', 'Saya mendapat buah persik ini dari Tanaka dari 3-chome.'),
  ('00000000-0000-4000-8000-000000007149', 'よくその本屋に行きます。', 'I go to that bookstore often.'),
  ('00000000-0000-4000-8000-000000007149', 'この本屋には、ツアーガイドブックがたく山おいてあります。', 'This bookshop has a lot of tourist guidebooks.'),
  ('00000000-0000-4000-8000-000000007149', '本屋のレジでアルバイトをしています。', 'I work part time at the bookstore cash register.'),
  ('00000000-0000-4000-8000-000000007451', 'ようやく、ゆめに向かって一歩ふみ出しました。', 'I’ve finally taken one step forward toward my dream.'),
  ('00000000-0000-4000-8000-000000007451', '千里の道も一歩からって言うでしょ？', 'They say, a journey of a thousand miles begins with a single step, right?'),
  ('00000000-0000-4000-8000-000000007451', '最初の一歩を踏み出すのに勇気がいる。', 'It takes courage to take the first step forward.'),
  ('00000000-0000-4000-8000-000000007455', 'バスはなん台いりますか？', 'How many buses do we need?'),
  ('00000000-0000-4000-8000-000000007455', 'し力がよくなるきかいを三台ちゅうもんしました。', 'I ordered three machines that makes your eyesight better.'),
  ('00000000-0000-4000-8000-000000007455', 'あのかねもちしゃちょうはこうきゅうしゃを三台もっています。', 'The rich company president has three luxury cars.'),
  ('00000000-0000-4000-8000-000000007456', 'まんがを三百さつもっています。', 'I have three hundred manga.'),
  ('00000000-0000-4000-8000-000000007456', 'ひるねをしていた時に、だれかがインターホンを三百回もならした。', 'When I was taking a nap, somebody rang the doorbell 300 times.'),
  ('00000000-0000-4000-8000-000000007456', '一年は三百六十五日です。', 'One year is three hundred and sixty-five days.'),
  ('00000000-0000-4000-8000-000000007458', '今人気のプログラミング言語は何ですか？', 'What are the popular programming languages right now?'),
  ('00000000-0000-4000-8000-000000007458', '言語オタクたちが朝まで言語について語りつくすオフ会にさんかしてきました。', 'I joined an offline gathering where language geeks got together and talk about language all night long.'),
  ('00000000-0000-4000-8000-000000007458', '新しいコンピュータ言語の勉強を始めました。', 'I started to study a new computer language.'),
  ('00000000-0000-4000-8000-000000007459', ' 木のはが地上におちた。', 'The leaves fell to the ground.'),
  ('00000000-0000-4000-8000-000000007459', 'コウイチは地上1kmの所に、ひみつき地をもっている。', 'Koichi has a Secret Base 1km above ground.'),
  ('00000000-0000-4000-8000-000000007459', '東京タワーは、地上から見上げると物凄い迫力がありますね。', 'When you look at Tokyo Tower from the ground it feels tremendously powerful.'),
  ('00000000-0000-4000-8000-000000007460', '全部ですか。', 'Semuanya?'),
  ('00000000-0000-4000-8000-000000007460', 'わたしのベーコンクッキーを一はこ全部食べちゃったのはだれ！？', 'Siapa yang memakan seluruh kotak kue bacon saya?'),
  ('00000000-0000-4000-8000-000000007460', 'この靴下、全部穴があいていますよ。', 'Semua kaus kaki ini berlubang.'),
  ('00000000-0000-4000-8000-000000007461', '三時になったらおやつ休けいにしましょう。', 'When it’s three o’clock let’s have our afternoon snack break.'),
  ('00000000-0000-4000-8000-000000007461', 'コウイチの家の台どころで二時半にまちあわせね。', 'Let''s meet up at Koichi''s kitchen at 2:30, ok?'),
  ('00000000-0000-4000-8000-000000007461', 'いつも１５時にワニカニのレビューをするんですか？', 'Do you usually do your WaniKani reviews at 3pm?'),
  ('00000000-0000-4000-8000-000000007462', 'このはいゆうは、万人に人気がある。', 'That actor is popular with everyone.'),
  ('00000000-0000-4000-8000-000000007462', 'セキセイインコのにおいは万人にうけるにおいらしい。', 'I heard that everybody likes the smell of parakeets.'),
  ('00000000-0000-4000-8000-000000007462', 'これは万人に共通の感想だろう。', 'This seems to be the common impression among everybody.'),
  ('00000000-0000-4000-8000-000000007464', 'ニッカちゃん、マジ天使だわー。', 'Nikka really is an angel.'),
  ('00000000-0000-4000-8000-000000007464', 'あの天使と、少しきょりをおきたいと思っています。', 'I think I need to distance myself from the angel for a while.'),
  ('00000000-0000-4000-8000-000000007464', '天使のように可愛い女の子に会った。', 'I met a girl who was as cute as an angel.'),
  ('00000000-0000-4000-8000-000000007465', 'ぜんぶで十人いました。', 'There were 10 people, altogether.'),
  ('00000000-0000-4000-8000-000000007465', 'トーフグにはなん人のしゃいんがいますか？', 'How many workers are in Tofugu?'),
  ('00000000-0000-4000-8000-000000007465', 'わたしは三人子どもがいます。', 'I have three children.'),
  ('00000000-0000-4000-8000-000000007472', '新かん線はふつうの電車より速いです。', 'Shinkansen lebih cepat dari kereta biasa.'),
  ('00000000-0000-4000-8000-000000007472', 'ポートランドから東京まで、だれが一番速く泳げるかきょうそうしました。', 'Kami mengadakan kompetisi untuk melihat siapa yang paling cepat berenang dari Portland ke Tokyo.'),
  ('00000000-0000-4000-8000-000000007472', 'うちの家族は、ご飯を食べるのがとても速いです。', 'Di keluarga saya, kami makan malam dengan sangat cepat.'),
  ('00000000-0000-4000-8000-000000007474', 'ぼくは、北海道で雪合戦をしたことがあります。', 'I’ve gone snowball fighting in Hokkaido.'),
  ('00000000-0000-4000-8000-000000007474', '北海道についたどー！本もののすしを食べるどー！', 'I''ve arrived in Hokkaido! Time to eat some real sushi!'),
  ('00000000-0000-4000-8000-000000007474', '北海道のお土産といえば、何が有名でしょうか。', 'Speaking of Hokkaido souvenirs, what’s famous?'),
  ('00000000-0000-4000-8000-000000007475', '新年、明けましておめでとうございます。', 'Selamat tahun baru!'),
  ('00000000-0000-4000-8000-000000007475', '新年のほうふはもう決めましたか？', 'Have you decided your New Year''s resolution yet?'),
  ('00000000-0000-4000-8000-000000007475', '新年の挨拶に、親戚の家を回りました。', 'We went around to our relatives houses exchanging New Year’s greetings.'),
  ('00000000-0000-4000-8000-000000007477', '三足す二は五です。', 'Three plus two is five.'),
  ('00000000-0000-4000-8000-000000007477', 'このスープ、もう少し水を足した方がいいんじゃないかな。', 'Maybe it would be better to add more water to this soup.'),
  ('00000000-0000-4000-8000-000000007477', 'ここにもう少し文章を書き足すことはできますか？', 'Can you add a little more to this sentence here?'),
  ('00000000-0000-4000-8000-000000007478', '玉ねぎとトマトと大こんが要ります。', 'Kamu membutuhkan bawang bombay, tomat, dan lobak.'),
  ('00000000-0000-4000-8000-000000007478', 'ふくろは要りますか？', 'Apakah Anda memerlukan tas?'),
  ('00000000-0000-4000-8000-000000007478', '要るものと要らないものをリストに書き出しなさい。', 'Tuliskan daftar hal-hal yang Anda lakukan dan tidak perlukan.'),
  ('00000000-0000-4000-8000-000000007482', 'ただいま、車両の点けんをしています。', 'Halo, saya sedang memeriksa gerbong kereta.'),
  ('00000000-0000-4000-8000-000000007482', '日本では、車両は左がわを走ります。', 'Di Jepang, kendaraan melaju di sisi kiri jalan.'),
  ('00000000-0000-4000-8000-000000007482', 'この車両は女性専用車両です。', 'Gerbong kereta api ini merupakan gerbong khusus wanita.'),
  ('00000000-0000-4000-8000-000000007487', 'コウイチとスティーヴ・ブシェミのゆめの対談が実げんしました！', 'Impian berbicara Koichi dan Steve Buscemi menjadi kenyataan!'),
  ('00000000-0000-4000-8000-000000007487', 'ざんねんながら、そろそろこの対談をおわらせる時間になってしまいました。', 'Sayangnya, inilah waktunya untuk mengakhiri pembicaraan ini.'),
  ('00000000-0000-4000-8000-000000007487', '有名な作家と対談してみたい。', 'Saya ingin berbicara dengan seorang penulis terkenal.'),
  ('00000000-0000-4000-8000-000000007515', 'らい月の二日に、あねとえいがをみにいきます。', 'I will go see a movie with my older sister on the second day of next month.'),
  ('00000000-0000-4000-8000-000000007515', '王子が子犬をおってふじ山のじゅかいにきえてから二日がたちました。', 'It''s been two days since the prince followed the puppy and disappeared in the woods of Mt. Fuji.'),
  ('00000000-0000-4000-8000-000000007515', 'ひらがななんて、しんけんにべんきょうすれば二日あれば十ぶんさ。', 'If you study diligently, two days is enough to learn hiragana.'),
  ('00000000-0000-4000-8000-000000007517', 'なぜ人々はくるまをかうのでしょうか？', 'Why do people buy cars?'),
  ('00000000-0000-4000-8000-000000007517', 'おおくのパプアニューギニアの人々は水中でもいきができるらしい。', 'I heard that many Papuan people can breathe underwater.'),
  ('00000000-0000-4000-8000-000000007517', 'このちいきの人々は、みんないい人ばかりです。', 'The people in the area are all just good natured people.'),
  ('00000000-0000-4000-8000-000000007518', 'その少女は、ゆうめいなアイドルです。', 'That young lady is a famous idol.'),
  ('00000000-0000-4000-8000-000000007518', '久しぶりに、天才少女ゴルファーがあらわれました。', 'A genius girl golfer has appeared for the first time in a long time.'),
  ('00000000-0000-4000-8000-000000007518', '犬と少女が、はまべをかけていった。', 'The dog and the little girl ran on the beach.'),
  ('00000000-0000-4000-8000-000000007519', '日本へのひこうきだいは、十万五千円でした。', 'The plane ticket to Japan cost 105,000 yen.'),
  ('00000000-0000-4000-8000-000000007519', 'まいとしコウイチは、バレンタインデーに万たんいのチョコレートをもらいます。', 'Every year Koichi receives tens of thousands of chocolates on Valentine''s Day.'),
  ('00000000-0000-4000-8000-000000007519', 'ごしゅうぎのそうばは大たい三万円です。', 'The estimate on a congratulatory gift is approximately 30,000 yen.'),
  ('00000000-0000-4000-8000-000000007520', '赤いネクタイをください。', 'Could I have the red necktie?'),
  ('00000000-0000-4000-8000-000000007520', '今年は赤いマニキュアがはやっています。', 'This year the red nail polish is popular.'),
  ('00000000-0000-4000-8000-000000007520', '赤いニット帽を被った女の子がスケートをしている。', 'The girl wearing the red knit hat is skating.'),
  ('00000000-0000-4000-8000-000000007521', '外では、白いゆきがふっていました。', 'There was white snow falling outside.'),
  ('00000000-0000-4000-8000-000000007521', 'うちの牛は白いのよりもくろいのの方が元気がいい。', 'Our black cows are more energetic than the white ones.'),
  ('00000000-0000-4000-8000-000000007521', 'フワフワで白いウサギが野原でピョンピョン跳ねていました。', 'A fluffy, white rabbit was hopping in the field.'),
  ('00000000-0000-4000-8000-000000007522', '一しゅうかんで、百ページよみました。', 'I read one hundred pages in one week.'),
  ('00000000-0000-4000-8000-000000007522', '王子がレベル百になったら王か女王にてんしょくできますよ。', 'When you get to Level 100, Prince, you can change your job from prince to king or queen.'),
  ('00000000-0000-4000-8000-000000007522', '百円で色々なものが買えるんですね。', 'I can buy a bunch of different things with a hundred yen.'),
  ('00000000-0000-4000-8000-000000007523', 'きんようびの夜に、女子会をします。', 'I’m having a girls-only party on Friday night.'),
  ('00000000-0000-4000-8000-000000007523', 'そのメンバーの会はとてもおも白そうですね。', 'The assembly with those members sounds very interesting.'),
  ('00000000-0000-4000-8000-000000007523', 'この会、また開こうよ！', 'Let’s open this meeting again!'),
  ('00000000-0000-4000-8000-000000007524', 'きのうはどうして早く学校に行きましたか。', 'Why did you go to school early yesterday?'),
  ('00000000-0000-4000-8000-000000007524', 'ゆっくり休んで早くよくなってください。', 'Please get plenty of rest and feel better soon!'),
  ('00000000-0000-4000-8000-000000007524', '早く食べなさい。', 'Eat quickly.'),
  ('00000000-0000-4000-8000-000000007525', 'その死は早すぎました。', 'Their death was too soon.'),
  ('00000000-0000-4000-8000-000000007525', '人は死をのがれることはできない…コウイチい外は。', 'People cannot escape death, except for Koichi.'),
  ('00000000-0000-4000-8000-000000007525', '愛犬の死に打ちひしがれています。', 'I’m stricken with grief over the death of my pet dog.'),
  ('00000000-0000-4000-8000-000000007526', '姉のいえに行くところです。', 'I’m just about to go to my older sister’s house.'),
  ('00000000-0000-4000-8000-000000007526', 'わたしは、姉の五ばいのりょうの本をもっています。', 'I have five times as many books as my older sister does.'),
  ('00000000-0000-4000-8000-000000007526', '姉はスチュワーデスをしています。', 'My big sister works as a stewardess.'),
  ('00000000-0000-4000-8000-000000007527', 'きょう室に入ってください。', 'Come into the classroom, please.'),
  ('00000000-0000-4000-8000-000000007527', 'このゲーム、むずかしすぎるよ。このめんで、１５６９号室まで行くには、どうがんばってもじかんが足りないんだ。', 'This game is too difficult. I never have enough time to get to room number 1569 in this stage no matter how hard I try.'),
  ('00000000-0000-4000-8000-000000007527', '保健室で眠っていました。', 'I was sleeping in the school infirmary.'),
  ('00000000-0000-4000-8000-000000007528', '大きくいきをついてください。', 'Please exhale deeply.'),
  ('00000000-0000-4000-8000-000000007528', 'このトウフ＆フグのピザチェーンは、大きくきぼをかく大している。', 'This Tofu & Fugu pizza chain is expanding its franchise in a big way.'),
  ('00000000-0000-4000-8000-000000007528', '円の価値が大きく上昇した。', 'The value of yen has risen greatly.'),
  ('00000000-0000-4000-8000-000000007529', '今は、学校の近くに、姉とすんでいます。', 'I’m currently living with my sister near the school.'),
  ('00000000-0000-4000-8000-000000007529', 'あのアイドル、近くで見るとあんまりかわいくないね。', 'Seen close up, that teen idol is not pretty at all, huh?'),
  ('00000000-0000-4000-8000-000000007529', '近くの焼き鳥屋で、一杯ひっかけていかないか。', 'Don’t you want to have a drink at the yakitori shop nearby?'),
  ('00000000-0000-4000-8000-000000007530', 'おれはとつぜんカメラを向けられるのが大っきらいなんだよ！', 'Saya memiliki fobia besar terhadap kamera yang tiba-tiba mengarah ke saya.'),
  ('00000000-0000-4000-8000-000000007530', 'スマホじゃなくて子どもに、目を向けてあげてください。', 'Harap alihkan perhatian Anda dari ponsel ke anak Anda.'),
  ('00000000-0000-4000-8000-000000007530', 'その男はゆっくりと俺に銃口を向けた。', 'Pria itu perlahan mengarahkan moncong pistolnya ke arahku.'),
  ('00000000-0000-4000-8000-000000007531', '一生お前といっしょに生きていきたいんだ。', 'I want to live my whole life with you.'),
  ('00000000-0000-4000-8000-000000007531', '女のことお前ってよぶ男本当にきらいだわ。', 'I really hate men who call women "you."'),
  ('00000000-0000-4000-8000-000000007531', 'お前の作る餃子は本当に美味しいな。', 'The gyoza you make is really tasty.'),
  ('00000000-0000-4000-8000-000000007532', '大しきゅう、へんしゅう部の部長をよんでくれないか。', 'Bisakah Anda menghubungi kepala departemen editorial secepatnya?'),
  ('00000000-0000-4000-8000-000000007532', '中学の時は、けん道部でした。', 'Saya tergabung dalam klub kendo saat SMP.'),
  ('00000000-0000-4000-8000-000000007532', '経理部の部長をしています。', 'Saya kepala departemen akuntansi.'),
  ('00000000-0000-4000-8000-000000007533', 'この部分は、何色にしますか？', 'Warna apa yang Anda inginkan untuk bagian ini?'),
  ('00000000-0000-4000-8000-000000007533', 'のうの前の部分の名前って何だっけ？', 'Apa lagi otak bagian depan?'),
  ('00000000-0000-4000-8000-000000007533', 'この映画、共感出来る部分だらけでめちゃくちゃ泣けた。', 'Film itu penuh dengan bagian-bagian yang membuatku bersimpati dan aku menangis sekujur tubuhku.'),
  ('00000000-0000-4000-8000-000000007534', 'かれは千葉県人です。', 'Dia dari Chiba.'),
  ('00000000-0000-4000-8000-000000007534', 'わたしの母は、千葉県さんの落花生が大すきです。', 'Ibuku suka kacang yang dibuat di Chiba.'),
  ('00000000-0000-4000-8000-000000007534', 'ここから千葉までだと、片道1時間30分から2時間ぐらいかかりますね。', 'Biasanya diperlukan waktu satu setengah hingga dua jam untuk sekali jalan dari sini ke Chiba.'),
  ('00000000-0000-4000-8000-000000007535', '思わず本音を口にしてしまいました。', 'I spoke of my real intentions unintentionally.'),
  ('00000000-0000-4000-8000-000000007535', 'コウイチがすんげー大きな音のオナラをしたから、みんな思わず耳をふさいだんだけど、はなをふさいだ方がよかったね。', 'Koichi farted sooooo loudly that everybody reflexively covered their ears, but we should have covered our noses instead.'),
  ('00000000-0000-4000-8000-000000007535', '美味しそうな写真を見て、思わず涎が出た。', 'I saw the delicious looking picture and involuntarily started drooling.'),
  ('00000000-0000-4000-8000-000000007536', '夏には、テラスせきで立ち飲みもできます。', 'In summer you can stand and drink on the terrace.'),
  ('00000000-0000-4000-8000-000000007536', '東京の新ばしえき近辺には立ち飲み屋がたくさんあります。', 'There are a lot of stand-and-drink bars near Shinbashi Station in Tokyo.'),
  ('00000000-0000-4000-8000-000000007536', '昨日、あの立ち飲み屋の後、誰かとやった？', 'Did you get any action last night after leaving the standing bar?'),
  ('00000000-0000-4000-8000-000000007560', 'あなたののうは、ほんとうに人工ののうなんですか？', 'Is your brain really artificial?'),
  ('00000000-0000-4000-8000-000000007560', 'この川は、人工の川です。', 'This river is man-made.'),
  ('00000000-0000-4000-8000-000000007560', 'にわに人工しばをしいてみました。', 'I put artificial turf in the garden.')
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES
  ('00000000-0000-4000-8000-000000007561', 'きのうは一日テストのべんきょうをしていました。', 'I was studying for the test all day yesterday.'),
  ('00000000-0000-4000-8000-000000007561', '六月一日にアメリカ人とフランス人のふうふ二人がいっしょにエベレストをのぼりきったことは人々のきおくにあたらしい。', 'The fact that an American and French couple succeeded to climb Mt. Everest on June 1st is still fresh in people''s memory.'),
  ('00000000-0000-4000-8000-000000007561', '本とうに一日でこの本をよんだんですか？', 'Did you really read this book in one day?'),
  ('00000000-0000-4000-8000-000000007562', 'かぜで、七日かんもねこんでいました。', 'I was in bed for seven whole days because of a cold.'),
  ('00000000-0000-4000-8000-000000007562', 'まい月七日に、おはかまいりをします。', 'I visit our family grave on the 7th of every month.'),
  ('00000000-0000-4000-8000-000000007562', 'たった七日でかいしゃをやめた。', 'I left the company after only seven days.'),
  ('00000000-0000-4000-8000-000000007563', '二人は、せんせん月の三日にどこであいましたか？', 'Where did those two people meet on the third, two months ago?'),
  ('00000000-0000-4000-8000-000000007563', '三日も水をのんでいません。', 'I haven''t had water for three days.'),
  ('00000000-0000-4000-8000-000000007563', '三月三日はひなまつりです。', 'The third day of March is Girl’s Day.'),
  ('00000000-0000-4000-8000-000000007564', '今日は、おげんきですか？', 'Hello, how are you?'),
  ('00000000-0000-4000-8000-000000007564', '「今日は」はひらがなでかくことの方がおおい。', '"Konnichiwa" is often written in hiragana.'),
  ('00000000-0000-4000-8000-000000007564', '大きなこえで、「今日は」といいましょう。', 'Let’s shout, "hello."'),
  ('00000000-0000-4000-8000-000000007565', '二十日にテストがあります。', 'There is a test on the twentieth.'),
  ('00000000-0000-4000-8000-000000007565', 'あと二十日で２０１９年です。', 'It will be 2019 in twenty days.'),
  ('00000000-0000-4000-8000-000000007565', '毎月二十日は給料日です。', 'Payday is the twentieth day of every month.'),
  ('00000000-0000-4000-8000-000000007566', '一とうの牛が草地をのんびり歩いていました。 ', 'Ada seekor sapi berjalan santai di padang rumput.'),
  ('00000000-0000-4000-8000-000000007566', 'アイルランドには、ぼく草地や草地が多い。', 'Ada banyak padang rumput dan padang rumput di Irlandia.'),
  ('00000000-0000-4000-8000-000000007566', 'この金は、あそこの草地に隠そう。', 'Mari kita sembunyikan uang ini di padang rumput sebelah sana.'),
  ('00000000-0000-4000-8000-000000007567', '今回の台風は弱いので、あまり心ぱいしなくてもよさそうです。', 'This typhoon is weak, so it seems that we don’t have to worry too much.'),
  ('00000000-0000-4000-8000-000000007567', 'ひじょうに強い台風トウフ号が、月よう日、西日本に上りくしました。', 'Strong typhoon Tofu made landfall in western Japan on Monday.'),
  ('00000000-0000-4000-8000-000000007567', '大型の台風が日本列島に近づいています。', 'A large typhoon is approaching the Japanese islands.'),
  ('00000000-0000-4000-8000-000000007568', 'わたしは、日本の考古学にきょうみがあります。', 'I’m interested in Japanese archeology.'),
  ('00000000-0000-4000-8000-000000007568', '今月末でこの考古学のしごとをやめるんです。', 'I''m going to quit this archeology job at the end of the month. '),
  ('00000000-0000-4000-8000-000000007568', 'この大学では、考古学を学べます。', 'You can study archeology at this university.'),
  ('00000000-0000-4000-8000-000000007569', 'さい近、地中海りょうりにハマっているんですよね。', 'Lately, I’ve been obsessed with Mediterranean cooking.'),
  ('00000000-0000-4000-8000-000000007569', 'ただ今、地中海からきたく中でーす。', 'I''m on my way home from the Mediterranean Sea.'),
  ('00000000-0000-4000-8000-000000007569', '夏休みに、家族で地中海をクルーズしてきました。', 'I went on a cruise with my family on the Mediterranean Sea over summer vacation.'),
  ('00000000-0000-4000-8000-000000007570', '毎朝、シャワーをあびます。', 'I take a shower every morning'),
  ('00000000-0000-4000-8000-000000007570', '毎朝、本当に楽しかったです。ありがとうございました。', 'I had a really great time with you every morning. Thank you so much.'),
  ('00000000-0000-4000-8000-000000007570', '毎朝ラジオ体操をします。', 'I do radio exercises every morning.'),
  ('00000000-0000-4000-8000-000000007571', '何不自由ない生活をしてるくせに、ぜいたくだよ！', 'Anda telah hidup dalam kenyamanan seperti itu. Anda tidak boleh meminta terlalu banyak.'),
  ('00000000-0000-4000-8000-000000007571', 'このせきは、お年よりや体の不自由な方のためのゆう先ざせきですよ。', 'Ini tempat duduk prioritas untuk lansia dan difabel ya.'),
  ('00000000-0000-4000-8000-000000007571', '私の兄は、足が不自由です。', 'Kaki kakak laki-laki saya cacat.'),
  ('00000000-0000-4000-8000-000000007572', 'あなたは、父さんの教えをしっかりまもって生きるのよ。', 'You keep my father’s teachings alive and well.'),
  ('00000000-0000-4000-8000-000000007572', 'それはすばらしい教えですね。', 'It''s such a great lesson, isn''t it?'),
  ('00000000-0000-4000-8000-000000007572', '君の教えに従うと、ろくなことがない。', 'When I follow your teachings nothing goes well.'),
  ('00000000-0000-4000-8000-000000007573', '表はピンク色にぬってください。', 'Silakan cat bagian depannya dengan warna pink.'),
  ('00000000-0000-4000-8000-000000007573', 'コウイチの表のかおはトーフグ社長であるが、うらのかおは世界でも有数のジャグリングせん手である。', 'Wajah publik Koichi adalah presiden Tofugu, namun wajah pribadinya adalah pemain sulap paling terkenal di dunia.'),
  ('00000000-0000-4000-8000-000000007573', '十円玉の表はどちらですか？', 'Sisi mana dari koin sepuluh yen yang merupakan sisi mukanya?'),
  ('00000000-0000-4000-8000-000000007574', 'なかなか作業がはかどらないんです。', 'I’m not making any progress in my work.'),
  ('00000000-0000-4000-8000-000000007574', 'きのうは、一日中作業ハンドブックを作る作業をしていました。', 'Yesterday, I was working on making an operations handbook all day long.'),
  ('00000000-0000-4000-8000-000000007574', 'あなたのせいで、製造作業が全て停止してしまったってこと、分かっていますか？', 'Do you understand that all manufacturing operations were shut down because of you?'),
  ('00000000-0000-4000-8000-000000007575', 'あっぱくめんせつって、終わった後、ほんと病むよな。', 'Stress interviews make you feel really sick afterwards, don''t you agree?'),
  ('00000000-0000-4000-8000-000000007575', 'しょく場の同りょうは、仕事のストレスが原いんで病んでしまいました。', 'My coworker got sick from work-related stress.'),
  ('00000000-0000-4000-8000-000000007575', 'まさかアイツが心を病むなんてな。', 'I never thought that he would get mentally ill.'),
  ('00000000-0000-4000-8000-000000007614', '九日に、いっしょにサッカーをみにいきませんか。', 'Would you like to go watch some soccer with me on the ninth?'),
  ('00000000-0000-4000-8000-000000007614', 'コウイチは九日もニッカにあっていないので、さびしくてしにそうだ。', 'Since Koichi hasn''t seen Nikka for nine days, he feels so lonely he could die.'),
  ('00000000-0000-4000-8000-000000007614', 'マミのたんじょう日は四月九日だ。', 'Mami’s birthday is April ninth.'),
  ('00000000-0000-4000-8000-000000007615', 'わたしのなつやすみは、八日かんです。', 'My summer break is eight days long.'),
  ('00000000-0000-4000-8000-000000007615', 'すみませんが、水を下さいませんか。もう八日もなにもたべていないんです。', 'Could you please give me some water? I haven''t eaten anything for eight days.'),
  ('00000000-0000-4000-8000-000000007615', 'らい月の八日にじの手じゅつをするよていです。', 'I’m going to get hemorrhoid surgery on the eighth of next month.'),
  ('00000000-0000-4000-8000-000000007616', 'このくすりを、十日かんのんでください。', 'Please take this medicine for ten days.'),
  ('00000000-0000-4000-8000-000000007616', '十日でかんせいさせてください。', 'Please complete it within ten days.'),
  ('00000000-0000-4000-8000-000000007616', '七月十日はそふのめい日です。', 'The tenth of July is the anniversary of my grandfather’s death.'),
  ('00000000-0000-4000-8000-000000007617', 'このゆびわは、一生、大切にします。', 'I will treasure this ring my entire life. '),
  ('00000000-0000-4000-8000-000000007617', 'わたしの父は、しぬまで一生どくしんでした。', 'My father remained single all his life.'),
  ('00000000-0000-4000-8000-000000007617', '一生かけて償います。', 'I’ll make up for it with my life.'),
  ('00000000-0000-4000-8000-000000007618', 'あの国王は、とてもよくばりです。', 'Raja itu sangat rakus.'),
  ('00000000-0000-4000-8000-000000007618', 'わたしは、国王のことをじょじょにりかいしてきました。', 'Saya mulai memahami raja.'),
  ('00000000-0000-4000-8000-000000007618', '18歳という若さで国王になった。', 'Saya menjadi raja saat remaja berusia 18 tahun.'),
  ('00000000-0000-4000-8000-000000007619', '水星には大気がありません。', 'Merkurius tidak memiliki atmosfer.'),
  ('00000000-0000-4000-8000-000000007619', 'こんなはずじゃなかったんですが、もう十年も水星でホームレスをしています。', 'Ini bukan yang saya minta, tapi saya sudah menjadi tunawisma selama 10 tahun di Merkurius.'),
  ('00000000-0000-4000-8000-000000007619', '水星は、日の出直前、または日没直後しか見ることができない。', 'Saya hanya bisa melihat Merkurius sebelum matahari terbit dan setelah matahari terbenam.'),
  ('00000000-0000-4000-8000-000000007620', 'あそこに見えているのは、金星です。', 'Apa yang Anda lihat di sana adalah Venus.'),
  ('00000000-0000-4000-8000-000000007620', '金星の学こうには、うんどう会はありますか？', 'Apakah mereka mengadakan Hari Olahraga di sekolah di Venus?'),
  ('00000000-0000-4000-8000-000000007620', '人類はいつか金星に移住することになるだろう。', 'Suatu saat manusia akan bermigrasi ke Venus.'),
  ('00000000-0000-4000-8000-000000007621', 'このゲーム、ぜったい売れるだろ。', 'This game will definitely sell well.'),
  ('00000000-0000-4000-8000-000000007621', 'その千円札、五百円でネットオークションにかけたら、よゆうで売れるっしょ。', 'I''d say, if you put up the thousand yen bill for online auction, it would easily sell for five hundred yen.'),
  ('00000000-0000-4000-8000-000000007621', '売れる小説の書き方を教えてあげよう。', 'I will teach you how to write novels that sell.'),
  ('00000000-0000-4000-8000-000000007622', '船体にらくがきをしたのはだれだ！？', 'Siapa yang membuat coretan lambung kapal?'),
  ('00000000-0000-4000-8000-000000007622', 'クラーケンがしょく手で船体をつきやぶったんだ。', 'Kraken itu menghancurkan tentakelnya melalui lambung kapal.'),
  ('00000000-0000-4000-8000-000000007622', '船体は思った以上に大きかった。', 'Lambungnya lebih besar dari yang saya kira.'),
  ('00000000-0000-4000-8000-000000007623', 'こんな当たり前のこと、どうして分からないの？', 'Ini adalah hal yang normal, mengapa Anda tidak bisa mendapatkannya?'),
  ('00000000-0000-4000-8000-000000007623', 'でも、これが当たり前のことだとは思わないでくださいね。', 'Namun, jangan anggap remeh.'),
  ('00000000-0000-4000-8000-000000007623', '今日のような当たり前の日をすごせることに、かんしゃしなきゃいけませんよね。', 'Bukankah kita harusnya bersyukur bisa menjalani hari biasa seperti hari ini.'),
  ('00000000-0000-4000-8000-000000007624', 'この水道の水は、のんでも平気ですよ。', 'This tap water is safe to drink.'),
  ('00000000-0000-4000-8000-000000007624', '水道代がはらえなかったので、水道が止められてしまいました。', 'I couldn''t pay the water bill, so my water was shut off.'),
  ('00000000-0000-4000-8000-000000007624', '水道が凍結してしまいました。', 'The water line froze.'),
  ('00000000-0000-4000-8000-000000007625', 'この付近に、コンビニはありますか？', 'Apakah lingkungan ini memiliki toko serba ada?'),
  ('00000000-0000-4000-8000-000000007625', '付近には、外国人見物客もたくさんいました。', 'Ada banyak penonton asing di dekatnya juga.'),
  ('00000000-0000-4000-8000-000000007625', 'この付近に公衆便所はありますか。', 'Apakah ada toilet umum di lingkungan ini?'),
  ('00000000-0000-4000-8000-000000007628', '病じょうがあっ化し、入院する事になりました。', 'His condition deteriorated and they decided he''s to be hospitalized.'),
  ('00000000-0000-4000-8000-000000007628', '入院中は、たいくつであくびが止まらなかったよ。', 'While I was hospitalized, I was so bored that I couldn''t stop yawning.'),
  ('00000000-0000-4000-8000-000000007628', '今度、乳癌で入院することになったんです。', 'I''m going to be hospitalized due to breast cancer soon.'),
  ('00000000-0000-4000-8000-000000007629', 'きのうは風が強かったので、木から葉が全部落ちてしまいました。', 'Kemarin angin kencang sekali hingga daun-daun di pepohonan berguguran.'),
  ('00000000-0000-4000-8000-000000007629', 'あきになって、木の葉の色が色んな色にかわってきた。', 'Di musim gugur, dedaunan di pepohonan berubah warna.'),
  ('00000000-0000-4000-8000-000000007629', '大根の葉でふりかけを作りました。', 'Saya membuat furikake dengan daun daikon.'),
  ('00000000-0000-4000-8000-000000007668', '大いにまなびましょう。', 'Let’s learn a lot!'),
  ('00000000-0000-4000-8000-000000007668', '王は王子と王女に、「大いにこくみんのぜいきんをつかっていいぞ」といった。', 'The king said to the prince and the princess, "Go ahead and use a lot of the citizens'' tax money."'),
  ('00000000-0000-4000-8000-000000007668', 'きょうは大いにのみたまえ。', 'Please drink a lot today.'),
  ('00000000-0000-4000-8000-000000007669', 'なにも用がない。', 'I have nothing to do.'),
  ('00000000-0000-4000-8000-000000007669', 'なにかご用ですか？', 'Do you need me for something?'),
  ('00000000-0000-4000-8000-000000007669', '用もないのにでんわしてくんじゃねーよ。', 'Don’t call me unless you have a reason.'),
  ('00000000-0000-4000-8000-000000007670', 'かの女が花をつむ仕草が大すきです。', 'Saya suka melihatnya memetik bunga.'),
  ('00000000-0000-4000-8000-000000007670', 'うちのクラスの先生は、仕草がいつも大げさだ。', 'Guru kelas kami selalu melebih-lebihkan gerak-geriknya.'),
  ('00000000-0000-4000-8000-000000007670', '煙草を吸う大人の仕草にドキッとした。', 'Saya terkejut dengan perilaku orang dewasa yang merokok.'),
  ('00000000-0000-4000-8000-000000007671', 'あごひげがよく生えます。', 'My beard grows quickly.'),
  ('00000000-0000-4000-8000-000000007671', '「くさ生える」とは、おもしろいとおもったときにつかう日本のネットスラングで、「w」をくさに見立てたことからつかわれはじめました。', '"Weeds grow," is Japanese Internet slang used when you think something''s funny. It started because "w" (lol) looks like weeds.'),
  ('00000000-0000-4000-8000-000000007671', 'こんなところにキノコが生えるのかね。', 'Do mushrooms grow in places like this?'),
  ('00000000-0000-4000-8000-000000007672', 'です・ます形ではなしをするとていねいにきこえます。', 'Saat Anda berbicara menggunakan bentuk desu dan masu, Anda terdengar sopan.'),
  ('00000000-0000-4000-8000-000000007672', 'ひてい形から会わに入る人はコミュしょうのかのうせいがたかい。', 'Seseorang yang memulai percakapan dengan kalimat berbentuk negatif kemungkinan besar akan mengalami kesulitan dalam berkomunikasi dengan orang lain.'),
  ('00000000-0000-4000-8000-000000007672', 'どうして今、過去形で言ったの？', 'Mengapa kamu hanya mengatakan itu dalam bentuk lampau?'),
  ('00000000-0000-4000-8000-000000007673', 'どれが土星か、分かりますか。', 'Tahukah Anda yang mana Saturnus?'),
  ('00000000-0000-4000-8000-000000007673', '土星にはどうやって行けばいいですか？', 'Bagaimana cara menuju Saturnus?'),
  ('00000000-0000-4000-8000-000000007673', '私は土星出身の宇宙人です。', 'Saya alien dari Saturnus.'),
  ('00000000-0000-4000-8000-000000007674', 'この町は、とても活気があります。', 'Kota ini sangat ramai.'),
  ('00000000-0000-4000-8000-000000007674', 'ニッカはいつも活気にあふれている。', 'Nikka selalu penuh energi.'),
  ('00000000-0000-4000-8000-000000007674', '市場は活気にあふれていた。', 'Pasar dipenuhi dengan energi.'),
  ('00000000-0000-4000-8000-000000007675', 'おきゃくさまのおへやは、302号室になります。', 'Kamarmu 302.'),
  ('00000000-0000-4000-8000-000000007675', 'このマンションの444号室はゆうれいが出ることで有名です。', 'Kamar 444 apartemen ini terkenal berhantu.'),
  ('00000000-0000-4000-8000-000000007675', '102号室の坂本と申します。', 'Saya Sakamoto dari kamar 102.'),
  ('00000000-0000-4000-8000-000000007676', '大空を見ていたら、いやな気もちがふきとんだ。', 'The unpleasant feeling vanished when I looked up at the sky.'),
  ('00000000-0000-4000-8000-000000007676', 'アイリちゃんは大空にうかぶお星さまになったんだよ。', 'Airi became a star in the firmament.'),
  ('00000000-0000-4000-8000-000000007676', '鷲が大空を悠々と飛んでいた。', 'The eagle flew leisurely in the heavens.'),
  ('00000000-0000-4000-8000-000000007677', 'さいふが見当たりません。', 'Saya tidak dapat menemukan dompet saya.'),
  ('00000000-0000-4000-8000-000000007677', 'さがしたけど、どこにも見当たらなかったんです。', 'Saya mencarinya, tetapi tidak dapat menemukannya di mana pun.'),
  ('00000000-0000-4000-8000-000000007677', '俺の老眼鏡が見当たらないんだ。', 'Saya tidak dapat menemukan kacamata baca saya.'),
  ('00000000-0000-4000-8000-000000007678', 'どうすれば、三角形のオニギリをにぎれるんですか？', 'Bagaimana cara membuat onigiri menjadi segitiga?'),
  ('00000000-0000-4000-8000-000000007678', '夏の夜空には、天の川をはさんでことざとわしざと白鳥ざの一とう星をむすんだ大三角形が広がります。', 'Sebuah segitiga besar, terdiri dari tiga bintang berkekuatan besar dari Lyra, Aquila, dan Cygnus, terbentang di langit malam musim panas.'),
  ('00000000-0000-4000-8000-000000007678', 'そこには、三角形の公園があります。', 'Ada taman segitiga di sana.'),
  ('00000000-0000-4000-8000-000000007679', 'このどうしの活用形を教えてください。', 'Tolong ajari aku bentuk terkonjugasi dari kata kerja ini.'),
  ('00000000-0000-4000-8000-000000007679', '昨日から、じょどうしの活用形をべんきょうし直してます。', 'Kemarin, aku mulai mempelajari kembali bentuk terkonjugasi dari kata kerja bantu.'),
  ('00000000-0000-4000-8000-000000007679', 'この辞書アプリでは、活用形から動詞の逆引き検索も可能です。', 'Di aplikasi kamus ini, kamu bisa mencari kata kerja menggunakan bentuk terkonjugasinya.'),
  ('00000000-0000-4000-8000-000000007680', '役場でしょう明しょをもらってきてください。', 'Silakan dapatkan sertifikat dari balai kota.'),
  ('00000000-0000-4000-8000-000000007680', '役場のかべ紙は、かべからはがれてきています。', 'Wallpaper balai kota terkelupas dari dinding.'),
  ('00000000-0000-4000-8000-000000007680', '役場に行って転出届を出してきたよ。', 'Saya pergi ke balai kota dan menyerahkan informasi perubahan alamat saya.'),
  ('00000000-0000-4000-8000-000000007681', '電気を点けてくれ。', 'Nyalakan lampu.'),
  ('00000000-0000-4000-8000-000000007681', 'ラジオの点け方が分かりません。', 'Saya tidak tahu cara menyalakan radio.'),
  ('00000000-0000-4000-8000-000000007681', 'テレビを点けてもらえますか。', 'Bisakah Anda menyalakan TV?'),
  ('00000000-0000-4000-8000-000000007682', '人生には本当に大切なしゅん間が何度かおとずれる。', 'We all have really important moments, a few times in our lives.'),
  ('00000000-0000-4000-8000-000000007682', 'トーフグは、おなかが空いたサメに食べられそうになったことが何度もある。', 'Tofugu has almost been eaten by the hungry shark many times.'),
  ('00000000-0000-4000-8000-000000007682', '何度同じことを言えば分かるんだ？', 'How many times do I have to say the same thing before you understand?'),
  ('00000000-0000-4000-8000-000000007683', 'マイケルは魚よりも泳ぎが上手です。', 'Renang Michael lebih baik dari pada ikan!'),
  ('00000000-0000-4000-8000-000000007683', 'カエルの泳ぎにあこがれて必死に平泳ぎをれんしゅうしていたら、手と足がほそ長くなりました。', 'Saya mengagumi renang katak, jadi saya dengan panik berlatih gaya dada hingga lengan dan kaki saya bertambah panjang.'),
  ('00000000-0000-4000-8000-000000007683', '泳ぎはあまり得意ではありません。', 'Saya tidak pandai berenang.'),
  ('00000000-0000-4000-8000-000000007684', 'わたしは、アメリカの教いくについて、記事をかきました。', 'Saya menulis artikel tentang pendidikan Amerika.'),
  ('00000000-0000-4000-8000-000000007684', 'クリスティンの記事、今月号のナショナル・ジオグラフィックで見たよ！', 'Kristen, saya baru saja menemukan artikel Anda di majalah National Geographic bulan ini!'),
  ('00000000-0000-4000-8000-000000007684', 'この記事はデタラメだ。', 'Berita ini tidak masuk akal.'),
  ('00000000-0000-4000-8000-000000007685', 'かの女は口調がキツイのでちょっと苦手です。', 'Saya tidak terlalu menyukainya karena nadanya yang kasar.'),
  ('00000000-0000-4000-8000-000000007685', 'コウイチは、とてもきびしい口調で、「うんも実力のうちだ」と言った。', 'Koichi berkata dengan suara yang sangat tegas bahwa keberuntungan hanyalah sebagian dari bakatnya.'),
  ('00000000-0000-4000-8000-000000007685', '厳しい口調で責め立てられた。', 'Dia memarahiku dengan nada kasar.'),
  ('00000000-0000-4000-8000-000000007686', '次のセミナーでは、何について語る予定ですか？', 'What do you plan to talk about at the next seminar?'),
  ('00000000-0000-4000-8000-000000007686', '田中さん、時間がないので、ぼうけんだんを語るのはこの辺で止めてください。', 'Mr. Tanaka, time is up, so please wrap up your adventure tale.'),
  ('00000000-0000-4000-8000-000000007686', 'この事件を人に語ることはできない。', 'I can’t talk about this case with people.'),
  ('00000000-0000-4000-8000-000000007728', '水中でしか使えない。', 'It can only be used underwater.'),
  ('00000000-0000-4000-8000-000000007728', '右をみると、水中のせかいがひろがっていました。', 'When I looked to the right, there was an underwater world in front of me.'),
  ('00000000-0000-4000-8000-000000007728', '水中でめをあけることができません。', 'I can’t open my eyes underwater.'),
  ('00000000-0000-4000-8000-000000007729', 'わたしは、そのうたを丸ごとあんきしています。', 'Saya menghafal keseluruhan lagunya.'),
  ('00000000-0000-4000-8000-000000007729', 'その牛、半分だけじゃなくて丸ごと一とう下さい。', 'Tolong beri saya seluruh sapi, bukan setengahnya.'),
  ('00000000-0000-4000-8000-000000007729', 'このケーキには林檎が丸ごと入っています。', 'Kue ini seluruhnya diisi dengan apel.'),
  ('00000000-0000-4000-8000-000000007730', '今日は、日本の外交についてはなしあいをしました。', 'Kami membahas diplomasi Jepang hari ini.'),
  ('00000000-0000-4000-8000-000000007730', '外交かんが不足している。', 'Kita kekurangan diplomat.'),
  ('00000000-0000-4000-8000-000000007730', '日本は外交があまり上手ではない。', 'Jepang tidak pandai dalam diplomasi.'),
  ('00000000-0000-4000-8000-000000007731', 'わたしは日本人ですが、生まれはサンフランシスコです。', 'I’m Japanese, but I was born in San Francisco.'),
  ('00000000-0000-4000-8000-000000007731', 'つまは、アメリカ生まれの日本人なんです。', 'My wife is American-born Japanese.'),
  ('00000000-0000-4000-8000-000000007731', '生まれは大阪ですが、育ちは奈良です。', 'My birthplace is Osaka, but I was raised in Nara.'),
  ('00000000-0000-4000-8000-000000007732', '地中は、冬にはあたたかく、なつはつめたいです。', 'Underground it’s warm in the winter and cold in the summer.'),
  ('00000000-0000-4000-8000-000000007732', '多くのみずうみは、地中の水ろでつながっています。', 'Many of the lakes are connected by subterranean channels.'),
  ('00000000-0000-4000-8000-000000007732', '地中の温度を測るにはどうすればいいですか。', 'What do I need to do to gauge the temperature underground?'),
  ('00000000-0000-4000-8000-000000007733', '今日は、どうしの活用をべんきょうします。', 'Hari ini kita akan belajar konjugasi kata kerja.'),
  ('00000000-0000-4000-8000-000000007733', 'ちょこっとあいたじかんを活用して、ワニカニで日本ごをべんきょうします。', 'Saya memanfaatkan sedikit waktu dan belajar bahasa Jepang di WaniKani.'),
  ('00000000-0000-4000-8000-000000007733', 'このデータをうまく活用して、何かできないかな。', 'Saya tidak tahu apakah saya dapat memanfaatkan data ini dengan baik.'),
  ('00000000-0000-4000-8000-000000007734', '一体どうなっているんだ。', 'What the heck is going on?'),
  ('00000000-0000-4000-8000-000000007734', '「あいとにくしみはひょうり一体」って、一体全体どういういみなんだ！？', 'What the heck does, "There''s a thin line between love and hate," mean?'),
  ('00000000-0000-4000-8000-000000007734', '一体俺が何をしたって言うんだよ？', 'What the heck did you say I did?'),
  ('00000000-0000-4000-8000-000000007735', '二人とも、どうして小声ではなしているの？', 'Mengapa mereka berdua berbisik?'),
  ('00000000-0000-4000-8000-000000007735', '「ビエトに学ランをきてもらいたいんだ。に合うと思うんだよね。」と、わたしのもうそうの中でコウイチがビエトに小声で言った。', '“Aku ingin kamu mencoba seragam sekolah. Menurutku kamu akan terlihat bagus jika memakainya.” Koichi berbisik pada Viet dalam fantasiku.'),
  ('00000000-0000-4000-8000-000000007735', '男は、小声で話し始めた。', 'Pria itu mulai berbicara dengan suara rendah.'),
  ('00000000-0000-4000-8000-000000007736', 'その辺に、ホテルはありますか。', 'Apakah ada hotel di sekitar sana?'),
  ('00000000-0000-4000-8000-000000007736', 'あの辺はごう雪地たいです。', 'Mereka mengalami hujan salju yang sangat lebat di wilayah itu.'),
  ('00000000-0000-4000-8000-000000007736', '今日はこの辺で、終わりにします。', 'Saya akan mengakhirinya di sini untuk hari ini.'),
  ('00000000-0000-4000-8000-000000007737', 'おれのゆう者としての役目は、もうおわったんだ。', 'Tugasku sebagai pahlawan sudah berakhir.'),
  ('00000000-0000-4000-8000-000000007737', 'サラさん、来客のめんどうを見るのはあなたの役目でしょう？', 'Sarah, urusanmu mengurus pengunjung, kan?'),
  ('00000000-0000-4000-8000-000000007737', '役目を果たせなかったことを残念に思っています。', 'Sayangnya, aku tidak bisa memenuhi tugasku.'),
  ('00000000-0000-4000-8000-000000007738', 'マリメッコの生地でクッションを作りました。', 'I made a cushion out of Marimekko fabric.'),
  ('00000000-0000-4000-8000-000000007738', 'このカーテンは、パラシュート生地でできています。', 'This curtain is made of parachute material.'),
  ('00000000-0000-4000-8000-000000007738', '冷凍のパイ生地を買ってきてください。', 'Please go buy a frozen piecrust.'),
  ('00000000-0000-4000-8000-000000007740', '火事があった場所は、アパートの五かいです。', 'The fire was on the fifth floor of the apartment.'),
  ('00000000-0000-4000-8000-000000007740', '何か臭うんだけど。もしかして、火事じゃない？', 'I smell something strange! Maybe a fire?'),
  ('00000000-0000-4000-8000-000000007740', '昨日、家が火事になる夢を見たんです。', 'Yesterday I had a dream that my house caught on fire.'),
  ('00000000-0000-4000-8000-000000007741', 'ガラスは光を通します。', 'Glass lets light pass through it.'),
  ('00000000-0000-4000-8000-000000007741', 'お肉には、しっかり火を通してください。', 'Please heat the meat thoroughly.'),
  ('00000000-0000-4000-8000-000000007741', '針に糸を通すのは難しい。', 'Threading a needle is difficult.'),
  ('00000000-0000-4000-8000-000000007742', '母は、台所でりょうりをしています。', 'Ibuku sedang memasak di dapur.'),
  ('00000000-0000-4000-8000-000000007742', 'マイケルの家の台所にはなっとうの空きばこが三百万八千九百十七こおいてあるんだって。', 'Kudengar di dapur Michael, ada 3.008.917 kotak natto kosong.'),
  ('00000000-0000-4000-8000-000000007742', '台所から焦げ臭い臭いがするよ。', 'Aku mencium sesuatu yang terbakar di dapur.'),
  ('00000000-0000-4000-8000-000000007743', '日よう日、小麦のしゅうかくを体験しに、農場へ行ってきました。', 'Saya pergi ke pertanian pada hari Minggu untuk menikmati panen gandum.'),
  ('00000000-0000-4000-8000-000000007743', '農場で、引きつづきはたらかないかと聞かれました。', 'Saya ditanya apakah saya ingin tetap bekerja di pertanian.'),
  ('00000000-0000-4000-8000-000000007743', 'オーガニック農場を始めるつもりです。', 'Saya berencana memulai pertanian organik.'),
  ('00000000-0000-4000-8000-000000008659', 'さとうさんの犬は、とても大人しいです。', 'Satou’s dog is very obedient.'),
  ('00000000-0000-4000-8000-000000008659', 'なんなのアイツ。がっこうでは大人しいいんキャのくせに。', 'What''s with that guy? He''s just a quiet nerd at school.'),
  ('00000000-0000-4000-8000-000000008659', '大人しい子どもだったよ。', 'He was a quiet kid.'),
  ('00000000-0000-4000-8000-000000008660', '母は、デパートへかいものに出かけました。', 'Mom went out shopping at the department store.'),
  ('00000000-0000-4000-8000-000000008660', 'おっとが子どもをつれて出かけたので、今日はドラクエ三まいです。', 'Since my husband went out with kids, I can play Dragon Quest as much as I want.'),
  ('00000000-0000-4000-8000-000000008660', '日曜日は家族で海に出かけるの。', 'I’m going out to the beach with my family on Sunday.'),
  ('00000000-0000-4000-8000-000000008661', '大体あっています。', 'That’s about right.'),
  ('00000000-0000-4000-8000-000000008661', '大体同じぐらいのせです。', 'We are about the same height.'),
  ('00000000-0000-4000-8000-000000008661', '私は大体6時に起きます。', 'I generally get up at 6 o’clock.'),
  ('00000000-0000-4000-8000-000000008662', '海王星は、太ようから八ばん目のわく星です。', 'Neptunus adalah planet kedelapan dari matahari.'),
  ('00000000-0000-4000-8000-000000008662', '海王星に行くことをずっとゆめ見てきたんです。', 'Saya selalu bermimpi pergi ke Neptunus.')
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES
  ('00000000-0000-4000-8000-000000008662', '海王星は1846年9月23日に発見されました。', 'Neptunus ditemukan pada tanggal 23 September 1846.'),
  ('00000000-0000-4000-8000-000000008663', '五千円以下の本だなをさがしています。', 'I’m looking for a bookshelf that’s 5,000 yen or less.'),
  ('00000000-0000-4000-8000-000000008663', 'コウイチのすきなネコのしゅるいは以下の通りです。', 'The list of cat breeds that Koichi likes is as follows:'),
  ('00000000-0000-4000-8000-000000008663', '以下同文です。', 'Those below are the same.'),
  ('00000000-0000-4000-8000-000000008664', 'この番組はおも白くありませんでしたが、わたしのすきなはいゆうが出ていました。', 'Acara TV ini tidak menarik, tapi aktor favoritku ada di dalamnya.'),
  ('00000000-0000-4000-8000-000000008664', 'きのうの番組で、あの二人はついに両しゃがなっとくするだきょうあんにたどりついたよ。', 'Dalam acara kemarin, keduanya akhirnya berhasil mencapai kompromi.'),
  ('00000000-0000-4000-8000-000000008664', '最近はバラエティ番組しか見ません。', 'Aku belum menonton apa pun kecuali variety show akhir-akhir ini.'),
  ('00000000-0000-4000-8000-000000008665', 'そのまんがなら、部室に全かんそろってるよ。', 'Sedangkan untuk manga itu, kami memiliki seluruh serinya di ruang klub.'),
  ('00000000-0000-4000-8000-000000008665', '何ぜか部室に魚を口にくわえたネコがいるんです。', 'Entah kenapa, ada seekor kucing dengan ikan di mulutnya di ruang klub.'),
  ('00000000-0000-4000-8000-000000008665', '部室に忘れ物をしちゃった。', 'Aku lupa sesuatu di ruang klub.'),
  ('00000000-0000-4000-8000-000000008666', '大学院をそつぎょうしたんだけど、仕事が見つからないんだ。', 'I graduated from grad school, but I can’t find a job.'),
  ('00000000-0000-4000-8000-000000008666', 'この大学院の自どうはん売きは、つめたい飲み物しか売っていません。', 'You can only buy cold drinks from the vending machines at this grad school.'),
  ('00000000-0000-4000-8000-000000008666', '私は大学院進学を考えております。', 'I’m thinking about going to graduate school.'),
  ('00000000-0000-4000-8000-000000008693', 'それは大いにてんきに左右される。', 'That really depends on the weather.'),
  ('00000000-0000-4000-8000-000000008693', 'ビエトのサスペンダー、左右のいろがちがっていておしゃれだね。', 'Viet''s suspenders have different colors on the right and the left, it''s so fashionable!'),
  ('00000000-0000-4000-8000-000000008693', 'みちをわたるまえに、左右をよくたしかめましょう。', 'Make sure you look both ways before crossing the street.'),
  ('00000000-0000-4000-8000-000000008694', '大気おせんマップを毎日チェックしています。', 'I check the atmospheric pollution map everyday.'),
  ('00000000-0000-4000-8000-000000008694', 'そらがあおいのは、ちきゅうの大気の分子があおとみどりのひかりをさんらんするからです。', 'The sky is blue because blue and green lights are scattered in all directions by the air molecules in Earth''s atmosphere.'),
  ('00000000-0000-4000-8000-000000008694', '今日も、ぜんこく的に大気のじょうたいがふあんていです。', 'Air conditions are unstable nationwide again today.'),
  ('00000000-0000-4000-8000-000000008695', '今すぐ町民をひなんさせるべきです！', 'Penduduk kota harus mencari perlindungan sekarang juga!'),
  ('00000000-0000-4000-8000-000000008695', 'この町民たちは、みんなちゃんと後かた付けができる。', 'Semua penduduk kota ini mampu membersihkan diri mereka sendiri.'),
  ('00000000-0000-4000-8000-000000008695', 'この町の人達はみんな、この町の町民であることを誇りに思っています。', 'Saya merasa semua orang di kota ini membanggakan diri sebagai warga kota di sini.'),
  ('00000000-0000-4000-8000-000000008696', '文学をよむいみとは何だろうか。', 'What’s the significance of reading literature?'),
  ('00000000-0000-4000-8000-000000008696', 'わたしは大学で、イギリス文学をせんこうしていました。', 'I was majoring in English literature in university.'),
  ('00000000-0000-4000-8000-000000008696', '村上春樹の作品は、純文学のふりをした大衆文学だと思います。', 'I think Haruki Murakami''s work is pop literature pretending to be pure literature.'),
  ('00000000-0000-4000-8000-000000008697', 'ルーターのさいきどうの仕方を知っていますか？', 'Do you know how to reboot the router?'),
  ('00000000-0000-4000-8000-000000008697', 'あなたも知っているように、コウイチはロボットです。', 'As you know, Koichi is a robot.'),
  ('00000000-0000-4000-8000-000000008697', '新聞で白黒ダートルの発見を知った。', 'I found out about the discovery of a black and white durtle in the newspaper.'),
  ('00000000-0000-4000-8000-000000008698', '来週の日よう日にレストランに行きます。', 'I’m going to a restaurant next Sunday.'),
  ('00000000-0000-4000-8000-000000008698', '来週はどれぐらい雪がふるかな？', 'I wonder how much snow we''ll get next week.'),
  ('00000000-0000-4000-8000-000000008698', '飲み会は来週に延期になりました。', 'The drinking party was postponed until next week.'),
  ('00000000-0000-4000-8000-000000008699', 'とくいな科目とにが手な科目を教えてください。', 'Ceritakan tentang subjek kuat dan subjek lemah Anda.'),
  ('00000000-0000-4000-8000-000000008699', '多分、その科目、さいじゅこうしないといけないと思う。', 'Saya mungkin harus mengambil kembali kursus itu.'),
  ('00000000-0000-4000-8000-000000008699', '好きな科目は何ですか？', 'Mata pelajaran apa yang kamu suka?'),
  ('00000000-0000-4000-8000-000000008701', 'かわらでなぞの生物を発見した。', 'A mysterious creature was discovered at a dry river bed.'),
  ('00000000-0000-4000-8000-000000008701', '地きゅう上でもっとも大きい生物はシロナガスクジラではなく、シロナガスフグです。', 'The largest living thing on the planet isn''t blue whale but blue blowfish.'),
  ('00000000-0000-4000-8000-000000008701', 'こないだの生物の授業のノート、見せてくれないかな。', 'Can I see your notes from the other day in Bio?'),
  ('00000000-0000-4000-8000-000000008702', '家事、本当にめんどくさいけど、がんばる。', 'Housework is really annoying, but I’ll do my best.'),
  ('00000000-0000-4000-8000-000000008702', '主人はいつもわたしにばかり家事をおし付けてくるから本当にこまります。', 'My husband has me do chores all the time and I''m not happy about it at all.'),
  ('00000000-0000-4000-8000-000000008702', '家事全般が苦手なんですよね。', 'I’m bad at all of the housework.'),
  ('00000000-0000-4000-8000-000000008703', '今朝、くすりを飲むのをわすれました。', 'I forgot to take my medicine this morning.'),
  ('00000000-0000-4000-8000-000000008703', '今朝から両足がいたくて思うように歩けません。', 'My legs have been hurting since I woke up this morning, so I can''t move as much as I''d like.'),
  ('00000000-0000-4000-8000-000000008703', '今朝ここで玉突き事故があったんだ。', 'This morning there was a multi-vehicle accident here.'),
  ('00000000-0000-4000-8000-000000008733', 'データの入力をおえました。', 'I finished inputting the data.'),
  ('00000000-0000-4000-8000-000000008733', 'ここに王子のソーシャルセキュリティーナンバーを入力してください。', 'Please enter the prince''s social security number here.'),
  ('00000000-0000-4000-8000-000000008733', '「ローマじ入力」と「かな入力」、どちらをつかっていますか？', 'Do you use "romaji input" or "kana input"?'),
  ('00000000-0000-4000-8000-000000008734', '戸をたたかないでください。', 'Tolong jangan mengetuk pintu.'),
  ('00000000-0000-4000-8000-000000008734', 'うちのねこは戸をカリカリするのがすきです。', 'Kucing saya suka menggaruk pintu.'),
  ('00000000-0000-4000-8000-000000008734', 'この戸は立てつけがわるい。', 'Pintu ini membuka dan menutup dengan keras.'),
  ('00000000-0000-4000-8000-000000008735', 'わたしは女の人にいじめられた。', 'I was bullied by a woman.'),
  ('00000000-0000-4000-8000-000000008735', 'そのカフェは女の人だらけでした。', 'The cafe was full of women.'),
  ('00000000-0000-4000-8000-000000008735', '女の人としゃべるのが苦手です。', 'I’m not good at talking to women.'),
  ('00000000-0000-4000-8000-000000008736', 'このサイトは本来かめのせいそくちとしてつかわれていた。', 'This site was originally used as a turtle habitat.'),
  ('00000000-0000-4000-8000-000000008736', 'その言ばの本来のいみをしっていますか。', 'Do you know the original meaning of that word?'),
  ('00000000-0000-4000-8000-000000008736', '本来漢字は悪いものではない。', 'Kanji in and of itself isn’t a bad thing.'),
  ('00000000-0000-4000-8000-000000008737', 'ころんで手首をひねった。', 'Aku terjatuh dan pergelangan tanganku terkilir.'),
  ('00000000-0000-4000-8000-000000008737', 'あぶらが手首にはねてヤケドしてしまった。', 'Minyak panas memercik ke pergelangan tangan saya dan saya terbakar.'),
  ('00000000-0000-4000-8000-000000008737', '双子の妹には、手首にホクロがあるんだ。', 'Adik kembarku mempunyai tahi lalat di pergelangan tangannya.'),
  ('00000000-0000-4000-8000-000000008738', '星がきらきら光っている。', 'Bintang-bintang bersinar.'),
  ('00000000-0000-4000-8000-000000008738', '右のくつに、光るとりょうが付いてるよ。', 'Ada cat berkilauan di sepatu kanan Anda.'),
  ('00000000-0000-4000-8000-000000008738', 'あそこで確かに何かが光るのを見たんだ。', 'Saya yakin saya melihat sesuatu yang bersinar di sana.'),
  ('00000000-0000-4000-8000-000000008739', '数年がすぎさった。', 'Beberapa tahun berlalu.'),
  ('00000000-0000-4000-8000-000000008739', '数年前まで、日本に住んでいました。', 'Saya tinggal di Jepang sampai beberapa tahun yang lalu.'),
  ('00000000-0000-4000-8000-000000008739', 'この絵が完成するには、あと数年かかります。', 'Diperlukan waktu beberapa tahun untuk menyelesaikan lukisan itu.'),
  ('00000000-0000-4000-8000-000000008740', 'みなさんは絵文字はつかいますか？', 'Apakah Anda semua menggunakan emoji?'),
  ('00000000-0000-4000-8000-000000008740', 'しいて言えば、この絵文字がすきです。', 'Jika saya harus memilih, saya suka emoji ini.'),
  ('00000000-0000-4000-8000-000000008740', '一番よく使う絵文字を教えてください。', 'Bisakah Anda memberi tahu saya emoji mana yang paling sering Anda gunakan?'),
  ('00000000-0000-4000-8000-000000008741', 'このかん字の部首は何ですか？', 'Apa radikal kanji ini?'),
  ('00000000-0000-4000-8000-000000008741', '部首をわらうものは部首になく。', 'Seseorang yang menertawakan kaum radikal pada akhirnya akan menangisi kaum radikal.'),
  ('00000000-0000-4000-8000-000000008741', '私は全部の部首を覚えています。', 'Saya ingat semua radikal.'),
  ('00000000-0000-4000-8000-000000008742', '近所の人はしずかですか？', 'Apakah tetangganya tenang?'),
  ('00000000-0000-4000-8000-000000008742', 'トーフグのオフィスの近所には、おしゃれなお店が多く集まっています。', 'Banyak toko mewah berkumpul di sekitar kantor Tofugu.'),
  ('00000000-0000-4000-8000-000000008742', '近所にコインランドリーがあるわよ。', 'Ada binatu di lingkungan ini.'),
  ('00000000-0000-4000-8000-000000008743', 'わたしは足し算ができない。', 'Saya tidak bisa melakukan penambahan.'),
  ('00000000-0000-4000-8000-000000008743', 'その足し算コンテストに、かん客としてさんかすることはできますか？', 'Bisakah saya berpartisipasi dalam kontes penambahan sebagai penonton?'),
  ('00000000-0000-4000-8000-000000008743', '今日、学校で足し算の勉強をしました。', 'Hari ini kami belajar penjumlahan di sekolah.'),
  ('00000000-0000-4000-8000-000000008744', 'もちろん、わたしは引き算ができます！', 'Tentu saja saya bisa melakukan pengurangan!'),
  ('00000000-0000-4000-8000-000000008744', 'この引き算のじゅぎょうは長すぎて、あくびが止まりません。', 'Kelas pengurangan sangat lama sehingga saya tidak bisa berhenti menguap.'),
  ('00000000-0000-4000-8000-000000008744', '引き算を習うのは、小学校何年生ですか？', 'Di sekolah dasar tahun berapa kita akan belajar pengurangan?'),
  ('00000000-0000-4000-8000-000000008800', 'このお札は、げんかんのドアの内がわにはっておいてください。', 'Silakan letakkan jimat ini di bagian dalam pintu depan Anda.'),
  ('00000000-0000-4000-8000-000000008800', '自分の札を見せないようにした方がいいよ。', 'Anda harus berhati-hati untuk tidak menunjukkan tangan Anda.'),
  ('00000000-0000-4000-8000-000000008800', 'ジェロってほんとにキモい。ドクロマークの絵が描かれた札でも付けておくべきだよ。', 'Jello benar-benar menjijikkan. Harus ada gambar tengkorak dan tulang bersilang pada labelnya.'),
  ('00000000-0000-4000-8000-000000008801', '「以後、このようなことがないように、気をつけるんだぞ。」「はい、先生。以後、もっと気をつけます。」', '"After this you need to be more careful so this doesn''t happen again." "Yes, teacher. I''ll be more careful from now on."'),
  ('00000000-0000-4000-8000-000000008801', '10月29日のトーフグの日以後、ビエトは行方をくらましているんだ。', 'Viet hasn''t been heard of since October 29—Tofugu Day.'),
  ('00000000-0000-4000-8000-000000008801', 'それ以後、その作家は酒を一滴も飲まなくなった。', 'After that, the writer stopped drinking alcohol, not even a single drop.'),
  ('00000000-0000-4000-8000-000000008802', 'このクーポンの使用の仕方が分かりません。', 'I don''t know how to use this coupon.'),
  ('00000000-0000-4000-8000-000000008802', '明日、九時から会ぎ室を使用したいんですが、空いていますか？', 'I want to use the meeting room at nine tomorrow. Is it available?'),
  ('00000000-0000-4000-8000-000000008802', '「へー！使用人って被雇用者のことも言うんだ。てっきり召使いって意味だと思ってた。」「そうだよ。使用者も、利用者だけじゃなくて雇用主って意味もあるしね。」', '"Oh! Shiyounin is used for an employee too? I always thought it just meant servant." "Yup. And shiyousha not only means user, but employer too."'),
  ('00000000-0000-4000-8000-000000008803', '番号札をとって、お待ちください。', 'Silakan ambil tiket bernomor dan tunggu giliran Anda.'),
  ('00000000-0000-4000-8000-000000008803', 'すみません、この辺りに番号札は落ちていませんでしたか？', 'Maaf, bukankah ada tanda nomor yang tertinggal di sekitar sini?'),
  ('00000000-0000-4000-8000-000000008803', 'こちらがお客様のお荷物の番号札となります。', 'Ini adalah label bernomor untuk bagasi Anda.'),
  ('00000000-0000-4000-8000-000000008814', 'そのダルビッシュ投手の人形はいくらですか？', 'Berapa harga boneka kendi itu, Darvish?'),
  ('00000000-0000-4000-8000-000000008814', '二丁目には、田中投手が住んでいます。', 'Pelempar, Tanaka, tinggal di 2-Chome.'),
  ('00000000-0000-4000-8000-000000008814', '今日の先発投手は誰になると思いますか？', 'Menurut Anda, siapa pelempar awal hari ini?'),
  ('00000000-0000-4000-8000-000000008895', 'ストレスで4斤のパンを一気に食べてしまった。', 'Saya makan empat potong roti sekaligus karena stres.'),
  ('00000000-0000-4000-8000-000000008895', '食パンを五斤買うなら、自分で焼いた方が安いよ。', 'Akan lebih murah untuk membuat roti sendiri jika Anda membeli lima potong roti tawar sekaligus.'),
  ('00000000-0000-4000-8000-000000008895', '8斤のパンで、卵サンドが23個とツナサンドが23個できる予定だ。', 'Delapan potong roti akan menghasilkan dua puluh tiga sandwich telur dan dua puluh tiga sandwich tuna.'),
  ('00000000-0000-4000-8000-000000008896', '一斤のパンは6枚切りか8枚切りで売られていることが多い。', 'Roti sering kali dijual dalam potongan enam atau delapan.'),
  ('00000000-0000-4000-8000-000000008896', 'たった一斤のパンで給料日までを生き延びなければいけない。', 'Saya hanya perlu bertahan hidup dengan satu potong roti sampai hari gajian.'),
  ('00000000-0000-4000-8000-000000008896', '食パン一斤と、ニュテラがあれば生きていけるよ。', 'Saya bisa hidup dari sepotong roti dan sedikit Nutella.'),
  ('00000000-0000-4000-8000-000000008897', '二斤買えば100円もお得です。', 'Jika Anda membeli dua potong roti, harganya akan lebih murah 100 yen.'),
  ('00000000-0000-4000-8000-000000008897', 'パンを二斤も焼いたのに、すぐに食べ切ってしまった。', 'Meskipun saya memanggang dua potong roti, kami menghabiskan semuanya.'),
  ('00000000-0000-4000-8000-000000008897', '賞味期限が明後日だけど、二斤も食べきれるかな？', 'Apakah menurut Anda kita bisa menghabiskan dua potong roti ini meskipun masa berlakunya sudah habis lusa?'),
  ('00000000-0000-4000-8000-000000008938', 'ひとりでにテレビが点いた。', 'TV menyala dengan sendirinya.'),
  ('00000000-0000-4000-8000-000000008938', '中々ライターが点かなくて、イライラした。', 'Pemantiknya tidak mau menyala dan itu membuatku jengkel!'),
  ('00000000-0000-4000-8000-000000008938', 'バイクのライトが点くようになった。', 'Lampu sepeda motor saya menyala sekarang.'),
  ('00000000-0000-4000-8000-000000008945', '日本にそのウィルスを広げたのは水だった。', 'It was water that spread the virus in Japan.'),
  ('00000000-0000-4000-8000-000000008945', '大人三人でブランケットを広げた。', 'Three adults unfolded a blanket.'),
  ('00000000-0000-4000-8000-000000008945', '中に入ってすぐ本を広げた。', 'As soon as I went inside, I opened the book.'),
  ('00000000-0000-4000-8000-000000008952', 'コンセントを外したら、出口から出てください。', 'Once you disconnect the plug, please use the exit.'),
  ('00000000-0000-4000-8000-000000008952', 'またターゲットを外してしまった。', 'I missed the target again.'),
  ('00000000-0000-4000-8000-000000008952', 'キョーコをチームから外した。', 'We excluded Kyoko from the team.'),
  ('00000000-0000-4000-8000-000000008952', 'エンジンを外しましょう。', 'Let''s remove the engine.'),
  ('00000000-0000-4000-8000-000000008957', '山びこが聞こえる！', 'I can hear an echo!'),
  ('00000000-0000-4000-8000-000000008957', '山びこがひびいた。 ', 'The echos reverberated.'),
  ('00000000-0000-4000-8000-000000008957', '「ヤッホー」と言ったら、「ヤッホー」と山びこが返ってきた。', 'I said "yoo-hoo" and "yoo-hoo" came echoing back at me.'),
  ('00000000-0000-4000-8000-000000008958', '力いっぱいがんばりました！', 'We did our best!'),
  ('00000000-0000-4000-8000-000000008958', 'ドアを力いっぱいおしてください。', 'Please push on the door as hard as you can.'),
  ('00000000-0000-4000-8000-000000008958', 'リレーでは力いっぱいはしりました。', 'I ran as fast as I could in the relay.'),
  ('00000000-0000-4000-8000-000000008959', '本はテーブルの上にあります。', 'The book is on the table.'),
  ('00000000-0000-4000-8000-000000008959', 'テーブルの上にグラスを三つおいてください。', 'Please put three glasses on the table.'),
  ('00000000-0000-4000-8000-000000008959', 'さっき、テーブルの上をきれいにしたよ。', 'I cleaned the table earlier.'),
  ('00000000-0000-4000-8000-000000008960', 'ベッドの下には2000さつのマンガがある。', 'There are 2000 manga under my bed.'),
  ('00000000-0000-4000-8000-000000008960', 'ベッドの下はまったくそうじしないでしょう。', 'You never clean under your bed, do you?'),
  ('00000000-0000-4000-8000-000000008960', 'ベッドの下にかくれてぜんぜん出てこない。', 'I''m going to hide under the bed and never come out.'),
  ('00000000-0000-4000-8000-000000008961', 'ぜったいにそのなまえを口にしないでね。', 'Don''t ever mention that name, okay?'),
  ('00000000-0000-4000-8000-000000008961', '女王は「好き」と口にした。', 'The words "I love you" slipped out of the queen''s mouth.'),
  ('00000000-0000-4000-8000-000000008961', '王女はおそるおそる玉ねぎを口にした。', 'The princess ate the onion timidly.'),
  ('00000000-0000-4000-8000-000000008962', '子犬と山道を歩きました。', 'I walked the mountain trail with my puppy.'),
  ('00000000-0000-4000-8000-000000008962', 'そこから山道になる。', 'From there on, it becomes a mountain path.'),
  ('00000000-0000-4000-8000-000000008962', 'その先で山道に入る。', 'Beyond that point, the road enters the mountains.'),
  ('00000000-0000-4000-8000-000000009010', '今夜は火星と土星が見えるよ！', 'Mars dan Saturnus akan terlihat malam ini!'),
  ('00000000-0000-4000-8000-000000009010', '火星には水がありますか？', 'Apakah ada air di Mars?'),
  ('00000000-0000-4000-8000-000000009010', 'オリンポス山は、火星にある火山の名です。', 'Olympus Mons adalah nama gunung berapi di Mars.'),
  ('00000000-0000-4000-8000-000000009011', 'いつか、木星に行きたいと思っています。', 'Saya ingin pergi ke Jupiter suatu hari nanti.'),
  ('00000000-0000-4000-8000-000000009011', '火星と木星のあいだには、何がありますか。', 'Ada apa antara Mars dan Jupiter?'),
  ('00000000-0000-4000-8000-000000009011', '木星や土星はこうして生まれたんですよ。', 'Beginilah asal usul planet seperti Jupiter dan Saturnus.'),
  ('00000000-0000-4000-8000-000000009020', 'どこの出身ですか。', 'Where are you from?'),
  ('00000000-0000-4000-8000-000000009020', '私たちは二人とも中国出身です。', 'We are both originally from China.'),
  ('00000000-0000-4000-8000-000000009020', '夕べのパーティーに、同じ出身の人がいました。', 'At the party last night, there was someone from my hometown.'),
  ('00000000-0000-4000-8000-000000009037', 'こちらに回答を入力してください。', 'Silakan masukkan jawaban Anda di sini.'),
  ('00000000-0000-4000-8000-000000009037', 'ご回答お待ちしています。', 'Saya menantikan balasan Anda.'),
  ('00000000-0000-4000-8000-000000009037', 'アンケートへの回答、ありがとうございました。', 'Terima kasih atas tanggapan Anda terhadap survei ini.'),
  ('00000000-0000-4000-8000-000000009042', 'クマは山から人里に出てくることがある。', 'Bears sometimes come out of the mountains into human habitations.'),
  ('00000000-0000-4000-8000-000000009042', 'ここは人里はなれたところだな。', 'We''re in the middle of nowhere, huh?'),
  ('00000000-0000-4000-8000-000000009042', '人里はなれた山の中からは、月が明るく見える。', 'The moon was brightly visible from the middle of the remote mountains.'),
  ('00000000-0000-4000-8000-000000009052', 'PDFの次頁がエラーになって見れません。', 'I cannot see the next page of the PDF because of an error.'),
  ('00000000-0000-4000-8000-000000009052', '全頁カラーのマンガをかきました。', 'I drew a full-page color manga.'),
  ('00000000-0000-4000-8000-000000009052', '毎日一頁ずつ読み進めた。', 'I read through one page each day.'),
  ('00000000-0000-4000-8000-000000009070', '大体、二分くらいかかります。', 'It generally takes about two minutes.'),
  ('00000000-0000-4000-8000-000000009070', '十五分休みましょうか。', 'Shall we rest for fifteen minutes?'),
  ('00000000-0000-4000-8000-000000009070', 'その一年生はベッドの下に四十五分もかくれている。', 'That first year student has been hiding under the bed for forty-five minutes.'),
  ('00000000-0000-4000-8000-000000009078', '十六年ぶりの社長交代です。', 'Ini adalah pergantian presiden perusahaan yang pertama dalam enam belas tahun.'),
  ('00000000-0000-4000-8000-000000009078', 'ラグビーなど、多くのスポーツで交代のルールがあります。', 'Di banyak cabang olahraga, seperti rugbi, terdapat aturan pergantian pemain.'),
  ('00000000-0000-4000-8000-000000009078', '交代の時に来なかったし、電話をかけても出ないんだ。', 'Dia tidak muncul pada shiftnya, dan dia tidak menjawab teleponnya ketika saya meneleponnya.'),
  ('00000000-0000-4000-8000-000000009082', '大学では空手をやっているんですか。', 'Are you doing karate at university?'),
  ('00000000-0000-4000-8000-000000009082', 'その女の子は空手の先生になりたいと思っていた。', 'The girl wanted to be a karate teacher.'),
  ('00000000-0000-4000-8000-000000009082', '子どもでも大人でも空手を学ぶことができます。', 'Both children and adults can learn karate.'),
  ('00000000-0000-4000-8000-000000009084', '今日は、八時に出社しました。', 'Today I arrived at the office at 8 o''clock.'),
  ('00000000-0000-4000-8000-000000009084', '出社前って、どんな風にすごしてますか？', 'How do you spend your time before going to work?'),
  ('00000000-0000-4000-8000-000000009084', 'もう出社しているはずなのに。', 'They should be at work by now, though.'),
  ('00000000-0000-4000-8000-000000009088', 'その他色々あります。', 'Masih banyak lainnya.'),
  ('00000000-0000-4000-8000-000000009088', 'その他、何か言いたいことはありますか？', 'Selain itu, adakah yang ingin Anda katakan?'),
  ('00000000-0000-4000-8000-000000009088', 'その他のゴミはどうすればいいですか。', 'Apa yang harus saya lakukan dengan sampah lainnya?'),
  ('00000000-0000-4000-8000-000000009150', 'このスーツのジャケットには内ポケットがありません。', 'Jas ini tidak memiliki saku dalam.'),
  ('00000000-0000-4000-8000-000000009150', 'このノートは、バッグの内ポケットに入ります。', 'Buku catatan ini muat di saku bagian dalam tas.'),
  ('00000000-0000-4000-8000-000000009150', '見て、あの子、内ポケットに虫を入れてるよ！', 'Lihat, anak itu memasukkan serangga ke dalam sakunya.'),
  ('00000000-0000-4000-8000-000000009159', '今日は、ナポレオン三世について学びましょう。', 'Today, we''re going to learn about Napoleon The Third.'),
  ('00000000-0000-4000-8000-000000009159', 'ナポレオン三世は1808年に生まれた。', 'Napoleon III was born in the year 1808.'),
  ('00000000-0000-4000-8000-000000009159', 'ナポレオン・ボナパルトはナポレオン三世より有名ですよね。', 'Napoleon Bonaparte is more famous than Napoleon III, isn''t he? ')
